INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85876, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "利用连续的画面和声音记录并放映故事或事件的艺术形式。", "primary_collocate": null, "pronunciation": "diàn yǐng", "ipa": "tjɛn˥˩ iŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "电影是一门把画面和声音放在一起的艺术。", "target_word": "电影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就喜欢电影，长大后想学电影。", "target_word": "电影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影和音乐一样，都是人们喜欢的艺术。", "target_word": "电影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师在大学里教电影，学生都爱听他的课。", "target_word": "电影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国电影这几年越来越受世界欢迎。", "target_word": "电影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影艺术需要导演、演员和很多工作人员。", "target_word": "电影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对电影很有研究，什么导演都知道。", "target_word": "电影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影可以记录一个时代的生活。", "target_word": "电影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学电影的学生要先学习电影理论。", "target_word": "电影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位导演一生都在为电影工作。", "target_word": "电影", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "电影院", "label": "复合"}, {"form": "电影艺术", "label": "复合"}, {"form": "電影", "label": "繁体"}], "register": "中性", "sense_fingerprint": "电影：用画面和声音讲故事的一门艺术", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee9cc0a1-56c1-4470-a8fc-b7afcfb653ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85876, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电影", "is_correct": true, "explanation": "正确。“电影是一门把画面和声音放在一起的艺术”，这是对电影这种艺术形式的定义。"}, {"text": "绘画", "is_correct": false, "explanation": "语义：绘画只有画面，没有声音，不能用“把画面和声音放在一起”来定义。"}, {"text": "摄影", "is_correct": false, "explanation": "搭配：“摄影”一般不与“声音”一起作为定义，“一门……的艺术”的说法与它不符。"}, {"text": "雕塑", "is_correct": false, "explanation": "语义：雕塑是立体造型，没有声音，与“画面和声音”的定义不符。"}], "explanations": {"电影": "正确。“电影是一门把画面和声音放在一起的艺术”，这是对电影这种艺术形式的定义。", "绘画": "语义：绘画只有画面，没有声音，不能用“把画面和声音放在一起”来定义。", "摄影": "搭配：“摄影”一般不与“声音”一起作为定义，“一门……的艺术”的说法与它不符。", "雕塑": "语义：雕塑是立体造型，没有声音，与“画面和声音”的定义不符。"}, "sentence_index": 0, "correct_answer": "电影"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上喝一杯电影。", "explanation": "这里应该用〈牛奶〉。“电影”不能喝，“喝”的对象是饮品。"}, {"text": "他的爸爸是电影。", "explanation": "这里应该用〈工程师〉。“电影”是一门艺术，不能用来指人。"}, {"text": "我的电影没电了。", "explanation": "这里应该用〈电脑〉。“没电”说的是有电池的设备，电影不是设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0dc6dfe-fc46-4ee2-b5fa-292425c0baf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85876, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电影", "is_correct": true, "explanation": "正确。“对电影很有研究”与后句“什么导演都知道”相呼应，符合句意。"}, {"text": "历史", "is_correct": false, "explanation": "语义：“历史”与后句“什么导演都知道”不相关，前后意思接不上。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球与后句“什么导演都知道”的语境不相关，句意前后不连贯。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“研究”多用于学问和事物，“对脾气很有研究”不是常见说法。"}], "explanations": {"电影": "正确。“对电影很有研究”与后句“什么导演都知道”相呼应，符合句意。", "历史": "语义：“历史”与后句“什么导演都知道”不相关，前后意思接不上。", "足球": "语义：足球与后句“什么导演都知道”的语境不相关，句意前后不连贯。", "脾气": "搭配：“研究”多用于学问和事物，“对脾气很有研究”不是常见说法。"}, "sentence_index": 6, "correct_answer": "电影"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天和朋友一起吃电影。", "explanation": "这里应该用〈饭〉。“吃”的对象是食物，电影不能吃。"}, {"text": "他把电影洗干净了。", "explanation": "这里应该用〈衣服〉。“洗”的对象是衣物，电影不能洗。"}, {"text": "他在花园里种电影。", "explanation": "这里应该用〈树〉。“电影”不能种在地里，“种”的对象是植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0dc6dfe-fc46-4ee2-b5fa-292425c0baf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85876, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他向电影很有研究。", "corrected_sentence": "他对电影很有研究。", "error_description": "表示研究的对象要用介词“对”，应说“对电影很有研究”；“向”表示方向，不能这样用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0dc6dfe-fc46-4ee2-b5fa-292425c0baf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她给电影很感兴趣。", "corrected_sentence": "她对电影很感兴趣。", "error_description": "表示感兴趣的对象要用介词“对”，应说“对电影很感兴趣”；“给”不能引出兴趣的对象。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0dc6dfe-fc46-4ee2-b5fa-292425c0baf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
