INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85878, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "敬辞，称在场或有关的每一个人。", "primary_collocate": null, "pronunciation": "gè wèi", "ipa": "kɤ˥˩ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "各位来宾，欢迎你们来到我们公司。", "target_word": "各位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各位同学，请把书打开到第十页。", "target_word": "各位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各位老师，大家好，我先说几句话。", "target_word": "各位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各位观众，晚上好，欢迎收看节目。", "target_word": "各位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各位领导，谢谢你们对我们的帮助。", "target_word": "各位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各位朋友，请安静，会议马上开始。", "target_word": "各位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各位乘客，前面就是北京站了。", "target_word": "各位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各位女士，各位先生，晚会现在开始。", "target_word": "各位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢各位今天来参加我们的活动。", "target_word": "各位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请各位在这里写上自己的名字。", "target_word": "各位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "正式场合尊敬地称呼在场或有关的每一个人，敬辞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95568041-1756-4a69-ab1f-8a712d7a8619') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85878, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "各位", "is_correct": true, "explanation": "正确：“各位来宾”是对在场或有关的每一位来宾的敬称，与后面的“你们”相符。"}, {"text": "这位", "is_correct": false, "explanation": "语义：“这位”指一个人，与后面的“你们”不一致。"}, {"text": "哪位", "is_correct": false, "explanation": "语义：“哪位”是疑问代词，不能用在欢迎致辞中指全体来宾。"}, {"text": "某位", "is_correct": false, "explanation": "语义：“某位”指不确定的某一个人，与后面的“你们”不一致。"}], "explanations": {"各位": "正确：“各位来宾”是对在场或有关的每一位来宾的敬称，与后面的“你们”相符。", "这位": "语义：“这位”指一个人，与后面的“你们”不一致。", "哪位": "语义：“哪位”是疑问代词，不能用在欢迎致辞中指全体来宾。", "某位": "语义：“某位”指不确定的某一个人，与后面的“你们”不一致。"}, "sentence_index": 0, "correct_answer": "各位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "各位是他的同学。", "explanation": "这里应该用〈他们〉。“各位”是敬称，用于直接称呼听众，不用来第三人称指代人群，应说“他们是他的同学”。"}, {"text": "我的各位都想去北京。", "explanation": "这里应该用〈大家〉。“我的各位”不是自然的说法，“各位”不用于指说话人一方。"}, {"text": "王老师，各位今天身体好吗？", "explanation": "这里只对王老师一个人说话，应该用〈您〉。“各位”称呼的是在场的多个人，不能用来称呼一个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85878, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "各位", "is_correct": true, "explanation": "正确：“各位乘客”是对全车乘客的称呼，与前面的广播内容相符。"}, {"text": "那位", "is_correct": false, "explanation": "语义：“那位”指一个人，而广播是对全车乘客说的。"}, {"text": "另一位", "is_correct": false, "explanation": "语义：“另一位”指再一个人，与全车乘客的广播不符。"}, {"text": "任何一位", "is_correct": false, "explanation": "搭配：“任何一位”强调个别的人，与“各位”指全体的称呼不搭配。"}], "explanations": {"各位": "正确：“各位乘客”是对全车乘客的称呼，与前面的广播内容相符。", "那位": "语义：“那位”指一个人，而广播是对全车乘客说的。", "另一位": "语义：“另一位”指再一个人，与全车乘客的广播不符。", "任何一位": "搭配：“任何一位”强调个别的人，与“各位”指全体的称呼不搭配。"}, "sentence_index": 6, "correct_answer": "各位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们家的各位都在吃饭。", "explanation": "这里应该用〈人〉或〈大家〉。“各位”是对听话人的敬称，不能用来说自己家里的人。"}, {"text": "各位猫咪们，别抢食了。", "explanation": "“各位”只用来称呼人，这里称呼的是猫，应该用“猫咪们”。"}, {"text": "各位，您的票掉在地上了。", "explanation": "这里只对一个人说话，应该用〈先生〉之类的单数称呼，不能用“各位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家各位领导，欢迎光临指导。", "corrected_sentence": "各位领导，欢迎光临指导。", "error_description": "错误：“各位”前面不能再加“大家”，二者重复。称呼在场的人直接说“各位”即可。正确说法是“各位领导，欢迎光临指导。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "感谢各位大家到场。", "corrected_sentence": "感谢各位到场。", "error_description": "错误：“各位”已经表示“诸位”，后面不能再加“大家”，二者重复。正确说法是“感谢各位到场。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
