INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85879, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "“不要”是叫别人不能做某件事。", "primary_collocate": null, "pronunciation": "bú yào", "ipa": "pu³⁵ jɑʊ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "上课的时候不要说话。", "target_word": "不要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要在教室里吃东西。", "target_word": "不要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，你不要一个人出去。", "target_word": "不要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要忘了带你的钥匙。", "target_word": "不要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子睡着了，请大家不要大声说话。", "target_word": "不要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有水，不要跑。", "target_word": "不要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要生气，我不是故意的。", "target_word": "不要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把垃圾扔在地上。", "target_word": "不要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试的时候不要看别人的卷子。", "target_word": "不要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要担心，我们已经准备好了。", "target_word": "不要", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "副词，口语，用在动词前，表示禁止或劝阻别人做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d5411b8-c47e-45db-bf56-b96827d1edf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85879, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不要", "is_correct": true, "explanation": "不要（bú yào）：叫别人不要做某件事，是正确答案。"}, {"text": "服药", "is_correct": false, "explanation": "服药（fú yào）与不要（bú yào）声母不同（f 与 b），意思是吃药。"}, {"text": "毒药", "is_correct": false, "explanation": "毒药（dú yào）与不要（bú yào）声母不同（d 与 b），意思是有毒的药。"}, {"text": "补药", "is_correct": false, "explanation": "补药（bǔ yào）与不要（bú yào）声调不同（第三声与第二声），意思是滋补身体的药。"}], "explanations": {"不要": "不要（bú yào）：叫别人不要做某件事，是正确答案。", "服药": "服药（fú yào）与不要（bú yào）声母不同（f 与 b），意思是吃药。", "毒药": "毒药（dú yào）与不要（bú yào）声母不同（d 与 b），意思是有毒的药。", "补药": "补药（bǔ yào）与不要（bú yào）声调不同（第三声与第二声），意思是滋补身体的药。"}, "sentence_index": null, "correct_answer": "不要"}, "level_3": {"options": [{"text": "不要", "is_correct": true, "explanation": "正确：“不要”表示禁止，上课时不能说话，符合语境。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，句中没有前后对立的语境，「上课的时候却说话」意思不通。"}, {"text": "马上", "is_correct": false, "explanation": "搭配：“马上”表示立刻，不能与泛指的“上课的时候”这一时段搭配。"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示刚刚发生，与“上课的时候”这一时段冲突。"}], "explanations": {"不要": "正确：“不要”表示禁止，上课时不能说话，符合语境。", "却": "语义：“却”表示转折，句中没有前后对立的语境，「上课的时候却说话」意思不通。", "马上": "搭配：“马上”表示立刻，不能与泛指的“上课的时候”这一时段搭配。", "刚": "语义：“刚”表示刚刚发生，与“上课的时候”这一时段冲突。"}, "sentence_index": 0, "correct_answer": "不要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天不要是周末，我们要上课。", "explanation": "这里应该用〈不是〉。“不要”不能作判断句的系词，判断的否定要用“不是”。"}, {"text": "昨天他不要来上课，老师很担心。", "explanation": "这里应该用〈没〉。叙述已经发生的事实要用“没”，“不要”只用于禁止或劝阻。"}, {"text": "这间屋子不要人住，太冷了。", "explanation": "这里应该用〈没人〉。“不要”只表示禁止或不想要，不能用来描述房间是否有人居住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85879, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不要", "is_correct": true, "explanation": "正确：“不要”表示劝阻，与“我不是故意的”的道歉语境相合。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去的经历，而句子表达的是劝阻，不是叙述过去。"}, {"text": "千万", "is_correct": false, "explanation": "搭配：“千万”要与“别”“不要”等否定词配合表示叮嘱，单用“千万生气”不通。"}, {"text": "也", "is_correct": false, "explanation": "语义：“也”表示同样，与“我不是故意的”的劝解语境不符，且“你也生气”改变了句子的意思。"}], "explanations": {"不要": "正确：“不要”表示劝阻，与“我不是故意的”的道歉语境相合。", "曾经": "语义：“曾经”指过去的经历，而句子表达的是劝阻，不是叙述过去。", "千万": "搭配：“千万”要与“别”“不要”等否定词配合表示叮嘱，单用“千万生气”不通。", "也": "语义：“也”表示同样，与“我不是故意的”的劝解语境不符，且“你也生气”改变了句子的意思。"}, "sentence_index": 6, "correct_answer": "不要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个苹果不要甜，我不喜欢。", "explanation": "这里应该用〈不〉。否定形容词要用“不”，“不要”只用于禁止或劝阻别人做事。"}, {"text": "他十岁不要学会游泳，爸爸很高兴。", "explanation": "这里应该用〈才〉。表示学会某事时间晚要用“才”，“不要”不能表达这个意思。"}, {"text": "上个星期我不要去商店，因为一直下雨。", "explanation": "这里应该用〈没〉。叙述过去没有发生的事要用“没”，“不要”只用于禁止或劝阻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85879, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晚上请大家不要了大声说话。", "corrected_sentence": "晚上请大家不要大声说话。", "error_description": "错误在于“不要”后多加了“了”。禁止副词“不要”不带“了”，应说“晚上请大家不要大声说话”，不说“晚上请大家不要了大声说话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85879, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晚上你不要的关灯，我还要看书。", "corrected_sentence": "晚上你不要关灯，我还要看书。", "error_description": "错误在于“不要”后多加了“的”。副词“不要”不能直接带“的”修饰动词，应说“晚上你不要关灯”，不说“晚上你不要的关灯”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
