INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85881, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "细小的圆形痕迹；也指一小块地方。", "primary_collocate": null, "pronunciation": "diǎn", "ipa": "tjɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "纸上有一个点，很小很小。", "target_word": "点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的那个点就是我家。", "target_word": "点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在线上画一个点。", "target_word": "点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远处天空有一个点，是一只鸟。", "target_word": "点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个点太小了，我看不清楚。", "target_word": "点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画了两个点。", "target_word": "点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把两个点连成一条线。", "target_word": "点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海上的小船远看就像一个点。", "target_word": "点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条线的两头各有一个点。", "target_word": "点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，墙上那个点是一只小虫。", "target_word": "点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "點", "label": "繁体"}, {"form": "圆点", "label": "复合"}, {"form": "黑点", "label": "复合"}], "register": "中性", "sense_fingerprint": "点：很小的圆形痕迹或一小块地方，如纸上的点、地图上的点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09d30940-30c9-4220-8182-85dc93122623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85881, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "点", "is_correct": true, "explanation": "正确：diǎn（第三声）指纸上很小的圆形痕迹，也指一小块地方。"}, {"text": "电", "is_correct": false, "explanation": "声调：diàn（第四声）与 diǎn（第三声）声调不同，意思是电。"}, {"text": "店", "is_correct": false, "explanation": "声调：diàn（第四声）与 diǎn（第三声）声调不同，意思是商店。"}, {"text": "垫", "is_correct": false, "explanation": "声调：diàn（第四声）与 diǎn（第三声）声调不同，意思是垫子。"}, {"text": "颠", "is_correct": false, "explanation": "声调：diān（第一声）与 diǎn（第三声）声调不同，意思是颠倒、摔。"}], "explanations": {"点": "正确：diǎn（第三声）指纸上很小的圆形痕迹，也指一小块地方。", "电": "声调：diàn（第四声）与 diǎn（第三声）声调不同，意思是电。", "店": "声调：diàn（第四声）与 diǎn（第三声）声调不同，意思是商店。", "垫": "声调：diàn（第四声）与 diǎn（第三声）声调不同，意思是垫子。", "颠": "声调：diān（第一声）与 diǎn（第三声）声调不同，意思是颠倒、摔。"}, "sentence_index": null, "correct_answer": "点"}, "level_3": {"options": [{"text": "巨人", "is_correct": false, "explanation": "语义：“巨人”是很大的人，与“很小很小”相矛盾。"}, {"text": "点", "is_correct": true, "explanation": "正确：“纸上有一个点”指纸上很小的圆形痕迹，与“很小很小”相合。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“纸上有”后接的应是看得见的物体，“声音”不能出现在纸上。"}, {"text": "夜晚", "is_correct": false, "explanation": "搭配：“纸上有”后接的应是可见的东西，“夜晚”是时间，不能画在纸上。"}], "explanations": {"巨人": "语义：“巨人”是很大的人，与“很小很小”相矛盾。", "点": "正确：“纸上有一个点”指纸上很小的圆形痕迹，与“很小很小”相合。", "声音": "搭配：“纸上有”后接的应是看得见的物体，“声音”不能出现在纸上。", "夜晚": "搭配：“纸上有”后接的应是可见的东西，“夜晚”是时间，不能画在纸上。"}, "sentence_index": 0, "correct_answer": "点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "衣服上有一根点，怎么也洗不掉。", "explanation": "这里应该用量词“个”。“根”用于细长的东西，“点”不能用“根”来数。"}, {"text": "墙上有一只点。", "explanation": "这里应该用量词“个”。“只”用于动物，点是小圆痕，不能用“只”。"}, {"text": "他的袖子上有一条点，很显眼。", "explanation": "这里应该用量词“个”。“条”用于细长的东西，“点”不能用“条”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85881, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "秘密", "is_correct": false, "explanation": "语义：“秘密”是看不见的，不能用线把它们连成一条线。"}, {"text": "点", "is_correct": true, "explanation": "正确：“两个点”指可以连成线的小圆点，与“连成一条线”相合。"}, {"text": "情绪", "is_correct": false, "explanation": "搭配：“连成一条线”用于可以排列的具体事物，不能说“连情绪”。"}, {"text": "梦", "is_correct": false, "explanation": "语义：“梦”是虚幻的，不能被用线连成一条线。"}], "explanations": {"秘密": "语义：“秘密”是看不见的，不能用线把它们连成一条线。", "点": "正确：“两个点”指可以连成线的小圆点，与“连成一条线”相合。", "情绪": "搭配：“连成一条线”用于可以排列的具体事物，不能说“连情绪”。", "梦": "语义：“梦”是虚幻的，不能被用线连成一条线。"}, "sentence_index": 6, "correct_answer": "点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的手上留下了一道点，很快就好了。", "explanation": "这里应该用量词“个”，说“一个点”。“道”用于伤痕、线条这类细长的东西，不用于小圆点“点”。"}, {"text": "草地上有一座点，是露水。", "explanation": "这里应该用量词“个”。“座”用于山、房屋这类大型固定的东西，“点”不能用“座”来数。"}, {"text": "信封上有一张点，是墨迹。", "explanation": "这里应该用量词“个”。“张”用于纸、床单这类平面的东西，“点”不能用“张”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85881, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "黑板上有一只点，是粉笔灰。", "corrected_sentence": "黑板上有一个点，是粉笔灰。", "error_description": "量词用错：“点”是小圆痕，应用量词“个”，说“一个点”；“只”用于动物，不能说“一只点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85881, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请在纸上画两张点。", "corrected_sentence": "请在纸上画两个点。", "error_description": "量词用错：“点”是小圆痕，应用量词“个”，说“两个点”；“张”用于纸、桌子这类平面的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
