INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85882, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一定的位置、时间或某个方面。", "primary_collocate": null, "pronunciation": "diǎn", "ipa": "tjɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "到点了，我们该下班了。", "target_word": "点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个点的人很多，超市里挤满了人。", "target_word": "点", "complexity_tier": "T3", "furigana": "zhè gè diǎn de rén hěn duō, chāo shì lǐ jǐ mǎn le rén.", "sentence_source": "generated"}, {"text": "这一点我同意你的看法。", "target_word": "点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天到点就睡觉。", "target_word": "点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个点离学校很近。", "target_word": "点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在哪个点见面？", "target_word": "点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快到点了，大家别说话了。", "target_word": "点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个点的风景很美，值得停下来看看。", "target_word": "点", "complexity_tier": "T3", "furigana": "zhè gè diǎn de fēng jǐng hěn měi, zhí dé tíng xià lái kàn kan.", "sentence_source": "generated"}, {"text": "他一到点就关了电脑。", "target_word": "点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把集合的那个点说清楚，别让我们走错。", "target_word": "点", "complexity_tier": "T3", "furigana": "qǐng nǐ bǎ jí hé de nà gè diǎn shuō qīng chu, bié ràng wǒ men zǒu cuò.", "sentence_source": "generated"}], "morphological_forms": [{"form": "點", "label": "繁体"}, {"form": "起点", "label": "复合"}, {"form": "终点", "label": "复合"}], "register": "中性", "sense_fingerprint": "点：一定的位置、时间或某个方面，如到点了、这一点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09d30940-30c9-4220-8182-85dc93122623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85882, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "点", "is_correct": true, "explanation": "正确：diǎn（第三声）指一定的时间、位置或某个方面。"}, {"text": "电", "is_correct": false, "explanation": "声调：diàn（第四声）与 diǎn（第三声）声调不同，意思是电。"}, {"text": "店", "is_correct": false, "explanation": "声调：diàn（第四声）与 diǎn（第三声）声调不同，意思是商店。"}, {"text": "垫", "is_correct": false, "explanation": "声调：diàn（第四声）与 diǎn（第三声）声调不同，意思是垫子。"}, {"text": "颠", "is_correct": false, "explanation": "声调：diān（第一声）与 diǎn（第三声）声调不同，意思是颠倒、摔。"}], "explanations": {"点": "正确：diǎn（第三声）指一定的时间、位置或某个方面。", "电": "声调：diàn（第四声）与 diǎn（第三声）声调不同，意思是电。", "店": "声调：diàn（第四声）与 diǎn（第三声）声调不同，意思是商店。", "垫": "声调：diàn（第四声）与 diǎn（第三声）声调不同，意思是垫子。", "颠": "声调：diān（第一声）与 diǎn（第三声）声调不同，意思是颠倒、摔。"}, "sentence_index": null, "correct_answer": "点"}, "level_3": {"options": [{"text": "墙", "is_correct": false, "explanation": "搭配：“到”后接时间或地点，“墙”不能用于表示时刻的“到点了”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不是时间，不能表示“到了规定的时刻”。"}, {"text": "点", "is_correct": true, "explanation": "正确：“到点了”指到了规定的时刻，与“该下班了”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不表示时刻，与“该下班了”的时间语境不合。"}], "explanations": {"墙": "搭配：“到”后接时间或地点，“墙”不能用于表示时刻的“到点了”。", "声音": "语义：“声音”不是时间，不能表示“到了规定的时刻”。", "点": "正确：“到点了”指到了规定的时刻，与“该下班了”相合。", "颜色": "语义：“颜色”不表示时刻，与“该下班了”的时间语境不合。"}, "sentence_index": 0, "correct_answer": "点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天到一段点就睡觉。", "explanation": "这里应该说“到这个点”。“段”用于一段时间，“点”指某个时刻，不能用“段”来数。"}, {"text": "他每天到一把点就睡觉。", "explanation": "这里应该用量词“个”，说“到这个点”。“把”用于有柄的器具，“点”指某个时刻，不能用“把”来数。"}, {"text": "他每天到一只点就睡觉。", "explanation": "这里应该用量词“个”。时刻用“这个点”“那个点”，“只”不能用于“点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85882, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是家具，不能表示时间，“快到椅子了”不成句。"}, {"text": "点", "is_correct": true, "explanation": "正确：“快到点了”指快到规定的时刻，与“大家别说话”相合。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：“墨水”是液体，不能表示时刻，“快到墨水了”不成句。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：“镜子”是物体，不能表示时间或地点。"}], "explanations": {"椅子": "语义：“椅子”是家具，不能表示时间，“快到椅子了”不成句。", "点": "正确：“快到点了”指快到规定的时刻，与“大家别说话”相合。", "墨水": "语义：“墨水”是液体，不能表示时刻，“快到墨水了”不成句。", "镜子": "语义：“镜子”是物体，不能表示时间或地点。"}, "sentence_index": 6, "correct_answer": "点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一到一块点就关了电脑。", "explanation": "这里应该用量词“个”，说“到这个点”。“块”用于成块的东西，不用于表示时刻的“点”。"}, {"text": "这一条点的人很多，超市里挤满了人。", "explanation": "这里应该用量词“个”，说“这个点”。“条”用于细长的东西，不用于表示时刻的“点”。"}, {"text": "我们在哪一张点见面？", "explanation": "这里应该用量词“个”，说“哪个点”。“张”用于纸、桌子这类平面的东西，不用于表示位置的“点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只点的车站一般没什么人。", "corrected_sentence": "这个点的车站一般没什么人。", "error_description": "量词用错：“点”指时刻时，应用量词“个”，说“这个点”；“只”用于动物，不能说“这只点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85882, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在那只点见面吧。", "corrected_sentence": "我们在那个点见面吧。", "error_description": "量词用错：“点”指时刻或位置时，应用量词“个”，说“那个点”；“只”用于动物，不能说“那只点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
