INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85883, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "“只是”是说只有这一件，没有别的。", "primary_collocate": null, "pronunciation": "zhǐ shì", "ipa": "ʈʂɻ̩²¹⁴ ʂɻ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "他只是个孩子，别生他的气。", "target_word": "只是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只是想问一下，没有别的意思。", "target_word": "只是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是一个小问题。", "target_word": "只是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别紧张，这只是练习。", "target_word": "只是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只是路过，不进去了。", "target_word": "只是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她只是笑了笑，什么也没说。", "target_word": "只是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是我自己的看法。", "target_word": "只是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们只是普通朋友。", "target_word": "只是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只是有点累，没有生病。", "target_word": "只是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只是忘了带伞，没什么大不了的。", "target_word": "只是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，用在动词或名词性成分前，表示仅仅如此，没有别的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d5411b8-c47e-45db-bf56-b96827d1edf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85883, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "只是", "is_correct": true, "explanation": "只是（zhǐ shì）：表示仅仅如此，没有别的，是正确答案。"}, {"text": "直视", "is_correct": false, "explanation": "直视（zhí shì）与只是（zhǐ shì）第一个字声调不同（第二声与第三声），意思是目光直直地看着。"}, {"text": "志士", "is_correct": false, "explanation": "志士（zhì shì）与只是第一个字声调不同（第四声与第三声），意思是有志向的人。"}, {"text": "史事", "is_correct": false, "explanation": "史事（shǐ shì）与只是声母不同（sh 与 zh），意思是历史上的事。"}], "explanations": {"只是": "只是（zhǐ shì）：表示仅仅如此，没有别的，是正确答案。", "直视": "直视（zhí shì）与只是（zhǐ shì）第一个字声调不同（第二声与第三声），意思是目光直直地看着。", "志士": "志士（zhì shì）与只是第一个字声调不同（第四声与第三声），意思是有志向的人。", "史事": "史事（shǐ shì）与只是声母不同（sh 与 zh），意思是历史上的事。"}, "sentence_index": null, "correct_answer": "只是"}, "level_3": {"options": [{"text": "只是", "is_correct": true, "explanation": "正确：“只是”表示仅仅如此，“他只是个孩子”说明他年纪小，符合语境。"}, {"text": "却是", "is_correct": false, "explanation": "语义：“却是”表示转折，后半句「别生他的气」没有转折的语境。"}, {"text": "何止是", "is_correct": false, "explanation": "语域：“何止是”带有书面的强调口吻，与口语化的「别生他的气」不协调。"}, {"text": "不是", "is_correct": false, "explanation": "语义：“不是”否定了“个孩子”，与「别生他的气」的劝解语境相反，逻辑不通。"}], "explanations": {"只是": "正确：“只是”表示仅仅如此，“他只是个孩子”说明他年纪小，符合语境。", "却是": "语义：“却是”表示转折，后半句「别生他的气」没有转折的语境。", "何止是": "语域：“何止是”带有书面的强调口吻，与口语化的「别生他的气」不协调。", "不是": "语义：“不是”否定了“个孩子”，与「别生他的气」的劝解语境相反，逻辑不通。"}, "sentence_index": 0, "correct_answer": "只是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "只是明天下雨，我们就不去公园了。", "explanation": "这里应该用〈要是〉，表示假设。“只是”表示仅仅如此，不能引出假设条件。"}, {"text": "我只是的很想去。", "explanation": "这里多了“的”。“只是”后不能直接接“的”，应写作「我只是很想去」。"}, {"text": "这本书只是有趣，还很有用。", "explanation": "这里应该用〈不仅〉，表示递进。“只是”表示仅仅如此，不能和“还”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85883, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "只是", "is_correct": true, "explanation": "正确：“只是”表示仅仅如此，“这只是我自己的看法”强调范围小，符合语境。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能直接修饰名词性成分“我自己的看法”。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”修饰形容词或心理动词，不能直接放在“我自己的看法”前。"}, {"text": "已经", "is_correct": false, "explanation": "语法：“已经”后要接动词（如“已经是”），不能直接接名词性成分。"}], "explanations": {"只是": "正确：“只是”表示仅仅如此，“这只是我自己的看法”强调范围小，符合语境。", "很": "语法：“很”是程度副词，不能直接修饰名词性成分“我自己的看法”。", "非常": "语法：“非常”修饰形容词或心理动词，不能直接放在“我自己的看法”前。", "已经": "语法：“已经”后要接动词（如“已经是”），不能直接接名词性成分。"}, "sentence_index": 6, "correct_answer": "只是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他十岁只是学会了游泳，所以爸爸很高兴。", "explanation": "这里应该用〈才〉，表示学会某事时间晚。“只是”表示仅仅如此，不能用来说明时间晚。"}, {"text": "只是你努力，就能成功。", "explanation": "这里应该用〈只要〉，引出条件。“只是”不能引出条件。"}, {"text": "这只是的一个小问题。", "explanation": "这里多了“的”。“只是”后不能直接接“的”，应写作「这只是一个小问题」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85883, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我只是是来看看，不买东西。", "corrected_sentence": "我只是来看看，不买东西。", "error_description": "“是”多余：“只是”是一个整体，后面不能再接“是”，应写作「我只是来看看」，不能写成「只是是来看看」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85883, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这很只是个玩笑，你别当真。", "corrected_sentence": "这只是个玩笑，你别当真。", "error_description": "“很”误加：“只是”表示仅仅如此，不能受程度副词“很”修饰，应写作「这只是个玩笑」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e22d55-1c8a-4c96-b8ed-33abc2c482a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
