INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85885, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "各个是说每一个，一个都不少。", "primary_collocate": null, "pronunciation": "gè gè", "ipa": "kɤ˥˩ kɤ˥˩", "syllable_count": 2, "sentences": [{"text": "各个班的学生都来参加比赛了。", "target_word": "各个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各个部门都要参加今天的会。", "target_word": "各个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司各个门口都有人看着。", "target_word": "各个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各个队都准备好了，比赛可以开始了。", "target_word": "各个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各个房间都打扫得很干净。", "target_word": "各个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全校各个年级都在做这件事。", "target_word": "各个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各个商店今天都开门了。", "target_word": "各个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各个小组都交了作业，一个也不少。", "target_word": "各个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上各个路口都有警察。", "target_word": "各个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各个公园今天人都很多。", "target_word": "各个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "各個", "label": "繁体"}], "register": "中性", "sense_fingerprint": "指全部的每一个，强调没有遗漏，一个都不少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95568041-1756-4a69-ab1f-8a712d7a8619') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85885, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "各个", "is_correct": true, "explanation": "各个：代词，指全部的每一个，与“都”相合。"}, {"text": "其中", "is_correct": false, "explanation": "搭配：“其中”后须接“的”或数量结构，不能直接修饰“班”，“其中班的学生”不成立。"}, {"text": "哪个", "is_correct": false, "explanation": "语义：“哪个”是疑问代词，句子是陈述，且只指一个班，与“都”的全部义不合。"}, {"text": "此", "is_correct": false, "explanation": "语域：“此”是书面语，“此班”偏正式，与这句中性的口语语境不合。"}], "explanations": {"各个": "各个：代词，指全部的每一个，与“都”相合。", "其中": "搭配：“其中”后须接“的”或数量结构，不能直接修饰“班”，“其中班的学生”不成立。", "哪个": "语义：“哪个”是疑问代词，句子是陈述，且只指一个班，与“都”的全部义不合。", "此": "语域：“此”是书面语，“此班”偏正式，与这句中性的口语语境不合。"}, "sentence_index": 0, "correct_answer": "各个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大部分同学都来参加了比赛，各个同学没来。", "explanation": "这里应该用〈个别〉。前句说“大部分同学都来参加了比赛”，“各个”指全部，不能用来表示个别同学没来。"}, {"text": "各个同学一起进了教室。", "explanation": "这里应该用〈所有〉。〈所有〉指全体一起行动，“各个”强调逐一分开，与“一起进了教室”的集体行动相矛盾。"}, {"text": "我们班只有他一个人，各个同学都参加了。", "explanation": "这里只有一个人，应该用〈这位同学〉，不能用〈各个同学〉。“各个”要求两个或以上的个体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85885, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "各个", "is_correct": true, "explanation": "各个：代词，指全部的每一个，与“都”相合。"}, {"text": "每", "is_correct": false, "explanation": "语法：“每”后须接量词，“每商店”不成立。"}, {"text": "哪些", "is_correct": false, "explanation": "语义：“哪些”是疑问代词，句子是陈述，不能用来指“哪几家商店”。"}, {"text": "一", "is_correct": false, "explanation": "语法：“一”后须接量词，“一商店”不成立。"}], "explanations": {"各个": "各个：代词，指全部的每一个，与“都”相合。", "每": "语法：“每”后须接量词，“每商店”不成立。", "哪些": "语义：“哪些”是疑问代词，句子是陈述，不能用来指“哪几家商店”。", "一": "语法：“一”后须接量词，“一商店”不成立。"}, "sentence_index": 6, "correct_answer": "各个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "各个窗户都开着，有的窗户关着。", "explanation": "这里应该用〈部分〉。“各个”指每一个都如此，与后句“有的窗户关着”矛盾，表示一部分时应用〈部分〉。"}, {"text": "我们班只有一个人交了作业，各个人都没有交。", "explanation": "这里应该用〈大多数〉或〈有的〉。它们表示部分，“各个”指全部，与“只有一个人交了作业”矛盾。"}, {"text": "只有各个窗户没关，我们检查了一下。", "explanation": "这里应该用〈某〉。“只有某个窗户没关”说的是其中一扇，“各个”指全部，与“只有”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85885, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一各个部门的经理都到齐了。", "corrected_sentence": "各个部门的经理都到齐了。", "error_description": "“各个”前面不能加数词“一”。错误形式：一各个部门；正确形式：各个部门。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85885, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "各个个班级的学生都交了报名表。", "corrected_sentence": "各个班级的学生都交了报名表。", "error_description": "“各个”后面不能再加量词“个”。错误形式：各个个班级；正确形式：各个班级。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
