INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85886, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "每一个；不止一个，一个一个分开来看。", "primary_collocate": null, "pronunciation": "gè gè", "ipa": "kɤ˥˩ kɤ˥˩", "syllable_count": 2, "sentences": [{"text": "我们要把各个问题分开来看。", "target_word": "各个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师分别和各个学生谈了话。", "target_word": "各个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各个国家的文化都不一样。", "target_word": "各个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各个城市的天气不太一样。", "target_word": "各个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把各个房间一间一间看了一遍。", "target_word": "各个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各个小组的做法有什么不同？", "target_word": "各个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先说各个办法的好处。", "target_word": "各个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各个商店的价格都不一样。", "target_word": "各个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司对各个部门分别做了检查。", "target_word": "各个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各个季节的风景都有自己的美。", "target_word": "各个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "各個", "label": "繁体"}], "register": "中性", "sense_fingerprint": "指不止一个的事物，强调一个一个分开来看、各有不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95568041-1756-4a69-ab1f-8a712d7a8619') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85886, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "各个", "is_correct": true, "explanation": "各个：代词，指每一个，与“分开来看”相合。"}, {"text": "其中", "is_correct": false, "explanation": "搭配：“其中”后须接“的”或数量结构，“把其中问题”不成立。"}, {"text": "一", "is_correct": false, "explanation": "语法：“一”后须接量词，“把一问题”不成立。"}, {"text": "每", "is_correct": false, "explanation": "语法：“每”须接量词，不能单独修饰“问题”，“把每问题”不成立。"}], "explanations": {"各个": "各个：代词，指每一个，与“分开来看”相合。", "其中": "搭配：“其中”后须接“的”或数量结构，“把其中问题”不成立。", "一": "语法：“一”后须接量词，“把一问题”不成立。", "每": "语法：“每”须接量词，不能单独修饰“问题”，“把每问题”不成立。"}, "sentence_index": 0, "correct_answer": "各个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "各个学生一起去了操场。", "explanation": "这里应该用〈所有〉。〈所有〉指全体一起行动，“各个”强调逐一分开，与“一起去了操场”的整体行动相矛盾。"}, {"text": "大部分同学都准时到了，各个同学迟到了。", "explanation": "这里应该用〈个别〉。〈个别〉表示少数，与前句“大部分同学都准时到了”相呼应；“各个”指全部，不能用来表示少数人迟到。"}, {"text": "各个同学一起唱了一首歌。", "explanation": "这里应该用〈全部〉。〈全部〉指集体的整体，“各个”强调逐一分开，与“一起唱了一首歌”的集体行动相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85886, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "各个", "is_correct": true, "explanation": "各个：代词，指每一种办法，与“先说各个办法的好处”相合。"}, {"text": "一", "is_correct": false, "explanation": "语法：“一”后须接量词，“一办法”不成立。"}, {"text": "几", "is_correct": false, "explanation": "语法：“几”后须接量词，“几办法”不成立。"}, {"text": "两", "is_correct": false, "explanation": "语法：“两”后须接量词，“两办法”不成立。"}], "explanations": {"各个": "各个：代词，指每一种办法，与“先说各个办法的好处”相合。", "一": "语法：“一”后须接量词，“一办法”不成立。", "几": "语法：“几”后须接量词，“几办法”不成立。", "两": "语法：“两”后须接量词，“两办法”不成立。"}, "sentence_index": 6, "correct_answer": "各个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学校只有一座图书馆，各个图书馆都很大。", "explanation": "这里只有一座图书馆，应该用〈这座〉，不能用〈各个〉。“各个”指同类中的每一个，要求两个或以上的个体。"}, {"text": "这件事只有一个问题，我们把各个问题分开来看。", "explanation": "这里只有一个问题，应该用〈这个〉。“各个”指不止一个的每一个，要求两个或以上的个体。"}, {"text": "只有各个学生知道答案。", "explanation": "这里应该用〈某〉。“只有某个学生知道答案”说的是其中一人，“各个”指全部每一个，与“只有”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "各个个学校的老师都很忙。", "corrected_sentence": "各个学校的老师都很忙。", "error_description": "“各个”后面不能再加量词“个”。错误形式：各个个学校；正确形式：各个学校。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一各个地区的学生都很努力。", "corrected_sentence": "各个地区的学生都很努力。", "error_description": "“各个”前面不能加数词“一”。错误形式：一各个地区；正确形式：各个地区。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
