INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85889, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "天下是天空下面所有的地方，指全世界。", "primary_collocate": null, "pronunciation": "tiān xià", "ipa": "tʰjɛn˥ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "天下没有不散的宴席。", "target_word": "天下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天下的人都知道他。", "target_word": "天下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这样的好人天下少有。", "target_word": "天下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷说，天下的父母都爱孩子。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走遍天下，看过很多地方。", "target_word": "天下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天下这么大，我想去看看。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的画传遍天下，大家都知道。", "target_word": "天下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朋友遍布天下。", "target_word": "天下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天下的河最后都流向大海。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天下的孩子都爱玩。", "target_word": "天下", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "天空下面所有的地方，全世界", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '537c4520-879d-4465-a1a7-51ade1e4b38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85889, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天下", "is_correct": true, "explanation": "正确答案。天下 tiān xià 指天空下面所有的地方，即全世界。"}, {"text": "天线", "is_correct": false, "explanation": "xiàn（第四声）与 xià（第四声）声调相同，但韵尾不同（多一个 n），意思是天线，不是天下。"}, {"text": "甜虾", "is_correct": false, "explanation": "tián（第二声）与 tiān（第一声）、xiā（第一声）与 xià（第四声）声调不同，意思是甜虾，不是天下。"}, {"text": "天象", "is_correct": false, "explanation": "xiàng（第四声）与 xià（第四声）韵尾不同（多一个 ng），意思是天体现象，不是天下。"}], "explanations": {"天下": "正确答案。天下 tiān xià 指天空下面所有的地方，即全世界。", "天线": "xiàn（第四声）与 xià（第四声）声调相同，但韵尾不同（多一个 n），意思是天线，不是天下。", "甜虾": "tián（第二声）与 tiān（第一声）、xiā（第一声）与 xià（第四声）声调不同，意思是甜虾，不是天下。", "天象": "xiàng（第四声）与 xià（第四声）韵尾不同（多一个 ng），意思是天体现象，不是天下。"}, "sentence_index": null, "correct_answer": "天下"}, "level_3": {"options": [{"text": "天下", "is_correct": true, "explanation": "正确：天下指全世界，作主语，句意是“全世界都没有不散的宴席”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指冷热阴晴，不指所有地方，句子说的范围对不上。"}, {"text": "老天爷", "is_correct": false, "explanation": "语域：老天爷是口语化的神的称呼，与“天下”的中性说法不符，句子也说不通。"}, {"text": "酒桌", "is_correct": false, "explanation": "搭配：酒桌是放桌子的地方，不能作“宴席散不散”的范围主语，“酒桌没有宴席”说不通。"}], "explanations": {"天下": "正确：天下指全世界，作主语，句意是“全世界都没有不散的宴席”。", "天气": "语义：天气指冷热阴晴，不指所有地方，句子说的范围对不上。", "老天爷": "语域：老天爷是口语化的神的称呼，与“天下”的中性说法不符，句子也说不通。", "酒桌": "搭配：酒桌是放桌子的地方，不能作“宴席散不散”的范围主语，“酒桌没有宴席”说不通。"}, "sentence_index": 0, "correct_answer": "天下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窗外的天下很蓝，我们去散步吧。", "explanation": "这里应该用〈天空〉。天下指全世界，不指天空；说天空的颜色要用“天空”。"}, {"text": "今天的天下很好，我们出去玩吧。", "explanation": "这里应该用〈天气〉。天下指全世界，不指天气；说天气好要用“天气”。"}, {"text": "这个天下很甜。", "explanation": "这里应该用〈西瓜〉。“天下”指全世界，不指水果；“甜”的主语应是“西瓜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85889, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "天下", "is_correct": true, "explanation": "正确答案。天下 tiān xià 指天空下面所有的地方，即全世界。"}, {"text": "天价", "is_correct": false, "explanation": "jià（第四声）与 xià（第四声）韵母相同，只是声母不同（j 与 x），意思是极高的价格，不是天下。"}, {"text": "天蝎", "is_correct": false, "explanation": "xiē（第一声）与 xià（第四声）声母相同，但韵母不同（e 与 a），声调也不同，意思是蝎子座，不是天下。"}, {"text": "天涯", "is_correct": false, "explanation": "yá（第二声）与 xià（第四声）韵母相同，声母不同（零声母与 x），声调也不同，意思是天边、远方，不是天下。"}], "explanations": {"天下": "正确答案。天下 tiān xià 指天空下面所有的地方，即全世界。", "天价": "jià（第四声）与 xià（第四声）韵母相同，只是声母不同（j 与 x），意思是极高的价格，不是天下。", "天蝎": "xiē（第一声）与 xià（第四声）声母相同，但韵母不同（e 与 a），声调也不同，意思是蝎子座，不是天下。", "天涯": "yá（第二声）与 xià（第四声）韵母相同，声母不同（零声母与 x），声调也不同，意思是天边、远方，不是天下。"}, "sentence_index": null, "correct_answer": "天下"}, "level_3": {"options": [{"text": "天下", "is_correct": true, "explanation": "正确：天下指全世界，作“传遍”的宾语，句意是“画的名声传遍全世界”。"}, {"text": "画家", "is_correct": false, "explanation": "配价：“传遍”要求一个处所作宾语，“画家”是人，不能作“传遍”的范围。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是一件物品，不是可以让画作传遍的范围，句意说不通。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是一门学科，不是地点或范围，“传遍数学”没有意义。"}], "explanations": {"天下": "正确：天下指全世界，作“传遍”的宾语，句意是“画的名声传遍全世界”。", "画家": "配价：“传遍”要求一个处所作宾语，“画家”是人，不能作“传遍”的范围。", "手机": "语义：手机是一件物品，不是可以让画作传遍的范围，句意说不通。", "数学": "语义：数学是一门学科，不是地点或范围，“传遍数学”没有意义。"}, "sentence_index": 6, "correct_answer": "天下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些天下，他一直很忙。", "explanation": "这里应该用〈天〉。“天”可以表示一段时间，如“这些天”；“天下”指全世界，不能用来计算时间。"}, {"text": "他的天下受伤了，不能写字。", "explanation": "这里应该用〈手〉。“天下”指全世界，不指身体部位；受伤的应是“手”。"}, {"text": "天下在院子里跑来跑去。", "explanation": "这里应该用〈小狗〉。“天下”指全世界，不指动物；在院子里跑的应是“小狗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85889, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的歌传遍天下们，大家都会唱。", "corrected_sentence": "他的歌传遍天下，大家都会唱。", "error_description": "词缀错误：“天下”后不能加复数词尾“们”，应为“传遍天下”，“天下们”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85889, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天下得老师都很辛苦。", "corrected_sentence": "天下的老师都很辛苦。", "error_description": "结构助词错误：修饰名词要用“的”，“得”用于动词后作补语。这里应为“天下的老师”，写成“天下得老师”是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
