INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85890, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家的政权，即统治国家的权力。", "primary_collocate": null, "pronunciation": "tiān xià", "ipa": "tʰjɛn˥ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "他们一起打天下，吃了很多苦。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个皇帝用十年得了天下。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天下是打出来的，不是等来的。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古时候，人们都想得到天下。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想夺天下，可是没成功。", "target_word": "天下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "秦始皇统一了天下。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他打下天下以后，当了皇帝。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老皇帝把天下交给了儿子。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他坐了二十年天下，最后老了。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位将军帮皇帝守住了天下。", "target_word": "天下", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "国家的政权，统治的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '537c4520-879d-4465-a1a7-51ade1e4b38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85890, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天下", "is_correct": true, "explanation": "正确答案。天下 tiān xià 指国家的政权，也指全世界。"}, {"text": "天线", "is_correct": false, "explanation": "xiàn（第四声）与 xià（第四声）声调相同，但韵尾不同（多一个 n），意思是天线，不是天下。"}, {"text": "甜虾", "is_correct": false, "explanation": "tián（第二声）与 tiān（第一声）、xiā（第一声）与 xià（第四声）声调不同，意思是甜虾，不是天下。"}, {"text": "添加", "is_correct": false, "explanation": "jiā（第一声）与 xià（第四声）声母不同（j 与 x），声调也不同，意思是添加，不是天下。"}, {"text": "天象", "is_correct": false, "explanation": "xiàng（第四声）与 xià（第四声）韵尾不同（多一个 ng），意思是天体现象，不是天下。"}], "explanations": {"天下": "正确答案。天下 tiān xià 指国家的政权，也指全世界。", "天线": "xiàn（第四声）与 xià（第四声）声调相同，但韵尾不同（多一个 n），意思是天线，不是天下。", "甜虾": "tián（第二声）与 tiān（第一声）、xiā（第一声）与 xià（第四声）声调不同，意思是甜虾，不是天下。", "添加": "jiā（第一声）与 xià（第四声）声母不同（j 与 x），声调也不同，意思是添加，不是天下。", "天象": "xiàng（第四声）与 xià（第四声）韵尾不同（多一个 ng），意思是天体现象，不是天下。"}, "sentence_index": null, "correct_answer": "天下"}, "level_3": {"options": [{"text": "天下", "is_correct": true, "explanation": "正确：天下指国家政权，“打天下”即争夺政权，与句意“一起奋斗吃苦”相符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“打”不能与“天气”搭配，不说“打天气”。"}, {"text": "杂志", "is_correct": false, "explanation": "搭配：“打杂志”不成立，“打”后不接印刷品。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：不说“打牛奶”，“打”不与“牛奶”搭配。"}], "explanations": {"天下": "正确：天下指国家政权，“打天下”即争夺政权，与句意“一起奋斗吃苦”相符。", "天气": "搭配：“打”不能与“天气”搭配，不说“打天气”。", "杂志": "搭配：“打杂志”不成立，“打”后不接印刷品。", "牛奶": "搭配：不说“打牛奶”，“打”不与“牛奶”搭配。"}, "sentence_index": 0, "correct_answer": "天下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个天下很香。", "explanation": "这里应该用〈面包〉。“天下”指全世界或国家政权，不指食物；说香的应是“面包”。"}, {"text": "我天下有空。", "explanation": "这里应该用〈下午〉。“天下”指全世界或国家政权，不指时间；说有空的时间要用“下午”。"}, {"text": "他想去天下留学，开阔眼界。", "explanation": "这里应该用〈国外〉。留学要去具体的国家或地方，“天下”不能作留学的去处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85890, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "天下", "is_correct": true, "explanation": "正确答案。天下 tiān xià 指国家的政权，也指全世界。"}, {"text": "天价", "is_correct": false, "explanation": "jià（第四声）与 xià（第四声）韵母相同，只是声母不同（j 与 x），意思是极高的价格，不是天下。"}, {"text": "天蝎", "is_correct": false, "explanation": "xiē（第一声）与 xià（第四声）声母相同，但韵母不同（e 与 a），声调也不同，意思是蝎子座，不是天下。"}, {"text": "天涯", "is_correct": false, "explanation": "yá（第二声）与 xià（第四声）韵母相同，声母不同（零声母与 x），声调也不同，意思是天边、远方，不是天下。"}], "explanations": {"天下": "正确答案。天下 tiān xià 指国家的政权，也指全世界。", "天价": "jià（第四声）与 xià（第四声）韵母相同，只是声母不同（j 与 x），意思是极高的价格，不是天下。", "天蝎": "xiē（第一声）与 xià（第四声）声母相同，但韵母不同（e 与 a），声调也不同，意思是蝎子座，不是天下。", "天涯": "yá（第二声）与 xià（第四声）韵母相同，声母不同（零声母与 x），声调也不同，意思是天边、远方，不是天下。"}, "sentence_index": null, "correct_answer": "天下"}, "level_3": {"options": [{"text": "天下", "is_correct": true, "explanation": "正确：天下指国家政权，“打下天下”即夺得政权，所以后来当了皇帝。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不能被“打下”，打下河流也不能让人当皇帝。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：不说“打下课本”，课本与当皇帝无关。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：夏天是季节，不能“打下”，句意说不通。"}], "explanations": {"天下": "正确：天下指国家政权，“打下天下”即夺得政权，所以后来当了皇帝。", "河流": "语义：河流不能被“打下”，打下河流也不能让人当皇帝。", "课本": "搭配：不说“打下课本”，课本与当皇帝无关。", "夏天": "语义：夏天是季节，不能“打下”，句意说不通。"}, "sentence_index": 6, "correct_answer": "天下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天下在屋顶上睡觉。", "explanation": "这里应该用〈小猫〉。“天下”指全世界或国家政权，不指动物；在屋顶上睡觉的应是“小猫”。"}, {"text": "天下开得很快。", "explanation": "这里应该用〈汽车〉。“天下”指全世界或国家政权，不是交通工具；开得快的应是“汽车”。"}, {"text": "天下很厚，我读不完。", "explanation": "这里应该用〈书〉。“天下”指全世界或国家政权，不是书籍；说厚的应是“书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于守了住天下，大家都很佩服。", "corrected_sentence": "他终于守住了天下，大家都很佩服。", "error_description": "补语位置错误：“守住”中的“住”是结果补语，应紧跟动词，“了”放在“守住”之后；写成“守了住”是错的，应为“守住了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他年轻时打了过天下，很有经验。", "corrected_sentence": "他年轻时打过天下，很有经验。", "error_description": "体标错误：“过”表示经历，动词后不能再加“了”，两个体标叠用是错的；应为“打过天下”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
