INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85891, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "“根据”是说做事情是按照什么来做的。", "primary_collocate": null, "pronunciation": "gēn jù", "ipa": "kən˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "根据地图，我们应该往左走。", "target_word": "根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们根据天气决定去不去公园。", "target_word": "根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们根据菜单点了几个菜。", "target_word": "根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生根据检查结果开了药。", "target_word": "根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他根据说明书把桌子装好了。", "target_word": "根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据书上的方法，我做了一个蛋糕。", "target_word": "根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察根据声音找到了那个人。", "target_word": "根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他根据妈妈的话买了水果。", "target_word": "根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校根据成绩给学生分班。", "target_word": "根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们根据价格选了这家饭店。", "target_word": "根据", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "介词：说明做事所按照的依据，如按地图走、按天气决定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1d1a1f-4209-4221-be5e-541950d52f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85891, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "根据", "is_correct": true, "explanation": "正确：根据表示以地图为依据，符合句意。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替某人做事，“替地图”说不通，与“往左走”冲突。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”字句需要“把+受事+动词”，这里只有“把地图”，结构不成立。"}, {"text": "为", "is_correct": false, "explanation": "语义：“为”表示目的或对象，“为地图”不能引出“往左走”的依据。"}], "explanations": {"根据": "正确：根据表示以地图为依据，符合句意。", "替": "语义：“替”表示代替某人做事，“替地图”说不通，与“往左走”冲突。", "把": "配价：“把”字句需要“把+受事+动词”，这里只有“把地图”，结构不成立。", "为": "语义：“为”表示目的或对象，“为地图”不能引出“往左走”的依据。"}, "sentence_index": 0, "correct_answer": "根据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的书根据桌子上。", "explanation": "这里应该用〈在〉。“根据”不能表示位置，应说“在桌子上”。"}, {"text": "根据参加比赛，他每天练习。", "explanation": "这里应该用〈为了〉。“为了”引出目的，“根据”只表示依据，不能引出做事的目的。"}, {"text": "火车根据北京出发。", "explanation": "这里应该用〈从〉。“根据”不表示起点，应说“从北京出发”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85891, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根据", "is_correct": true, "explanation": "正确：根据表示以声音为依据，符合句意。"}, {"text": "向", "is_correct": false, "explanation": "语义：“向”引出动作的方向或对象，“向声音”说不通，无法表示找人的依据。"}, {"text": "给", "is_correct": false, "explanation": "配价：“给”需要接受者，“给声音找到了那个人”结构不成立。"}, {"text": "对", "is_correct": false, "explanation": "语义：“对”引出对象，“对声音”与“找到了那个人”不搭，句意不通。"}], "explanations": {"根据": "正确：根据表示以声音为依据，符合句意。", "向": "语义：“向”引出动作的方向或对象，“向声音”说不通，无法表示找人的依据。", "给": "配价：“给”需要接受者，“给声音找到了那个人”结构不成立。", "对": "语义：“对”引出对象，“对声音”与“找到了那个人”不搭，句意不通。"}, "sentence_index": 6, "correct_answer": "根据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他根据家里回来了。", "explanation": "这里应该用〈从〉。“根据”不表示起点，应说“从家里回来”。"}, {"text": "根据努力，他考上了大学。", "explanation": "这里应该用〈经过〉。“经过”表示经历的过程，“根据”不能表示靠努力达到的结果。"}, {"text": "他根据同学去开会。", "explanation": "这里应该用〈替〉。“替”表示代替某人，“根据”不能引出代替的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
