INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85892, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，表示以某种事物作为前提或基础。", "primary_collocate": null, "pronunciation": "gēn jù", "ipa": "kən˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "根据他说的话，我觉得他很累。", "target_word": "根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据地图上的路线，我们一小时能到。", "target_word": "根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事是根据真人真事写的。", "target_word": "根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据报告，今年的客人比去年多。", "target_word": "根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据法律，小孩不能开车。", "target_word": "根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板根据大家的意见改了计划。", "target_word": "根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据我的了解，他不喜欢吃辣。", "target_word": "根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影是根据一本小说拍的。", "target_word": "根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据天气预报，周末会很冷。", "target_word": "根据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据这些数字，公司今年赚钱了。", "target_word": "根据", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "介词：以某事物为前提或基础来推断、创作或规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1d1a1f-4209-4221-be5e-541950d52f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85892, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "根据", "is_correct": true, "explanation": "正确：根据表示以他说的话为依据，符合句意。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替，“替他说的话”说不通，无法表示判断的依据。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”字句需要“把+受事+动词”，这里后面没有处置动词，结构不成立。"}, {"text": "向", "is_correct": false, "explanation": "语义：“向”引出对象或方向，“向他说的话”不能表示判断的依据。"}], "explanations": {"根据": "正确：根据表示以他说的话为依据，符合句意。", "替": "语义：“替”表示代替，“替他说的话”说不通，无法表示判断的依据。", "把": "配价：“把”字句需要“把+受事+动词”，这里后面没有处置动词，结构不成立。", "向": "语义：“向”引出对象或方向，“向他说的话”不能表示判断的依据。"}, "sentence_index": 0, "correct_answer": "根据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的伞根据门口。", "explanation": "这里应该用〈放在〉。“根据”不能表示位置，应说“放在门口”。"}, {"text": "这列火车根据上海出发。", "explanation": "这里应该用〈从〉。“根据”不表示起点，应说“从上海出发”。"}, {"text": "根据努力，他考上了大学。", "explanation": "这里应该用〈经过〉。“经过”表示经历的过程，“根据”不能表示靠努力达到的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85892, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根据", "is_correct": true, "explanation": "正确：根据表示以我的了解为依据，符合句意。"}, {"text": "给", "is_correct": false, "explanation": "配价：“给”需要接受者，“给我的了解”结构不成立。"}, {"text": "为", "is_correct": false, "explanation": "语义：“为”表示目的或为了谁，“为我的了解”与句意冲突。"}, {"text": "对", "is_correct": false, "explanation": "语义：“对”引出对象，“对我的了解”不能作为判断的依据，句意不通。"}], "explanations": {"根据": "正确：根据表示以我的了解为依据，符合句意。", "给": "配价：“给”需要接受者，“给我的了解”结构不成立。", "为": "语义：“为”表示目的或为了谁，“为我的了解”与句意冲突。", "对": "语义：“对”引出对象，“对我的了解”不能作为判断的依据，句意不通。"}, "sentence_index": 6, "correct_answer": "根据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们根据学校出发去看电影。", "explanation": "这里应该用〈从〉。“根据”不表示起点，应说“从学校出发”。"}, {"text": "他根据我们买了票。", "explanation": "这里应该用〈替〉。“替”表示代替我们做事，“根据”不能引出代替的人。"}, {"text": "我根据朋友去了公园。", "explanation": "这里应该用〈跟〉。“跟”表示和某人一起，“根据”不能引出同行的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85892, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们根据过经理的意见修改了方案。", "corrected_sentence": "我们根据经理的意见修改了方案。", "error_description": "错误：“根据”是介词，后面不能直接接动态助词“过”。应删去“过”，说“根据经理的意见”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85892, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们根据了这份报告修改了方案。", "corrected_sentence": "我们根据这份报告修改了方案。", "error_description": "错误：“根据”后面多加了“了”。“根据”是介词，后面不能直接接“了”，应说“根据这份报告”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
