INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85893, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心里是人想事情、有感觉的地方。", "primary_collocate": null, "pronunciation": "xīn lǐ", "ipa": "ɕin˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "收到礼物，我心里很高兴。", "target_word": "心里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个消息，他心里有点儿难过。", "target_word": "心里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心里一直想着远方的家人。", "target_word": "心里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前，我心里特别紧张。", "target_word": "心里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到妈妈，孩子心里很温暖。", "target_word": "心里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嘴上不说，心里其实很生气。", "target_word": "心里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友走了，我心里空空的。", "target_word": "心里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你现在心里在想什么？", "target_word": "心里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，她心里很害怕，不敢出门。", "target_word": "心里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里觉得很不舒服，一句话也没说。", "target_word": "心里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "心裡", "label": "繁体"}], "register": "口语", "sense_fingerprint": "名词：人感受和想事情的地方，如“心里很高兴”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef952436-ac10-4596-8374-89ff1cbf54ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85893, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心里", "is_correct": true, "explanation": "正确：「收到礼物，我心里很高兴」中“心里”指内心的感受，语境相符。"}, {"text": "手里", "is_correct": false, "explanation": "语义：“手里”是手的位置，不能表示“高兴”的感受，句子说不通。"}, {"text": "脑子", "is_correct": false, "explanation": "语义：“脑子”指大脑，不能说“脑子很高兴”。"}, {"text": "桌上", "is_correct": false, "explanation": "搭配：“桌上”是处所，不能与“很高兴”的感受搭配。"}], "explanations": {"心里": "正确：「收到礼物，我心里很高兴」中“心里”指内心的感受，语境相符。", "手里": "语义：“手里”是手的位置，不能表示“高兴”的感受，句子说不通。", "脑子": "语义：“脑子”指大脑，不能说“脑子很高兴”。", "桌上": "搭配：“桌上”是处所，不能与“很高兴”的感受搭配。"}, "sentence_index": 0, "correct_answer": "心里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把钱放在心里。", "explanation": "这里应该用〈口袋里〉。心里指内心，不是装东西的地方，放钱要说口袋里。"}, {"text": "我心里拿着一本书。", "explanation": "这里应该用〈手里〉。心里指内心的感受，不能拿东西，拿书要说手里。"}, {"text": "他心里带着钥匙。", "explanation": "这里应该用〈身上〉。心里是内心，不能带东西，随身携带要说身上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85893, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心里", "is_correct": true, "explanation": "正确：「朋友走了，我心里空空的」表示内心的失落，与“朋友走了”相符。"}, {"text": "天上", "is_correct": false, "explanation": "语义：“天上”指天空，人的内心状态不能说成“天上空空的”。"}, {"text": "树上", "is_correct": false, "explanation": "语义：“树上”是树的位置，与“我……空空的”的语境不符。"}, {"text": "地上", "is_correct": false, "explanation": "搭配：“地上”不能与“我……空空的”搭配，句子说不通。"}], "explanations": {"心里": "正确：「朋友走了，我心里空空的」表示内心的失落，与“朋友走了”相符。", "天上": "语义：“天上”指天空，人的内心状态不能说成“天上空空的”。", "树上": "语义：“树上”是树的位置，与“我……空空的”的语境不符。", "地上": "搭配：“地上”不能与“我……空空的”搭配，句子说不通。"}, "sentence_index": 6, "correct_answer": "心里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我心里有很多书。", "explanation": "这里应该用〈书包里〉。心里指内心，书不能放在心里，要说书包里。"}, {"text": "我心里有一瓶牛奶。", "explanation": "这里应该用〈冰箱里〉。心里是内心，不能装牛奶，要说冰箱里。"}, {"text": "我心里放着钥匙。", "explanation": "这里应该用〈抽屉里〉。心里指内心，不是放东西的地方，钥匙要说抽屉里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85893, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈来了，我心里了很高兴。", "corrected_sentence": "妈妈来了，我心里很高兴。", "error_description": "错误：“了”不能直接加在“心里”后面，句中多出的“了”应删去。正确形式：我心里很高兴。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85893, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把心里很难过。", "corrected_sentence": "他心里很难过。", "error_description": "错误：“把”字句不能用于“很难过”这类表示感受的句子，“把”应删去。正确形式：他心里很难过。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
