INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85894, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "内心；思想里面。", "primary_collocate": null, "pronunciation": "xīn lǐ", "ipa": "ɕin˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "这件事我一直记在心里。", "target_word": "心里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把秘密藏在心里，谁也没说。", "target_word": "心里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有话就直说，别放在心里。", "target_word": "心里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我心里明白，他是为我好。", "target_word": "心里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心里有数，不用别人提醒。", "target_word": "心里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话，我都记在心里了。", "target_word": "心里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里有个梦想，想当医生。", "target_word": "心里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的好意，我心里清楚。", "target_word": "心里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然没说话，他心里早就同意了。", "target_word": "心里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些年，她心里一直有一个问题。", "target_word": "心里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "心裡", "label": "繁体"}], "register": "口语", "sense_fingerprint": "名词：内心、思想里面，如“记在心里”“心里明白”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef952436-ac10-4596-8374-89ff1cbf54ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85894, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心里", "is_correct": true, "explanation": "正确：「这件事我一直记在心里」表示牢牢记住，与“一直”的语境相符。"}, {"text": "天上", "is_correct": false, "explanation": "语义：“天上”不能用来记事，“记在天上”说不通。"}, {"text": "天边", "is_correct": false, "explanation": "语义：“天边”是遥远的地方，不能用来记住事情。"}, {"text": "脚下", "is_correct": false, "explanation": "搭配：“脚下”是处所，不能与“记”搭配表示记住事情。"}], "explanations": {"心里": "正确：「这件事我一直记在心里」表示牢牢记住，与“一直”的语境相符。", "天上": "语义：“天上”不能用来记事，“记在天上”说不通。", "天边": "语义：“天边”是遥远的地方，不能用来记住事情。", "脚下": "搭配：“脚下”是处所，不能与“记”搭配表示记住事情。"}, "sentence_index": 0, "correct_answer": "心里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "心里有一支笔。", "explanation": "这里应该用〈盒子里〉。心里指内心，不是放笔的地方，笔要说盒子里。"}, {"text": "心里装着衣服。", "explanation": "这里应该用〈箱子里〉。心里指内心的想法，不能装衣服，衣服要说箱子里。"}, {"text": "心里放着一本书。", "explanation": "这里应该用〈书桌上〉。心里指内心，不能放书，书要说书桌上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85894, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心里", "is_correct": true, "explanation": "正确：「他心里有个梦想，想当医生」指内心的想法，与“想当医生”相符。"}, {"text": "地上", "is_correct": false, "explanation": "语义：梦想不能放在地上，“地上有个梦想”说不通。"}, {"text": "包里", "is_correct": false, "explanation": "语义：“包里”是装东西的地方，梦想不能放在包里。"}, {"text": "手上", "is_correct": false, "explanation": "搭配：“手上有个梦想”不是常用的说法，有梦想一般说在心里。"}], "explanations": {"心里": "正确：「他心里有个梦想，想当医生」指内心的想法，与“想当医生”相符。", "地上": "语义：梦想不能放在地上，“地上有个梦想”说不通。", "包里": "语义：“包里”是装东西的地方，梦想不能放在包里。", "手上": "搭配：“手上有个梦想”不是常用的说法，有梦想一般说在心里。"}, "sentence_index": 6, "correct_answer": "心里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她心里有水。", "explanation": "这里应该用〈水杯里〉。心里指内心，不能装水，水要说水杯里。"}, {"text": "她心里放着被子。", "explanation": "这里应该用〈柜子里〉。心里指内心，不是放被子的地方，被子要说柜子里。"}, {"text": "她心里有很多鸟。", "explanation": "这里应该用〈树林里〉。心里是内心，不能容纳动物，鸟要说树林里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我一直把它记在心里里。", "corrected_sentence": "我一直把它记在心里。", "error_description": "错误：“里”重复，“心里”本身已含方位词“里”，多出的“里”应删去。正确形式：我一直把它记在心里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的话我都记在心里的了。", "corrected_sentence": "他的话我都记在心里了。", "error_description": "错误：“的”不能加在“心里”和“了”之间，句中多出的“的”应删去。正确形式：他的话我都记在心里了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
