INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85896, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "代词，指近处或眼前的人或事物，相当于“这”“这个”。", "primary_collocate": null, "pronunciation": "cǐ", "ipa": "tsʰɹ̩˨˩˦", "syllable_count": 1, "sentences": [{"text": "此人是我的老师。", "target_word": "此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此路不通，请走那边。", "target_word": "此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对此很感兴趣。", "target_word": "此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此人站在门口，请大家让一让。", "target_word": "此", "complexity_tier": "T3", "furigana": "cǐ rén zhàn zài ménkǒu, qǐng dàjiā ràng yi ràng.", "sentence_source": "generated"}, {"text": "此事很重要，请你记住。", "target_word": "此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此事我已经处理完了。", "target_word": "此", "complexity_tier": "T3", "furigana": "cǐ shì wǒ yǐjīng chǔlǐ wán le.", "sentence_source": "generated"}, {"text": "他对此一点也不知道。", "target_word": "此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此人的态度让我很感动。", "target_word": "此", "complexity_tier": "T3", "furigana": "cǐ rén de tàidu ràng wǒ hěn gǎndòng.", "sentence_source": "generated"}, {"text": "此事的原因还没有查清楚。", "target_word": "此", "complexity_tier": "T3", "furigana": "cǐ shì de yuányīn hái méiyǒu chá qīngchu.", "sentence_source": "generated"}, {"text": "你不要对此担心。", "target_word": "此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "指近处或眼前的人或事物，相当于“这”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1dfd233-60e1-4be7-a6ef-22ae12c1f292') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85896, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "此", "is_correct": true, "explanation": "此（cǐ）指近处或眼前的人或事物，与词条一致。"}, {"text": "次", "is_correct": false, "explanation": "次（cì）是第四声，与 cǐ 声调不同，意思是次数。"}, {"text": "紫", "is_correct": false, "explanation": "紫（zǐ）与 cǐ 声母不同（z/c），意思是紫色。"}, {"text": "尺", "is_correct": false, "explanation": "尺（chǐ）与 cǐ 声母不同（ch/c），意思是长度单位尺。"}, {"text": "死", "is_correct": false, "explanation": "死（sǐ）与 cǐ 声母不同（s/c），意思是死亡。"}], "explanations": {"此": "此（cǐ）指近处或眼前的人或事物，与词条一致。", "次": "次（cì）是第四声，与 cǐ 声调不同，意思是次数。", "紫": "紫（zǐ）与 cǐ 声母不同（z/c），意思是紫色。", "尺": "尺（chǐ）与 cǐ 声母不同（ch/c），意思是长度单位尺。", "死": "死（sǐ）与 cǐ 声母不同（s/c），意思是死亡。"}, "sentence_index": null, "correct_answer": "此"}, "level_3": {"options": [{"text": "此", "is_correct": true, "explanation": "此指眼前或近处的人，与“人是我的老师”搭配。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，陈述句中不能用它指代已知的人。"}, {"text": "哪", "is_correct": false, "explanation": "语义：“哪”用于询问哪一个，与“人是我的老师”这个陈述不符。"}, {"text": "每", "is_correct": false, "explanation": "搭配：“每人”要与“都”呼应，不能单独作主语说“每人是我的老师”。"}], "explanations": {"此": "此指眼前或近处的人，与“人是我的老师”搭配。", "谁": "语义：“谁”是疑问代词，陈述句中不能用它指代已知的人。", "哪": "语义：“哪”用于询问哪一个，与“人是我的老师”这个陈述不符。", "每": "搭配：“每人”要与“都”呼应，不能单独作主语说“每人是我的老师”。"}, "sentence_index": 0, "correct_answer": "此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "此人在远处站着，请你去叫他。", "explanation": "这里应该用〈那个人〉。此指近处或眼前的人，远处的人要用“那”。"}, {"text": "此个苹果很甜，你尝尝。", "explanation": "这里应该用〈这个〉。“此”是书面语，后面直接接名词（如“此人”“此事”），不能加量词“个”。"}, {"text": "此人站在那边的桌子旁，请大家让一让。", "explanation": "这里应该用〈那个人〉。此指近处的人，桌子那边的人要用“那”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85896, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "此", "is_correct": true, "explanation": "此（cǐ）指近处或眼前的人或事物，与词条一致。"}, {"text": "子", "is_correct": false, "explanation": "子（zǐ）与 cǐ 声母不同（z/c），意思是儿子或小东西。"}, {"text": "齿", "is_correct": false, "explanation": "齿（chǐ）与 cǐ 声母不同（ch/c），意思是牙齿。"}, {"text": "刺", "is_correct": false, "explanation": "刺（cì）是第四声，与 cǐ 声调不同，意思是刺。"}, {"text": "瓷", "is_correct": false, "explanation": "瓷（cí）是第二声，与 cǐ 声调不同，意思是瓷器。"}], "explanations": {"此": "此（cǐ）指近处或眼前的人或事物，与词条一致。", "子": "子（zǐ）与 cǐ 声母不同（z/c），意思是儿子或小东西。", "齿": "齿（chǐ）与 cǐ 声母不同（ch/c），意思是牙齿。", "刺": "刺（cì）是第四声，与 cǐ 声调不同，意思是刺。", "瓷": "瓷（cí）是第二声，与 cǐ 声调不同，意思是瓷器。"}, "sentence_index": null, "correct_answer": "此"}, "level_3": {"options": [{"text": "此", "is_correct": true, "explanation": "此指所说的事，与“对……一点也不知道”搭配。"}, {"text": "何", "is_correct": false, "explanation": "语义：“何”是疑问代词，陈述句中不能用它指代已知的事。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”是程度副词，不能充当“对”的宾语。"}, {"text": "的", "is_correct": false, "explanation": "语法：“的”是结构助词，不能充当“对”的宾语。"}], "explanations": {"此": "此指所说的事，与“对……一点也不知道”搭配。", "何": "语义：“何”是疑问代词，陈述句中不能用它指代已知的事。", "很": "搭配：“很”是程度副词，不能充当“对”的宾语。", "的": "语法：“的”是结构助词，不能充当“对”的宾语。"}, "sentence_index": 6, "correct_answer": "此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你快来看此！", "explanation": "这里应该用〈这〉。口语中让人看眼前的东西要说“看这个”，“此”是书面语，不能这样单独作口语宾语。"}, {"text": "此个问题很难回答。", "explanation": "这里应该用〈这个〉。“此”后面直接接名词，说“此问题”，不能加量词“个”。"}, {"text": "此些书都是我的。", "explanation": "这里应该用〈这些〉。表示复数要说“这些”，“此”不能与“些”组合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "此的人我以前见过。", "corrected_sentence": "此人我以前见过。", "error_description": "“此”是指示词，后面不能直接加结构助词“的”，应直接接名词。错误形式：此的人；正确形式：此人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85896, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "事此我们已经讨论过了。", "corrected_sentence": "此事我们已经讨论过了。", "error_description": "“此”作定语要放在名词前，不能放在名词后。错误形式：事此；正确形式：此事。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
