INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85897, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "性质是事物本来具有的属性。", "primary_collocate": null, "pronunciation": "xìng zhì", "ipa": "ɕiŋ˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "水和油的性质不同。", "target_word": "性质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种水的性质不一样。", "target_word": "性质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这种东西的性质吗？", "target_word": "性质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了这种东西的性质。", "target_word": "性质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先看看这块石头的性质。", "target_word": "性质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种材料的性质很稳定。", "target_word": "性质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒精的性质是容易着火。", "target_word": "性质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做实验前，要先了解药的性质。", "target_word": "性质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糖和盐的性质完全不一样。", "target_word": "性质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金属有哪些共同的性质？", "target_word": "性质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种性质", "label": "量词"}, {"form": "性質", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：事物本来具有的属性，如“水和油的性质不同”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef952436-ac10-4596-8374-89ff1cbf54ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85897, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "性质", "is_correct": true, "explanation": "正确答案：性质（xìng zhì），指事物本来具有的样子。"}, {"text": "性急", "is_correct": false, "explanation": "jí 与 zhì 声母不同（j 与 zh），意思是性子急。"}, {"text": "姓氏", "is_correct": false, "explanation": "zhì（第四声）与 shì（第四声）声母不同（zh 与 sh），意思是姓氏。"}, {"text": "限制", "is_correct": false, "explanation": "xiàn（第四声）与 xìng（第四声）韵母不同（ian 与 ing），意思是限制。"}], "explanations": {"性质": "正确答案：性质（xìng zhì），指事物本来具有的样子。", "性急": "jí 与 zhì 声母不同（j 与 zh），意思是性子急。", "姓氏": "zhì（第四声）与 shì（第四声）声母不同（zh 与 sh），意思是姓氏。", "限制": "xiàn（第四声）与 xìng（第四声）韵母不同（ian 与 ing），意思是限制。"}, "sentence_index": null, "correct_answer": "性质"}, "level_3": {"options": [{"text": "性质", "is_correct": true, "explanation": "性质：事物本来的样子，“水和油的性质不同”说的是它们本来的特点不一样。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”只用于人或动物，不能说水和油的年龄不同。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”指人的情绪，水和油没有心情。"}, {"text": "国籍", "is_correct": false, "explanation": "语义：“国籍”指人所属的国家，水和油没有国籍。"}], "explanations": {"性质": "性质：事物本来的样子，“水和油的性质不同”说的是它们本来的特点不一样。", "年龄": "搭配：“年龄”只用于人或动物，不能说水和油的年龄不同。", "心情": "语义：“心情”指人的情绪，水和油没有心情。", "国籍": "语义：“国籍”指人所属的国家，水和油没有国籍。"}, "sentence_index": 0, "correct_answer": "性质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的性质很开朗，大家都喜欢和他一起玩。", "explanation": "这里应该用〈性格〉。性质指事物本来的样子，形容人的个性要用性格。"}, {"text": "这个孩子的性质很倔，老师都拿他没办法。", "explanation": "这里应该用〈脾气〉。性质指事物本来的样子，说人倔强、急躁要用脾气。"}, {"text": "这辆车的性质很好，加速快，油耗也低。", "explanation": "这里应该用〈性能〉。性质指事物本来的特点，说机器的功能和表现要用性能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85897, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "性质", "is_correct": true, "explanation": "正确答案：性质（xìng zhì），指事物本来具有的样子。"}, {"text": "行止", "is_correct": false, "explanation": "xíng zhǐ（第二声、第三声）与 xìng zhì（第四声、第四声）声调不同，意思是人的行为举止。"}, {"text": "形制", "is_correct": false, "explanation": "xíng（第二声）与 xìng（第四声）声调不同，意思是器物的形状和构造。"}, {"text": "性子", "is_correct": false, "explanation": "zi（轻声）与 zhì（第四声）声母不同（z 与 zh），声调也不同，意思是脾气。"}], "explanations": {"性质": "正确答案：性质（xìng zhì），指事物本来具有的样子。", "行止": "xíng zhǐ（第二声、第三声）与 xìng zhì（第四声、第四声）声调不同，意思是人的行为举止。", "形制": "xíng（第二声）与 xìng（第四声）声调不同，意思是器物的形状和构造。", "性子": "zi（轻声）与 zhì（第四声）声母不同（z 与 zh），声调也不同，意思是脾气。"}, "sentence_index": null, "correct_answer": "性质"}, "level_3": {"options": [{"text": "性质", "is_correct": true, "explanation": "性质：事物本来的特点，“酒精的性质是容易着火”正好说明它的特点。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能决定酒精是否容易着火，这句话说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”是感官上的特点，和是否容易着火没有关系。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”只用于人或动物，不能用于酒精。"}], "explanations": {"性质": "性质：事物本来的特点，“酒精的性质是容易着火”正好说明它的特点。", "颜色": "语义：“颜色”不能决定酒精是否容易着火，这句话说不通。", "味道": "语义：“味道”是感官上的特点，和是否容易着火没有关系。", "身高": "搭配：“身高”只用于人或动物，不能用于酒精。"}, "sentence_index": 6, "correct_answer": "性质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱金属的性质是五公斤。", "explanation": "这里应该用〈重量〉。性质指事物本来的特点，说物体有多重要用重量。"}, {"text": "这只小鸡的性质是公的。", "explanation": "这里应该用〈性别〉。性质指事物本来的特点，说动物的雌雄要用性别。"}, {"text": "他的性质很高，两米多，篮球打得特别好。", "explanation": "这里应该用〈身高〉。性质指事物本来的属性，说人的高矮要用身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85897, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种金属有一只特殊的性质。", "corrected_sentence": "这种金属有一种特殊的性质。", "error_description": "量词错误：“性质”是抽象名词，应该用量词“种”，写成“只”不对。正确形式：一种性质。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85897, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种药的很性质很特别。", "corrected_sentence": "这种药的性质很特别。", "error_description": "错误：程度副词“很”不能直接修饰名词“性质”，句中“性质”前多出的“很”应删去。正确形式：这种药的性质很特别。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
