INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85898, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物所具有的特点和本质。", "primary_collocate": null, "pronunciation": "xìng zhì", "ipa": "ɕiŋ˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这是两个性质不同的问题。", "target_word": "性质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作性质很特别。", "target_word": "性质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的性质是什么？", "target_word": "性质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的性质很严重。", "target_word": "性质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个活动的性质是帮助孩子。", "target_word": "性质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先说明这笔钱的性质。", "target_word": "性质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两家公司的性质完全不同。", "target_word": "性质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校和医院的性质不一样。", "target_word": "性质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先看清楚问题的性质。", "target_word": "性质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个比赛是公益性质的。", "target_word": "性质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种性质", "label": "量词"}, {"form": "性質", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：事物的特点和本质，如“工作性质”“问题的性质”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef952436-ac10-4596-8374-89ff1cbf54ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
