INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85899, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85899, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“任何”是说哪一个都可以，没有不一样的。", "primary_collocate": null, "pronunciation": "rèn hé", "ipa": "ɻən˥˩ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "任何人都可以来参加。", "target_word": "任何", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我没有任何问题。", "target_word": "任何", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事任何人都不知道。", "target_word": "任何", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不想跟任何人说话。", "target_word": "任何", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "任何时候你都可以给我打电话。", "target_word": "任何", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要努力，任何事情都能做好。", "target_word": "任何", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间里没有任何东西。", "target_word": "任何", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在任何地方，我们都要守规矩。", "target_word": "任何", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走的时候，没带任何行李。", "target_word": "任何", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "任何孩子都喜欢好吃的东西。", "target_word": "任何", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "任何人", "label": "复合"}], "register": "中性", "sense_fingerprint": "任何:哪一个都可以，无区别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25afb08-42c1-4494-8c54-317012e5d40c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85899, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "任何", "is_correct": true, "explanation": "“任何”表示哪一个都可以，与“都可以来参加”相符。"}, {"text": "有的", "is_correct": false, "explanation": "语义：“有的”表示一部分，与“都可以来参加”矛盾。"}, {"text": "有些", "is_correct": false, "explanation": "语义：“有些”表示一部分，与表示全体的“都”矛盾。"}, {"text": "某个", "is_correct": false, "explanation": "搭配：“某个”指特定的一个，不能与表示全体的“都”连用。"}], "explanations": {"任何": "“任何”表示哪一个都可以，与“都可以来参加”相符。", "有的": "语义：“有的”表示一部分，与“都可以来参加”矛盾。", "有些": "语义：“有些”表示一部分，与表示全体的“都”矛盾。", "某个": "搭配：“某个”指特定的一个，不能与表示全体的“都”连用。"}, "sentence_index": 0, "correct_answer": "任何"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们把任何的钱都花光了。", "explanation": "这里应该用〈所有〉。“任何”强调不论哪一个，指全部的钱要用“所有”。"}, {"text": "我在任何这个地方找到了钥匙。", "explanation": "这里应该去掉〈任何〉，说“我在这个地方找到了钥匙”。“任何”表示不论哪一个，不能与“这个”指定的具体地方连用。"}, {"text": "我今天吃了任何三个苹果。", "explanation": "这里应该用〈三个〉。“任何”表示不论哪一个都行，不能用来陈述已经发生的具体数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85899, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "任何", "is_correct": true, "explanation": "“任何”表示不论哪一样，与否定句“没有”搭配，符合句意。"}, {"text": "所有", "is_correct": false, "explanation": "语义：“所有”表示全部，与“没有”矛盾，不能说“没有所有东西”。"}, {"text": "全部", "is_correct": false, "explanation": "语义：“全部”表示全部，与“没有”矛盾。"}, {"text": "个别", "is_correct": false, "explanation": "搭配：“个别”多修饰人或事件，不说“个别东西”。"}], "explanations": {"任何": "“任何”表示不论哪一样，与否定句“没有”搭配，符合句意。", "所有": "语义：“所有”表示全部，与“没有”矛盾，不能说“没有所有东西”。", "全部": "语义：“全部”表示全部，与“没有”矛盾。", "个别": "搭配：“个别”多修饰人或事件，不说“个别东西”。"}, "sentence_index": 6, "correct_answer": "任何"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "任何这个答案我都知道。", "explanation": "这里应该去掉〈任何〉，说“这个答案我都知道”。“任何”不能与“这个”同时限定同一名词。"}, {"text": "我昨天给了孩子任何一颗糖。", "explanation": "这里应该用〈一颗〉。“任何”表示不论哪一个都行，不指昨天给的具体某颗糖。"}, {"text": "有些任何人都来了。", "explanation": "这里应该用〈所有〉，说“所有人都来了”。“任何”不能与表示部分的“有些”同用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85899, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "任何位老师都能帮你。", "corrected_sentence": "任何一位老师都能帮你。", "error_description": "错误：“任何”后接量词时要带“一”，应说“任何一位老师”，不能说“任何位老师”。正确：“任何一位老师都能帮你”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85899, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "任何件事都能做好。", "corrected_sentence": "任何一件事都能做好。", "error_description": "错误：“任何”后接量词时要带“一”，应说“任何一件事”，不能说“任何件事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6313af3a-885f-4fc4-91c8-2d441ec0705c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
