INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85901, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“只有”是说一定要有这个，事情才能做成。", "primary_collocate": null, "pronunciation": "zhǐ yǒu", "ipa": "ʈʂɻ̩˨˩ joʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "只有找到钥匙，门才能打开。", "target_word": "只有", "complexity_tier": "T3", "furigana": "zhǐ yǒu zhǎo dào yào shi, mén cái néng dǎ kāi.", "sentence_source": "generated"}, {"text": "只有用热水，茶才会好喝。", "target_word": "只有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有你在，这个会才能开。", "target_word": "只有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有买了票，我们才能进去。", "target_word": "只有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有带着地图，我们才不会迷路。", "target_word": "只有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有加盐，这道菜才好吃。", "target_word": "只有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有通电，灯才会亮。", "target_word": "只有", "complexity_tier": "T3", "furigana": "zhǐ yǒu tōng diàn, dēng cái huì liàng.", "sentence_source": "generated"}, {"text": "只有连上网，手机才能用。", "target_word": "只有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有医生同意，他才能出院。", "target_word": "只有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有排队，我们才能买到票。", "target_word": "只有", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "必须具备某个事物或人，事情才能成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09d30940-30c9-4220-8182-85dc93122623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85901, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "只有", "is_correct": true, "explanation": "只有 zhǐ yǒu：表示一定要有某个条件，事情才能成。"}, {"text": "挚友", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，“挚友”指亲密的朋友，与“只有”声音不同。"}, {"text": "质优", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，yōu（第一声）与 yǒu（第三声）声调也不同，“质优”指质量好。"}, {"text": "至友", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，yǒu 相同；“至友”指最好的朋友，与“只有”只差声调。"}, {"text": "知友", "is_correct": false, "explanation": "zhī（第一声）与 zhǐ（第三声）声调不同，yǒu 相同；“知友”指知心朋友，与“只有”只差声调。"}], "explanations": {"只有": "只有 zhǐ yǒu：表示一定要有某个条件，事情才能成。", "挚友": "zhì（第四声）与 zhǐ（第三声）声调不同，“挚友”指亲密的朋友，与“只有”声音不同。", "质优": "zhì（第四声）与 zhǐ（第三声）声调不同，yōu（第一声）与 yǒu（第三声）声调也不同，“质优”指质量好。", "至友": "zhì（第四声）与 zhǐ（第三声）声调不同，yǒu 相同；“至友”指最好的朋友，与“只有”只差声调。", "知友": "zhī（第一声）与 zhǐ（第三声）声调不同，yǒu 相同；“知友”指知心朋友，与“只有”只差声调。"}, "sentence_index": null, "correct_answer": "只有"}, "level_3": {"options": [{"text": "只有", "is_correct": true, "explanation": "“只有”表示一定要有这个条件，与后面的“才能”配合，句子成立。"}, {"text": "无论", "is_correct": false, "explanation": "搭配：“无论”要与“都”或“也”配合，不能与“才能”配合。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：“虽然”表示让步，前后是事实，不表示必须具备的条件。"}, {"text": "即使", "is_correct": false, "explanation": "语义：“即使”表示让步，与“门才能打开”所表达的必要条件矛盾。"}], "explanations": {"只有": "“只有”表示一定要有这个条件，与后面的“才能”配合，句子成立。", "无论": "搭配：“无论”要与“都”或“也”配合，不能与“才能”配合。", "虽然": "语义：“虽然”表示让步，前后是事实，不表示必须具备的条件。", "即使": "语义：“即使”表示让步，与“门才能打开”所表达的必要条件矛盾。"}, "sentence_index": 0, "correct_answer": "只有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "只有买了票，我们就能进去。", "explanation": "“只有”表示必要条件，要与“才”配合；与“就”配合的是“只要”。"}, {"text": "只有排队，我们也能买到票。", "explanation": "“只有”要与“才”配合，表示必须具备的条件，不能用“也”。"}, {"text": "只有你在，这个会都能开。", "explanation": "“只有”要与“才”配合，表示必须具备的条件，不能用“都”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85901, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "只有", "is_correct": true, "explanation": "只有 zhǐ yǒu：表示一定要有某个条件，事情才能成。"}, {"text": "执友", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，yǒu 相同；“执友”指志同道合的朋友。"}, {"text": "直邮", "is_correct": false, "explanation": "zhí yóu：声调与 zhǐ yǒu 不同，“直邮”指直接邮寄。"}, {"text": "挚友", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，“挚友”指亲密的朋友。"}], "explanations": {"只有": "只有 zhǐ yǒu：表示一定要有某个条件，事情才能成。", "执友": "zhí（第二声）与 zhǐ（第三声）声调不同，yǒu 相同；“执友”指志同道合的朋友。", "直邮": "zhí yóu：声调与 zhǐ yǒu 不同，“直邮”指直接邮寄。", "挚友": "zhì（第四声）与 zhǐ（第三声）声调不同，“挚友”指亲密的朋友。"}, "sentence_index": null, "correct_answer": "只有"}, "level_3": {"options": [{"text": "只有", "is_correct": true, "explanation": "“只有”表示一定要有这个条件，与后面的“才会”配合，句子成立。"}, {"text": "不但", "is_correct": false, "explanation": "配价：“不但”需要后面的“而且”或“也”来配合，句中没有这种配合。"}, {"text": "纵使", "is_correct": false, "explanation": "语义：“纵使”表示让步，不能与“才会”配合表示必要条件。"}, {"text": "尽管", "is_correct": false, "explanation": "语义：“尽管”表示让步，与“灯才会亮”所表达的必要条件矛盾。"}], "explanations": {"只有": "“只有”表示一定要有这个条件，与后面的“才会”配合，句子成立。", "不但": "配价：“不但”需要后面的“而且”或“也”来配合，句中没有这种配合。", "纵使": "语义：“纵使”表示让步，不能与“才会”配合表示必要条件。", "尽管": "语义：“尽管”表示让步，与“灯才会亮”所表达的必要条件矛盾。"}, "sentence_index": 6, "correct_answer": "只有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "只有通电，灯就会亮。", "explanation": "“只有”表示必要条件，要与“才”配合；与“就”配合的是“只要”。"}, {"text": "只有连上网，手机都能用。", "explanation": "“只有”要与“才”配合，表示必须具备的条件，不能用“都”。"}, {"text": "只有医生同意，他就能出院。", "explanation": "“只有”表示必要条件，要与“才”配合；与“就”配合的是“只要”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85901, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "只有通过考试，你能拿到证书。", "corrected_sentence": "只有通过考试，你才能拿到证书。", "error_description": "“只有”表示必须具备的条件，要与“才能”配合；这里漏掉了“才”。应改为“你才能拿到证书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85901, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "只有带好钥匙，我们也能进屋。", "corrected_sentence": "只有带好钥匙，我们才能进屋。", "error_description": "“只有”要与“才”配合，表示必须具备的条件；这里把“才”错用成“也”。应改为“我们才能进屋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85903, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相信", "is_correct": true, "explanation": "“相信”是认为话或事是真的，与“觉得不一定是真的”相对。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”是仔细地看，与“怀疑”没有反义关系。"}, {"text": "放弃", "is_correct": false, "explanation": "“放弃”是不再坚持，与“怀疑”不构成反义。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”是交换意见，与“怀疑”不构成反义。"}], "correct_answer": "相信", "explanations": {"相信": "“相信”是认为话或事是真的，与“觉得不一定是真的”相对。", "观察": "“观察”是仔细地看，与“怀疑”没有反义关系。", "放弃": "“放弃”是不再坚持，与“怀疑”不构成反义。", "讨论": "“讨论”是交换意见，与“怀疑”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85903, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相信", "is_correct": true, "explanation": "“相信”是认为话或事是真的，与“觉得不一定是真的”相对。"}, {"text": "发明", "is_correct": false, "explanation": "“发明”是创造新事物，与“怀疑”没有反义关系。"}, {"text": "记得", "is_correct": false, "explanation": "“记得”是记在心里，与“怀疑”不构成反义。"}, {"text": "收藏", "is_correct": false, "explanation": "“收藏”是保存东西，与“怀疑”不构成反义。"}], "correct_answer": "相信", "explanations": {"相信": "“相信”是认为话或事是真的，与“觉得不一定是真的”相对。", "发明": "“发明”是创造新事物，与“怀疑”没有反义关系。", "记得": "“记得”是记在心里，与“怀疑”不构成反义。", "收藏": "“收藏”是保存东西，与“怀疑”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85903, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "怀疑是心里觉得不一定是真的。", "primary_collocate": null, "pronunciation": "huái yí", "ipa": "xuaɪ̯˧˥ i˧˥", "syllable_count": 2, "sentences": [{"text": "我怀疑这个消息是不是真的。", "target_word": "怀疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人怀疑这个办法有没有用。", "target_word": "怀疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怀疑自己能不能考好。", "target_word": "怀疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了他的话，我有点怀疑。", "target_word": "怀疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不怀疑这份调查结果的真实性。", "target_word": "怀疑", "complexity_tier": "T3", "furigana": "shuí yě bù huáiyí zhè fèn diàochá jiéguǒ de zhēnshíxìng", "sentence_source": "generated"}, {"text": "你为什么怀疑我的话？", "target_word": "怀疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对他的说法有点怀疑。", "target_word": "怀疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都怀疑这个故事是不是真的。", "target_word": "怀疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来不怀疑老师说的话。", "target_word": "怀疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这家店的广告很怀疑。", "target_word": "怀疑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "怀疑了", "label": "体标"}, {"form": "怀疑过", "label": "体标"}, {"form": "怀疑着", "label": "体标"}, {"form": "懷疑", "label": "繁体"}], "register": "中性", "sense_fingerprint": "觉得话或事不一定是真的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef0daaba-e68b-4c3c-a684-5319cdf29e05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85903, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怀疑", "is_correct": true, "explanation": "“怀疑”是觉得消息不一定是真的，与句意相合。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”是乐意接受的好事，对消息真假的判断不适用。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”是为喜事而庆贺，与怀疑消息真假的语境不符。"}, {"text": "背诵", "is_correct": false, "explanation": "搭配：“背诵”的宾语是文字内容，不能用来表示对消息真假的判断。"}], "explanations": {"怀疑": "“怀疑”是觉得消息不一定是真的，与句意相合。", "欢迎": "语义：“欢迎”是乐意接受的好事，对消息真假的判断不适用。", "庆祝": "语义：“庆祝”是为喜事而庆贺，与怀疑消息真假的语境不符。", "背诵": "搭配：“背诵”的宾语是文字内容，不能用来表示对消息真假的判断。"}, "sentence_index": 0, "correct_answer": "怀疑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很怀疑那段时光。", "explanation": "这里应该用〈怀念〉。怀念是思念过去的时光，“怀疑”是心里不相信，不能用于时光。"}, {"text": "他怀疑了房间。", "explanation": "这里应该用〈打扫〉。打扫是清理房间，“怀疑”不能用于房间。"}, {"text": "他每天怀疑花。", "explanation": "这里应该用〈浇〉。浇水是给植物供水，“怀疑”不能用于花草。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85903, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怀疑", "is_correct": true, "explanation": "“怀疑”是觉得他的说法不一定是真的，与句意相合。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”是表示谢意，不能说“对说法有点感谢”。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”的对象是活动，不能说“对说法有点参加”。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”是称赞，不能说“对说法有点夸奖”。"}], "explanations": {"怀疑": "“怀疑”是觉得他的说法不一定是真的，与句意相合。", "感谢": "语义：“感谢”是表示谢意，不能说“对说法有点感谢”。", "参加": "搭配：“参加”的对象是活动，不能说“对说法有点参加”。", "夸奖": "语义：“夸奖”是称赞，不能说“对说法有点夸奖”。"}, "sentence_index": 6, "correct_answer": "怀疑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她心中怀疑着春天。", "explanation": "这里应该用〈盼望〉。盼望是心里希望某事到来，“怀疑”是心里不相信，不能接“春天”。"}, {"text": "工人怀疑货物。", "explanation": "这里应该用〈搬运〉。搬运是移动物品，“怀疑”不能用于货物。"}, {"text": "妈妈怀疑晚饭。", "explanation": "这里应该用〈烹饪〉。烹饪是做饭，“怀疑”不能用于晚饭这样的食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85903, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我怀疑这份合同过有问题。", "corrected_sentence": "我怀疑这份合同有问题。", "error_description": "多出一个“过”，夹在“这份合同”和“有问题”之间，句子不通。这里没有经历的意思，应删去，说“我怀疑这份合同有问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85903, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们怀疑的很厉害。", "corrected_sentence": "他们怀疑得很厉害。", "error_description": "“得”误写成“的”。“得”引出补语，说明“怀疑”的程度，应说“怀疑得很厉害”，“的”不能用在动词后引出补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85904, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相信", "is_correct": true, "explanation": "“相信”与“怀疑”是反义词：怀疑是心里不相信，相信是认为是真的。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”是仔细地看，与“怀疑”没有反义关系。"}, {"text": "放弃", "is_correct": false, "explanation": "“放弃”是不再坚持，与“怀疑”不构成反义。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”是交换意见，与“怀疑”不构成反义。"}], "correct_answer": "相信", "explanations": {"相信": "“相信”与“怀疑”是反义词：怀疑是心里不相信，相信是认为是真的。", "观察": "“观察”是仔细地看，与“怀疑”没有反义关系。", "放弃": "“放弃”是不再坚持，与“怀疑”不构成反义。", "讨论": "“讨论”是交换意见，与“怀疑”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85904, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相信", "is_correct": true, "explanation": "“相信”与“怀疑”是反义词：怀疑是心里不相信，相信是认为是真的。"}, {"text": "发明", "is_correct": false, "explanation": "“发明”是创造新事物，与“怀疑”没有反义关系。"}, {"text": "记得", "is_correct": false, "explanation": "“记得”是记在心里，与“怀疑”不构成反义。"}, {"text": "收藏", "is_correct": false, "explanation": "“收藏”是保存东西，与“怀疑”不构成反义。"}], "correct_answer": "相信", "explanations": {"相信": "“相信”与“怀疑”是反义词：怀疑是心里不相信，相信是认为是真的。", "发明": "“发明”是创造新事物，与“怀疑”没有反义关系。", "记得": "“记得”是记在心里，与“怀疑”不构成反义。", "收藏": "“收藏”是保存东西，与“怀疑”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85904, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "心里不相信；猜测有问题。", "primary_collocate": null, "pronunciation": "huái yí", "ipa": "xuaɪ̯˧˥ i˧˥", "syllable_count": 2, "sentences": [{"text": "警察怀疑他说了假话。", "target_word": "怀疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怀疑这件事有问题。", "target_word": "怀疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师怀疑他抄了别人的作业。", "target_word": "怀疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈怀疑我昨天没有去学校。", "target_word": "怀疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怀疑有人动过我的电脑。", "target_word": "怀疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怀疑店里的东西是假的。", "target_word": "怀疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生怀疑她得了重病。", "target_word": "怀疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都怀疑小王拿了钱。", "target_word": "怀疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怀疑他们两个人在骗我。", "target_word": "怀疑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怀疑门没有关好，又回去看了。", "target_word": "怀疑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "怀疑了", "label": "体标"}, {"form": "怀疑过", "label": "体标"}, {"form": "怀疑着", "label": "体标"}, {"form": "懷疑", "label": "繁体"}], "register": "中性", "sense_fingerprint": "猜测某人或某事有问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef0daaba-e68b-4c3c-a684-5319cdf29e05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85904, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怀疑", "is_correct": true, "explanation": "“怀疑”是心里不相信，猜测他说的未必是真的，与句意相合。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”是称赞好的方面，说假话不值得称赞，与句意相反。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的宾语是作品、才能等，不能接“说了假话”这样的事件。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示谢意，与警察因他说假话而起的疑心不符。"}], "explanations": {"怀疑": "“怀疑”是心里不相信，猜测他说的未必是真的，与句意相合。", "赞美": "语义：“赞美”是称赞好的方面，说假话不值得称赞，与句意相反。", "欣赏": "搭配：“欣赏”的宾语是作品、才能等，不能接“说了假话”这样的事件。", "感谢": "语义：“感谢”表示谢意，与警察因他说假话而起的疑心不符。"}, "sentence_index": 0, "correct_answer": "怀疑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很怀疑老家的那棵树。", "explanation": "这里应该用〈怀念〉。怀念是思念过去的人或事，“怀疑”是心里不相信，不能用于树这样的事物。"}, {"text": "妈妈很怀疑我的心情。", "explanation": "这里应该用〈担心〉。担心是为可能的不好结果忧虑，“怀疑”是心里不相信或猜测有问题，不能用于“心情”这样的感受。"}, {"text": "医生给病人怀疑了身体。", "explanation": "这里应该用〈检查〉。检查身体是查看身体情况，“怀疑”是心里不相信或猜测有问题，不能说“给病人怀疑身体”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85904, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怀疑", "is_correct": true, "explanation": "“怀疑”是觉得她得重病未必确定，与句意相合。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”用于喜事，得重病不是值得祝贺的事。"}, {"text": "羡慕", "is_correct": false, "explanation": "搭配：“羡慕”后接他人拥有的事物或处境，不能接“得了重病”这样的事件。"}, {"text": "庆幸", "is_correct": false, "explanation": "语义：“庆幸”是因好事而高兴，得重病不值得庆幸。"}], "explanations": {"怀疑": "“怀疑”是觉得她得重病未必确定，与句意相合。", "祝贺": "语义：“祝贺”用于喜事，得重病不是值得祝贺的事。", "羡慕": "搭配：“羡慕”后接他人拥有的事物或处境，不能接“得了重病”这样的事件。", "庆幸": "语义：“庆幸”是因好事而高兴，得重病不值得庆幸。"}, "sentence_index": 6, "correct_answer": "怀疑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很怀疑家乡的月亮。", "explanation": "这里应该用〈思念〉。思念是惦记远方的人或事，“怀疑”不能用于月亮这样的对象。"}, {"text": "妈妈怀疑了三碗饭。", "explanation": "这里应该用〈吃〉。吃是把食物咽下，“怀疑”不能接“三碗饭”这样的数量。"}, {"text": "她心中怀疑着温暖。", "explanation": "这里应该用〈怀抱〉。怀抱是心里存着某种感情，“怀疑”是心里不相信，不能接“温暖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他怀疑过过我的话。", "corrected_sentence": "他怀疑过我的话。", "error_description": "错误形式：“他怀疑过过我的话”；正确形式：“他怀疑过我的话”。“过”表示经历，紧跟动词只用一次，这里重复出现，应删去多余的一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
