INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85905, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "“自”是说从哪里或哪个时候开始。", "primary_collocate": null, "pronunciation": "zì", "ipa": "tsɹ̩˥˩", "syllable_count": 1, "sentences": [{"text": "自周一至周五，图书馆早上八点开门。", "target_word": "自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自明年起，这里的车票会便宜一些。", "target_word": "自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自五岁开始，她每天练习写字。", "target_word": "自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自学校到我家，走路要二十分钟。", "target_word": "自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自上海往北走，天气越来越冷。", "target_word": "自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自今年夏天起，他一直住在南京。", "target_word": "自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自昨晚八点，雨就一直没有停。", "target_word": "自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自一月到六月，我每周都去游泳。", "target_word": "自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自这里向东走五分钟，就是地铁站。", "target_word": "自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自公园南门进去，左边有个小湖。", "target_word": "自", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自从", "label": "复合"}, {"form": "自古", "label": "复合"}], "register": "书面", "sense_fingerprint": "介词，说明地点或时间从哪里、从何时开始", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: 3 words above tier T1 (max 2): 向东 (Zipf 3.71), 五分钟 (Zipf 3.84), 地铁站 (Zipf 3.96)']::text[], '2d966616-493e-40f8-b90c-9c883ccf91ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85905, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自", "is_correct": true, "explanation": "“自”（zì，第四声）是介词，说明从何处或何时开始。"}, {"text": "子", "is_correct": false, "explanation": "zǐ（第三声）与 zì（第四声）声调不同，意思是“子女”“儿子”。"}, {"text": "四", "is_correct": false, "explanation": "sì 与 zì 声母不同（s 与 z），意思是数字“四”。"}, {"text": "次", "is_correct": false, "explanation": "cì 与 zì 声母不同（c 与 z），意思是“次数”的“次”。"}, {"text": "至", "is_correct": false, "explanation": "zhì 与 zì 声母不同（zh 与 z），意思是“到”，如“至今”。"}], "explanations": {"自": "“自”（zì，第四声）是介词，说明从何处或何时开始。", "子": "zǐ（第三声）与 zì（第四声）声调不同，意思是“子女”“儿子”。", "四": "sì 与 zì 声母不同（s 与 z），意思是数字“四”。", "次": "cì 与 zì 声母不同（c 与 z），意思是“次数”的“次”。", "至": "zhì 与 zì 声母不同（zh 与 z），意思是“到”，如“至今”。"}, "sentence_index": null, "correct_answer": "自"}, "level_3": {"options": [{"text": "自", "is_correct": true, "explanation": "“自”引出时间或地点的起点，“自周一至周五”符合句意。"}, {"text": "为", "is_correct": false, "explanation": "语义：“为”表示目的或为了谁，“为周一至周五开门”说不通。"}, {"text": "对", "is_correct": false, "explanation": "搭配：“对”引出对象，不能引出时间的起点。"}, {"text": "向", "is_correct": false, "explanation": "语义：“向”表示朝向，“向周一至周五开门”说不通。"}], "explanations": {"自": "“自”引出时间或地点的起点，“自周一至周五”符合句意。", "为": "语义：“为”表示目的或为了谁，“为周一至周五开门”说不通。", "对": "搭配：“对”引出对象，不能引出时间的起点。", "向": "语义：“向”表示朝向，“向周一至周五开门”说不通。"}, "sentence_index": 0, "correct_answer": "自"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只猫自沙发上睡觉。", "explanation": "这里应该用〈在〉表示静止的位置。“自”引出起点，不能说明在哪里睡觉。"}, {"text": "这次比赛自老师负责。", "explanation": "这里应该用〈由〉引出负责的人。“自”只表示起点，不能引出执行者。"}, {"text": "他自非常聪明。", "explanation": "这里应该用〈非常〉修饰形容词。“自”不能修饰形容词“聪明”，表示程度要用程度副词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85905, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "自", "is_correct": true, "explanation": "“自”（zì，第四声）是介词，说明从何处或何时开始。"}, {"text": "紫", "is_correct": false, "explanation": "zǐ（第三声）与 zì（第四声）声调不同，意思是“紫色”。"}, {"text": "寺", "is_correct": false, "explanation": "sì 与 zì 声母不同（s 与 z），意思是“寺庙”的“寺”。"}, {"text": "刺", "is_correct": false, "explanation": "cì 与 zì 声母不同（c 与 z），意思是“刺”，如“针刺”。"}, {"text": "资", "is_correct": false, "explanation": "zī（第一声）与 zì（第四声）声调不同，意思是“资料”的“资”。"}], "explanations": {"自": "“自”（zì，第四声）是介词，说明从何处或何时开始。", "紫": "zǐ（第三声）与 zì（第四声）声调不同，意思是“紫色”。", "寺": "sì 与 zì 声母不同（s 与 z），意思是“寺庙”的“寺”。", "刺": "cì 与 zì 声母不同（c 与 z），意思是“刺”，如“针刺”。", "资": "zī（第一声）与 zì（第四声）声调不同，意思是“资料”的“资”。"}, "sentence_index": null, "correct_answer": "自"}, "level_3": {"options": [{"text": "自", "is_correct": true, "explanation": "“自”引出时间的起点，“自昨晚八点”符合句意。"}, {"text": "跟", "is_correct": false, "explanation": "搭配：“跟”引出伴随的人或事，不能引出时间的起点。"}, {"text": "凭", "is_correct": false, "explanation": "语义：“凭”表示依据，“凭昨晚八点”说不通。"}, {"text": "替", "is_correct": false, "explanation": "配价：“替”需要一个被代替的对象，这里“雨停”没有这样的对象。"}], "explanations": {"自": "“自”引出时间的起点，“自昨晚八点”符合句意。", "跟": "搭配：“跟”引出伴随的人或事，不能引出时间的起点。", "凭": "语义：“凭”表示依据，“凭昨晚八点”说不通。", "替": "配价：“替”需要一个被代替的对象，这里“雨停”没有这样的对象。"}, "sentence_index": 6, "correct_answer": "自"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师自学生很耐心。", "explanation": "这里应该用〈对〉引出对象。“自”不能引出对象，说“自学生很耐心”不通。"}, {"text": "经理自张总一起检查了报告。", "explanation": "这里应该用〈和〉引出一起行动的人。“自”只表示起点，不能引出共同行动的人。"}, {"text": "这件事自计划进行。", "explanation": "这里应该用〈依照〉表示依据。“自”不能引出依据，说“自计划进行”不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXC