INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85905, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "对早上七点起，她每天都去跑步。", "corrected_sentence": "自早上七点起，她每天都去跑步。", "error_description": "错误形式：“对早上七点起”。正确形式：“自早上七点起”。“对”引出对象，不能引出时间的起点；表示从某时开始要用“自……起”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85905, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "自周末开，我们每天晚上都要复习。", "corrected_sentence": "自周末起，我们每天晚上都要复习。", "error_description": "“自……起”中的“起”被误写成“开”。“自周末开”不完整，应说“自周末起”，“起”与“自”配合表示从某时开始。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
