INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85906, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，表示起点，相当于“从”。", "primary_collocate": null, "pronunciation": "zì", "ipa": "tsɹ̩˥˩", "syllable_count": 1, "sentences": [{"text": "这列火车自北京出发，明天早上到上海。", "target_word": "自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自上个月起，公司开始实行新规定。", "target_word": "自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自今天起，我每天早上六点起床。", "target_word": "自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自三月一日起，这家商店晚上营业到十点。", "target_word": "自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河自西向东流，最后流进大海。", "target_word": "自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自去年冬天以来，他一直住在北京。", "target_word": "自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信自南方寄来，走了五天。", "target_word": "自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自九月开始，学校要求学生穿校服。", "target_word": "自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机自广州起飞，两个小时后到达。", "target_word": "自", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自上星期五起，我们搬到了新办公室。", "target_word": "自", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自从", "label": "复合"}, {"form": "自古", "label": "复合"}], "register": "书面", "sense_fingerprint": "介词，引出地点或时间的起点，相当于“从”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d966616-493e-40f8-b90c-9c883ccf91ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85906, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自", "is_correct": true, "explanation": "“自”（zì，第四声）是介词，表示起点，相当于“从”。"}, {"text": "子", "is_correct": false, "explanation": "zǐ（第三声）与 zì（第四声）声调不同，意思是“子女”“儿子”。"}, {"text": "四", "is_correct": false, "explanation": "sì 与 zì 声母不同（s 与 z），意思是数字“四”。"}, {"text": "次", "is_correct": false, "explanation": "cì 与 zì 声母不同（c 与 z），意思是“次数”的“次”。"}, {"text": "至", "is_correct": false, "explanation": "zhì 与 zì 声母不同（zh 与 z），意思是“到”，如“至今”。"}], "explanations": {"自": "“自”（zì，第四声）是介词，表示起点，相当于“从”。", "子": "zǐ（第三声）与 zì（第四声）声调不同，意思是“子女”“儿子”。", "四": "sì 与 zì 声母不同（s 与 z），意思是数字“四”。", "次": "cì 与 zì 声母不同（c 与 z），意思是“次数”的“次”。", "至": "zhì 与 zì 声母不同（zh 与 z），意思是“到”，如“至今”。"}, "sentence_index": null, "correct_answer": "自"}, "level_3": {"options": [{"text": "自", "is_correct": true, "explanation": "“自”引出起点，“自北京出发”符合句意。"}, {"text": "为", "is_correct": false, "explanation": "语义：“为”表示目的或为了谁，“为北京出发”说不通。"}, {"text": "对", "is_correct": false, "explanation": "搭配：“对”引出对象，不能引出出发的起点。"}, {"text": "跟", "is_correct": false, "explanation": "语义：“跟”引出伴随的人或事，“跟北京出发”说不通。"}], "explanations": {"自": "“自”引出起点，“自北京出发”符合句意。", "为": "语义：“为”表示目的或为了谁，“为北京出发”说不通。", "对": "搭配：“对”引出对象，不能引出出发的起点。", "跟": "语义：“跟”引出伴随的人或事，“跟北京出发”说不通。"}, "sentence_index": 0, "correct_answer": "自"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书自桌子上放着。", "explanation": "这里应该用〈在〉表示静止的位置。“自”只引出起点，不能说明东西停放的地点。"}, {"text": "这幅画自毛笔画成。", "explanation": "这里应该用〈用〉引出所用的工具。“自”只表示起点，不能引出完成动作所用的工具。"}, {"text": "这个问题自十分难解决。", "explanation": "这里应该用〈十分〉修饰形容词。“自”不能作程度副词修饰“难”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85906, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "自", "is_correct": true, "explanation": "“自”（zì，第四声）是介词，表示起点，相当于“从”。"}, {"text": "紫", "is_correct": false, "explanation": "zǐ（第三声）与 zì（第四声）声调不同，意思是“紫色”。"}, {"text": "寺", "is_correct": false, "explanation": "sì 与 zì 声母不同（s 与 z），意思是“寺庙”的“寺”。"}, {"text": "刺", "is_correct": false, "explanation": "cì 与 zì 声母不同（c 与 z），意思是“刺”，如“针刺”。"}, {"text": "资", "is_correct": false, "explanation": "zī（第一声）与 zì（第四声）声调不同，意思是“资料”的“资”。"}], "explanations": {"自": "“自”（zì，第四声）是介词，表示起点，相当于“从”。", "紫": "zǐ（第三声）与 zì（第四声）声调不同，意思是“紫色”。", "寺": "sì 与 zì 声母不同（s 与 z），意思是“寺庙”的“寺”。", "刺": "cì 与 zì 声母不同（c 与 z），意思是“刺”，如“针刺”。", "资": "zī（第一声）与 zì（第四声）声调不同，意思是“资料”的“资”。"}, "sentence_index": null, "correct_answer": "自"}, "level_3": {"options": [{"text": "自", "is_correct": true, "explanation": "“自”引出起点，“自南方寄来”符合句意。"}, {"text": "替", "is_correct": false, "explanation": "配价：“替”需要一个被代替的对象，这里“寄来”没有这样的对象。"}, {"text": "向", "is_correct": false, "explanation": "语义：“向”表示朝向，“向南方寄来”说不通，信件不能朝某地寄来。"}, {"text": "凭", "is_correct": false, "explanation": "语义：“凭”表示依据或凭借，“凭南方寄来”说不通。"}], "explanations": {"自": "“自”引出起点，“自南方寄来”符合句意。", "替": "配价：“替”需要一个被代替的对象，这里“寄来”没有这样的对象。", "向": "语义：“向”表示朝向，“向南方寄来”说不通，信件不能朝某地寄来。", "凭": "语义：“凭”表示依据或凭借，“凭南方寄来”说不通。"}, "sentence_index": 6, "correct_answer": "自"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他自朋友很好。", "explanation": "这里应该用〈对〉引出对象。“自”不能引出对象，说“自朋友很好”不通。"}, {"text": "他自朋友一起去看电影。", "explanation": "这里应该用〈和〉引出一起行动的人。“自”只表示起点，不能引出共同行动的对象。"}, {"text": "这件工作自计划进行。", "explanation": "这里应该用〈按照〉表示依据。“自”不能引出依据，说“自计划进行”不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这封信自广州寄出，两天后自到了。", "corrected_sentence": "这封信自广州寄出，两天后到了。", "error_description": "多加了介词“自”。“两天后”之后的“到了”不需要“自”，“自”只引出起点，应说“两天后到了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "自明年开，学校每天要多上一节课。", "corrected_sentence": "自明年起，学校每天要多上一节课。", "error_description": "“自……起”中的“起”被误写成“开”。“自明年开”不完整，应说“自明年起”，“起”与“自”配合表示从某时开始。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
