INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85907, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“这里”是说离我们很近的这个地方。", "primary_collocate": null, "pronunciation": "zhè lǐ", "ipa": "ʈʂɤ˥˩ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "这里有很多人，真热闹。", "target_word": "这里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我住在这里，你住在哪里？", "target_word": "这里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在这里等我，我马上回来。", "target_word": "这里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的水很干净，可以喝。", "target_word": "这里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，这里有一只小猫。", "target_word": "这里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里离学校很近，走路五分钟。", "target_word": "这里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欢迎来到这里，请坐。", "target_word": "这里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里不能抽烟，请去外面。", "target_word": "这里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次来这里，路不太熟。", "target_word": "这里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的饭很好吃，我常来。", "target_word": "这里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "这儿", "label": "口语变体"}], "register": "中性", "sense_fingerprint": "代词：说话人所在或附近的这个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1d1a1f-4209-4221-be5e-541950d52f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85907, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "这里", "is_correct": true, "explanation": "指说话人附近的地方，与“有很多人，真热闹”相符。"}, {"text": "我", "is_correct": false, "explanation": "语义：“我”指人，不指处所，不能作“有很多人”这一处所句的主语。"}, {"text": "谁", "is_correct": false, "explanation": "配价：“有很多人”要求处所作主语，“谁”是疑问代词，句子变成疑问，不是陈述。"}, {"text": "大家", "is_correct": false, "explanation": "搭配：“大家”指人群，不能与“有很多人，真热闹”这种处所句式搭配。"}], "explanations": {"这里": "指说话人附近的地方，与“有很多人，真热闹”相符。", "我": "语义：“我”指人，不指处所，不能作“有很多人”这一处所句的主语。", "谁": "配价：“有很多人”要求处所作主语，“谁”是疑问代词，句子变成疑问，不是陈述。", "大家": "搭配：“大家”指人群，不能与“有很多人，真热闹”这种处所句式搭配。"}, "sentence_index": 0, "correct_answer": "这里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里离我们很远，需要坐三个小时的飞机才能到。", "explanation": "这里应该用〈那里〉。这里指离说话人很近的地方，不能说离我们很远；描述远处的地方要用“那里”。"}, {"text": "这里是我的爸爸。", "explanation": "这里应该用〈这〉。这里只指处所，不能指人，介绍人要用“这”。"}, {"text": "这里是我的生日，我很高兴。", "explanation": "这里应该用〈今天〉。这里只指处所，不能指日子，说日子要用“今天”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85907, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这里", "is_correct": true, "explanation": "指说话人所在的地方，与“请坐”的近处语境相符。"}, {"text": "那里", "is_correct": false, "explanation": "语义：“那里”指较远的地方，与“请坐”（请对方在此就座）的近处语境冲突。"}, {"text": "哪里", "is_correct": false, "explanation": "语义：“哪里”是疑问代词，句子是“欢迎”的陈述，不能作欢迎的处所。"}, {"text": "他", "is_correct": false, "explanation": "配价：“来到”要求处所作宾语，“他”指人，不能作“来到”的处所宾语。"}], "explanations": {"这里": "指说话人所在的地方，与“请坐”的近处语境相符。", "那里": "语义：“那里”指较远的地方，与“请坐”（请对方在此就座）的近处语境冲突。", "哪里": "语义：“哪里”是疑问代词，句子是“欢迎”的陈述，不能作欢迎的处所。", "他": "配价：“来到”要求处所作宾语，“他”指人，不能作“来到”的处所宾语。"}, "sentence_index": 6, "correct_answer": "这里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里离我们很远，我们走了两天才到。", "explanation": "这里应该用〈那里〉。这里指离说话人很近的地方，不能用来指远处；说远处的地方要用“那里”。"}, {"text": "这里是一个苹果。", "explanation": "这里应该用〈这〉。这里只指处所，不能指具体的物品，指物应说“这是一个苹果”。"}, {"text": "这里是昨天，我们去了公园。", "explanation": "这里应该用〈那天〉。这里只指处所，不能指时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85907, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里离车站到很近，我们可以走过去。", "corrected_sentence": "这里离车站很近，我们可以走过去。", "error_description": "错误：“到”插在了“车站”和“很近”之间。距离要用“离”引出，“到”不应插在此处；应说“这里离车站很近”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85907, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "从这里从医院很近。", "corrected_sentence": "从这里到医院很近。", "error_description": "错误：终点介词用错。“从”引出起点，终点要用“到”，前后不能都用“从”；应说“从这里到医院很近”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
