INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85908, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指示代词，指较近的处所。", "primary_collocate": null, "pronunciation": "zhè lǐ", "ipa": "ʈʂɤ˥˩ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "这里是我的新家，请进。", "target_word": "这里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在这里下车吧。", "target_word": "这里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里有一家很大的书店。", "target_word": "这里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把书放在这里就好。", "target_word": "这里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里夏天很热，冬天很冷。", "target_word": "这里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里有人吗？我可以坐吗？", "target_word": "这里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这里到车站要十分钟。", "target_word": "这里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都在这里玩儿。", "target_word": "这里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的人都很友好。", "target_word": "这里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，这里可以拍照吗？", "target_word": "这里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "这儿", "label": "口语变体"}], "register": "口语", "sense_fingerprint": "指示代词：指示较近的处所，与“那里”相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1d1a1f-4209-4221-be5e-541950d52f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85908, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "这里", "is_correct": true, "explanation": "指说话人所在的地方，与“请进”相符。"}, {"text": "那里", "is_correct": false, "explanation": "语义：“那里”指较远的地方，与“请进”（请对方进入此处）冲突。"}, {"text": "我", "is_correct": false, "explanation": "语义：“我”指人，不指处所，不能作“是……新家”的主语。"}, {"text": "大家", "is_correct": false, "explanation": "搭配：“大家”指人群，不能与“是我的新家”搭配。"}], "explanations": {"这里": "指说话人所在的地方，与“请进”相符。", "那里": "语义：“那里”指较远的地方，与“请进”（请对方进入此处）冲突。", "我": "语义：“我”指人，不指处所，不能作“是……新家”的主语。", "大家": "搭配：“大家”指人群，不能与“是我的新家”搭配。"}, "sentence_index": 0, "correct_answer": "这里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里离我们很远，需要坐三个小时的飞机才能到。", "explanation": "这里应该用〈那里〉。这里指离说话人很近的地方，不能说离我们很远；描述远处的地方要用“那里”。"}, {"text": "这里是我的新朋友。", "explanation": "这里应该用〈这〉。这里只指处所，不能指人，介绍人要用“这”。"}, {"text": "这里我们去公园吧，明天再去书店。", "explanation": "这里应该用〈今天〉。这里只指处所，不能指时间，说“今天”与“明天”对比时要用“今天”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85908, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这里", "is_correct": true, "explanation": "指说话人所在的地方，是“从”的起点，与“到车站要十分钟”相符。"}, {"text": "那个", "is_correct": false, "explanation": "搭配：“那个”不指处所，不能作“从……到车站”的起点。"}, {"text": "谁", "is_correct": false, "explanation": "配价：“从……到”要求处所起点，“谁”是疑问代词，句子变成疑问，不是陈述。"}, {"text": "他", "is_correct": false, "explanation": "语义：“他”指人，不指处所，不能作“从”的起点。"}], "explanations": {"这里": "指说话人所在的地方，是“从”的起点，与“到车站要十分钟”相符。", "那个": "搭配：“那个”不指处所，不能作“从……到车站”的起点。", "谁": "配价：“从……到”要求处所起点，“谁”是疑问代词，句子变成疑问，不是陈述。", "他": "语义：“他”指人，不指处所，不能作“从”的起点。"}, "sentence_index": 6, "correct_answer": "这里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你看，山那边的那座房子，这里就是我奶奶家。", "explanation": "这里应该用〈那里〉。房子在“山那边”，离说话人很远，不能用“这里”，指远处要用“那里”。"}, {"text": "这里是我妈妈，她是老师。", "explanation": "这里应该用〈这〉。这里只指处所，不能指人，介绍人要用“这是我妈妈”。"}, {"text": "我很喜欢这里本书。", "explanation": "这里应该用〈这〉。这里是处所代词，不能直接放在“本书”前作指示词，指物要用“这本书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里在有很多好吃的东西。", "corrected_sentence": "这里有很多好吃的东西。", "error_description": "错误：“这里”作主语，表示存在的处所，后面的“有”已标示存在，前面多加了“在”，形成重复。正确：删去“在”，应说“这里有很多好吃的东西”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "离这里到火车站很远。", "corrected_sentence": "从这里到火车站很远。", "error_description": "错误：“离”用于“这里”前，表示距离的参照点，但与“到”同用时不通。正确：引出起点要用“从”，应说“从这里到火车站很远”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
