INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85909, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "会所是一些人聚在一起玩和休息的房子。", "primary_collocate": null, "pronunciation": "huì suǒ", "ipa": "xweɪ˥˩ swo˨˩˦", "syllable_count": 2, "sentences": [{"text": "我家附近有一家会所。", "target_word": "会所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去会所打球吧。", "target_word": "会所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个会所里有游泳池。", "target_word": "会所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常和朋友在会所喝茶。", "target_word": "会所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会所的房子很大，也很安静。", "target_word": "会所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸是这家会所的会员。", "target_word": "会所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班后我们去会所休息一下。", "target_word": "会所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家会所有很多好玩的东西。", "target_word": "会所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会所在山上，开车半个小时到。", "target_word": "会所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在会所里玩了一下午。", "target_word": "会所", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一家会所", "label": "量词"}, {"form": "會所", "label": "繁体"}], "register": "口语", "sense_fingerprint": "人们聚在一起玩和休息的房子，口语里常指有会员的休闲地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95568041-1756-4a69-ab1f-8a712d7a8619') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85909, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会所", "is_correct": true, "explanation": "会所：供人聚会、休闲的场所，与“一家”搭配，符合“我家附近”的语境。"}, {"text": "车站", "is_correct": false, "explanation": "搭配：“车站”的量词通常是“个”或“座”，一般不说“一家车站”。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：“公园”的量词是“个”或“座”，不说“一家公园”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”不是可以开设的场所，“我家附近有一家空气”说不通。"}], "explanations": {"会所": "会所：供人聚会、休闲的场所，与“一家”搭配，符合“我家附近”的语境。", "车站": "搭配：“车站”的量词通常是“个”或“座”，一般不说“一家车站”。", "公园": "搭配：“公园”的量词是“个”或“座”，不说“一家公园”。", "空气": "语义：“空气”不是可以开设的场所，“我家附近有一家空气”说不通。"}, "sentence_index": 0, "correct_answer": "会所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家附近新开了一台会所。", "explanation": "量词“台”多用于机器、设备，会所应该用“家”，这里应说“一家会所”。"}, {"text": "他是我们的会所，很能帮忙。", "explanation": "这里指人，应该用〈朋友〉。会所指供人聚会、休闲的场所，不指人，不能说“他是我们的会所”。"}, {"text": "他常去会所看病。", "explanation": "这里说的是看病，应该用〈医院〉。会所是供人聚会、休闲的场所，不能用来看病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85909, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会所", "is_correct": true, "explanation": "会所：供人聚会、休闲的场所，符合“下班后去休息”的语境。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是工作的地方，下班后去工厂休息说不通。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：“去”后接地点，“电影”是物，应说“看电影”。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不是可以休息的地方，这里说不通。"}], "explanations": {"会所": "会所：供人聚会、休闲的场所，符合“下班后去休息”的语境。", "工厂": "语义：工厂是工作的地方，下班后去工厂休息说不通。", "电影": "搭配：“去”后接地点，“电影”是物，应说“看电影”。", "垃圾": "语义：垃圾不是可以休息的地方，这里说不通。"}, "sentence_index": 6, "correct_answer": "会所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家附近新开了一张会所。", "explanation": "量词“张”多用于平面的东西，会所应该用“家”，这里应说“一家会所”。"}, {"text": "我去会所取了钱。", "explanation": "这里说的是取钱，应该用〈银行〉。会所是供人聚会、休闲的场所，不办理存取款。"}, {"text": "孩子们在会所里打了一下午针。", "explanation": "这里说的是打针，应该用〈诊所〉。会所是供人聚会、休闲的场所，不能用来打针。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85909, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我们在那只会所门口等车。", "corrected_sentence": "周末我们在那家会所门口等车。", "error_description": "“会所”的量词应为“家”，“只”多用于动物等。错误形式：那只会所；正确形式：那家会所。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85909, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在会所们门口等我。", "corrected_sentence": "他在会所门口等我。", "error_description": "“会所”是场所名词，不能加“们”表示复数。错误形式：会所们门口；正确形式：会所门口。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
