INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85910, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供人聚会、休闲、娱乐的场所。", "primary_collocate": null, "pronunciation": "huì suǒ", "ipa": "xweɪ˥˩ swo˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家会所可以举办小型聚会。", "target_word": "会所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区里新开了一家会所。", "target_word": "会所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会所为客人提供休闲和娱乐服务。", "target_word": "会所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个会所晚上十点才关门。", "target_word": "会所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司在会所里办了一场晚会。", "target_word": "会所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会所的健身房运动。", "target_word": "会所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家会所的环境很不错。", "target_word": "会所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会所里的服务员都很热情。", "target_word": "会所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们约好在会所门口见面。", "target_word": "会所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末会所里来了很多客人。", "target_word": "会所", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一家会所", "label": "量词"}, {"form": "會所", "label": "繁体"}], "register": "中性", "sense_fingerprint": "提供聚会、休闲和娱乐服务的场所，多指商业或小区会所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95568041-1756-4a69-ab1f-8a712d7a8619') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85910, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会所", "is_correct": true, "explanation": "会所：可以举办聚会的休闲场所，与“这家”搭配，符合“举办小型聚会”的语境。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不是用来举办聚会的场所，句子说不通。"}, {"text": "监狱", "is_correct": false, "explanation": "语义：监狱不能举办小型聚会，句子说不通。"}, {"text": "煤矿", "is_correct": false, "explanation": "语义：煤矿是采煤的地方，不能举办聚会，“这家煤矿”也不符合语境。"}], "explanations": {"会所": "会所：可以举办聚会的休闲场所，与“这家”搭配，符合“举办小型聚会”的语境。", "医院": "语义：医院不是用来举办聚会的场所，句子说不通。", "监狱": "语义：监狱不能举办小型聚会，句子说不通。", "煤矿": "语义：煤矿是采煤的地方，不能举办聚会，“这家煤矿”也不符合语境。"}, "sentence_index": 0, "correct_answer": "会所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台会所晚上十点才关门。", "explanation": "量词“台”多用于机器、设备，会所应该用“家”，这里应说“这家会所”。"}, {"text": "他把会所装进了行李箱。", "explanation": "这里应该用〈物品〉。会所是供人聚会、休闲的场所，不是可以装进行李箱的东西。"}, {"text": "他去会所拔牙了。", "explanation": "这里说的是拔牙，应该用〈诊所〉。会所是供人聚会、休闲的场所，不能用来拔牙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85910, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会所", "is_correct": true, "explanation": "会所：供人休闲的场所，与“这家”搭配，符合“环境很不错”的评价。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是物品，不是场所，“这家雨伞的环境”说不通。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线不是场所，“这家电线”说不通，也无法谈“环境”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是场所，“这家空气”说不通。"}], "explanations": {"会所": "会所：供人休闲的场所，与“这家”搭配，符合“环境很不错”的评价。", "雨伞": "语义：雨伞是物品，不是场所，“这家雨伞的环境”说不通。", "电线": "语义：电线不是场所，“这家电线”说不通，也无法谈“环境”。", "空气": "语义：空气不是场所，“这家空气”说不通。"}, "sentence_index": 6, "correct_answer": "会所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们小区新开了一片会所。", "explanation": "量词“片”多用于成片的地域或平面，会所应该用“家”，这里应说“一家会所”。"}, {"text": "周末我们在会所里进行手术。", "explanation": "这里说的是手术，应该用〈医院〉。会所是供人聚会、休闲、娱乐的场所，不能用来做手术。"}, {"text": "周末我去会所考驾照。", "explanation": "这里说的是考驾照，应该用〈驾校〉。会所是供人聚会、休闲的场所，不能考驾照。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85910, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小区里那条会所最近装修了。", "corrected_sentence": "小区里那家会所最近装修了。", "error_description": "“会所”的量词应为“家”，“条”用于长条形的事物。错误形式：那条会所；正确形式：那家会所。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在会所们楼下吃晚饭吧。", "corrected_sentence": "我们在会所楼下吃晚饭吧。", "error_description": "“会所”是场所名词，不能加“们”表示复数。错误形式：会所们楼下；正确形式：会所楼下。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e495ad-9d1b-4ec0-80c6-62a92300d687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
