INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85911, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "“一起”是说几个人在同一个地方，一块儿做事。", "primary_collocate": null, "pronunciation": "yì qǐ", "ipa": "i˥˩ tɕʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "周末我们一起去公园玩。", "target_word": "一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和朋友一起吃晚饭。", "target_word": "一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一起在图书馆学习汉语。", "target_word": "一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈和我一起做饭。", "target_word": "一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课以后，我们一起回家吧。", "target_word": "一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天你想和谁一起看电影？", "target_word": "一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们一起唱了一首歌。", "target_word": "一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起努力，一定能学好中文。", "target_word": "一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和哥哥一起去过北京。", "target_word": "一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起帮我搬家。", "target_word": "一起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：几个人一块儿做同一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2ce387-de1a-4dee-a2b5-d7f05cb692cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85911, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一起", "is_correct": true, "explanation": "正确答案：一起 yì qǐ，指几个人一块儿做事。"}, {"text": "义气", "is_correct": false, "explanation": "qì（第四声）与 qǐ（第三声）声调不同，意思是讲义气、重情义。"}, {"text": "一气", "is_correct": false, "explanation": "一气 yīqì：yī 与 yì、qì 与 qǐ 声调都不同，意思是一口气、连续地。"}, {"text": "意气", "is_correct": false, "explanation": "yì 与一起相同，仅 qì 与 qǐ 声调不同，意思是意气、情绪。"}, {"text": "以期", "is_correct": false, "explanation": "yǐ 与 yì、qī 与 qǐ 声调不同，意思是为了希望。"}], "explanations": {"一起": "正确答案：一起 yì qǐ，指几个人一块儿做事。", "义气": "qì（第四声）与 qǐ（第三声）声调不同，意思是讲义气、重情义。", "一气": "一气 yīqì：yī 与 yì、qì 与 qǐ 声调都不同，意思是一口气、连续地。", "意气": "yì 与一起相同，仅 qì 与 qǐ 声调不同，意思是意气、情绪。", "以期": "yǐ 与 yì、qī 与 qǐ 声调不同，意思是为了希望。"}, "sentence_index": null, "correct_answer": "一起"}, "level_3": {"options": [{"text": "一起", "is_correct": true, "explanation": "“一起”表示几个人共同做事，与“我们”和“去公园玩”相符。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：“刚才”指说话前不久的过去，与“周末”这种将来的时间不合。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，与“周末”这种预先安排的时间不合。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示动作已经完成，与“周末”这种将来的时间不合。"}], "explanations": {"一起": "“一起”表示几个人共同做事，与“我们”和“去公园玩”相符。", "刚才": "语义：“刚才”指说话前不久的过去，与“周末”这种将来的时间不合。", "忽然": "语义：“忽然”表示突然发生，与“周末”这种预先安排的时间不合。", "已经": "语义：“已经”表示动作已经完成，与“周末”这种将来的时间不合。"}, "sentence_index": 0, "correct_answer": "一起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班一起有四十个学生。", "explanation": "这里表示总数，应该用〈一共〉。“一起”表示几个人共同做事，不用于计总数。"}, {"text": "我一起去超市买东西。", "explanation": "“一起”指几个人一块儿做事，只有一个人时不能用，应该说〈一个人〉去。"}, {"text": "这两个苹果一起是红色的。", "explanation": "这里表示“全都”，应该用〈都〉。“一起”只用于几个人共同做事，不能表示“都”，更不能用来描述颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85911, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一起", "is_correct": true, "explanation": "“一起”表示几个人共同做事，与“同学们”和“唱了一首歌”相符。"}, {"text": "单独", "is_correct": false, "explanation": "搭配：“单独”强调一方自己行动，与“同学们”集体唱歌的动作不合。"}, {"text": "正在", "is_correct": false, "explanation": "语法：“正在”表示动作进行中，与已完成的“唱了”不合。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示即刻要发生，与已经完成的“唱了”不合。"}], "explanations": {"一起": "“一起”表示几个人共同做事，与“同学们”和“唱了一首歌”相符。", "单独": "搭配：“单独”强调一方自己行动，与“同学们”集体唱歌的动作不合。", "正在": "语法：“正在”表示动作进行中，与已完成的“唱了”不合。", "马上": "语义：“马上”表示即刻要发生，与已经完成的“唱了”不合。"}, "sentence_index": 6, "correct_answer": "一起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是我们一起的责任。", "explanation": "“一起”是副词，不能直接修饰名词“责任”，这里应该用〈共同〉。"}, {"text": "我一起考了第一名。", "explanation": "这里只有我一个人考试，“一起”表示几个人共同做事，应该用〈独自〉。"}, {"text": "大家一起都是学生。", "explanation": "“一起”不能与“是”搭配表示身份，表示全体应该用〈都〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85911, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们一起一起去超市买菜。", "corrected_sentence": "我们一起去超市买菜。", "error_description": "副词“一起”不能重复出现。“我们一起一起去超市买菜”中多了一个“一起”，正确形式是“我们一起去超市买菜”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85911, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天的一起开会吧。", "corrected_sentence": "我们明天一起开会吧。", "error_description": "副词“一起”前面不能加“的”，否则变成修饰语。正确形式是“我们明天一起开会吧”，“一起”直接放在动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85913, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85913, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85913, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“因此”是说前面的事是原因，后面的事是结果。", "primary_collocate": null, "pronunciation": "yīn cǐ", "ipa": "in˥ tsʰɿ˨˩˦", "syllable_count": 2, "sentences": [{"text": "昨晚下了大雨，因此比赛改到明天。", "target_word": "因此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天练习，因此汉语进步很快。", "target_word": "因此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵车，因此我迟到了。", "target_word": "因此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天天气很冷，因此很多人没出门。", "target_word": "因此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很爱笑，因此大家都喜欢她。", "target_word": "因此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜很便宜，因此客人特别多。", "target_word": "因此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病了，因此没来上课。", "target_word": "因此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天睡得太晚，因此今天很累。", "target_word": "因此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车坏了，因此我们晚了两个小时。", "target_word": "因此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直很努力，因此考了第一名。", "target_word": "因此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "连词：前一分句是原因，因此引出后一分句的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 3 words above tier T1 (max 2): 睡得 (Zipf 3.28), 太晚 (Zipf 3.5), 很累 (Zipf 3.45)']::text[], '1d1d1a1f-4209-4221-be5e-541950d52f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85913, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "因此", "is_correct": true, "explanation": "表示因果：前句“下了大雨”是原因，后句“比赛改到明天”是结果。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，与“下大雨→比赛改期”的因果关系不符。"}, {"text": "而且", "is_correct": false, "explanation": "语义：“而且”表示递进或并列，不能表示前后的因果关系。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与后文“但/却”呼应，这里没有配套分句，不成立。"}], "explanations": {"因此": "表示因果：前句“下了大雨”是原因，后句“比赛改到明天”是结果。", "但是": "语义：“但是”表示转折，与“下大雨→比赛改期”的因果关系不符。", "而且": "语义：“而且”表示递进或并列，不能表示前后的因果关系。", "虽然": "搭配：“虽然”要与后文“但/却”呼应，这里没有配套分句，不成立。"}, "sentence_index": 0, "correct_answer": "因此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "因此下雨，我们就不去。", "explanation": "这里应该用〈如果〉。因此表示因果，引出结果，不能引出条件；提出假设条件要用“如果”。"}, {"text": "这家店的菜很好，因此很便宜。", "explanation": "这里应该用〈而且〉。“很便宜”不是“菜很好”的结果，因此表示因果不合适，应用“而且”表示递进。"}, {"text": "他很累，因此很开心。", "explanation": "这里应该用〈但是〉。因此表示因果，“很开心”与“很累”是转折关系，不能用因果词连接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85913, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "因此", "is_correct": true, "explanation": "表示因果：生病是原因，没来上课是结果。"}, {"text": "尽管", "is_correct": false, "explanation": "搭配：“尽管”要与后文“但/却”呼应，这里没有配套分句，不成立。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”意思是“如果不这样”，引出假设的后果；“生病”与“没来上课”是实际的因果，不能用“否则”。"}, {"text": "何况", "is_correct": false, "explanation": "语义：“何况”表示更进一层，与“生病→没来上课”的因果关系不符。"}], "explanations": {"因此": "表示因果：生病是原因，没来上课是结果。", "尽管": "搭配：“尽管”要与后文“但/却”呼应，这里没有配套分句，不成立。", "否则": "语义：“否则”意思是“如果不这样”，引出假设的后果；“生病”与“没来上课”是实际的因果，不能用“否则”。", "何况": "语义：“何况”表示更进一层，与“生病→没来上课”的因果关系不符。"}, "sentence_index": 6, "correct_answer": "因此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他吃完饭，因此去上课。", "explanation": "这里应该用〈然后〉。因此表示因果，“去上课”不是“吃完饭”的结果，表示先后应用“然后”。"}, {"text": "你可以坐车，因此也可以走路去。", "explanation": "这里应该用〈或者〉。因此表示因果，不能表示选择；两种方式可以任选时要用“或者”。"}, {"text": "尽管天下雨了，比赛因此照常进行。", "explanation": "这里应该用〈仍然〉。“尽管”表示让步，“照常进行”不是下雨的结果，不能用因此表因果，应说“比赛仍然照常进行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85913, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天下雨了因此，我们不出去。", "corrected_sentence": "天下雨了，因此我们不出去。", "error_description": "错误：“因此”放在了分句末尾、逗号之前，位置不对。正确：“因此”应紧跟在逗号之后，引出结果分句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85913, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很认真，因此但是成绩很好。", "corrected_sentence": "他很认真，因此成绩很好。", "error_description": "错误：“因此”与“但是”连用，前者表因果，后者表转折，二者意思相反。正确：只用“因此”，去掉“但是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
