INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85914, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示因果关系，引出结果，相当于“所以”。", "primary_collocate": null, "pronunciation": "yīn cǐ", "ipa": "in˥ tsʰɿ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这里的风景很美，因此来玩的人很多。", "target_word": "因此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢吃肉，因此只点了青菜。", "target_word": "因此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲得很清楚，因此大家都听懂了。", "target_word": "因此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没带钱，因此不能买这本书。", "target_word": "因此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市很安静，因此我愿意住在这里。", "target_word": "因此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学习很认真，因此老师常常表扬他。", "target_word": "因此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天停电了，因此我们没有看电视。", "target_word": "因此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市今天打折，因此人特别多。", "target_word": "因此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟太小，因此不能一个人出门。", "target_word": "因此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会说三种话，因此找工作很容易。", "target_word": "因此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "连词：表示因果关系，引出结果，相当于“所以”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1d1a1f-4209-4221-be5e-541950d52f9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85914, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "因此", "is_correct": true, "explanation": "表示因果：风景美是原因，来玩的人多是结果。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与后文“但/却”呼应，这里没有配套分句，不成立。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示不然的后果，与“风景美→人多”的因果关系不符。"}, {"text": "何况", "is_correct": false, "explanation": "语义：“何况”表示更进一层，“风景美”与“人多”之间没有递进关系。"}], "explanations": {"因此": "表示因果：风景美是原因，来玩的人多是结果。", "虽然": "搭配：“虽然”要与后文“但/却”呼应，这里没有配套分句，不成立。", "否则": "语义：“否则”表示不然的后果，与“风景美→人多”的因果关系不符。", "何况": "语义：“何况”表示更进一层，“风景美”与“人多”之间没有递进关系。"}, "sentence_index": 0, "correct_answer": "因此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你可以坐火车，因此也可以坐飞机。", "explanation": "这里应该用〈或者〉。因此表示因果，不能表示选择；两种交通方式任选时要用“或者”。"}, {"text": "这家店的菜很好，因此很便宜。", "explanation": "这里应该用〈而且〉。“很便宜”不是“菜很好”的结果，表示递进应用“而且”。"}, {"text": "他吃完饭，因此去上班。", "explanation": "这里应该用〈然后〉。因此表示因果，“去上班”不是“吃完饭”的结果，表示先后应用“然后”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85914, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "因此", "is_correct": true, "explanation": "表示因果：停电是原因，没有看电视是结果。"}, {"text": "而是", "is_correct": false, "explanation": "搭配：“而是”需与前面的“不是”呼应，这里没有否定词，不成立。"}, {"text": "尽管", "is_correct": false, "explanation": "搭配：“尽管”要与后文“但/却/还是”呼应，这里没有配套分句，不成立。"}, {"text": "甚至", "is_correct": false, "explanation": "语义：“甚至”表示递进或突出，不表示因果，停电与不看电视不构成结果。"}], "explanations": {"因此": "表示因果：停电是原因，没有看电视是结果。", "而是": "搭配：“而是”需与前面的“不是”呼应，这里没有否定词，不成立。", "尽管": "搭配：“尽管”要与后文“但/却/还是”呼应，这里没有配套分句，不成立。", "甚至": "语义：“甚至”表示递进或突出，不表示因果，停电与不看电视不构成结果。"}, "sentence_index": 6, "correct_answer": "因此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很聪明，因此不太努力。", "explanation": "这里应该用〈但是〉。因此表示因果，“不太努力”与“很聪明”是转折关系，不能用因果词连接。"}, {"text": "他看起来很累，因此他很开心。", "explanation": "这里应该用〈其实〉。因此表示因果，“很开心”与“看起来很累”是转折关系，不能用因果连接。"}, {"text": "因此明天天气好，我们就去爬山。", "explanation": "这里应该用〈如果〉。因此表示因果，引出结果，不能用来提出条件；假设条件要用“如果”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没有带钱因此，不能买东西。", "corrected_sentence": "他没有带钱，因此不能买东西。", "error_description": "错误：“因此”紧接在“没有带钱”之后、逗号之前，位置不对。正确：“因此”应放在逗号之后，引出结果分句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天没睡好，因此但是今天很累。", "corrected_sentence": "我昨天没睡好，因此今天很累。", "error_description": "错误：“因此”与“但是”连用，前者表因果，后者表转折，二者意思相反。正确：只用“因此”，去掉“但是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b720888a-1880-4bb1-8857-25817945de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
