INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85916, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "给予；使对方得到（多带抽象宾语）。", "primary_collocate": null, "pronunciation": "gěi yǐ", "ipa": "kei²¹⁴ i²¹⁴", "syllable_count": 2, "sentences": [{"text": "老师对我们给以很大的帮助。", "target_word": "给以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会应该对老人给以更多关心。", "target_word": "给以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家对他的工作给以高度评价。", "target_word": "给以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生对病人给以细心照顾。", "target_word": "给以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友对我的决定给以支持。", "target_word": "给以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对我的问题给以回答。", "target_word": "给以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母对孩子的进步给以鼓励。", "target_word": "给以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府对受灾的人给以帮助。", "target_word": "给以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家对她的表演给以热烈掌声。", "target_word": "给以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居对这位老人给以照顾。", "target_word": "给以", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "对某人某事给予帮助、关心等抽象事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7cea0ef-f5d6-475e-98b1-4539dcad4711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85916, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "给以", "is_correct": true, "explanation": "正确：给以表示施予者对他人给予抽象的帮助，与“对我们”的搭配一致。"}, {"text": "收到", "is_correct": false, "explanation": "语义：收到表示接受，而句中的“老师”是施予方，与句意相反。"}, {"text": "打", "is_correct": false, "explanation": "搭配：“打”不能与“帮助”搭配作宾语。"}, {"text": "发生", "is_correct": false, "explanation": "配价：发生是不及物动词，不能带“很大的帮助”作宾语。"}], "explanations": {"给以": "正确：给以表示施予者对他人给予抽象的帮助，与“对我们”的搭配一致。", "收到": "语义：收到表示接受，而句中的“老师”是施予方，与句意相反。", "打": "搭配：“打”不能与“帮助”搭配作宾语。", "发生": "配价：发生是不及物动词，不能带“很大的帮助”作宾语。"}, "sentence_index": 0, "correct_answer": "给以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对他给以一本书。", "explanation": "这里应该用〈送〉。给以多接帮助、关心等抽象事物，书是实物，应说送给他。"}, {"text": "法院对这件案子给以了判决。", "explanation": "这里应该用〈作出〉。判决要说作出，给以不能与判决搭配。"}, {"text": "领导对员工给以了命令。", "explanation": "这里应该用〈下达〉。命令要说下达，给以不能用来表示发布命令。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85916, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "给以", "is_correct": true, "explanation": "正确：父母施予鼓励，给以与“对孩子的进步”的搭配一致。"}, {"text": "感到", "is_correct": false, "explanation": "语义：感到表示主体自身的感受，句中父母是施予鼓励的一方。"}, {"text": "接受", "is_correct": false, "explanation": "语义：接受表示被动承受，与句中父母施予鼓励的语义相反。"}, {"text": "嘱咐", "is_correct": false, "explanation": "搭配：嘱咐的对象是话语，不能以“鼓励”作宾语。"}], "explanations": {"给以": "正确：父母施予鼓励，给以与“对孩子的进步”的搭配一致。", "感到": "语义：感到表示主体自身的感受，句中父母是施予鼓励的一方。", "接受": "语义：接受表示被动承受，与句中父母施予鼓励的语义相反。", "嘱咐": "搭配：嘱咐的对象是话语，不能以“鼓励”作宾语。"}, "sentence_index": 6, "correct_answer": "给以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对我给以了一个吻。", "explanation": "这里应该用〈亲〉。亲吻是身体动作，不用“给以”表示，“给以”多用于抽象的帮助、关心等。"}, {"text": "学校对学生给以了一次活动。", "explanation": "这里应该用〈开展〉。活动要说开展，给以不能与活动搭配。"}, {"text": "学校对学生给以了一套校服。", "explanation": "这里应该用〈发〉。校服是具体实物，应说“给学生发校服”；给以多接帮助、关心等抽象事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府给灾民给以很大的帮助。", "corrected_sentence": "政府对灾民给以很大的帮助。", "error_description": "错误：引进受事“灾民”的介词应为“对”，不能用动词“给”；句中“给”与“给以”连用，句子不通。正确说法是“政府对灾民给以很大的帮助。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朋友对我给以着很大的支持。", "corrected_sentence": "朋友对我给以很大的支持。", "error_description": "错误：“给以”是书面动词，后面不能加“着”表示持续，通常也不带体标，直接接抽象宾语。正确说法是“朋友对我给以很大的支持。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
