INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85918, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示让步，常与“但是”“可是”配合使用。", "primary_collocate": null, "pronunciation": "suī rán", "ipa": "sweɪ˥ ɻan˧˥", "syllable_count": 2, "sentences": [{"text": "虽然他很有钱，但是一点也不骄傲。", "target_word": "虽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然妈妈不在家，但是饭已经做好了。", "target_word": "虽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然汉字很难，可是我很喜欢写。", "target_word": "虽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她虽然很害怕，但是还是走进去了。", "target_word": "虽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然时间不多，但是我们能做完。", "target_word": "虽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然我不饿，但是想吃一点。", "target_word": "虽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然这件衣服贵，但是质量很好。", "target_word": "虽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然他没来，可是给我打了电话。", "target_word": "虽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然今天是周末，但是爸爸还要工作。", "target_word": "虽然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然我们很少见面，但是常常联系。", "target_word": "虽然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示让步，常与“但是”“可是”配合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1dfd233-60e1-4be7-a6ef-22ae12c1f292') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85918, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，与“但是……一点也不……”的转折不符。"}, {"text": "只要", "is_correct": false, "explanation": "搭配：“只要”要接“就”表示充分条件，不能接“但是”。"}, {"text": "而且", "is_correct": false, "explanation": "语义：“而且”表示递进或并列，不表示让步，与“但是”的转折冲突。"}, {"text": "虽然", "is_correct": true, "explanation": "让步：有钱是事实，但不骄傲，符合“虽然……但是……”。"}], "explanations": {"因为": "语义：“因为”表示原因，与“但是……一点也不……”的转折不符。", "只要": "搭配：“只要”要接“就”表示充分条件，不能接“但是”。", "而且": "语义：“而且”表示递进或并列，不表示让步，与“但是”的转折冲突。", "虽然": "让步：有钱是事实，但不骄傲，符合“虽然……但是……”。"}, "sentence_index": 0, "correct_answer": "虽然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "虽然他生病了，所以没来上课。", "explanation": "这里应该用〈因为〉。〈虽然〉表示让步，不能引出“所以”的结果；说明原因要用“因为……所以……”。"}, {"text": "虽然你肯努力，就一定会进步。", "explanation": "这里应该用〈只要〉。“只要……就……”表示充分条件；〈虽然〉只表示让步，不能推出必然的结果。"}, {"text": "虽然那家店很近，于是我们就去了。", "explanation": "这里应该用〈既然〉。〈虽然〉表示让步，前后要有转折；这句是以“那家店很近”为前提，推出行动，应用〈既然〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，“衣服贵”不能导致“质量很好”。"}, {"text": "如果", "is_correct": false, "explanation": "搭配：“如果”要和“就”配合表示假设，这里陈述的是已有的事实。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，与“但是”的转折冲突。"}, {"text": "虽然", "is_correct": true, "explanation": "让步：衣服贵是事实，但质量好，符合“虽然……但是……”。"}], "explanations": {"所以": "语义：“所以”表示结果，“衣服贵”不能导致“质量很好”。", "如果": "搭配：“如果”要和“就”配合表示假设，这里陈述的是已有的事实。", "因为": "语义：“因为”表示原因，与“但是”的转折冲突。", "虽然": "让步：衣服贵是事实，但质量好，符合“虽然……但是……”。"}, "sentence_index": 6, "correct_answer": "虽然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书不是小说，虽然是散文。", "explanation": "这里应该用〈而是〉。〈虽然〉表示让步，前后要构成转折；这里是更正“不是……”的说法，应用〈而是〉。"}, {"text": "虽然你去哪儿，我都陪着你。", "explanation": "这里应该用〈无论〉。〈虽然〉针对已发生的事实；“去哪儿”是任意条件，要用“无论”。"}, {"text": "虽然这本书很便宜，而且很有趣。", "explanation": "这里应该用〈不但〉。〈虽然〉要求前后意思转折；“很便宜”和“很有趣”都是优点，是递进关系，应说“不但……而且……”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "虽然他个子不高，因为篮球打得很好。", "corrected_sentence": "虽然他个子不高，但是篮球打得很好。", "error_description": "〈虽然〉后面应接〈但是〉表示转折；〈因为〉说原因，与让步关系冲突，应改为〈但是〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "虽然他年纪大，所以身体很好。", "corrected_sentence": "虽然他年纪大，但是身体很好。", "error_description": "〈虽然〉后面应接〈但是〉表示转折；〈所以〉表示结果，与让步关系冲突，应改为〈但是〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
