INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85920, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "互联网上；通过互联网。", "primary_collocate": null, "pronunciation": "wǎng shàng", "ipa": "waŋ˨˩˦ ʂaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我常常在网上买衣服。", "target_word": "网上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以在网上报名参加比赛。", "target_word": "网上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把照片放到了网上。", "target_word": "网上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天的课改成网上上课了。", "target_word": "网上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天在网上订了一张火车票。", "target_word": "网上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不会在网上付钱，我来帮她。", "target_word": "网上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多人喜欢在网上看电影。", "target_word": "网上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题你在网上查一下就知道了。", "target_word": "网上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们在网上交作业。", "target_word": "网上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上认识了一个新朋友。", "target_word": "网上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "網上", "label": "繁体"}], "register": "口语", "sense_fingerprint": "通过互联网做某事（网上购物、网上报名）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87aa3fbb-5473-40d6-85f3-a36aa4409ac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85920, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "网上", "is_correct": true, "explanation": "网上：指通过互联网，与“买衣服”的场所相符。"}, {"text": "树上", "is_correct": false, "explanation": "语义：树上不是买衣服的地方，句意不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是购买衣服的场所，与“买衣服”不相符。"}, {"text": "地里", "is_correct": false, "explanation": "搭配：“买衣服”的场所应是商店或网络，“地里”不能作买衣服的地点。"}], "explanations": {"网上": "网上：指通过互联网，与“买衣服”的场所相符。", "树上": "语义：树上不是买衣服的地方，句意不通。", "厨房": "语义：厨房不是购买衣服的场所，与“买衣服”不相符。", "地里": "搭配：“买衣服”的场所应是商店或网络，“地里”不能作买衣服的地点。"}, "sentence_index": 0, "correct_answer": "网上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我常常在网上洗澡。", "explanation": "这里应该用〈浴室里〉。“网上”指互联网上，洗澡应在浴室里进行。"}, {"text": "我们中午在网上吃午饭吧。", "explanation": "这里应该用〈食堂里〉。“网上”指互联网上，吃饭要在食堂里等实际地点。"}, {"text": "杯子放在网上。", "explanation": "这里应该用〈桌子上〉。“网上”指互联网上，放在物体表面的位置应用〈桌子上〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85920, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网上", "is_correct": true, "explanation": "网上：指通过互联网，与“看电影”的方式相符。"}, {"text": "水底", "is_correct": false, "explanation": "语义：水底不能看电影，与句意不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱里不能看电影，句意不通。"}, {"text": "墓地", "is_correct": false, "explanation": "搭配：“看电影”的场所应是影院或家中，墓地不适合作看电影的地点。"}], "explanations": {"网上": "网上：指通过互联网，与“看电影”的方式相符。", "水底": "语义：水底不能看电影，与句意不符。", "冰箱": "语义：冰箱里不能看电影，句意不通。", "墓地": "搭配：“看电影”的场所应是影院或家中，墓地不适合作看电影的地点。"}, "sentence_index": 6, "correct_answer": "网上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在网上刷牙。", "explanation": "这里应该用〈洗手间里〉。“网上”指互联网上，刷牙应在洗手间里进行。"}, {"text": "他在网上等公共汽车。", "explanation": "这里应该用〈车站〉。“网上”指互联网上，等车要在车站。"}, {"text": "小船在网上慢慢漂。", "explanation": "这里应该用〈水面上〉。“网上”指互联网上，船漂在水面上应用〈水面上〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85920, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他习惯在网上很订餐。", "corrected_sentence": "他习惯在网上订餐。", "error_description": "错误：「网上很订餐」，「很」不能直接修饰动作动词「订餐」，应删去。正确：「在网上订餐」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85920, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份资料你可以对网上找到。", "corrected_sentence": "这份资料你可以在网上找到。", "error_description": "介词误用：表示动作发生的地点要用「在」，不用「对」。应说「在网上找到」，不说「对网上找到」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
