INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85921, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“今天”是我们现在过的这一天。", "primary_collocate": null, "pronunciation": "jīn tiān", "ipa": "tɕin˥ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "今天比昨天冷。", "target_word": "今天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下午有一个会。", "target_word": "今天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说今天给我做鱼。", "target_word": "今天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我们去公园玩。", "target_word": "今天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天买了一本新书。", "target_word": "今天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你今天忙不忙？", "target_word": "今天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的雨下得很大。", "target_word": "今天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天早上我六点就起床了。", "target_word": "今天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天没带手机。", "target_word": "今天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天是几月几号？", "target_word": "今天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "今日", "label": "书面语形式"}, {"form": "今儿", "label": "口语形式"}], "register": "中性", "sense_fingerprint": "今天：我们现在正在过的这一天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09d30940-30c9-4220-8182-85dc93122623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85921, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "今天", "is_correct": true, "explanation": "正确：“今天比昨天冷”比较的是两个日子的气温。"}, {"text": "因为", "is_correct": false, "explanation": "语法：“因为”是连词，不能作“比”字句的比较主体。"}, {"text": "漂亮", "is_correct": false, "explanation": "语法：“漂亮”是形容词，不能作主语与“昨天”比较冷暖。"}, {"text": "喜欢", "is_correct": false, "explanation": "语法：“喜欢”是动词，不能作主语与“昨天”比较。"}], "explanations": {"今天": "正确：“今天比昨天冷”比较的是两个日子的气温。", "因为": "语法：“因为”是连词，不能作“比”字句的比较主体。", "漂亮": "语法：“漂亮”是形容词，不能作主语与“昨天”比较冷暖。", "喜欢": "语法：“喜欢”是动词，不能作主语与“昨天”比较。"}, "sentence_index": 0, "correct_answer": "今天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学校今天都举办一次运动会。", "explanation": "这里应该用〈每年〉。“今天”只指我们正在过的这一天，不能表示反复出现的周期；每年都发生的事要用〈每年〉。"}, {"text": "我在北京住了今天了。", "explanation": "这里应该用〈三年〉之类的时长。“今天”只指正在过的这一天，是一个时间点，不能作“住了”后面的时长。"}, {"text": "我们班里每个今天都很忙。", "explanation": "“今天”只指我们正在过的这一天，是唯一的，不能用“每个”计数；说每一天要用“每天”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85921, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "今天", "is_correct": true, "explanation": "正确：“今天的雨”指说话时这一天的雨。"}, {"text": "书包", "is_correct": false, "explanation": "语义：雨不会下在书包上，书包不能作降雨的范围。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：饭店是场所，不指一天，不能作“雨”的时间定语。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“冰箱”与“下雨”不搭配，雨不会下在冰箱里。"}], "explanations": {"今天": "正确：“今天的雨”指说话时这一天的雨。", "书包": "语义：雨不会下在书包上，书包不能作降雨的范围。", "饭店": "语义：饭店是场所，不指一天，不能作“雨”的时间定语。", "冰箱": "搭配：“冰箱”与“下雨”不搭配，雨不会下在冰箱里。"}, "sentence_index": 6, "correct_answer": "今天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那天下午他突然生病，今天就去了医院。", "explanation": "这里应该用〈当天〉。“今天”指说话时的这一天；叙述过去的事件时，指事件当天要用“当天”。"}, {"text": "她今天在北京工作，后来才回老家。", "explanation": "这里应该用〈当年〉。“今天”指说话的这一天，与“后来才回老家”的过去时间冲突；讲过去的经历要用“当年”。"}, {"text": "我爷爷今天还是个小孩子，现在已经八十岁了。", "explanation": "这里应该用〈当年〉。“今天”指说话的这一天，不能指很多年前；讲过去的经历要用“当年”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85921, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今天的去超市买菜。", "corrected_sentence": "我今天去超市买菜。", "error_description": "错误形式：“我今天的去超市买菜”；正确形式：“我今天去超市买菜”。时间名词“今天”作状语时，后面不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85921, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我今天了写完作业。", "corrected_sentence": "我今天写完作业。", "error_description": "错误形式：“我今天了写完作业”；正确形式：“我今天写完作业”。“了”不能紧跟在时间词“今天”后面，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
