INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85923, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "“岁”用来说一个人有多大，比如五岁。", "primary_collocate": null, "pronunciation": "suì", "ipa": "swei˥˩", "syllable_count": 1, "sentences": [{"text": "他看起来很年轻，其实已经三十岁了。", "target_word": "岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥比我大五岁。", "target_word": "岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷今年七十岁，还爱喝茶。", "target_word": "岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了今天，我就二十岁了。", "target_word": "岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小女孩才四岁，说话很清楚。", "target_word": "岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她二十五岁时结了婚。", "target_word": "岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子满六岁就可以上小学。", "target_word": "岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人快一百岁了。", "target_word": "岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你几岁开始学游泳的？", "target_word": "岁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我十岁的时候，家里养了一只猫。", "target_word": "岁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "岁数", "label": "复合"}, {"form": "歲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "岁：说一个人有多大的量词，如五岁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee9cc0a1-56c1-4470-a8fc-b7afcfb653ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85923, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "岁", "is_correct": true, "explanation": "岁：说人有多大的量词，读 suì（第四声），是正确答案。"}, {"text": "随", "is_correct": false, "explanation": "suí（第二声）与 suì（第四声）声调不同，意思是跟随。"}, {"text": "睡", "is_correct": false, "explanation": "shuì 与 suì 声母不同（sh 与 s），意思是睡觉。"}, {"text": "最", "is_correct": false, "explanation": "zuì 与 suì 声母不同（z 与 s），意思是最。"}, {"text": "脆", "is_correct": false, "explanation": "cuì 与 suì 声母不同（c 与 s），意思是脆。"}], "explanations": {"岁": "岁：说人有多大的量词，读 suì（第四声），是正确答案。", "随": "suí（第二声）与 suì（第四声）声调不同，意思是跟随。", "睡": "shuì 与 suì 声母不同（sh 与 s），意思是睡觉。", "最": "zuì 与 suì 声母不同（z 与 s），意思是最。", "脆": "cuì 与 suì 声母不同（c 与 s），意思是脆。"}, "sentence_index": null, "correct_answer": "岁"}, "level_3": {"options": [{"text": "岁", "is_correct": true, "explanation": "岁：说人有多大的量词，与“三十”组合，填入空格正确。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”多用于动物或成对之物，不能用来计算人的年龄。"}, {"text": "次", "is_correct": false, "explanation": "语义：“次”计算次数，不能说明一个人活了多少年。"}, {"text": "位", "is_correct": false, "explanation": "语域：“位”带有敬称色彩，用来说“他”的年龄语气不合适。"}], "explanations": {"岁": "岁：说人有多大的量词，与“三十”组合，填入空格正确。", "只": "搭配：“只”多用于动物或成对之物，不能用来计算人的年龄。", "次": "语义：“次”计算次数，不能说明一个人活了多少年。", "位": "语域：“位”带有敬称色彩，用来说“他”的年龄语气不合适。"}, "sentence_index": 0, "correct_answer": "岁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们结婚已经三岁了。", "explanation": "这里应该用〈年〉。岁只说人或动物的年龄，说结婚了多长时间要用〈年〉。"}, {"text": "我在北京住了三岁。", "explanation": "这里应该用〈年〉。岁只说人或动物的年龄，说住了多长时间要用〈年〉。"}, {"text": "他借了两岁书。", "explanation": "这里应该用〈本〉。岁只用于计算人或动物的年龄，计算书要用量词〈本〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0dc6dfe-fc46-4ee2-b5fa-292425c0baf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85923, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "岁", "is_correct": true, "explanation": "岁：说人有多大的量词，读 suì（第四声），是正确答案。"}, {"text": "贵", "is_correct": false, "explanation": "guì 与 suì 声母不同（g 与 s），意思是贵。"}, {"text": "会", "is_correct": false, "explanation": "huì 与 suì 声母不同（h 与 s），意思是会议、会。"}, {"text": "对", "is_correct": false, "explanation": "duì 与 suì 声母不同（d 与 s），意思是对。"}, {"text": "退", "is_correct": false, "explanation": "tuì 与 suì 声母不同（t 与 s），意思是后退。"}], "explanations": {"岁": "岁：说人有多大的量词，读 suì（第四声），是正确答案。", "贵": "guì 与 suì 声母不同（g 与 s），意思是贵。", "会": "huì 与 suì 声母不同（h 与 s），意思是会议、会。", "对": "duì 与 suì 声母不同（d 与 s），意思是对。", "退": "tuì 与 suì 声母不同（t 与 s），意思是后退。"}, "sentence_index": null, "correct_answer": "岁"}, "level_3": {"options": [{"text": "岁", "is_correct": true, "explanation": "岁：说人有多大的量词，与“六”组合说明孩子的年龄，填入空格正确。"}, {"text": "个", "is_correct": false, "explanation": "搭配：“个”不能用来计算年龄，说“满六个”不通。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”用于有柄的器物，不能用来计算年龄。"}, {"text": "回", "is_correct": false, "explanation": "语义：“回”计算次数，“满六回”说的不是年龄。"}], "explanations": {"岁": "岁：说人有多大的量词，与“六”组合说明孩子的年龄，填入空格正确。", "个": "搭配：“个”不能用来计算年龄，说“满六个”不通。", "把": "搭配：“把”用于有柄的器物，不能用来计算年龄。", "回": "语义：“回”计算次数，“满六回”说的不是年龄。"}, "sentence_index": 6, "correct_answer": "岁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在学校待了三岁。", "explanation": "这里应该用〈年〉。岁只说人或动物的年龄，说待了多长时间要用〈年〉。"}, {"text": "这次出差只有一岁。", "explanation": "这里应该用〈天〉或〈个月〉这样表示时间长短的词。岁只说年龄，不能说出差时间的长短。"}, {"text": "他们练习了两岁钢琴。", "explanation": "这里应该用〈年〉。岁只说年龄，说练习了多长时间要用〈年〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0dc6dfe-fc46-4ee2-b5fa-292425c0baf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid 