INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85923, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐今年二十个岁了。", "corrected_sentence": "我姐姐今年二十岁了。", "error_description": "错误在“岁”前多加了量词“个”。“岁”本身就是计算年龄的量词，数词后直接接“岁”，应说“二十岁”，不能说“二十个岁”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0dc6dfe-fc46-4ee2-b5fa-292425c0baf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85923, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他今年岁十了。", "corrected_sentence": "他今年十岁了。", "error_description": "错误在数词与“岁”的语序。应说“十岁”，数词在前、量词在后，不能说“岁十”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0dc6dfe-fc46-4ee2-b5fa-292425c0baf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
