INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85925, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "考试是老师出题目，看你会不会。", "primary_collocate": null, "pronunciation": "kǎo shì", "ipa": "kʰɑʊ˨˩˦ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这次考试很难，我只做对了一半。", "target_word": "考试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天有一个汉语考试。", "target_word": "考试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的考试几点开始？", "target_word": "考试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试的题目不多，但是很难。", "target_word": "考试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天没睡好，考试的时候很累。", "target_word": "考试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让大家认真准备这次考试。", "target_word": "考试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场考试一共有三个小时。", "target_word": "考试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试结束后，我们一起去吃饭了。", "target_word": "考试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他参加了学校的数学考试。", "target_word": "考试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试的成绩明天告诉大家。", "target_word": "考试", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一次考试", "label": "量词"}, {"form": "一场考试", "label": "量词"}, {"form": "考試", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：老师出题检查学生的一次测验，如“这次考试很难”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef952436-ac10-4596-8374-89ff1cbf54ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85925, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "考试", "is_correct": true, "explanation": "正确：「这次考试很难，我只做对了一半」指一次测验，做对题目的说法通顺。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭不能“做对了一半”，这句话说不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”一般不说“很难”，而且与“做对了一半”无关。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜没有“做对”的问题，句子的意思不成立。"}], "explanations": {"考试": "正确：「这次考试很难，我只做对了一半」指一次测验，做对题目的说法通顺。", "午饭": "语义：午饭不能“做对了一半”，这句话说不通。", "天气": "搭配：“天气”一般不说“很难”，而且与“做对了一半”无关。", "饭菜": "语义：饭菜没有“做对”的问题，句子的意思不成立。"}, "sentence_index": 0, "correct_answer": "考试"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我下周要做体温考试。", "explanation": "这里应该用〈测量〉。考试是考查知识或技能的测验，体温要说测量。"}, {"text": "这家公司正在进行项目考试。", "explanation": "这里应该用〈评估〉。考试针对人的知识或技能，对项目的好坏要说评估。"}, {"text": "这次人口考试很重要。", "explanation": "这里应该用〈普查〉。考试是考查知识的测验，人口统计要说普查。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85925, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考试", "is_correct": true, "explanation": "正确：「这场考试一共有三个小时」指一次持续三小时的测验，句子通顺。"}, {"text": "闪电", "is_correct": false, "explanation": "语义：闪电持续的时间很短，不可能“一共有三个小时”。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：量词“场”通常不与“手机”搭配，句子也说不通。"}, {"text": "爆竹", "is_correct": false, "explanation": "语义：爆竹的响声很短，不能持续“三个小时”。"}], "explanations": {"考试": "正确：「这场考试一共有三个小时」指一次持续三小时的测验，句子通顺。", "闪电": "语义：闪电持续的时间很短，不可能“一共有三个小时”。", "手机": "搭配：量词“场”通常不与“手机”搭配，句子也说不通。", "爆竹": "语义：爆竹的响声很短，不能持续“三个小时”。"}, "sentence_index": 6, "correct_answer": "考试"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我参加了一场生日考试。", "explanation": "这里应该用〈聚会〉。考试是考查知识或技能的测验，生日的欢聚要说聚会。"}, {"text": "我参加了一场马拉松考试。", "explanation": "这里应该用〈比赛〉。考试是考查知识或技能的测验，长跑的竞技要说比赛。"}, {"text": "我参加了一场晚会考试。", "explanation": "这里应该用〈演出〉。考试是考查知识或技能的测验，舞台上的表演要说演出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85925, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下周有一场考试过。", "corrected_sentence": "我下周有一场考试。", "error_description": "错误：“下周”指将来，“考试”这件事还没有发生，动态助词“过”只表示已经完成的动作，不能加在“考试”后面。应说“我下周有一场考试。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85925, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们下午有一把考试。", "corrected_sentence": "我们下午有一场考试。", "error_description": "错误：“考试”的量词应用“场”，“把”用于有柄的东西，不能用来数考试。应说“一场考试”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
