INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85926, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用问答或做题的方式检查知识或技能。", "primary_collocate": null, "pronunciation": "kǎo shì", "ipa": "kʰɑʊ˨˩˦ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "明天我们要考试，今晚得早点睡。", "target_word": "考试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨天考试了，今天很高兴。", "target_word": "考试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们正在教室里考试。", "target_word": "考试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们什么时候考试？", "target_word": "考试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说下周三考试，大家要复习。", "target_word": "考试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试的时候不能看手机。", "target_word": "考试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在考试，请你安静一点儿。", "target_word": "考试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她考试前一直在看书。", "target_word": "考试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们考试时有点儿紧张。", "target_word": "考试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们上午考试，下午就放假了。", "target_word": "考试", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "考试了", "label": "体标"}, {"form": "考试过", "label": "体标"}, {"form": "考試", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：用问答或做题检查知识技能，如“明天考试”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef952436-ac10-4596-8374-89ff1cbf54ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85926, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "考试", "is_correct": true, "explanation": "正确：「明天我们要考试，今晚得早点睡」中“考试”指用题目检查知识，句子通顺。"}, {"text": "下雨", "is_correct": false, "explanation": "搭配：“下雨”的主语只能是天气，“我们要下雨”说不通。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”与“今晚得早点睡”的逻辑对不上，前后不连贯。"}, {"text": "就寝", "is_correct": false, "explanation": "语义：“就寝”就是睡觉，“明天要就寝”和“今晚得早点睡”前后说不通，而且“就寝”是书面说法。"}], "explanations": {"考试": "正确：「明天我们要考试，今晚得早点睡」中“考试”指用题目检查知识，句子通顺。", "下雨": "搭配：“下雨”的主语只能是天气，“我们要下雨”说不通。", "迟到": "语义：“迟到”与“今晚得早点睡”的逻辑对不上，前后不连贯。", "就寝": "语义：“就寝”就是睡觉，“明天要就寝”和“今晚得早点睡”前后说不通，而且“就寝”是书面说法。"}, "sentence_index": 0, "correct_answer": "考试"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "质检员每天考试出厂的产品。", "explanation": "这里应该用〈检验〉。考试是用题目考查人的知识或技能，检查产品质量要用检验。"}, {"text": "工程师在实验室考试这款手机的电池。", "explanation": "这里应该用〈测试〉。考试只用于考查人的知识或技能，检测产品性能要用测试。"}, {"text": "医生正在考试病人的血压。", "explanation": "这里应该用〈测量〉。考试针对知识和技能，血压是身体指标，要说测量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85926, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考试", "is_correct": true, "explanation": "正确：「他们正在考试，请你安静一点儿」表示考试进行中，要求安静，语境相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳并不需要安静，“请你安静一点儿”的语境说不通。"}, {"text": "打篮球", "is_correct": false, "explanation": "搭配：“打篮球”一般不与“请你安静一点儿”搭配，打球时不会这样要求别人。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：洗澡时别人不需要保持安静，这句话的语境不成立。"}], "explanations": {"考试": "正确：「他们正在考试，请你安静一点儿」表示考试进行中，要求安静，语境相符。", "游泳": "语义：游泳并不需要安静，“请你安静一点儿”的语境说不通。", "打篮球": "搭配：“打篮球”一般不与“请你安静一点儿”搭配，打球时不会这样要求别人。", "洗澡": "语义：洗澡时别人不需要保持安静，这句话的语境不成立。"}, "sentence_index": 6, "correct_answer": "考试"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "实验室正在考试这批样品。", "explanation": "这里应该用〈化验〉。考试是考查人的知识或技能，检验样品要说化验。"}, {"text": "警察正在考试这起案件。", "explanation": "这里应该用〈调查〉。考试指测验知识或技能，查办案件要说调查。"}, {"text": "会计正在考试这份报告。", "explanation": "这里应该用〈审核〉。考试用于考查人的知识，审查文件内容要说审核。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85926, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天考试过。", "corrected_sentence": "我们明天考试。", "error_description": "错误：“明天”指将来，考试还没有发生，表示经历的“过”不能用在将来的事情上。应说“我们明天考试。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85926, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他考试得很好。", "corrected_sentence": "他考试考得很好。", "error_description": "错误：补语“得很好”要接在动词“考”之后，应说“考得很好”或“考试考得很好”，不能说“考试得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
