INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85927, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "而已放在句子最后，意思是只是这样，没有别的。", "primary_collocate": null, "pronunciation": "ér yǐ", "ipa": "ɚ˧˥ i˨˩˦", "syllable_count": 2, "sentences": [{"text": "我只是随便问问而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点小事，不值得生气，不过是个误会而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是生气，只是有点累而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是我的一点小想法而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别紧张，我们只是聊聊天而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说的不过是几句玩笑话而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别怪他，他只是个孩子而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别担心，这次只是练习而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我进去只是看了一眼而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成功不过是运气好而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "而已：句末助词，表示只是这样，没有别的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f239b726-4c9e-4af2-9b42-8368eb77c8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85927, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "而已", "is_correct": true, "explanation": "“而已”表示“只是这样，没有别的”，与“随便问问”的轻描淡写语气相合。"}, {"text": "吗", "is_correct": false, "explanation": "语义：“吗”表示疑问，前句是“我只是随便问问”的陈述，改成疑问后语义矛盾。"}, {"text": "呢", "is_correct": false, "explanation": "语义：“呢”表示追问或状态持续，“随便问问呢”不能表达“仅此而已”的意思。"}, {"text": "着", "is_correct": false, "explanation": "语法：“着”表示持续，不能放在“问问”这种重叠动词后面结束句子。"}], "explanations": {"而已": "“而已”表示“只是这样，没有别的”，与“随便问问”的轻描淡写语气相合。", "吗": "语义：“吗”表示疑问，前句是“我只是随便问问”的陈述，改成疑问后语义矛盾。", "呢": "语义：“呢”表示追问或状态持续，“随便问问呢”不能表达“仅此而已”的意思。", "着": "语法：“着”表示持续，不能放在“问问”这种重叠动词后面结束句子。"}, "sentence_index": 0, "correct_answer": "而已"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试是我一生中最重要的一次而已。", "explanation": "“而已”把事情往小里说，和“最重要”的强调矛盾。应删去“而已”。"}, {"text": "这个奖项是全国最高的荣誉而已。", "explanation": "“全国最高的荣誉”是强调，“而已”却表示没什么，前后矛盾。应删去“而已”。"}, {"text": "这位科学家的发现改变了人类的历史而已。", "explanation": "“改变人类的历史”是很大的事，不能用“而已”往小里说。应删去“而已”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85927, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "而已", "is_correct": true, "explanation": "“而已”表示“不过如此”，与“只是个孩子”呼应，表达轻描淡写的语气。"}, {"text": "哇", "is_correct": false, "explanation": "语义：“哇”表示惊叹，与“你别怪他”的劝解语气不合，句意说不通。"}, {"text": "过", "is_correct": false, "explanation": "语法：“过”是动词后的体标记，不能放在名词“孩子”后面结束句子。"}, {"text": "哦", "is_correct": false, "explanation": "语义：“哦”表示醒悟或应答，不能表达“仅此而已”的意思。"}], "explanations": {"而已": "“而已”表示“不过如此”，与“只是个孩子”呼应，表达轻描淡写的语气。", "哇": "语义：“哇”表示惊叹，与“你别怪他”的劝解语气不合，句意说不通。", "过": "语法：“过”是动词后的体标记，不能放在名词“孩子”后面结束句子。", "哦": "语义：“哦”表示醒悟或应答，不能表达“仅此而已”的意思。"}, "sentence_index": 6, "correct_answer": "而已"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是一次伟大的突破而已。", "explanation": "“伟大的突破”是强调，“而已”却表示没什么，前后矛盾。应删去“而已”。"}, {"text": "他是世界上最有名的科学家而已。", "explanation": "“世界上最有名”是强调，不能用“而已”往小里说。应删去“而已”。"}, {"text": "这是全国最大、最重要的城市而已。", "explanation": "“最大、最重要”是强调，与“而已”的轻描淡写矛盾。应删去“而已”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85927, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我只是问一下而已了。", "corrected_sentence": "我只是问一下而已。", "error_description": "“而已”是句末助词，后面不能再加“了”。“我只是问一下而已了”是错误的，应为“我只是问一下而已”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85927, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张照片不过个纪念品而已。", "corrected_sentence": "这张照片不过是个纪念品而已。", "error_description": "“不过是……而已”格式中漏掉了“是”。“不过个纪念品”不成句，应为“不过是个纪念品而已”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
