INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85928, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "助词，用于句末，表示仅此而已，有往小里说的语气。", "primary_collocate": null, "pronunciation": "ér yǐ", "ipa": "ɚ˧˥ i˨˩˦", "syllable_count": 2, "sentences": [{"text": "你别当真，他只是说说而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这不算什么，小事而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我就是想看看而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们只是同事而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不过是个新手而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没有恶意，只是想帮你而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服不贵，几十块钱而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我就喝了一小口而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不必道歉，只是迟到五分钟而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他什么也没说，只是笑了笑而已。", "target_word": "而已", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "而已：句末助词，把事情往小里说，语气轻描淡写", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f239b726-4c9e-4af2-9b42-8368eb77c8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85928, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "而已", "is_correct": true, "explanation": "“而已”表示“仅此而已”，与“别当真”的淡化语气相合。"}, {"text": "吗", "is_correct": false, "explanation": "语义：“吗”表示疑问，前句是“你别当真”的劝告，改成疑问后语义不通。"}, {"text": "着", "is_correct": false, "explanation": "语法：“着”表示持续，不能放在“说说”这种重叠动词后面结束句子。"}, {"text": "哇", "is_correct": false, "explanation": "语义：“哇”表示感叹，与“别当真”的淡化语气不合。"}], "explanations": {"而已": "“而已”表示“仅此而已”，与“别当真”的淡化语气相合。", "吗": "语义：“吗”表示疑问，前句是“你别当真”的劝告，改成疑问后语义不通。", "着": "语法：“着”表示持续，不能放在“说说”这种重叠动词后面结束句子。", "哇": "语义：“哇”表示感叹，与“别当真”的淡化语气不合。"}, "sentence_index": 0, "correct_answer": "而已"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛是我人生最大的挑战而已。", "explanation": "“人生最大的挑战”是强调，“而已”却往小里说，前后矛盾。应删去“而已”。"}, {"text": "他是我最尊敬的老师而已。", "explanation": "“最尊敬”是强调，不能用“而已”往小里说。应删去“而已”。"}, {"text": "这是我见过的最美的风景而已。", "explanation": "“最美”是强调，与“而已”的轻描淡写矛盾。应删去“而已”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85928, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "而已", "is_correct": true, "explanation": "“而已”表示“仅此而已”，与“不贵”呼应，说明价钱并不多。"}, {"text": "吗", "is_correct": false, "explanation": "语义：“吗”表示疑问，把“几十块钱”这一陈述变成询问，与句意不合。"}, {"text": "哦", "is_correct": false, "explanation": "语义：“哦”表示醒悟或应答，不能表达“仅此而已”的轻描淡写。"}, {"text": "过", "is_correct": false, "explanation": "语法：“过”是动词后的体标记，不能放在“几十块钱”后面结束句子。"}], "explanations": {"而已": "“而已”表示“仅此而已”，与“不贵”呼应，说明价钱并不多。", "吗": "语义：“吗”表示疑问，把“几十块钱”这一陈述变成询问，与句意不合。", "哦": "语义：“哦”表示醒悟或应答，不能表达“仅此而已”的轻描淡写。", "过": "语法：“过”是动词后的体标记，不能放在“几十块钱”后面结束句子。"}, "sentence_index": 6, "correct_answer": "而已"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是全世界最伟大的医生而已。", "explanation": "“全世界最伟大”是强调，“而已”却表示没什么，前后矛盾。应删去“而已”。"}, {"text": "这本书完全改变了我的一生而已。", "explanation": "“完全改变了我的一生”是很大的事，不能用“而已”往小里说。应删去“而已”。"}, {"text": "这是我们公司历史上最大的成功而已。", "explanation": "“历史上最大的成功”是强调，与“而已”矛盾。应删去“而已”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
