INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85929, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“而且”是说一件事以外，还有另一件事。", "primary_collocate": null, "pronunciation": "ér qiě", "ipa": "ɚ˧˥ tɕʰiɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这里很安静，而且很干净。", "target_word": "而且", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很聪明，而且非常努力。", "target_word": "而且", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天很冷，而且还下雨了。", "target_word": "而且", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜很好吃，而且不贵。", "target_word": "而且", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我累了，而且有点饿。", "target_word": "而且", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会说英语，而且说得很好。", "target_word": "而且", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服好看，而且很便宜。", "target_word": "而且", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住得很近，而且每天都来。", "target_word": "而且", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家离学校近，而且离地铁站也近。", "target_word": "而且", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路很长，而且天快黑了。", "target_word": "而且", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "说一件事以外，还有另一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1dfd233-60e1-4be7-a6ef-22ae12c1f292') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85929, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "而且", "is_correct": true, "explanation": "“而且”表示并列，安静和干净两个评价可以并存。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，安静和干净之间没有对立关系。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，“很干净”不能作“很安静”的原因。"}, {"text": "而是", "is_correct": false, "explanation": "搭配：“而是”要与“不是”呼应，句中没有“不是”。"}], "explanations": {"而且": "“而且”表示并列，安静和干净两个评价可以并存。", "但是": "语义：“但是”表示转折，安静和干净之间没有对立关系。", "因为": "语义：“因为”表示原因，“很干净”不能作“很安静”的原因。", "而是": "搭配：“而是”要与“不是”呼应，句中没有“不是”。"}, "sentence_index": 0, "correct_answer": "而且"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你可以今天来，而且明天来，只选一天。", "explanation": "这里应该用〈或者〉。“而且”表示并列，两天都来与“只选一天”矛盾；二选一要用〈或者〉。"}, {"text": "下雨了，而且我们还是去了公园。", "explanation": "这里应该用〈可是〉。前后是转折关系，“而且”只表示补充另一件事，不表示转折。"}, {"text": "虽然这个菜很好吃，而且不贵。", "explanation": "这里应该用〈但是〉。“虽然”后面要用“但是”或“却”，不能用“而且”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85929, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "而且", "is_correct": true, "explanation": "“而且”表示并列，衣服既好看又便宜，两个评价并存。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果，好看并不能导致便宜。"}, {"text": "还是", "is_correct": false, "explanation": "语义：“还是”表示选择，句子是在陈述两个评价，不是二选一。"}, {"text": "以致", "is_correct": false, "explanation": "搭配：“以致”后接的是不好的结果，“很便宜”不能作这种结果。"}], "explanations": {"而且": "“而且”表示并列，衣服既好看又便宜，两个评价并存。", "因此": "语义：“因此”表示因果，好看并不能导致便宜。", "还是": "语义：“还是”表示选择，句子是在陈述两个评价，不是二选一。", "以致": "搭配：“以致”后接的是不好的结果，“很便宜”不能作这种结果。"}, "sentence_index": 6, "correct_answer": "而且"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "路很长，而且我们还是走了。", "explanation": "这里应该用〈可是〉。前后是转折关系，“而且”只表示递进，不能表示转折。"}, {"text": "他很努力，而且成绩很差。", "explanation": "这里应该用〈可是〉。前后是转折关系，“而且”只表示递进，不表示转折。"}, {"text": "他很想去，而且没有时间。", "explanation": "这里应该用〈但是〉。前后是转折关系，“而且”只表示补充另一件事，不能表示转折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85929, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个饭店很大，但是而且很方便。", "corrected_sentence": "这个饭店很大，而且很方便。", "error_description": "“而且”前不能再加“但是”，两者都是连词，重复连接。错误形式：但是而且；正确形式：而且。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85929, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这双鞋好看，而且而且很舒服。", "corrected_sentence": "这双鞋好看，而且很舒服。", "error_description": "“而且”重复使用，只需一个。错误形式：而且而且很舒服；正确形式：而且很舒服。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
