INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85930, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示递进关系，常与“不但”配合使用。", "primary_collocate": null, "pronunciation": "ér qiě", "ipa": "ɚ˧˥ tɕʰiɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "她不但会唱歌，而且会跳舞。", "target_word": "而且", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店不但便宜，而且很干净。", "target_word": "而且", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不但是我的同学，而且是我的好朋友。", "target_word": "而且", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书不但有意思，而且很有用。", "target_word": "而且", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天不但下雨，而且很冷。", "target_word": "而且", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不但会说汉语，而且说得很好。", "target_word": "而且", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间不但大，而且很安静。", "target_word": "而且", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王不但学习好，而且爱帮助别人。", "target_word": "而且", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机不但好看，而且不贵。", "target_word": "而且", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不但教我们汉语，而且教我们做人。", "target_word": "而且", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示递进，常与“不但”配合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1dfd233-60e1-4be7-a6ef-22ae12c1f292') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85930, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "而且", "is_correct": true, "explanation": "“而且”表示递进，与“不但”呼应，说明会唱歌之外还会跳舞。"}, {"text": "但是", "is_correct": false, "explanation": "搭配：“不但”后要用“而且”“也”“还”呼应，不能接“但是”。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示选择，句子说的是两件事都会，不是二选一。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，唱歌和跳舞之间没有因果关系。"}], "explanations": {"而且": "“而且”表示递进，与“不但”呼应，说明会唱歌之外还会跳舞。", "但是": "搭配：“不但”后要用“而且”“也”“还”呼应，不能接“但是”。", "或者": "语义：“或者”表示选择，句子说的是两件事都会，不是二选一。", "所以": "语义：“所以”表示因果，唱歌和跳舞之间没有因果关系。"}, "sentence_index": 0, "correct_answer": "而且"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你可以坐火车，而且坐飞机，只能选一种。", "explanation": "这里应该用〈或者〉。“而且”表示并列，与“只能选一种”矛盾；表示二选一要用〈或者〉。"}, {"text": "不是我去，而且他去。", "explanation": "这里应该用〈而是〉。“不是……而是……”表示否定后的替换，不能用“而且”。"}, {"text": "这本书虽然有意思，而且很有用。", "explanation": "这里应该用〈但是〉。“虽然”后面要用“但是”或“却”，不能用“而且”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85930, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "而且", "is_correct": true, "explanation": "“而且”与“不但”呼应表示递进：房间大，更进一步还很安静。"}, {"text": "而是", "is_correct": false, "explanation": "搭配：“而是”要与“不是”呼应，句中没有“不是”。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，房间大和安静之间并没有对立关系。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果，房间大并不能导致它安静。"}], "explanations": {"而且": "“而且”与“不但”呼应表示递进：房间大，更进一步还很安静。", "而是": "搭配：“而是”要与“不是”呼应，句中没有“不是”。", "然而": "语义：“然而”表示转折，房间大和安静之间并没有对立关系。", "因此": "语义：“因此”表示因果，房间大并不能导致它安静。"}, "sentence_index": 6, "correct_answer": "而且"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师不是教我们汉语，而且教我们做人。", "explanation": "这里应该用〈而是〉。“不是……而是……”表示否定后的替换，不能用“而且”。"}, {"text": "他很想买，而且钱不够。", "explanation": "这里应该用〈但是〉。前后是转折关系，“而且”只表示递进，不表示转折。"}, {"text": "这个房间很大，而且有点儿吵。", "explanation": "这里应该用〈不过〉。“有点儿吵”是缺点，与“很大”构成转折，“而且”不表示转折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85930, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她不但会说英语，但是而且会写汉字。", "corrected_sentence": "她不但会说英语，而且会写汉字。", "error_description": "“而且”前不能再加“但是”，两者都是连词，重复连接。错误形式：但是而且；正确形式：而且。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85930, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不但会游泳，而且而且会打球。", "corrected_sentence": "他不但会游泳，而且会打球。", "error_description": "“而且”重复使用，只需一个。错误形式：而且而且会打球；正确形式：而且会打球。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
