INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85931, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "听说是听别人讲的，自己没有亲眼看到。", "primary_collocate": null, "pronunciation": "tīng shuō", "ipa": "tʰiŋ˥ ʂuɔ˥", "syllable_count": 2, "sentences": [{"text": "我听说他明天不来。", "target_word": "听说", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你听说那件事了吗？", "target_word": "听说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈听说我生病了，很担心。", "target_word": "听说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们都听说学校要办比赛。", "target_word": "听说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他听说那家饭店的鱼很好吃，就去了。", "target_word": "听说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我昨天才听说他搬家了。", "target_word": "听说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我听说过这位老师。", "target_word": "听说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没听说过这个办法。", "target_word": "听说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷听说过很多老故事，常讲给我们听。", "target_word": "听说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听说你要去北京工作，是真的吗？", "target_word": "听说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "听说过", "label": "体标：过"}, {"form": "听说了", "label": "体标：了"}], "register": "口语", "sense_fingerprint": "听别人讲起某事，不是亲眼所见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '090b0596-03c6-49fa-9960-4cdd5ded62a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85931, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "配价：“吃”需要接食物，不能接整个句子“他明天不来”。"}, {"text": "听说", "is_correct": true, "explanation": "听说：指从别人那里得知，与“他明天不来”这一消息相合。"}, {"text": "看见", "is_correct": false, "explanation": "语义：“看见”针对眼前的事，不能指向明天才会发生的事。"}, {"text": "洗", "is_correct": false, "explanation": "配价：“洗”需要接具体的东西，不能接一个句子。"}], "explanations": {"吃": "配价：“吃”需要接食物，不能接整个句子“他明天不来”。", "听说": "听说：指从别人那里得知，与“他明天不来”这一消息相合。", "看见": "语义：“看见”针对眼前的事，不能指向明天才会发生的事。", "洗": "配价：“洗”需要接具体的东西，不能接一个句子。"}, "sentence_index": 0, "correct_answer": "听说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我亲眼听说他跑进了教室。", "explanation": "这里应该用〈看见〉。“亲眼”表示自己看到，听说只表示从别人那里得知，二者矛盾。"}, {"text": "我亲身听说了那次地震。", "explanation": "这里应该用〈经历〉。听说指从别人那里听来的消息，不能用于自己亲身经历的事。"}, {"text": "我一看就听说这是假的。", "explanation": "这里应该用〈看出〉。“一看就”强调亲眼看到，听说不能用于亲眼做出的判断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85931, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿", "is_correct": false, "explanation": "搭配：“穿”接衣服、鞋子，不能接“这位老师”。"}, {"text": "买", "is_correct": false, "explanation": "语义：老师是人，不是商品，不能“买过”。"}, {"text": "听说", "is_correct": true, "explanation": "听说：与“过”连用，表示有过相关的听闻，与“这位老师”相合。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”接饮料，不能接人。"}], "explanations": {"穿": "搭配：“穿”接衣服、鞋子，不能接“这位老师”。", "买": "语义：老师是人，不是商品，不能“买过”。", "听说": "听说：与“过”连用，表示有过相关的听闻，与“这位老师”相合。", "喝": "搭配：“喝”接饮料，不能接人。"}, "sentence_index": 6, "correct_answer": "听说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我到处听说他的手机号码。", "explanation": "这里应该用〈打听〉。听说是别人告诉我，不是主动去问，不能和“到处”搭配。"}, {"text": "我在教室外听说了歌声。", "explanation": "这里应该用〈听见〉。听说只用于消息、话语，不能指听到声音。"}, {"text": "我走进教室，一下子听说了他。", "explanation": "这里应该用〈看到〉。听说针对消息，不能用来表示见到某个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85931, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我没听说了他下周要出差。", "corrected_sentence": "我没听说他下周要出差。", "error_description": "“了”的误用：否定句中“没”不能与“了”同用，“听说”前用“没”时应去掉“了”，错误形式是“没听说了”，正确形式是“没听说”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85931, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没听说着这个消息。", "corrected_sentence": "我没听说过这个消息。", "error_description": "体标错误：表示没有听说过某事的经历要用“过”，不能用“着”，应说“我没听说过这个消息”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
