INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85932, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "据说：放在句首，引出从别人那里听来的消息。", "primary_collocate": null, "pronunciation": "tīng shuō", "ipa": "tʰiŋ˥ ʂuɔ˥", "syllable_count": 2, "sentences": [{"text": "听说明天会下雨。", "target_word": "听说", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "听说他今年要结婚。", "target_word": "听说", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "听说这家店的面条很好吃。", "target_word": "听说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说那个电影很有意思，我们去看吧。", "target_word": "听说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说小王已经回国了。", "target_word": "听说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说老师病了，他就去医院看她。", "target_word": "听说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说下个月公司要搬到新楼里。", "target_word": "听说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说他以前在中国住过三年。", "target_word": "听说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说你拿到了第一名，真为你高兴。", "target_word": "听说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那里的冬天特别冷，你要多带衣服。", "target_word": "听说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "听说过", "label": "体标：过"}, {"form": "听说了", "label": "体标：了"}], "register": "口语", "sense_fingerprint": "据说，放在句首引出听来的消息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '090b0596-03c6-49fa-9960-4cdd5ded62a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85932, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跑", "is_correct": false, "explanation": "语义：“跑”指身体的动作，不能用来引出一条消息。"}, {"text": "听说", "is_correct": true, "explanation": "听说：用在句首引出听来的消息，与“明天会下雨”相合。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”需要接食物作宾语，不能带一个小句。"}, {"text": "洗", "is_correct": false, "explanation": "配价：“洗”需要接具体的宾语，不能带一个小句。"}], "explanations": {"跑": "语义：“跑”指身体的动作，不能用来引出一条消息。", "听说": "听说：用在句首引出听来的消息，与“明天会下雨”相合。", "吃": "配价：“吃”需要接食物作宾语，不能带一个小句。", "洗": "配价：“洗”需要接具体的宾语，不能带一个小句。"}, "sentence_index": 0, "correct_answer": "听说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在门外听说了敲门声。", "explanation": "这里应该用〈听到〉。“听说”指从别人那里得知消息，不能指直接听见的声音，声音要用“听到”。"}, {"text": "我亲眼听说他摔倒了。", "explanation": "这里应该用〈看见〉。“亲眼”表示自己看到，听说只表示从别人那里得知，二者矛盾。"}, {"text": "这道菜咸，我一吃就听说了。", "explanation": "这里应该用〈尝出〉。听说只用于听来的消息，不能用于味觉判断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85932, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "卖", "is_correct": false, "explanation": "语义：“卖”要接商品，不能引出公司搬迁的消息。"}, {"text": "修", "is_correct": false, "explanation": "配价：“修”需要接具体的东西，不能带一个小句。"}, {"text": "听说", "is_correct": true, "explanation": "听说：用在句首引出听来的消息，与“下个月公司要搬到新楼里”相合。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是演唱的动作，不能引出一件公司的事。"}], "explanations": {"卖": "语义：“卖”要接商品，不能引出公司搬迁的消息。", "修": "配价：“修”需要接具体的东西，不能带一个小句。", "听说": "听说：用在句首引出听来的消息，与“下个月公司要搬到新楼里”相合。", "唱": "语义：“唱”是演唱的动作，不能引出一件公司的事。"}, "sentence_index": 6, "correct_answer": "听说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一眼听说过他的背影。", "explanation": "这里应该用〈认出〉。“一眼”强调看见后辨认，听说只能表示从别人那里得知，不能指认出某人。"}, {"text": "我在路上听说过一片云。", "explanation": "这里应该用〈看见〉。听说指听来的消息，不能用来表示见到一片云。"}, {"text": "我在窗前听说过一阵雷声。", "explanation": "这里应该用〈听到〉。听说只能用于听来的消息，不能用于听见雷声这样的声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85932, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我没听说了他的新书很畅销。", "corrected_sentence": "我没听说他的新书很畅销。", "error_description": "“了”的误用：否定句中“没”与“了”不能同用，“听说”前用“没”时应去掉“了”，错误形式是“没听说了”，正确形式是“没听说”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85932, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我听说着这件事。", "corrected_sentence": "我听说过这件事。", "error_description": "体标错误：表示听说的经历要用“过”，不能用“着”，应说“我听说过这件事”，“听说着”不能成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85933, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最前", "is_correct": true, "explanation": "正确：“最前”指排在最前面，与“最后”在位置上构成反义。"}, {"text": "中间", "is_correct": false, "explanation": "不是反义：“中间”指居中的位置，与“最后”没有对立关系。"}, {"text": "中央", "is_correct": false, "explanation": "不是反义：“中央”指正中的位置，不与“最后”对立。"}, {"text": "旁边", "is_correct": false, "explanation": "不是反义：“旁边”指靠近的一侧，与“最后”没有对立关系。"}], "correct_answer": "最前", "explanations": {"最前": "正确：“最前”指排在最前面，与“最后”在位置上构成反义。", "中间": "不是反义：“中间”指居中的位置，与“最后”没有对立关系。", "中央": "不是反义：“中央”指正中的位置，不与“最后”对立。", "旁边": "不是反义：“旁边”指靠近的一侧，与“最后”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85933, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最前", "is_correct": true, "explanation": "正确：“最前”指排在最前面，与“最后”在位置上构成反义。"}, {"text": "中部", "is_correct": false, "explanation": "不是反义：“中部”指中间的部分，与“最后”没有对立关系。"}, {"text": "当中", "is_correct": false, "explanation": "不是反义：“当中”指中间位置，与“最后”不构成对立。"}, {"text": "途中", "is_correct": false, "explanation": "不是反义：“途中”指行进的过程中，与“最后”没有对立关系。"}], "correct_answer": "最前", "explanations": {"最前": "正确：“最前”指排在最前面，与“最后”在位置上构成反义。", "中部": "不是反义：“中部”指中间的部分，与“最后”没有对立关系。", "当中": "不是反义：“当中”指中间位置，与“最后”不构成对立。", "途中": "不是反义：“途中”指行进的过程中，与“最后”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85933, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“最后”是排在所有的后面，那一个就是最后。", "primary_collocate": null, "pronunciation": "zuì hòu", "ipa": "tsweɪ˥˩ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他排在队伍的最后。", "target_word": "最后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我坐在教室的最后一排。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明跑在最后，一直很慢。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "名单的最后是我的名字。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题放在试卷最后。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走在大家的最后。", "target_word": "最后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你排到队伍最后去。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "最后一个人把门关上了。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "名单上，我的名字在最后。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他考试得了最后一名。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "排列顺序中位于所有之后的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09d30940-30c9-4220-8182-85dc93122623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85933, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最后", "is_correct": true, "explanation": "正确：“排在队伍的最后”指排在队尾，“最后”表示位置在末尾。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是可以排队的位置，“排在队伍的冰箱”句子不成立。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“窗户”不能与“排在队伍的”搭配来表示位置。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：饭店是场所，不能指队伍中的位置，句子不通。"}], "explanations": {"最后": "正确：“排在队伍的最后”指排在队尾，“最后”表示位置在末尾。", "冰箱": "语义：冰箱不是可以排队的位置，“排在队伍的冰箱”句子不成立。", "窗户": "搭配：“窗户”不能与“排在队伍的”搭配来表示位置。", "饭店": "语义：饭店是场所，不能指队伍中的位置，句子不通。"}, "sentence_index": 0, "correct_answer": "最后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "最后站在队伍里的人，是排在第一位的我。", "explanation": "这里应该用〈首位〉。“最后”指排在末尾，与“排在第一位”相矛盾；指排在最前的位置要用〈首位〉。"}, {"text": "我站在队伍的最后，前面没有人。", "explanation": "这里应该用〈最前〉。“最后”指排在末尾，与“前面没有人”相矛盾；排在队伍第一位要用“最前”。"}, {"text": "名单的最后是我的名字，所以老师第一个叫到我。", "explanation": "这里应该用〈开头〉。“最后”指名单末尾，与“第一个叫到我”相矛盾；指名单最前的位置要用“开头”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85933, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最后", "is_correct": true, "explanation": "正确：“排到队伍最后去”指排到队尾。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是可以排队的位置，句子无法表示队伍中的位置。"}, {"text": "讲台", "is_correct": false, "explanation": "搭配：“讲台”是固定的站立位置，“排到队伍讲台去”不搭配。"}, {"text": "饭桌", "is_correct": false, "explanation": "语义：饭桌是吃饭用的家具，不是排队的位置，句子不通。"}], "explanations": {"最后": "正确：“排到队伍最后去”指排到队尾。", "书包": "语义：书包不是可以排队的位置，句子无法表示队伍中的位置。", "讲台": "搭配：“讲台”是固定的站立位置，“排到队伍讲台去”不搭配。", "饭桌": "语义：饭桌是吃饭用的家具，不是排队的位置，句子不通。"}, "sentence_index": 6, "correct_answer": "最后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他考试得了最后一名，全班都羡慕他的好成绩。", "explanation": "这里应该用〈第一名〉。“最后一名”指排在末尾，与“羡慕好成绩”相矛盾；表示名次靠前要用“第一名”。"}, {"text": "他是队伍的最后，走在大家前面。", "explanation": "这里应该用〈领头〉。“最后”指排在末尾，与“走在大家前面”相矛盾；表示排在最前、带头的人要用“领头”。"}, {"text": "他站在名单的最后，却排在第一位。", "explanation": "这里应该用〈首位〉。“最后”指名单末尾，与“排在第一位”相矛盾；表示排在名单首位要用“首位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85933, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他住在楼的最后得一层。", "corrected_sentence": "他住在楼的最后一层。", "error_description": "错误形式：“最后得一层”；正确形式：“最后一层”。“得”是补语标记，不能插在定语“最后”和数量短语“一层”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85933, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他跑在大家的了最后。", "corrected_sentence": "他跑在大家的最后。", "error_description": "错误形式：“的了最后”；正确形式：“的最后”。“了”不能插在定语“的”和“最后”之间，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85934, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最初", "is_correct": true, "explanation": "正确：“最初”指开始的时候，与“最后”在时间顺序上构成反义。"}, {"text": "中间", "is_correct": false, "explanation": "不是反义：“中间”指位置居中，与“最后”没有对立关系。"}, {"text": "过程", "is_correct": false, "explanation": "不是反义：“过程”指事情发展的经过，与“最后”不构成对立。"}, {"text": "中途", "is_correct": false, "explanation": "不是反义：“中途”指事情进行中的中间阶段，与“最后”没有对立关系。"}], "correct_answer": "最初", "explanations": {"最初": "正确：“最初”指开始的时候，与“最后”在时间顺序上构成反义。", "中间": "不是反义：“中间”指位置居中，与“最后”没有对立关系。", "过程": "不是反义：“过程”指事情发展的经过，与“最后”不构成对立。", "中途": "不是反义：“中途”指事情进行中的中间阶段，与“最后”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85934, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最初", "is_correct": true, "explanation": "正确：“最初”指开始的时候，与“最后”在时间顺序上构成反义。"}, {"text": "中央", "is_correct": false, "explanation": "不是反义：“中央”指位置居中，与“最后”没有对立关系。"}, {"text": "当中", "is_correct": false, "explanation": "不是反义：“当中”指中间部分，与“最后”不构成对立。"}, {"text": "途中", "is_correct": false, "explanation": "不是反义：“途中”指行进的过程中，与“最后”没有对立关系。"}], "correct_answer": "最初", "explanations": {"最初": "正确：“最初”指开始的时候，与“最后”在时间顺序上构成反义。", "中央": "不是反义：“中央”指位置居中，与“最后”没有对立关系。", "当中": "不是反义：“当中”指中间部分，与“最后”不构成对立。", "途中": "不是反义：“途中”指行进的过程中，与“最后”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85934, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名词，指次序或时间上在末尾的部分；也作形容词表示最末的。", "primary_collocate": null, "pronunciation": "zuì hòu", "ipa": "tsweɪ˥˩ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "音乐会的最后五分钟很精彩。", "target_word": "最后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的最后很感人。", "target_word": "最后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次考试我是班里的最后一名。", "target_word": "最后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛最后，我们赢了。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月的最后一天，我去看奶奶。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影的最后，他回家了。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的最后一句话是再见。", "target_word": "最后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年的最后，大家都很忙。", "target_word": "最后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是我最后一次来这里。", "target_word": "最后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是最后一个问题。", "target_word": "最后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "次序或时间上的末尾部分；最末的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09d30940-30c9-4220-8182-85dc93122623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85934, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最后", "is_correct": true, "explanation": "正确：“最后五分钟”指演出结束前的五分钟，“最后”修饰时段，表示末尾。"}, {"text": "最远", "is_correct": false, "explanation": "语义：“最远”说的是空间距离，不能修饰“五分钟”这样的时长。"}, {"text": "最贵", "is_correct": false, "explanation": "搭配：“最贵”说的是价格，不能用来修饰时间段。"}, {"text": "最高", "is_correct": false, "explanation": "语义：“最高”说的是高度或程度，不能修饰时长，句子不通。"}], "explanations": {"最后": "正确：“最后五分钟”指演出结束前的五分钟，“最后”修饰时段，表示末尾。", "最远": "语义：“最远”说的是空间距离，不能修饰“五分钟”这样的时长。", "最贵": "搭配：“最贵”说的是价格，不能用来修饰时间段。", "最高": "语义：“最高”说的是高度或程度，不能修饰时长，句子不通。"}, "sentence_index": 0, "correct_answer": "最后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他最后才到了，比所有人都早。", "explanation": "这里应该用〈最早〉。“最后”指末尾，与“比所有人都早”相矛盾；先于所有人要用〈最早〉。"}, {"text": "电影最后，他还是个孩子，后来长大了。", "explanation": "这里应该用〈开始〉。“最后”指末尾，与“后来长大了”的先后顺序矛盾；说电影开头要用“开始”。"}, {"text": "我们最后关灯，然后关门。", "explanation": "这里应该用〈首先〉。“最后”指末尾，与“然后”的顺序矛盾；表示第一步要用“首先”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85934, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最后", "is_correct": true, "explanation": "正确：“最后一句话”指末了的一句话，即“再见”那句。"}, {"text": "最热", "is_correct": false, "explanation": "搭配：“最热”说的是温度，不能修饰“一句话”。"}, {"text": "最凉", "is_correct": false, "explanation": "语义：“最凉”说的是温度，与“话”不相关，句子不成立。"}, {"text": "最低", "is_correct": false, "explanation": "语义：“最低”说的是高低程度，不能用来修饰一句话。"}], "explanations": {"最后": "正确：“最后一句话”指末了的一句话，即“再见”那句。", "最热": "搭配：“最热”说的是温度，不能修饰“一句话”。", "最凉": "语义：“最凉”说的是温度，与“话”不相关，句子不成立。", "最低": "语义：“最低”说的是高低程度，不能用来修饰一句话。"}, "sentence_index": 6, "correct_answer": "最后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他最后很努力，后来放弃了。", "explanation": "这里应该用〈最初〉。“最后”指末尾，与“后来放弃了”的先后不符；表示开始时要用“最初”。"}, {"text": "我们最后的时候人很少，后来越来越多。", "explanation": "这里应该用〈开始〉。“最后”表示末尾，与“后来越来越多”的先后顺序矛盾；讲开始的情形要用“开始”。"}, {"text": "最后这里没有路，现在有了一条大路。", "explanation": "这里应该用〈先前〉。“最后”指末尾，与“现在”的时间先后矛盾；表示过去的情形要用“先前”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "比赛的最后得三分钟很激烈。", "corrected_sentence": "比赛的最后三分钟很激烈。", "error_description": "错误形式：“最后得三分钟”；正确形式：“最后三分钟”。“得”是补语标记，不能插在定语“最后”和数量词“三分钟”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说了最后了一句话。", "corrected_sentence": "他说了最后一句话。", "error_description": "错误形式：“他说了最后了一句话”；正确形式：“他说了最后一句话”。“最后”与数量短语“一句话”之间不能插入“了”，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17dce598-91c0-445f-9a63-62c64b4a94ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85937, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "注销", "is_correct": true, "explanation": "反义：注销指取消已经登记的信息或资格，与“注册”相反。"}, {"text": "购买", "is_correct": false, "explanation": "无反义关系：购买是付钱取得物品，与登记信息无关。"}, {"text": "跑步", "is_correct": false, "explanation": "无反义关系：跑步是一种运动，不涉及登记或取消登记。"}, {"text": "唱歌", "is_correct": false, "explanation": "无反义关系：唱歌是表演，不是登记或取消登记。"}], "correct_answer": "注销", "explanations": {"注销": "反义：注销指取消已经登记的信息或资格，与“注册”相反。", "购买": "无反义关系：购买是付钱取得物品，与登记信息无关。", "跑步": "无反义关系：跑步是一种运动，不涉及登记或取消登记。", "唱歌": "无反义关系：唱歌是表演，不是登记或取消登记。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
