INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85937, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "注册是把你的名字写到一个本子或网站上，这样你就能用它。", "primary_collocate": null, "pronunciation": "zhù cè", "ipa": "tʂu˥˩ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "你先注册，然后就能玩游戏了。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想注册一个新的微信号。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在手机上注册了这个软件。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "注册很快，只要一分钟。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站注册不用花钱。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你已经注册了吗？", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在网上注册了账号。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了密码，只好重新注册。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "注册以后，你可以每天看书。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他帮奶奶注册了一个账号。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "注册了", "label": "体标"}, {"form": "注册过", "label": "体标"}, {"form": "重新注册", "label": "复合"}], "register": "中性", "sense_fingerprint": "把名字写到网站或本子上以便使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '537c4520-879d-4465-a1a7-51ade1e4b38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85937, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "注册", "is_correct": true, "explanation": "正确：注册指登记账号，完成后才能玩游戏，句意相符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病不能让人玩游戏，“先生病，然后就能玩游戏”说不通。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：发烧与玩游戏没有先后关系，句子说不通。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：翻译与玩游戏之间没有先后的前提关系，“先翻译，然后就能玩游戏”说不通。"}], "explanations": {"注册": "正确：注册指登记账号，完成后才能玩游戏，句意相符。", "生病": "语义：生病不能让人玩游戏，“先生病，然后就能玩游戏”说不通。", "发烧": "语义：发烧与玩游戏没有先后关系，句子说不通。", "翻译": "语义：翻译与玩游戏之间没有先后的前提关系，“先翻译，然后就能玩游戏”说不通。"}, "sentence_index": 0, "correct_answer": "注册"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们提前注册了餐厅。", "explanation": "这里应该用〈预约〉。预订餐厅要用“预约”；“注册”指登记姓名、信息等，不用于订位。"}, {"text": "他注册了一份工作。", "explanation": "这里应该用〈申请〉。应聘工作要用“申请”；“注册”不用于求职。"}, {"text": "他帮爷爷注册了一瓶酱油。", "explanation": "这里应该用〈买〉。买酱油要用“买”；“注册”指登记姓名、信息，不用于买东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85937, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "注册", "is_correct": true, "explanation": "正确：注册指在网上登记账号，这里表示孩子们登记了账号。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能用于账号，“吃了账号”说不通。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”不能与“账号”搭配，句子说不通。"}, {"text": "撒", "is_correct": false, "explanation": "搭配：“撒”不能用于账号，“撒了账号”不成立。"}], "explanations": {"注册": "正确：注册指在网上登记账号，这里表示孩子们登记了账号。", "吃": "语义：“吃”不能用于账号，“吃了账号”说不通。", "跑": "语义：“跑”不能与“账号”搭配，句子说不通。", "撒": "搭配：“撒”不能用于账号，“撒了账号”不成立。"}, "sentence_index": 6, "correct_answer": "注册"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他帮奶奶注册了一场雨。", "explanation": "注册的对象是账号、公司、商标等，不能指雨。这里应该用〈下〉。"}, {"text": "我想注册一顿晚饭。", "explanation": "注册的对象是账号、公司、商标等，不能指饭食。这里应该用〈吃〉。"}, {"text": "她注册了一片蓝天。", "explanation": "注册的对象是账号、公司、商标等，不能指天空。这里应该用〈欣赏〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85937, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我换了手机，只好重新注册着。", "corrected_sentence": "我换了手机，只好重新注册。", "error_description": "体标错误：“注册”是一次完成的动作，不能加“着”表示状态持续；应为“只好重新注册”，去掉“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85937, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在手机上注册得账号很安全。", "corrected_sentence": "他在手机上注册的账号很安全。", "error_description": "结构助词错误：修饰“账号”要用“的”，“得”用于动词后作补语。这里应为“注册的账号”，写成“注册得账号”是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
