INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85938, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "注销", "is_correct": true, "explanation": "反义：注销指取消已经登记的信息或资格，与“注册”相反。"}, {"text": "游泳", "is_correct": false, "explanation": "无反义关系：游泳是一种运动，与登记信息无关。"}, {"text": "吃饭", "is_correct": false, "explanation": "无反义关系：吃饭是进食，与登记或取消登记无关。"}, {"text": "画画", "is_correct": false, "explanation": "无反义关系：画画是创作活动，不涉及登记。"}], "correct_answer": "注销", "explanations": {"注销": "反义：注销指取消已经登记的信息或资格，与“注册”相反。", "游泳": "无反义关系：游泳是一种运动，与登记信息无关。", "吃饭": "无反义关系：吃饭是进食，与登记或取消登记无关。", "画画": "无反义关系：画画是创作活动，不涉及登记。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85938, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向有关机构或网站登记姓名等信息，以取得资格或使用权。", "primary_collocate": null, "pronunciation": "zhù cè", "ipa": "tʂu˥˩ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "你要先在网站上注册，才能买票。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天注册了一个新邮箱。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司去年在北京注册。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想注册一家小公司。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新生要在九月一号前注册。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用手机号注册账号。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你注册过这个网站吗？", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "注册的时候，要写真实的姓名。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不注册，就不能看这个视频。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的网上注册今天开始了。", "target_word": "注册", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "注册了", "label": "体标"}, {"form": "注册过", "label": "体标"}, {"form": "注册商标", "label": "复合"}, {"form": "注册会计师", "label": "复合"}], "register": "中性", "sense_fingerprint": "向机构或网站登记个人信息以取得资格或使用权", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '537c4520-879d-4465-a1a7-51ade1e4b38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85938, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "注册", "is_correct": true, "explanation": "正确：注册指在网站上登记信息以取得资格，这里表示先完成登记才能买票。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”不能与“网站上”搭配，“在网站上散步”说不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“唱歌”不能用于网站的操作，“在网站上唱歌”不成立。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉与买票的前提无关，“先睡觉才能买票”说不通。"}], "explanations": {"注册": "正确：注册指在网站上登记信息以取得资格，这里表示先完成登记才能买票。", "散步": "搭配：“散步”不能与“网站上”搭配，“在网站上散步”说不通。", "唱歌": "搭配：“唱歌”不能用于网站的操作，“在网站上唱歌”不成立。", "睡觉": "语义：睡觉与买票的前提无关，“先睡觉才能买票”说不通。"}, "sentence_index": 0, "correct_answer": "注册"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去银行注册了一笔贷款。", "explanation": "这里应该用〈申请〉。贷款要用“申请”；“注册”指登记信息以取得资格，不用于借钱。"}, {"text": "她注册了一张电影票。", "explanation": "这里应该用〈买〉。买电影票要用“买”；“注册”指登记姓名、信息，不用于买票。"}, {"text": "我们去超市注册了一些水果。", "explanation": "这里应该用〈挑选〉。挑水果要用“挑选”；“注册”指登记信息，不用于挑选商品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85938, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "注册", "is_correct": true, "explanation": "正确：“注册过”指曾在该网站登记过账号，句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与网站无关，“吃过这个网站”说不通。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”不能用于网站，“骑过这个网站”不成立。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”指移动，与登记账号无关，句意不通。"}], "explanations": {"注册": "正确：“注册过”指曾在该网站登记过账号，句意相符。", "吃": "语义：“吃”与网站无关，“吃过这个网站”说不通。", "骑": "搭配：“骑”不能用于网站，“骑过这个网站”不成立。", "跑": "语义：“跑”指移动，与登记账号无关，句意不通。"}, "sentence_index": 6, "correct_answer": "注册"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天注册了一位新朋友。", "explanation": "注册的对象是账号、公司、商标等，不能指人。结识新朋友要用〈认识〉。"}, {"text": "她每天都注册一次早饭。", "explanation": "注册的对象是账号、公司、商标等，不能指饭食。吃早饭要用〈吃〉。"}, {"text": "我们注册了这座山的美景。", "explanation": "注册的对象是账号、公司、商标等，不能指风景。欣赏美景要用〈欣赏〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经注册了了这个软件。", "corrected_sentence": "我已经注册了这个软件。", "error_description": "体标重复：“注册了”之后不能再加“了”，同一个“了”只用一次；应为“我已经注册了这个软件”，去掉多余的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他注册了过这个网站，所以很熟悉。", "corrected_sentence": "他注册过这个网站，所以很熟悉。", "error_description": "体标叠用：“注册”后的“了”与“过”不能同时使用，只保留“过”，应为“他注册过这个网站”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
