INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85940, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "议会的成员，由选举产生，参与议事和立法。", "primary_collocate": null, "pronunciation": "yì yuán", "ipa": "i˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这位议员明天要去市政厅开会。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议员们正在讨论新的交通法。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了十年议员，很了解老百姓的生活。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民给议员写了一封信，希望多建公园。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议员们投票决定了明年的预算。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位议员是去年选出来的。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者问议员对新法律有什么看法。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想成为议员，为城市做更多事。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议员应该多听听大家的意见。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天有三位议员来我们学校参观。", "target_word": "议员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "国会议员", "label": "复合"}, {"form": "議員", "label": "繁体"}], "register": "中性", "sense_fingerprint": "议会中由选举产生、参与议事和立法的成员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87aa3fbb-5473-40d6-85f3-a36aa4409ac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85940, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "议员", "is_correct": true, "explanation": "议员（yì yuán）：议会的成员，由选举产生，参与议事和立法。"}, {"text": "一元", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，“一元”是货币单位，意思不同。"}, {"text": "医院", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，yuàn（第四声）与 yuán（第二声）也不同，意思是医院。"}, {"text": "意愿", "is_correct": false, "explanation": "yuàn（第四声）与 yuán（第二声）声调不同，意思是愿望。"}, {"text": "议院", "is_correct": false, "explanation": "yuàn（第四声）与 yuán（第二声）声调不同，“议院”指议会机构，意思不同。"}], "explanations": {"议员": "议员（yì yuán）：议会的成员，由选举产生，参与议事和立法。", "一元": "yī（第一声）与 yì（第四声）声调不同，“一元”是货币单位，意思不同。", "医院": "yī（第一声）与 yì（第四声）声调不同，yuàn（第四声）与 yuán（第二声）也不同，意思是医院。", "意愿": "yuàn（第四声）与 yuán（第二声）声调不同，意思是愿望。", "议院": "yuàn（第四声）与 yuán（第二声）声调不同，“议院”指议会机构，意思不同。"}, "sentence_index": null, "correct_answer": "议员"}, "level_3": {"options": [{"text": "议员", "is_correct": true, "explanation": "议员：议会的成员，与“明天要去市政厅开会”相符。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不能去市政厅开会。"}, {"text": "鬼", "is_correct": false, "explanation": "搭配：“这位”指人，“鬼”不能与“去市政厅开会”搭配。"}, {"text": "神仙", "is_correct": false, "explanation": "语义：神仙不属于会议的参与者，不能去市政厅开会。"}], "explanations": {"议员": "议员：议会的成员，与“明天要去市政厅开会”相符。", "婴儿": "语义：婴儿不能去市政厅开会。", "鬼": "搭配：“这位”指人，“鬼”不能与“去市政厅开会”搭配。", "神仙": "语义：神仙不属于会议的参与者，不能去市政厅开会。"}, "sentence_index": 0, "correct_answer": "议员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位议员在比赛中吹哨判罚犯规。", "explanation": "这里应该用〈裁判〉。吹哨判罚犯规是裁判的工作，议员的职责是立法和议事。"}, {"text": "我昨天在会上见到了两只议员。", "explanation": "这里量词用错了。议员是人，应该用〈位〉或〈名〉，不能用〈只〉。"}, {"text": "这位议员负责管理学校的食堂。", "explanation": "这里应该用〈后勤主任〉。管理学校食堂属于后勤工作，议员负责立法和议事，不负责学校的具体事务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85940, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "议员", "is_correct": true, "explanation": "议员（yì yuán）：议会的成员，由选举产生，参与议事和立法。"}, {"text": "一员", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，“一员”指一个成员，意思不同。"}, {"text": "遗愿", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）、yuàn（第四声）与 yuán（第二声）声调都不同，意思是临终前的愿望。"}, {"text": "医院", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，yuàn（第四声）与 yuán（第二声）也不同，意思是看病的地方。"}], "explanations": {"议员": "议员（yì yuán）：议会的成员，由选举产生，参与议事和立法。", "一员": "yī（第一声）与 yì（第四声）声调不同，“一员”指一个成员，意思不同。", "遗愿": "yí（第二声）与 yì（第四声）、yuàn（第四声）与 yuán（第二声）声调都不同，意思是临终前的愿望。", "医院": "yī（第一声）与 yì（第四声）声调不同，yuàn（第四声）与 yuán（第二声）也不同，意思是看病的地方。"}, "sentence_index": null, "correct_answer": "议员"}, "level_3": {"options": [{"text": "议员", "is_correct": true, "explanation": "议员：议会的成员，与“记者问……对新法律有什么看法”相符。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物不能回答记者的问题，也没有对法律的看法。"}, {"text": "石头", "is_correct": false, "explanation": "体貌：石头没有发言能力，形体上也不能回答问题。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子无法对新法律表示看法。"}], "explanations": {"议员": "议员：议会的成员，与“记者问……对新法律有什么看法”相符。", "植物": "语义：植物不能回答记者的问题，也没有对法律的看法。", "石头": "体貌：石头没有发言能力，形体上也不能回答问题。", "桌子": "语义：桌子无法对新法律表示看法。"}, "sentence_index": 6, "correct_answer": "议员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位议员每天给客人理发。", "explanation": "这里应该用〈理发师〉。给客人理发是理发师的工作，议员的职责是立法和议事。"}, {"text": "议员在法庭上宣读了判决。", "explanation": "这里应该用〈法官〉。宣读判决是法官的职责，议员不参与审判。"}, {"text": "这位议员每天在工地上砌墙。", "explanation": "这里应该用〈泥瓦匠〉。砌墙是泥瓦匠的工作，议员的职责是立法和议事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他父亲二十年前就当上了一只议员。", "corrected_sentence": "他父亲二十年前就当上了一位议员。", "error_description": "错误：一只议员；正确：一位议员。议员指人，量词应用“位”或“名”，“只”多用于动物或某些物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只议员在任期内提出了很多建议。", "corrected_sentence": "这位议员在任期内提出了很多建议。", "error_description": "错误：这只议员；正确：这位议员。议员指人，指示量词应用“位”，“只”多用于动物或某些物品。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
