INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85941, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85941, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一旦是说如果有一天忽然发生了。", "primary_collocate": null, "pronunciation": "yí dàn", "ipa": "i˧˥ tan˥˩", "syllable_count": 2, "sentences": [{"text": "一旦发生火灾，大家要马上离开。", "target_word": "一旦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机一旦丢了，很多事情都会很麻烦。", "target_word": "一旦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一旦生病，工作就要停下来。", "target_word": "一旦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车一旦坏了，我们就走不了了。", "target_word": "一旦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一旦比赛开始，谁也不能进来。", "target_word": "一旦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一旦忘了密码，就打不开门了。", "target_word": "一旦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一旦出现危险，你就大声叫我。", "target_word": "一旦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水一旦流出来，地板就湿了。", "target_word": "一旦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一旦生气，谁的话也不听。", "target_word": "一旦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一旦错过这班车，我们就要等一个小时。", "target_word": "一旦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一旦：假设意外情况忽然发生，强调后果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f239b726-4c9e-4af2-9b42-8368eb77c8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85941, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一旦", "is_correct": true, "explanation": "正确：一旦（yí dàn）表示假设意外情况忽然发生，强调后果。"}, {"text": "一带", "is_correct": false, "explanation": "dài 与 dàn 韵尾不同（-ai 与 -an），意思是这一带。"}, {"text": "一半", "is_correct": false, "explanation": "bàn 与 dàn 声母不同（b 与 d），意思是一半。"}, {"text": "一单", "is_correct": false, "explanation": "一单 yì dān（第一声）与 yí dàn（第四声）声调不同，意思是一笔订单。"}], "explanations": {"一旦": "正确：一旦（yí dàn）表示假设意外情况忽然发生，强调后果。", "一带": "dài 与 dàn 韵尾不同（-ai 与 -an），意思是这一带。", "一半": "bàn 与 dàn 声母不同（b 与 d），意思是一半。", "一单": "一单 yì dān（第一声）与 yí dàn（第四声）声调不同，意思是一笔订单。"}, "sentence_index": null, "correct_answer": "一旦"}, "level_3": {"options": [{"text": "一旦", "is_correct": true, "explanation": "正确：一旦发生火灾，就立即离开，表示假设意外忽然发生。"}, {"text": "务必", "is_correct": false, "explanation": "语域：“务必”是书面语，多用于叮嘱，不能修饰“发生火灾”这种意外。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示催促，不能修饰“发生火灾”这种不由人控制的事件。"}, {"text": "不必", "is_correct": false, "explanation": "语义：“不必”表示没有必要，与“大家要马上离开”的要求相矛盾。"}], "explanations": {"一旦": "正确：一旦发生火灾，就立即离开，表示假设意外忽然发生。", "务必": "语域：“务必”是书面语，多用于叮嘱，不能修饰“发生火灾”这种意外。", "赶紧": "语义：“赶紧”表示催促，不能修饰“发生火灾”这种不由人控制的事件。", "不必": "语义：“不必”表示没有必要，与“大家要马上离开”的要求相矛盾。"}, "sentence_index": 0, "correct_answer": "一旦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天他一旦来了我家。", "explanation": "这里应该用〈突然〉。一旦表示假设将来可能发生的情况，不能叙述昨天已经发生的事，应说“昨天他突然来了我家”。"}, {"text": "他十点一旦起床。", "explanation": "这里应该用〈才〉。一旦表示意外情况突然发生，不能表示“十点才”这样的时间限定，应说“十点才起床”。"}, {"text": "我一旦就去。", "explanation": "这里应该用〈马上〉。一旦需要带出条件和结果，不能单独与“就”搭配表示立即，应说“我马上就去”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85941, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一旦", "is_correct": true, "explanation": "正确：一旦（yí dàn）表示假设意外情况忽然发生，强调后果。"}, {"text": "一档", "is_correct": false, "explanation": "dàng 与 dàn 韵尾不同（-ang 与 -an），意思是一档节目。"}, {"text": "一站", "is_correct": false, "explanation": "zhàn 与 dàn 声母不同（zh 与 d），意思是一个站点。"}, {"text": "一担", "is_correct": false, "explanation": "dān（第一声）与 dàn（第四声）声调不同，意思是一挑（的量）。"}, {"text": "一段", "is_correct": false, "explanation": "duàn 比 dàn 多了 u，意思是一段（路程或时间）。"}], "explanations": {"一旦": "正确：一旦（yí dàn）表示假设意外情况忽然发生，强调后果。", "一档": "dàng 与 dàn 韵尾不同（-ang 与 -an），意思是一档节目。", "一站": "zhàn 与 dàn 声母不同（zh 与 d），意思是一个站点。", "一担": "dān（第一声）与 dàn（第四声）声调不同，意思是一挑（的量）。", "一段": "duàn 比 dàn 多了 u，意思是一段（路程或时间）。"}, "sentence_index": null, "correct_answer": "一旦"}, "level_3": {"options": [{"text": "一旦", "is_correct": true, "explanation": "正确：一旦出现危险，就大声叫，表示假设意外忽然发生，与语境相合。"}, {"text": "只好", "is_correct": false, "explanation": "搭配：“只好”表示无奈地去做某事，不能修饰“出现危险”这种事件。"}, {"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示必然的要求，不能说“必须出现危险”，与语境不合。"}, {"text": "千万", "is_correct": false, "explanation": "语义：“千万”用于叮嘱，不能修饰“出现危险”，句意不通。"}], "explanations": {"一旦": "正确：一旦出现危险，就大声叫，表示假设意外忽然发生，与语境相合。", "只好": "搭配：“只好”表示无奈地去做某事，不能修饰“出现危险”这种事件。", "必须": "语义：“必须”表示必然的要求，不能说“必须出现危险”，与语境不合。", "千万": "语义：“千万”用于叮嘱，不能修饰“出现危险”，句意不通。"}, "sentence_index": 6, "correct_answer": "一旦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一旦他很努力，但是没有考上。", "explanation": "这里应该用〈虽然〉。一旦表示条件出现后随之发生，不表示让步，与“但是”搭配不通，应说“虽然他很努力，但是没有考上”。"}, {"text": "一旦天黑了，他还是坚持跑完了全程。", "explanation": "这里应该用〈尽管〉。一旦不表示让步，与“还是”搭配不通，应说“尽管天黑了，他还是坚持跑完了全程”。"}, {"text": "一旦下大雨，他也会去上学。", "explanation": "这里应该用〈即使〉。一旦引出导致后果的条件，不表示让步，应说“即使下大雨，他也会去上学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85941, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一旦停电，屋里就一旦很暗。", "corrected_sentence": "一旦停电，屋里就很暗。", "error_description": "重复误用：“一旦”只引出条件分句，不能再修饰“很暗”这一结果分句；多余的“一旦”应删去。正确应为：一旦停电，屋里就很暗。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85941, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一旦错过车，我们才得等。", "corrected_sentence": "一旦错过车，我们就得等。", "error_description": "搭配错误：“一旦……就……”是固定搭配，表示一出现某情况就有某结果，“才”不能替代“就”。正确应为：一旦错过车，我们就得等。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
