INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85944, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，从过去到现在一直（多用于否定）。", "primary_collocate": null, "pronunciation": "cóng lái", "ipa": "tsʰʊŋ˧˥ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "我从来不喝咖啡。", "target_word": "从来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没迟到。", "target_word": "从来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没去过那个地方。", "target_word": "从来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟从来不吃辣的菜。", "target_word": "从来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从来没跟我说过这件事。", "target_word": "从来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来不在晚上喝茶。", "target_word": "从来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷从来不玩手机。", "target_word": "从来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么好吃的饭，我从来没吃过。", "target_word": "从来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来不骗人。", "target_word": "从来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们从来没见过面。", "target_word": "从来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "从过去到现在一直没有（用于否定：从来不／从来没）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '537c4520-879d-4465-a1a7-51ade1e4b38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85944, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从来", "is_correct": true, "explanation": "正确：“从来不喝咖啡”表示从过去到现在一直不喝，与“不”搭配。"}, {"text": "连忙", "is_correct": false, "explanation": "语义：“连忙”指急忙地做某事，不能说明长期不喝咖啡的习惯。"}, {"text": "立即", "is_correct": false, "explanation": "语义：“立即”表示马上做某事，不能说明长期不喝咖啡的习惯。"}, {"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”指本人动手或到场，不能修饰“不喝咖啡”这种习惯。"}], "explanations": {"从来": "正确：“从来不喝咖啡”表示从过去到现在一直不喝，与“不”搭配。", "连忙": "语义：“连忙”指急忙地做某事，不能说明长期不喝咖啡的习惯。", "立即": "语义：“立即”表示马上做某事，不能说明长期不喝咖啡的习惯。", "亲自": "语义：“亲自”指本人动手或到场，不能修饰“不喝咖啡”这种习惯。"}, "sentence_index": 0, "correct_answer": "从来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我从来戒掉了咖啡。", "explanation": "这里应该用〈终于〉。从来表示一贯的状况，不能用来说明经过努力后才实现的结果。"}, {"text": "我从来没去过北京三次。", "explanation": "这里应该用〈曾经〉。“从来没”表示一次也没有，与“去过三次”自相矛盾，有限次数的经历要用曾经。"}, {"text": "爸爸从来在看报纸。", "explanation": "这里应该用〈正在〉。从来表示一贯的习惯，不用来描述说话时正在进行的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85944, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从来", "is_correct": true, "explanation": "正确：“从来不玩手机”表示一贯如此，与“不”搭配。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急忙去做某事，与长期不玩手机的习惯不合。"}, {"text": "顺便", "is_correct": false, "explanation": "语义：“顺便”表示附带做某事，不能说明长期的习惯。"}, {"text": "当场", "is_correct": false, "explanation": "搭配：“当场”多与“发生”“抓住”等搭配，不能修饰“不玩手机”这种习惯。"}], "explanations": {"从来": "正确：“从来不玩手机”表示一贯如此，与“不”搭配。", "赶紧": "语义：“赶紧”表示急忙去做某事，与长期不玩手机的习惯不合。", "顺便": "语义：“顺便”表示附带做某事，不能说明长期的习惯。", "当场": "搭配：“当场”多与“发生”“抓住”等搭配，不能修饰“不玩手机”这种习惯。"}, "sentence_index": 6, "correct_answer": "从来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我从来去过那家店了。", "explanation": "这里应该用〈已经〉。从来表示一贯的状况，不能用于说明已经完成的经历。"}, {"text": "他从来回家了。", "explanation": "这里应该用〈刚刚〉。从来表示一贯如此，不能用来说明刚刚发生的动作。"}, {"text": "他从来哭了。", "explanation": "这里应该用〈忽然〉。从来表示一贯的状况，不能用来说明突然发生的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85944, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的朋友从来没借了钱给别人。", "corrected_sentence": "我的朋友从来没借过钱给别人。", "error_description": "“从来没”后表示未曾有过的经历时应用“过”，不能用“了”；应说“从来没借过”，不说“从来没借了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85944, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没是医生。", "corrected_sentence": "他从来不是医生。", "error_description": "“没”不与“是”搭配，否定“是”应用“不”，应说“从来不是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
