INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85945, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "情绪是你心里的高兴、难过、生气这些感觉。", "primary_collocate": null, "pronunciation": "qíng xù", "ipa": "tɕʰiŋ˧˥ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "我今天的情绪不太好。", "target_word": "情绪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到朋友哭了，我的情绪也变差了。", "target_word": "情绪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要学会控制自己的情绪。", "target_word": "情绪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了这首歌，我的情绪好多了。", "target_word": "情绪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的情绪来得快，去得也快。", "target_word": "情绪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想把坏情绪带回家。", "target_word": "情绪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前，同学们的情绪都很紧张。", "target_word": "情绪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈发现我情绪不对，就问我怎么了。", "target_word": "情绪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大哭一场以后，他的情绪平静了下来。", "target_word": "情绪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别让坏情绪影响你的工作。", "target_word": "情绪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "情绪化", "label": "派生：后缀“化”"}], "register": "中性", "sense_fingerprint": "心里的高兴、难过、生气等感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '090b0596-03c6-49fa-9960-4cdd5ded62a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85945, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地址", "is_correct": false, "explanation": "语义：地址是住所的位置，没有“好”或“不好”的心理状态，句中说不通。"}, {"text": "情绪", "is_correct": true, "explanation": "情绪：指心里的感受，“情绪不太好”说的是心情差，与句意相合。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历是固定的教育经历，不随“今天”变化，不说“今天的学历”。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”说高矮，不说“好”或“不好”，不能接“不太好”。"}], "explanations": {"地址": "语义：地址是住所的位置，没有“好”或“不好”的心理状态，句中说不通。", "情绪": "情绪：指心里的感受，“情绪不太好”说的是心情差，与句意相合。", "学历": "语义：学历是固定的教育经历，不随“今天”变化，不说“今天的学历”。", "身高": "搭配：“身高”说高矮，不说“好”或“不好”，不能接“不太好”。"}, "sentence_index": 0, "correct_answer": "情绪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对工作的情绪很认真。", "explanation": "这里应该用〈态度〉。情绪指心里的感受，不指对工作的看法和做法，“认真”修饰的是态度。"}, {"text": "他和妻子的情绪很深。", "explanation": "这里应该用〈感情〉。情绪指一时的心理状态，长期的人际感情要用“感情”，“很深”也应用于感情。"}, {"text": "他对故乡有很深的情绪。", "explanation": "这里应该用〈情感〉。情绪多指一时的喜怒哀乐，表达对故乡深厚的依恋要用“情感”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85945, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课本", "is_correct": false, "explanation": "语义：课本是书，没有心理状态，不会“紧张”，句中说不通。"}, {"text": "情绪", "is_correct": true, "explanation": "情绪：心里的感受，“同学们的情绪都很紧张”指考前心里不安，与句意相合。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“紧张”描写人的心理，不修饰成绩，不说“成绩很紧张”。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是场所，不会“紧张”，与“同学们”的状态无关。"}], "explanations": {"课本": "语义：课本是书，没有心理状态，不会“紧张”，句中说不通。", "情绪": "情绪：心里的感受，“同学们的情绪都很紧张”指考前心里不安，与句意相合。", "成绩": "搭配：“紧张”描写人的心理，不修饰成绩，不说“成绩很紧张”。", "教室": "语义：教室是场所，不会“紧张”，与“同学们”的状态无关。"}, "sentence_index": 6, "correct_answer": "情绪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的情绪很清楚，我完全同意。", "explanation": "这里应该用〈观点〉。“清楚”形容看法或道理，情绪是心里的感受，不能说“很清楚”。"}, {"text": "他的情绪很先进。", "explanation": "这里应该用〈思想〉。“先进”形容思想、观念，情绪是心里的感受，不能说“很先进”。"}, {"text": "他的情绪安排得很详细。", "explanation": "这里应该用〈计划〉。“安排得很详细”用于计划、日程，情绪是心理状态，不能被安排。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85945, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他心里藏着一粒说不清的情绪。", "corrected_sentence": "他心里藏着一种说不清的情绪。", "error_description": "量词错误：“粒”用于颗粒状的东西，“情绪”应用量词“种”，应说“一种说不清的情绪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85945, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他心里泛起一滴复杂的情绪。", "corrected_sentence": "他心里泛起一种复杂的情绪。", "error_description": "量词错误：“滴”用于液体，“情绪”应用量词“种”，应说“一种复杂的情绪”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
