INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85946, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人在心理上的感受和状态，如喜怒哀乐。", "primary_collocate": null, "pronunciation": "qíng xù", "ipa": "tɕʰiŋ˧˥ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "好的睡眠对稳定情绪很有帮助。", "target_word": "情绪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的情绪一直很低落。", "target_word": "情绪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要关心学生的情绪变化。", "target_word": "情绪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐能改变人的情绪。", "target_word": "情绪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动可以帮助人调节情绪。", "target_word": "情绪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "情绪好的时候，人更有耐心。", "target_word": "情绪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最近情绪波动很大。", "target_word": "情绪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间加班会影响人的情绪。", "target_word": "情绪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用画画来表达自己的情绪。", "target_word": "情绪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的情绪都很高涨。", "target_word": "情绪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "情绪化", "label": "派生：后缀“化”"}], "register": "中性", "sense_fingerprint": "人的心理感受和状态，如喜怒哀乐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '090b0596-03c6-49fa-9960-4cdd5ded62a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85946, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "黑板", "is_correct": false, "explanation": "语义：黑板是物体，没有可以“稳定”的心理状态，句中说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“稳定”不用于窗户，窗户一般说“牢固”。"}, {"text": "情绪", "is_correct": true, "explanation": "情绪：指人的心理状态，好的睡眠对它稳定有帮助，与句意相合。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是场所，不能被“稳定”，与睡眠的作用无关。"}], "explanations": {"黑板": "语义：黑板是物体，没有可以“稳定”的心理状态，句中说不通。", "窗户": "搭配：“稳定”不用于窗户，窗户一般说“牢固”。", "情绪": "情绪：指人的心理状态，好的睡眠对它稳定有帮助，与句意相合。", "教室": "语义：教室是场所，不能被“稳定”，与睡眠的作用无关。"}, "sentence_index": 0, "correct_answer": "情绪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对朋友的情绪很真诚。", "explanation": "这里应该用〈态度〉。情绪指心里的感受，“真诚”形容的是对人的态度，不能修饰情绪。"}, {"text": "这家商店的情绪很便宜。", "explanation": "这里应该用〈东西〉。情绪是心里的感受，不能买卖，不能说“很便宜”。"}, {"text": "她和老朋友之间有很深的情绪。", "explanation": "这里应该用〈友谊〉。情绪指一时的心理状态，两人长期的交情要用“友谊”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85946, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教材", "is_correct": false, "explanation": "语义：教材是书，不会“波动”，句中说不通。"}, {"text": "情绪", "is_correct": true, "explanation": "情绪：心情起伏不定，“情绪波动很大”正指情绪的变化，与句意相合。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，没有心理状态或起伏，不能“波动”。"}, {"text": "钢笔", "is_correct": false, "explanation": "搭配：“波动”多用于情绪、价格、数据，不修饰钢笔。"}], "explanations": {"教材": "语义：教材是书，不会“波动”，句中说不通。", "情绪": "情绪：心情起伏不定，“情绪波动很大”正指情绪的变化，与句意相合。", "桌子": "语义：桌子是家具，没有心理状态或起伏，不能“波动”。", "钢笔": "搭配：“波动”多用于情绪、价格、数据，不修饰钢笔。"}, "sentence_index": 6, "correct_answer": "情绪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的情绪设计得很合理。", "explanation": "这里应该用〈方案〉。情绪是心理状态，不能说“设计得很合理”，被设计的是方案。"}, {"text": "他的情绪很陈旧，不愿接受新事物。", "explanation": "这里应该用〈观念〉。“陈旧”形容观念、做法，情绪是心理感受，不能说“很陈旧”。"}, {"text": "他的情绪写得很整齐。", "explanation": "这里应该用〈作业〉。“写得很整齐”形容字迹或作业，情绪不能这样描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他心里有一只说不清的情绪。", "corrected_sentence": "他心里有一种说不清的情绪。", "error_description": "量词错误：“只”用于动物等，“情绪”应用量词“种”，应说“一种说不清的情绪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他心里涌起一根复杂的情绪。", "corrected_sentence": "他心里涌起一股复杂的情绪。", "error_description": "量词错误：“根”用于细长的东西，“情绪”应用量词“股”，应说“一股复杂的情绪”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
