INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85947, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "投是用力把东西扔向前方。", "primary_collocate": null, "pronunciation": "tóu", "ipa": "tʰou̯˧˥", "syllable_count": 1, "sentences": [{"text": "他用力把球投向远处。", "target_word": "投", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把石头投进了河里。", "target_word": "投", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个球他投得很远。", "target_word": "投", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把纸团投到垃圾桶里。", "target_word": "投", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把小石子往水里投。", "target_word": "投", "complexity_tier": "T3", "furigana": "dì di bǎ xiǎo shí zi wǎng shuǐ lǐ tóu。", "sentence_source": "generated"}, {"text": "他投出的球又快又准。", "target_word": "投", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们把雪球投向树上的鸟。", "target_word": "投", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时，他投过一个很远的球。", "target_word": "投", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能把这个球投到我这里吗？", "target_word": "投", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把面包投进河里喂鱼。", "target_word": "投", "complexity_tier": "T3", "furigana": "lǎo rén bǎ miàn bāo tóu jìn hé lǐ wèi yú。", "sentence_source": "generated"}], "morphological_forms": [{"form": "投了", "label": "完成体"}, {"form": "投过", "label": "经验体"}, {"form": "投着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "投：用力把东西扔向前方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528460c6-b68d-4819-9976-ec879930a8cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85947, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "投", "is_correct": true, "explanation": "投（tóu）是用力把东西扔向前方，是本题的正确答案。"}, {"text": "偷", "is_correct": false, "explanation": "tōu（第一声）与 tóu（第二声）声调不同，意思是偷窃。"}, {"text": "透", "is_correct": false, "explanation": "tòu（第四声）与 tóu（第二声）声调不同，意思是穿透、透明。"}, {"text": "楼", "is_correct": false, "explanation": "lóu 与 tóu 声母不同（l 与 t），意思是楼房。"}, {"text": "愁", "is_correct": false, "explanation": "chóu 与 tóu 声母不同（ch 与 t），意思是忧愁。"}], "explanations": {"投": "投（tóu）是用力把东西扔向前方，是本题的正确答案。", "偷": "tōu（第一声）与 tóu（第二声）声调不同，意思是偷窃。", "透": "tòu（第四声）与 tóu（第二声）声调不同，意思是穿透、透明。", "楼": "lóu 与 tóu 声母不同（l 与 t），意思是楼房。", "愁": "chóu 与 tóu 声母不同（ch 与 t），意思是忧愁。"}, "sentence_index": null, "correct_answer": "投"}, "level_3": {"options": [{"text": "投", "is_correct": true, "explanation": "投：用力把球抛出去，与“用力”“向远处”相符。"}, {"text": "抱", "is_correct": false, "explanation": "语义：“抱”是用手臂环住，不能把球抛向远处。"}, {"text": "接", "is_correct": false, "explanation": "语义：“接”是承接飞来的东西，不能表示用力把球送出去。"}, {"text": "吹", "is_correct": false, "explanation": "搭配：“吹”多指吹气，不能说吹着球飞向远处。"}], "explanations": {"投": "投：用力把球抛出去，与“用力”“向远处”相符。", "抱": "语义：“抱”是用手臂环住，不能把球抛向远处。", "接": "语义：“接”是承接飞来的东西，不能表示用力把球送出去。", "吹": "搭配：“吹”多指吹气，不能说吹着球飞向远处。"}, "sentence_index": 0, "correct_answer": "投"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他小心翼翼地把钥匙投在了桌上。", "explanation": "这里应该用〈放〉。“投”含用力扔出去的意思，与“小心翼翼”的轻放动作矛盾，把钥匙轻轻安放在桌上要用“放”。"}, {"text": "他把水投进了杯子里。", "explanation": "这里应该用〈倒〉。倒水是把液体注入容器，“投”是用力扔出去，不能说把水投进杯子。"}, {"text": "他轻轻地把画投在了墙上。", "explanation": "这里应该用〈挂〉。挂是把画悬挂在墙上，“投”含用力扔出去的意思，与“轻轻”的动作矛盾，不能说把画投在墙上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85947, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "投", "is_correct": true, "explanation": "投（tóu）是用力把东西扔向前方，是本题的正确答案。"}, {"text": "猴", "is_correct": false, "explanation": "hóu 与 tóu 声母不同（h 与 t），意思是猴子。"}, {"text": "同", "is_correct": false, "explanation": "tóng 与 tóu 韵母不同（ong 与 ou），意思是相同。"}, {"text": "仇", "is_correct": false, "explanation": "chóu 与 tóu 声母不同（ch 与 t），意思是仇恨。"}, {"text": "筹", "is_correct": false, "explanation": "chóu 与 tóu 声母不同（ch 与 t），意思是筹划、筹集。"}], "explanations": {"投": "投（tóu）是用力把东西扔向前方，是本题的正确答案。", "猴": "hóu 与 tóu 声母不同（h 与 t），意思是猴子。", "同": "tóng 与 tóu 韵母不同（ong 与 ou），意思是相同。", "仇": "chóu 与 tóu 声母不同（ch 与 t），意思是仇恨。", "筹": "chóu 与 tóu 声母不同（ch 与 t），意思是筹划、筹集。"}, "sentence_index": null, "correct_answer": "投"}, "level_3": {"options": [{"text": "投", "is_correct": true, "explanation": "投：把雪球抛向目标，与“向树上的鸟”搭配。"}, {"text": "捏", "is_correct": false, "explanation": "搭配：“捏”是用手聚拢做形状，不能把雪球抛向鸟。"}, {"text": "堆", "is_correct": false, "explanation": "语义：“堆”是聚积堆放，不能表示把雪球射向目标。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是用水清洁东西，不能表示把雪球抛向鸟。"}], "explanations": {"投": "投：把雪球抛向目标，与“向树上的鸟”搭配。", "捏": "搭配：“捏”是用手聚拢做形状，不能把雪球抛向鸟。", "堆": "语义：“堆”是聚积堆放，不能表示把雪球射向目标。", "洗": "语义：“洗”是用水清洁东西，不能表示把雪球抛向鸟。"}, "sentence_index": 6, "correct_answer": "投"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把那双旧鞋投成了新的。", "explanation": "这里应该用〈换〉。把旧的换成新的要用“换”，“投”是抛出的意思，没有变化的含义，不能说投成新的。"}, {"text": "她把脚投向了门口。", "explanation": "这里应该用〈迈〉。“投”指用力扔出去，抬脚向前走要用“迈”，不能说把脚投向门口。"}, {"text": "她把长头发投成了短发。", "explanation": "这里应该用〈剪〉。把长发变短要用“剪”，“投”是用力扔出去，不能表示改变头发的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85947, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把球投了进篮筐。", "corrected_sentence": "他把球投进了篮筐。", "error_description": "错误：“投了进”。正确：“投进了”。“投”后接方向补语“进”时，“了”应放在补语之后，不能放在“投”和“进”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85947, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把旧报纸进投了纸箱。", "corrected_sentence": "妈妈把旧报纸投进了纸箱。", "error_description": "错误：“进投了”。正确：“投进了”。“进”是“投”的结果补语，应紧跟在“投”之后，不能放在“投”前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
