INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85948, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "扔；掷；也指放进去、送出去。", "primary_collocate": null, "pronunciation": "tóu", "ipa": "tʰou̯˧˥", "syllable_count": 1, "sentences": [{"text": "他把信投进了路边的邮筒。", "target_word": "投", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请往机器里投一块钱。", "target_word": "投", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这个空瓶子投进回收箱。", "target_word": "投", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给三家公司投过简历。", "target_word": "投", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他往杂志社投了一篇文章。", "target_word": "投", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人只能往一家公司投一份简历。", "target_word": "投", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把硬币投进了小盒子里。", "target_word": "投", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把申请表投到了办公室的箱子里。", "target_word": "投", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的意见投进这个箱子。", "target_word": "投", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我要把这封信投出去。", "target_word": "投", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "投了", "label": "完成体"}, {"form": "投过", "label": "经验体"}, {"form": "投着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "投：把东西放进去或送出去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '528460c6-b68d-4819-9976-ec879930a8cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85948, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "投", "is_correct": true, "explanation": "投（tóu）在本义上是把东西放进去或送出去，是本题的正确答案。"}, {"text": "偷", "is_correct": false, "explanation": "tōu（第一声）与 tóu（第二声）声调不同，意思是偷窃。"}, {"text": "楼", "is_correct": false, "explanation": "lóu 与 tóu 声母不同（l 与 t），意思是楼房。"}, {"text": "猴", "is_correct": false, "explanation": "hóu 与 tóu 声母不同（h 与 t），意思是猴子。"}, {"text": "愁", "is_correct": false, "explanation": "chóu 与 tóu 声母不同（ch 与 t），意思是忧愁。"}], "explanations": {"投": "投（tóu）在本义上是把东西放进去或送出去，是本题的正确答案。", "偷": "tōu（第一声）与 tóu（第二声）声调不同，意思是偷窃。", "楼": "lóu 与 tóu 声母不同（l 与 t），意思是楼房。", "猴": "hóu 与 tóu 声母不同（h 与 t），意思是猴子。", "愁": "chóu 与 tóu 声母不同（ch 与 t），意思是忧愁。"}, "sentence_index": null, "correct_answer": "投"}, "level_3": {"options": [{"text": "投", "is_correct": true, "explanation": "投：把信投入邮筒，与“进”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下，信件不能被吃进邮筒。"}, {"text": "捞", "is_correct": false, "explanation": "语义：“捞”是从水里取出东西，与“进”的方向相反。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”多用于较大的物件，不能说把信搬进邮筒。"}], "explanations": {"投": "投：把信投入邮筒，与“进”搭配。", "吃": "语义：“吃”指把食物咽下，信件不能被吃进邮筒。", "捞": "语义：“捞”是从水里取出东西，与“进”的方向相反。", "搬": "搭配：“搬”多用于较大的物件，不能说把信搬进邮筒。"}, "sentence_index": 0, "correct_answer": "投"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把作业投成了纸团。", "explanation": "这里应该用〈揉〉。把纸揉成团要用“揉”，“投”是抛出，不能表示揉成团的动作。"}, {"text": "他小心地把合同投在了桌上。", "explanation": "这里应该用〈放〉。“投”是把东西放进开口（如邮筒、箱子）或送出去，把合同小心地搁在桌面上要用“放”。"}, {"text": "他动作很轻，把外套投在了衣架上。", "explanation": "这里应该用〈挂〉。挂是把衣物悬挂起来，“投”是把东西放进开口或送出去，不能说把外套投在衣架上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85948, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "投", "is_correct": true, "explanation": "投（tóu）在本义上是把东西放进去或送出去，是本题的正确答案。"}, {"text": "透", "is_correct": false, "explanation": "tòu（第四声）与 tóu（第二声）声调不同，意思是透明、穿透。"}, {"text": "同", "is_correct": false, "explanation": "tóng 与 tóu 韵母不同（ong 与 ou），意思是相同。"}, {"text": "仇", "is_correct": false, "explanation": "chóu 与 tóu 声母不同（ch 与 t），意思是仇恨。"}, {"text": "绸", "is_correct": false, "explanation": "chóu 与 tóu 声母不同（ch 与 t），意思是丝绸。"}], "explanations": {"投": "投（tóu）在本义上是把东西放进去或送出去，是本题的正确答案。", "透": "tòu（第四声）与 tóu（第二声）声调不同，意思是透明、穿透。", "同": "tóng 与 tóu 韵母不同（ong 与 ou），意思是相同。", "仇": "chóu 与 tóu 声母不同（ch 与 t），意思是仇恨。", "绸": "chóu 与 tóu 声母不同（ch 与 t），意思是丝绸。"}, "sentence_index": null, "correct_answer": "投"}, "level_3": {"options": [{"text": "投", "is_correct": true, "explanation": "投：把硬币放进小盒子里，与“进”“里”搭配。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”指咽下，硬币不能被吞进小盒子里。"}, {"text": "掏", "is_correct": false, "explanation": "语义：“掏”是从里面取出，与“进”的方向相反。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”指摩擦，不能用来表示把硬币送进盒子。"}], "explanations": {"投": "投：把硬币放进小盒子里，与“进”“里”搭配。", "吞": "语义：“吞”指咽下，硬币不能被吞进小盒子里。", "掏": "语义：“掏”是从里面取出，与“进”的方向相反。", "擦": "搭配：“擦”指摩擦，不能用来表示把硬币送进盒子。"}, "sentence_index": 6, "correct_answer": "投"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把墙投成了白色。", "explanation": "这里应该用〈刷〉。给墙上颜色要用“刷”，“投”是把东西放进去或送出去，不能改变墙的颜色。"}, {"text": "我把帽子投在了头上。", "explanation": "这里应该用〈戴〉。把帽子放到头上要用“戴”，“投”指放进开口或送出去，不能用于穿戴。"}, {"text": "我把礼物投给了妈妈。", "explanation": "这里应该用〈送〉。送礼物给人要用“送”，“投给”多指投票或朝人抛出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把明信片投出了信箱。", "corrected_sentence": "我把明信片投进了信箱。", "error_description": "错误：“投出了信箱”。正确：“投进了信箱”。“出”表示由内向外，把明信片放入信箱要用“进”，说“投出了”意思相反。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "张老师把表格投给了收件箱。", "corrected_sentence": "张老师把表格投进了收件箱。", "error_description": "错误：“投给了收件箱”。正确：“投进了收件箱”。“给”表示送给人或投票，收件箱是地点，应使用方向补语“进”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bab692ef-45f0-4079-8daf-0f43695eb31d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85949, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "之前", "is_correct": true, "explanation": "反义：“下班之前”与“下班之后”的时间先后相反。"}, {"text": "傍晚", "is_correct": false, "explanation": "无关：“傍晚”是一天中的时段，与“之后”没有反义或近义关系。"}, {"text": "清晨", "is_correct": false, "explanation": "无关：“清晨”是一天中的时段，与“之后”没有反义或近义关系。"}, {"text": "中午", "is_correct": false, "explanation": "无关：“中午”是一天中的时段，与“之后”没有反义或近义关系。"}], "correct_answer": "之前", "explanations": {"之前": "反义：“下班之前”与“下班之后”的时间先后相反。", "傍晚": "无关：“傍晚”是一天中的时段，与“之后”没有反义或近义关系。", "清晨": "无关：“清晨”是一天中的时段，与“之后”没有反义或近义关系。", "中午": "无关：“中午”是一天中的时段，与“之后”没有反义或近义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85949, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "之前", "is_correct": true, "explanation": "反义：“看完这本书之前”与“看完这本书之后”的时间先后相反。"}, {"text": "深夜", "is_correct": false, "explanation": "无关：“深夜”是一天中的时段，与“之后”没有反义或近义关系。"}, {"text": "黎明", "is_correct": false, "explanation": "无关：“黎明”是一天中的时段，与“之后”没有反义或近义关系。"}, {"text": "午夜", "is_correct": false, "explanation": "无关：“午夜”是一天中的时段，与“之后”没有反义或近义关系。"}], "correct_answer": "之前", "explanations": {"之前": "反义：“看完这本书之前”与“看完这本书之后”的时间先后相反。", "深夜": "无关：“深夜”是一天中的时段，与“之后”没有反义或近义关系。", "黎明": "无关：“黎明”是一天中的时段，与“之后”没有反义或近义关系。", "午夜": "无关：“午夜”是一天中的时段，与“之后”没有反义或近义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85949, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“之后”是说在某件事或某个时间的后面，表示那以后。", "primary_collocate": null, "pronunciation": "zhī hòu", "ipa": "ʈʂɻ̩⁵⁵ xoʊ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "下班之后，我常常去跑步。", "target_word": "之后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完晚饭之后，他回房间看书了。", "target_word": "之后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三年之后，她又回到了这座城市。", "target_word": "之后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业之后，我想去北京工作。", "target_word": "之后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停之后，天空变得很蓝。", "target_word": "之后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会之后，经理请大家吃饭。", "target_word": "之后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到家之后，请给我打个电话。", "target_word": "之后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十点之后，这条路上车很少。", "target_word": "之后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家之后，我认识了新邻居。", "target_word": "之后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完这本书之后，我明白了很多。", "target_word": "之后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "之後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用在某事或某个时间后面，表示那以后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1dfd233-60e1-4be7-a6ef-22ae12c1f292') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85949, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "之内", "is_correct": false, "explanation": "语义：“之内”表示在某个范围里面，与“下班”这个时间点不合。"}, {"text": "之间", "is_correct": false, "explanation": "搭配：“之间”要有两端的时间或地点，这里只有“下班”一个点。"}, {"text": "之中", "is_correct": false, "explanation": "语义：“之中”指在某个过程里面，与“下班”这一时间点不合。"}, {"text": "之后", "is_correct": true, "explanation": "表示下班这个时间点以后再去跑步，符合句意。"}], "explanations": {"之内": "语义：“之内”表示在某个范围里面，与“下班”这个时间点不合。", "之间": "搭配：“之间”要有两端的时间或地点，这里只有“下班”一个点。", "之中": "语义：“之中”指在某个过程里面，与“下班”这一时间点不合。", "之后": "表示下班这个时间点以后再去跑步，符合句意。"}, "sentence_index": 0, "correct_answer": "之后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校之后有一个很大的公园。", "explanation": "这里〈之后〉表示空间位置，应说〈后面〉。〈之后〉用于时间，说的是某件事以后。"}, {"text": "我们一边吃饭，之后一起聊天。", "explanation": "这里应该用〈同时〉。〈之后〉表示先后顺序，这里两件事同时进行，不能用〈之后〉连接。"}, {"text": "我买了苹果之后香蕉。", "explanation": "这里应该用〈和〉。〈之后〉表示时间先后，不能连接并列的事物；并列的名词要用〈和〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85949, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "之后", "is_correct": true, "explanation": "表示到家这个时间点以后再打电话，符合句意。"}, {"text": "之上", "is_correct": false, "explanation": "语义：“之上”表示位置在上面，与“到家”这个时间点不合。"}, {"text": "之下", "is_correct": false, "explanation": "搭配：“之下”要接在某种条件或范围后面，这里不成立。"}, {"text": "之外", "is_correct": false, "explanation": "语义：“之外”表示范围以外，与“到家”的时间关系不符。"}], "explanations": {"之后": "表示到家这个时间点以后再打电话，符合句意。", "之上": "语义：“之上”表示位置在上面，与“到家”这个时间点不合。", "之下": "搭配：“之下”要接在某种条件或范围后面，这里不成立。", "之外": "语义：“之外”表示范围以外，与“到家”的时间关系不符。"}, "sentence_index": 6, "correct_answer": "之后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "之后下班，我常常去跑步。", "explanation": "语序错误：〈之后〉要放在表示事情或时间的词语后面，应说“下班之后”。"}, {"text": "我之后正在吃饭。", "explanation": "〈之后〉指以后，与“正在”表示的当前进行相矛盾；正在进行的动作不能用〈之后〉来定位。"}, {"text": "我家之后有一条小河。", "explanation": "这里应该用〈后面〉。〈之后〉表示时间上的以后，不表示空间位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85949, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两年之后之后，我们再见面。", "corrected_sentence": "两年之后，我们再见面。", "error_description": "〈之后〉重复。“两年之后”中的“之后”已表示时间，后面不能再加“之后”，应只说“两年之后”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85949, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们下完课之后的去吃饭。", "corrected_sentence": "我们下完课之后去吃饭。", "error_description": "“之后”后多加了“的”。错误形式：之后的去吃饭；正确形式：之后去吃饭。“之后”后面直接接动词，不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85950, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "之前", "is_correct": true, "explanation": "反义：“之前”与“之后”表示时间先后相反，“先洗手”在“吃东西”之前。"}, {"text": "中间", "is_correct": false, "explanation": "语义：“中间”表示位置，不表示时间先后，与“之后”不构成反义。"}, {"text": "旁边", "is_correct": false, "explanation": "语义：“旁边”表示空间位置，与表示时间的“之后”没有反义关系。"}, {"text": "时候", "is_correct": false, "explanation": "语义：“时候”指时间点，与“之后”表示的先后关系不构成反义。"}], "correct_answer": "之前", "explanations": {"之前": "反义：“之前”与“之后”表示时间先后相反，“先洗手”在“吃东西”之前。", "中间": "语义：“中间”表示位置，不表示时间先后，与“之后”不构成反义。", "旁边": "语义：“旁边”表示空间位置，与表示时间的“之后”没有反义关系。", "时候": "语义：“时候”指时间点，与“之后”表示的先后关系不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85950, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85950, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“之后”单用，表示先做一件事，接着再做另一件事。", "primary_collocate": null, "pronunciation": "zhī hòu", "ipa": "ʈʂɻ̩⁵⁵ xoʊ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "我们先吃饭，之后一起去公园。", "target_word": "之后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先写作业，之后才看电视。", "target_word": "之后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师先讲课，之后让大家做练习。", "target_word": "之后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先洗手，之后再吃东西。", "target_word": "之后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先去银行，之后去买菜。", "target_word": "之后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她先打了电话，之后就出门了。", "target_word": "之后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把门关好，之后你再走。", "target_word": "之后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先看电影，之后去喝咖啡。", "target_word": "之后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先坐地铁，之后换了公共汽车。", "target_word": "之后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先学会走路，之后才能学跑步。", "target_word": "之后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "之後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "单用，表示先做一件事，之后再做另一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1dfd233-60e1-4be7-a6ef-22ae12c1f292') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85950, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同时", "is_correct": false, "explanation": "语义：“同时”表示两件事一起发生，与“先吃饭”的先后顺序冲突。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已完成，与还没发生的“一起去公园”不合。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：“刚才”指过去的时间，不能引出接在“先吃饭”后面、将要进行的“去公园”。"}, {"text": "之后", "is_correct": true, "explanation": "表示先吃饭，之后再一起去公园，先后顺序正确。"}], "explanations": {"同时": "语义：“同时”表示两件事一起发生，与“先吃饭”的先后顺序冲突。", "已经": "体貌：“已经”表示动作已完成，与还没发生的“一起去公园”不合。", "刚才": "语义：“刚才”指过去的时间，不能引出接在“先吃饭”后面、将要进行的“去公园”。", "之后": "表示先吃饭，之后再一起去公园，先后顺序正确。"}, "sentence_index": 0, "correct_answer": "之后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们之后吃饭，先去公园。", "explanation": "顺序错误：〈之后〉引出后做的事，应说“先吃饭，之后去公园”，不能把〈之后〉放在先做的事前面。"}, {"text": "我们一边吃饭，之后一起聊天。", "explanation": "这里应该用〈同时〉。〈之后〉表示先后顺序，这里两件事同时进行，不能用〈之后〉连接。"}, {"text": "房子之后有一棵大树。", "explanation": "这里〈之后〉表示空间位置，应该说〈后面〉。〈之后〉在这里只用于时间或动作的先后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85950, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "之后", "is_correct": true, "explanation": "表示先把门关好，之后再走，先后顺序正确。"}, {"text": "偶尔", "is_correct": false, "explanation": "体貌：“偶尔”表示不定期地发生，与“先把门关好”后的一次性动作不合。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示出乎意料，与“先把门关好”的有计划顺序不符。"}, {"text": "结果", "is_correct": false, "explanation": "语义：“结果”表示因果，与“先把门关好”的先后关系不符。"}], "explanations": {"之后": "表示先把门关好，之后再走，先后顺序正确。", "偶尔": "体貌：“偶尔”表示不定期地发生，与“先把门关好”后的一次性动作不合。", "忽然": "语义：“忽然”表示出乎意料，与“先把门关好”的有计划顺序不符。", "结果": "语义：“结果”表示因果，与“先把门关好”的先后关系不符。"}, "sentence_index": 6, "correct_answer": "之后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他之后洗澡，先换了衣服。", "explanation": "顺序错误：〈之后〉引出后做的事，应说“先洗澡，之后换了衣服”。"}, {"text": "我买了苹果之后香蕉。", "explanation": "这里应该用〈和〉。〈之后〉表示时间先后，不能连接并列的事物；并列的名词要用〈和〉。"}, {"text": "我之后正在吃饭。", "explanation": "〈之后〉指以后，与“正在”表示的当前进行相矛盾；正在进行的动作不能用〈之后〉来定位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她先去超市，之后之后去了图书馆。", "corrected_sentence": "她先去超市，之后去了图书馆。", "error_description": "“之后”重复使用，只需一次。错误形式：之后之后；正确形式：之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他先洗澡，之后的换了衣服。", "corrected_sentence": "他先洗澡，之后换了衣服。", "error_description": "“之后”后多加了“的”。错误形式：之后的换了衣服；正确形式：之后换了衣服。“之后”后面直接接动词短语，不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
