INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85951, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "挂是把东西吊在高处，不让它掉下来。", "primary_collocate": null, "pronunciation": "guà", "ipa": "kua˥˩", "syllable_count": 1, "sentences": [{"text": "他把画挂在墙上。", "target_word": "挂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把衣服挂在门后面。", "target_word": "挂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把新窗帘挂好了。", "target_word": "挂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，我们把红灯笼挂起来。", "target_word": "挂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把照片挂在床边。", "target_word": "挂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把地图挂在黑板旁边。", "target_word": "挂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把帽子挂在这里吧。", "target_word": "挂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸正在挂一幅大画。", "target_word": "挂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在房间里挂一张世界地图。", "target_word": "挂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把包挂在椅子上，就出去了。", "target_word": "挂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挂了", "label": "体标"}, {"form": "挂着", "label": "体标"}, {"form": "挂过", "label": "体标"}, {"form": "悬挂", "label": "复合"}, {"form": "掛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把东西吊在高处使它不掉下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef0daaba-e68b-4c3c-a684-5319cdf29e05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85951, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "挂", "is_correct": true, "explanation": "挂（guà，第四声）：把东西吊在高处，使它不掉下来。"}, {"text": "瓜", "is_correct": false, "explanation": "guā（第一声）与 guà（第四声）声调不同，意思是瓜。"}, {"text": "怪", "is_correct": false, "explanation": "guài 与 guà 韵母不同（ai 与 a），意思是奇怪。"}, {"text": "跨", "is_correct": false, "explanation": "kuà 与 guà 声母不同（k 送气，g 不送气），意思是跨越。"}, {"text": "逛", "is_correct": false, "explanation": "guàng 比 guà 多了韵尾 -ng，意思是闲逛。"}], "explanations": {"挂": "挂（guà，第四声）：把东西吊在高处，使它不掉下来。", "瓜": "guā（第一声）与 guà（第四声）声调不同，意思是瓜。", "怪": "guài 与 guà 韵母不同（ai 与 a），意思是奇怪。", "跨": "kuà 与 guà 声母不同（k 送气，g 不送气），意思是跨越。", "逛": "guàng 比 guà 多了韵尾 -ng，意思是闲逛。"}, "sentence_index": null, "correct_answer": "挂"}, "level_3": {"options": [{"text": "挂", "is_correct": true, "explanation": "正确：“挂”表示把画吊在高处，与“墙上”相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，画不能被吃，“在墙上”也不合。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语是衣物、鞋袜，不能用于“画”。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”需要用牙齿接触对象，挂在墙上的画不能被咬。"}], "explanations": {"挂": "正确：“挂”表示把画吊在高处，与“墙上”相合。", "吃": "语义：“吃”的对象是食物，画不能被吃，“在墙上”也不合。", "穿": "搭配：“穿”的宾语是衣物、鞋袜，不能用于“画”。", "咬": "语义：“咬”需要用牙齿接触对象，挂在墙上的画不能被咬。"}, "sentence_index": 0, "correct_answer": "挂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把邮票挂在信封的右上角。", "explanation": "这里应该用〈贴〉。挂要求物体借助钩子等悬空，邮票是平贴在信封上的，要用贴。"}, {"text": "我把书挂在桌子上，就去吃饭了。", "explanation": "这里应该用〈放〉。挂要求物体悬空，桌上的书是平放的，要用放。"}, {"text": "他把旗子挂在土里，就去吃饭了。", "explanation": "这里应该用〈插〉。挂表示悬在高处，旗子是插在土里固定的，要用插。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85951, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "挂", "is_correct": true, "explanation": "挂（guà，第四声）：把东西吊在高处，使它不掉下来。"}, {"text": "刮", "is_correct": false, "explanation": "guā（第一声）与 guà（第四声）声调不同，意思是刮掉。"}, {"text": "惯", "is_correct": false, "explanation": "guàn 比 guà 多了韵尾 -n，意思是习惯。"}, {"text": "过", "is_correct": false, "explanation": "guò 与 guà 韵母不同（o 与 a），意思是经过。"}], "explanations": {"挂": "挂（guà，第四声）：把东西吊在高处，使它不掉下来。", "刮": "guā（第一声）与 guà（第四声）声调不同，意思是刮掉。", "惯": "guàn 比 guà 多了韵尾 -n，意思是习惯。", "过": "guò 与 guà 韵母不同（o 与 a），意思是经过。"}, "sentence_index": null, "correct_answer": "挂"}, "level_3": {"options": [{"text": "挂", "is_correct": true, "explanation": "正确：“挂”表示把帽子悬挂起来，与“挂在这里”相合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，“帽子”不能被吃。"}, {"text": "笑", "is_correct": false, "explanation": "语义：“笑”的主体须是人，帽子不能笑。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食材或水，不能用于“帽子”。"}], "explanations": {"挂": "正确：“挂”表示把帽子悬挂起来，与“挂在这里”相合。", "吃": "搭配：“吃”的宾语是食物，“帽子”不能被吃。", "笑": "语义：“笑”的主体须是人，帽子不能笑。", "煮": "搭配：“煮”的对象是食材或水，不能用于“帽子”。"}, "sentence_index": 6, "correct_answer": "挂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把茶杯挂在桌子上，然后去接电话了。", "explanation": "这里应该用〈摆〉。挂要借助钩子等悬空，茶杯平放在桌上，要用摆。"}, {"text": "他把碗挂在灶台边，然后去洗手了。", "explanation": "这里应该用〈搁〉。挂要求东西悬空，碗搁在灶台边是平放的，应该用搁。"}, {"text": "他把地毯挂在地上，然后坐在上面看书。", "explanation": "这里应该用〈铺〉。挂要求东西悬空，地毯是铺在地面上的，要用铺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85951, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把相框挂在门口挂了。", "corrected_sentence": "她把相框挂在门口了。", "error_description": "错误形式：“她把相框挂在门口挂了”；正确形式：“她把相框挂在门口了”。动词“挂”在这里重复出现，应删去多余的一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85951, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "墙上挂了着一幅很大的画。", "corrected_sentence": "墙上挂着一幅很大的画。", "error_description": "错误形式：“挂了着”；正确形式：“挂着”。描写墙上存在的状态要用“挂着”，“了”和“着”不能同时跟在“挂”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e92e3d5-8d9d-493c-b7f7-4117e7530e90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
