INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85954, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动词，请别人回答自己不明白的事；也指询问、探究。", "primary_collocate": null, "pronunciation": "wèn", "ipa": "wən˥˩", "syllable_count": 1, "sentences": [{"text": "他停下车，问一位老人怎么走。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想问一下，这件衣服多少钱？", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她走进店里问价钱。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你问清楚，明天几点开会。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去问一下，火车站怎么走。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打电话问了医院的开门时间。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他到处问，才找到那家书店。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问清楚了事情的原因。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在问自己为什么要这样做。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问过售货员，这里没有卖。", "target_word": "问", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "问了", "label": "体标"}, {"form": "问过", "label": "体标"}, {"form": "问问", "label": "重叠"}, {"form": "問", "label": "繁体"}], "register": "中性", "sense_fingerprint": "询问打听、探究", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e3854f-4e11-4bc9-a35e-a40d78ee0dbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85954, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "文", "is_correct": false, "explanation": "wén（第二声）与 wèn（第四声）声调不同，意思是文字、文章。"}, {"text": "问", "is_correct": true, "explanation": "正确答案：问（wèn），询问打听，探究不明白的事。"}, {"text": "吻", "is_correct": false, "explanation": "wěn（第三声）与 wèn（第四声）声调不同，意思是亲吻。"}, {"text": "蚊", "is_correct": false, "explanation": "wén（第二声）与 wèn（第四声）声调不同，意思是蚊子。"}], "explanations": {"文": "wén（第二声）与 wèn（第四声）声调不同，意思是文字、文章。", "问": "正确答案：问（wèn），询问打听，探究不明白的事。", "吻": "wěn（第三声）与 wèn（第四声）声调不同，意思是亲吻。", "蚊": "wén（第二声）与 wèn（第四声）声调不同，意思是蚊子。"}, "sentence_index": null, "correct_answer": "问"}, "level_3": {"options": [{"text": "问", "is_correct": true, "explanation": "正确：问，向人打听，这里是“问路”，即向老人询问怎么走。"}, {"text": "扶", "is_correct": false, "explanation": "语义：“扶”是搀扶，与“问路”的意思不符。"}, {"text": "摸", "is_correct": false, "explanation": "搭配：“摸”不能带“一位老人怎么走”这样的内容，搭配不当。"}, {"text": "推", "is_correct": false, "explanation": "配价：“推”的宾语是人或物，不能接“怎么走”作内容。"}], "explanations": {"问": "正确：问，向人打听，这里是“问路”，即向老人询问怎么走。", "扶": "语义：“扶”是搀扶，与“问路”的意思不符。", "摸": "搭配：“摸”不能带“一位老人怎么走”这样的内容，搭配不当。", "推": "配价：“推”的宾语是人或物，不能接“怎么走”作内容。"}, "sentence_index": 0, "correct_answer": "问"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他蹲在路边问了一只小猫。", "explanation": "这里应该用〈逗〉。问是请人回答或探究事情，不能用来指逗猫。"}, {"text": "工人问了这台机器。", "explanation": "这里应该用〈修〉。“问”指询问或探究事情，不能用于机器，修机器要用“修”。"}, {"text": "护士问了那支针。", "explanation": "这里应该用〈打〉。“问”不能用于针剂，给人打针要用“打”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85954, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "温", "is_correct": false, "explanation": "wēn（第一声）与 wèn（第四声）声调不同，意思是温暖。"}, {"text": "问", "is_correct": true, "explanation": "正确答案：问（wèn），询问打听，探究不明白的事。"}, {"text": "稳", "is_correct": false, "explanation": "wěn（第三声）与 wèn（第四声）声调不同，意思是稳定。"}, {"text": "闻", "is_correct": false, "explanation": "wén（第二声）与 wèn（第四声）声调不同，意思是听见、闻到。"}], "explanations": {"温": "wēn（第一声）与 wèn（第四声）声调不同，意思是温暖。", "问": "正确答案：问（wèn），询问打听，探究不明白的事。", "稳": "wěn（第三声）与 wèn（第四声）声调不同，意思是稳定。", "闻": "wén（第二声）与 wèn（第四声）声调不同，意思是听见、闻到。"}, "sentence_index": null, "correct_answer": "问"}, "level_3": {"options": [{"text": "问", "is_correct": true, "explanation": "正确：问，向人打听，这里是“到处问”，即四处打听。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不表示寻找的方式，“到处吃”与“找到书店”无关。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与寻找的方式不相容，句意不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“到处洗”不能表示寻找，与“找到书店”搭配不当。"}], "explanations": {"问": "正确：问，向人打听，这里是“到处问”，即四处打听。", "吃": "语义：“吃”不表示寻找的方式，“到处吃”与“找到书店”无关。", "唱": "语义：“唱”与寻找的方式不相容，句意不通。", "洗": "搭配：“到处洗”不能表示寻找，与“找到书店”搭配不当。"}, "sentence_index": 6, "correct_answer": "问"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他随手问了那扇门。", "explanation": "这里应该用〈关〉。“问”不能用于门这样的物体，关门要用“关”。"}, {"text": "公司问了那辆货车。", "explanation": "这里应该用〈开〉。“问”不能用于车辆，开货车要用“开”。"}, {"text": "医生问了那把手术刀。", "explanation": "这里应该用〈消毒〉。“问”不能用于器械，给手术刀消毒要用“消毒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85954, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想把他问一个问题。", "corrected_sentence": "我想问他一个问题。", "error_description": "把字句误用：“问”带双宾语时不用“把”，应说“问他一个问题”，不能说“把他问一个问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85954, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我问他了三次，他都没回答。", "corrected_sentence": "我问了他三次，他都没回答。", "error_description": "动态助词“了”位置错误：“了”须紧跟动词，应说“问了他三次”，不能说“问他了三次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85955, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "黑", "is_correct": true, "explanation": "“黑”与“白”相对，同为颜色词，是反义词。"}, {"text": "绿", "is_correct": false, "explanation": "“绿”也是颜色，但与“白”不构成反义关系。"}, {"text": "快", "is_correct": false, "explanation": "“快”说速度，与“白”没有反义关系。"}, {"text": "甜", "is_correct": false, "explanation": "“甜”说味道，与“白”没有反义关系。"}], "correct_answer": "黑", "explanations": {"黑": "“黑”与“白”相对，同为颜色词，是反义词。", "绿": "“绿”也是颜色，但与“白”不构成反义关系。", "快": "“快”说速度，与“白”没有反义关系。", "甜": "“甜”说味道，与“白”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85955, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "黑", "is_correct": true, "explanation": "“黑”与“白”相对，同为颜色词，是反义词。"}, {"text": "大", "is_correct": false, "explanation": "“大”说大小，与“白”没有反义关系。"}, {"text": "高", "is_correct": false, "explanation": "“高”说高低，与“白”没有反义关系。"}, {"text": "长", "is_correct": false, "explanation": "“长”说长短，与“白”没有反义关系。"}], "correct_answer": "黑", "explanations": {"黑": "“黑”与“白”相对，同为颜色词，是反义词。", "大": "“大”说大小，与“白”没有反义关系。", "高": "“高”说高低，与“白”没有反义关系。", "长": "“长”说长短，与“白”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85955, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "白是像雪和牛奶那样的颜色。", "primary_collocate": null, "pronunciation": "bái", "ipa": "pai˧˥", "syllable_count": 1, "sentences": [{"text": "天上的云很白。", "target_word": "白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米饭是白的，酱油是黑的。", "target_word": "白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病了，脸色白得很难看。", "target_word": "白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一件白的，不要红的。", "target_word": "白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这朵花是白的，那朵是黄的。", "target_word": "白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗的毛又白又软。", "target_word": "白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪下得很大，外面都白了。", "target_word": "白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的牙齿很白。", "target_word": "白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的头发已经白了。", "target_word": "白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白的比黑的更容易脏。", "target_word": "白", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "白：像雪和牛奶那样的颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f239b726-4c9e-4af2-9b42-8368eb77c8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85955, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "白", "is_correct": true, "explanation": "白 bái（第二声）是像雪和牛奶那样的颜色。"}, {"text": "百", "is_correct": false, "explanation": "百 bǎi（第三声）与 bái（第二声）声调不同，意思是一百。"}, {"text": "败", "is_correct": false, "explanation": "败 bài（第四声）与 bái（第二声）声调不同，意思是失败。"}, {"text": "排", "is_correct": false, "explanation": "排 pái 与 bái 声母不同（b 与 p），意思是排列。"}, {"text": "摆", "is_correct": false, "explanation": "摆 bǎi（第三声）与 bái（第二声）声调不同，意思是摆放。"}], "explanations": {"白": "白 bái（第二声）是像雪和牛奶那样的颜色。", "百": "百 bǎi（第三声）与 bái（第二声）声调不同，意思是一百。", "败": "败 bài（第四声）与 bái（第二声）声调不同，意思是失败。", "排": "排 pái 与 bái 声母不同（b 与 p），意思是排列。", "摆": "摆 bǎi（第三声）与 bái（第二声）声调不同，意思是摆放。"}, "sentence_index": null, "correct_answer": "白"}, "level_3": {"options": [{"text": "白", "is_correct": true, "explanation": "“天上的云很白”描写云的颜色，与“白”的颜色义相合。"}, {"text": "绿", "is_correct": false, "explanation": "语义：云一般不呈绿色，说“很绿”与句意不符。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，不能用来形容云。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”说质地，云一般不说“硬”，搭配不通。"}], "explanations": {"白": "“天上的云很白”描写云的颜色，与“白”的颜色义相合。", "绿": "语义：云一般不呈绿色，说“很绿”与句意不符。", "甜": "语义：“甜”说味道，不能用来形容云。", "硬": "搭配：“硬”说质地，云一般不说“硬”，搭配不通。"}, "sentence_index": 0, "correct_answer": "白"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "柠檬熟了以后是白的。", "explanation": "这里应该用〈黄〉。柠檬成熟后是黄色，“白”指白色，颜色用错了。"}, {"text": "成熟的番茄是白的，一口咬下去很甜。", "explanation": "这里应该用〈红〉。番茄成熟后是红色，“白”指白色，颜色用错了。"}, {"text": "墨水是白的，写出来的字很清楚。", "explanation": "这里应该用〈黑〉。墨水是黑色的，“白”指白色，与“黑”混淆了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85955, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "白", "is_correct": true, "explanation": "白 bái（第二声）是像雪和牛奶那样的颜色。"}, {"text": "埋", "is_correct": false, "explanation": "埋 mái 与 bái 声母不同（b 与 m），意思是埋藏。"}, {"text": "抬", "is_correct": false, "explanation": "抬 tái 与 bái 声母不同（b 与 t），意思是抬起。"}, {"text": "拜", "is_correct": false, "explanation": "拜 bài（第四声）与 bái（第二声）声调不同，意思是拜访或行礼。"}, {"text": "牌", "is_correct": false, "explanation": "牌 pái 与 bái 声母不同（b 与 p），意思是牌子或卡片。"}], "explanations": {"白": "白 bái（第二声）是像雪和牛奶那样的颜色。", "埋": "埋 mái 与 bái 声母不同（b 与 m），意思是埋藏。", "抬": "抬 tái 与 bái 声母不同（b 与 t），意思是抬起。", "拜": "拜 bài（第四声）与 bái（第二声）声调不同，意思是拜访或行礼。", "牌": "牌 pái 与 bái 声母不同（b 与 p），意思是牌子或卡片。"}, "sentence_index": null, "correct_answer": "白"}, "level_3": {"options": [{"text": "白", "is_correct": true, "explanation": "“外面都白了”说的是雪落后地面变白，与“白”的颜色义相合。"}, {"text": "宽", "is_correct": false, "explanation": "语义：“宽”说宽窄，外面不能说“宽了”，与句意不合。"}, {"text": "粗", "is_correct": false, "explanation": "搭配：“粗”说粗细，不用来描述大范围的环境，搭配不通。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”说速度，与“雪下得很大”的描写不合。"}], "explanations": {"白": "“外面都白了”说的是雪落后地面变白，与“白”的颜色义相合。", "宽": "语义：“宽”说宽窄，外面不能说“宽了”，与句意不合。", "粗": "搭配：“粗”说粗细，不用来描述大范围的环境，搭配不通。", "慢": "语义：“慢”说速度，与“雪下得很大”的描写不合。"}, "sentence_index": 6, "correct_answer": "白"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏天的树叶是白的，看起来很漂亮。", "explanation": "这里应该用〈绿〉。夏天的树叶是绿色的，“白”指白色，颜色用错了。"}, {"text": "乌鸦是白的，飞过天空很显眼。", "explanation": "这里应该用〈黑〉。乌鸦是黑色的，“白”指白色，与“黑”混淆了。"}, {"text": "熟透的草莓是白的，吃起来又甜又多汁。", "explanation": "这里应该用〈红〉。成熟的草莓是红色，“白”指白色，颜色用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85955, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的皮肤白像牛奶。", "corrected_sentence": "她的皮肤白得像牛奶。", "error_description": "“白”后接补语时要用“得”连接。“白像牛奶”不成句，应为“她的皮肤白得像牛奶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85955, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我爷爷的胡子了白。", "corrected_sentence": "我爷爷的胡子白了。", "error_description": "“白了”表示变成白色，“了”须紧跟在“白”后。“胡子了白”顺序颠倒，应为“胡子白了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a09b5fd-1f10-4481-8454-02aae73b5f5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
