INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85957, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "“对于”是说下面要讲的是哪一个人或哪一件事。", "primary_collocate": null, "pronunciation": "duì yú", "ipa": "tweɪ˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "对于学生来说，睡觉很重要。", "target_word": "对于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对于这个问题，我没有意见。", "target_word": "对于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对于我来说，汉字太难了。", "target_word": "对于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对于这件事，老师还不知道。", "target_word": "对于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对于中国菜，外国人有不同的看法。", "target_word": "对于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对于明天的比赛，我有点儿担心。", "target_word": "对于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对于老年人来说，散步是好运动。", "target_word": "对于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对于学习汉语，每天练习最重要。", "target_word": "对于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对于大城市的人来说，空气很重要。", "target_word": "对于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对于这次考试，同学们都很紧张。", "target_word": "对于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "對於", "label": "繁体"}], "register": "中性", "sense_fingerprint": "介词：引出所谈论的人或事（对于……来说）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2ce387-de1a-4dee-a2b5-d7f05cb692cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85957, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对于", "is_correct": true, "explanation": "正确：“对于”引出所谈论的对象，与“来说”搭配，句子意思是“就学生而言，睡觉很重要”。"}, {"text": "除了", "is_correct": false, "explanation": "语义：“除了”表示排除，“除了学生来说”会变成“学生以外”，与句子的谈论对象不符。"}, {"text": "通过", "is_correct": false, "explanation": "配价：“通过”要带一个凭借或途径作宾语，不能把“学生”直接作为谈论对象。"}, {"text": "因为", "is_correct": false, "explanation": "语法：“因为”引出原因，不能与“来说”组成框架，“因为学生来说”不成话。"}], "explanations": {"对于": "正确：“对于”引出所谈论的对象，与“来说”搭配，句子意思是“就学生而言，睡觉很重要”。", "除了": "语义：“除了”表示排除，“除了学生来说”会变成“学生以外”，与句子的谈论对象不符。", "通过": "配价：“通过”要带一个凭借或途径作宾语，不能把“学生”直接作为谈论对象。", "因为": "语法：“因为”引出原因，不能与“来说”组成框架，“因为学生来说”不成话。"}, "sentence_index": 0, "correct_answer": "对于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对于他笑了一下。", "explanation": "这里应该用〈对〉。“对于”只引出所谈论的人或事，不能表示动作朝向的对象，“对他笑”要用“对”。"}, {"text": "他对于老师请教问题。", "explanation": "这里应该用〈向〉。向别人请教要用“向”引出对象，“对于”不能引出动作的对象。"}, {"text": "他对于北方走去。", "explanation": "这里应该用〈向〉。表示朝某个方向移动要用“向”，“对于”不能引出动作的方向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85957, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对于", "is_correct": true, "explanation": "正确：“对于”引出所谈论的对象，与“来说”搭配，句子意思是“就老年人而言，散步是好运动”。"}, {"text": "面对", "is_correct": false, "explanation": "搭配：“面对”表示正面对着某人或某事，不能与“来说”组成谈论对象的框架。"}, {"text": "凭借", "is_correct": false, "explanation": "配价：“凭借”要带一个手段或条件作宾语，不能把“老年人”这样的人作为谈论对象。"}, {"text": "随着", "is_correct": false, "explanation": "语义：“随着”表示伴随某种变化，句子会变成“随着老年人”，与“散步是好运动”的判断不符。"}], "explanations": {"对于": "正确：“对于”引出所谈论的对象，与“来说”搭配，句子意思是“就老年人而言，散步是好运动”。", "面对": "搭配：“面对”表示正面对着某人或某事，不能与“来说”组成谈论对象的框架。", "凭借": "配价：“凭借”要带一个手段或条件作宾语，不能把“老年人”这样的人作为谈论对象。", "随着": "语义：“随着”表示伴随某种变化，句子会变成“随着老年人”，与“散步是好运动”的判断不符。"}, "sentence_index": 6, "correct_answer": "对于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我对于他一起去北京。", "explanation": "这里应该用〈跟〉。表示和某人一起做某事要用“跟”，“对于”只能引出所谈论的对象。"}, {"text": "他对于我高一点。", "explanation": "这里应该用〈比〉。表示两者比较要用“比”，“对于”不能表示比较。"}, {"text": "他对于我买了票。", "explanation": "这里应该用〈替〉。表示替别人做事要用“替”，“对于”不能表示替谁做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85957, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "对于的这次活动，大家都很期待。", "corrected_sentence": "对于这次活动，大家都很期待。", "error_description": "“对于”后面不能直接加“的”。错误形式是“对于的这次活动”，正确形式是“对于这次活动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85957, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "对于老师的来说，备课很重要。", "corrected_sentence": "对于老师来说，备课很重要。", "error_description": "“对于……来说”是一组固定框架，中间不能加“的”。错误形式是“对于老师的来说”，正确形式是“对于老师来说”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
