INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85959, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“由于”是说一件事的原因，后面的事是因为它才有的。", "primary_collocate": null, "pronunciation": "yóu yú", "ipa": "jou˧˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "由于他生病了，今天没来上课。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于这里太吵，我没有睡好。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于下雨了，我们没有去公园。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于路上堵车，爸爸回来得很晚。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于他很努力，成绩提高了不少。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于我没带钥匙，只好在门口等。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于她会说中文，公司请她当翻译。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于价格太贵，很多人不买。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于大家都很忙，会议改到了下周。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于我不知道地址，找了很久。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "由於", "label": "繁体"}], "register": "书面", "sense_fingerprint": "引出原因分句的连词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e3854f-4e11-4bc9-a35e-a40d78ee0dbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85959, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "由于", "is_correct": true, "explanation": "正确答案。“由于”是连词，引出原因分句。"}, {"text": "犹豫", "is_correct": false, "explanation": "与“由于”只有第二个音节声调不同（yù，第四声），意思是拿不定主意，不是引出原因。"}, {"text": "优于", "is_correct": false, "explanation": "与“由于”只有第一个音节声调不同（yōu，第一声），意思是比……更好。"}, {"text": "幼鱼", "is_correct": false, "explanation": "与“由于”只有第一个音节声调不同（yòu，第四声），意思是还没长大的小鱼。"}], "explanations": {"由于": "正确答案。“由于”是连词，引出原因分句。", "犹豫": "与“由于”只有第二个音节声调不同（yù，第四声），意思是拿不定主意，不是引出原因。", "优于": "与“由于”只有第一个音节声调不同（yōu，第一声），意思是比……更好。", "幼鱼": "与“由于”只有第一个音节声调不同（yòu，第四声），意思是还没长大的小鱼。"}, "sentence_index": null, "correct_answer": "由于"}, "level_3": {"options": [{"text": "由于", "is_correct": true, "explanation": "正确答案。“由于他生病了”引出今天没来上课的原因。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，这里前后没有转折关系。"}, {"text": "只要", "is_correct": false, "explanation": "语义：“只要”引出充分条件，表示有这一条件就够，与生病导致缺课的因果不符。"}, {"text": "无论", "is_correct": false, "explanation": "搭配：“无论”要与“都”呼应，这里没有“都”，不通。"}], "explanations": {"由于": "正确答案。“由于他生病了”引出今天没来上课的原因。", "但是": "语义：“但是”表示转折，这里前后没有转折关系。", "只要": "语义：“只要”引出充分条件，表示有这一条件就够，与生病导致缺课的因果不符。", "无论": "搭配：“无论”要与“都”呼应，这里没有“都”，不通。"}, "sentence_index": 0, "correct_answer": "由于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下了一场大雪，由于我们没去爬山。", "explanation": "这里应该用〈因此〉。“由于”引出原因，不能引出结果；“我们没去爬山”是结果。"}, {"text": "由于考上大学，我们每天努力学习。", "explanation": "这里应该用〈为了〉。“考上大学”是还没实现的目的，不是已经发生的原因，“由于”只引出原因。"}, {"text": "由于天气如何，我们都要去。", "explanation": "这里应该用〈无论〉。“由于”只引出原因，不能表示“不论怎样”的条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85959, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "由于", "is_correct": true, "explanation": "正确答案。“由于她会说中文”引出公司请她当翻译的原因。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示选择，这里前后是因果关系，不是选择关系。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”引出不利的后果，与“她会说中文”的因果关系不符。"}, {"text": "因而", "is_correct": false, "explanation": "搭配：“因而”引出结果，前面要有原因分句，这里句首用它不通。"}], "explanations": {"由于": "正确答案。“由于她会说中文”引出公司请她当翻译的原因。", "或者": "语义：“或者”表示选择，这里前后是因果关系，不是选择关系。", "否则": "语义：“否则”引出不利的后果，与“她会说中文”的因果关系不符。", "因而": "搭配：“因而”引出结果，前面要有原因分句，这里句首用它不通。"}, "sentence_index": 6, "correct_answer": "由于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "由于下雨，我们还是去了公园。", "explanation": "这里应该用〈虽然〉。“还是”要求前文有转折，“由于”引出原因，不能表示让步。"}, {"text": "由于开会之前，我们先喝茶。", "explanation": "这里应该用〈在……之前〉。“由于”只引出原因，不能表示时间先后，应说“在开会之前”。"}, {"text": "他由于骑自行车上学。", "explanation": "这里表示交通方式，不是原因。“由于”只引出原因，不能用来说明交通方式，这里应去掉“由于”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85959, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "因为由于忘了带伞，他淋湿了。", "corrected_sentence": "由于忘了带伞，他淋湿了。", "error_description": "“因为”和“由于”都引出原因，不能叠用。应去掉“因为”，写成“由于忘了带伞，他淋湿了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85959, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "由于的天气太热，我们不想出去。", "corrected_sentence": "由于天气太热，我们不想出去。", "error_description": "“由于”后面直接接原因，中间不能加“的”。应写成“由于天气太热”，不能说“由于的天气太热”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
