INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85960, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，表示原因，引出事情发生的理由。", "primary_collocate": null, "pronunciation": "yóu yú", "ipa": "jou˧˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "由于大雨，比赛改到了明天。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于工作原因，他很少回家。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于交通问题，我们迟到了。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于身体不好，爷爷不能去旅行。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于疫情，学校放假了。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于路滑，开车要慢一点。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于时间关系，我们先谈这些。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于大雪，高速路关了。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于经验不足，他做错了。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于一次小事故，火车晚点了。", "target_word": "由于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "由於", "label": "繁体"}], "register": "书面", "sense_fingerprint": "引出原因的介词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e3854f-4e11-4bc9-a35e-a40d78ee0dbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85960, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "由于", "is_correct": true, "explanation": "正确答案。“由于”是介词，表示原因，引出事情发生的理由。"}, {"text": "犹豫", "is_correct": false, "explanation": "与“由于”只有第二个音节声调不同（yù，第四声），意思是拿不定主意，不是引出原因。"}, {"text": "优于", "is_correct": false, "explanation": "与“由于”只有第一个音节声调不同（yōu，第一声），意思是比……更好。"}, {"text": "幼鱼", "is_correct": false, "explanation": "与“由于”只有第一个音节声调不同（yòu，第四声），意思是还没长大的小鱼。"}], "explanations": {"由于": "正确答案。“由于”是介词，表示原因，引出事情发生的理由。", "犹豫": "与“由于”只有第二个音节声调不同（yù，第四声），意思是拿不定主意，不是引出原因。", "优于": "与“由于”只有第一个音节声调不同（yōu，第一声），意思是比……更好。", "幼鱼": "与“由于”只有第一个音节声调不同（yòu，第四声），意思是还没长大的小鱼。"}, "sentence_index": null, "correct_answer": "由于"}, "level_3": {"options": [{"text": "由于", "is_correct": true, "explanation": "正确答案。“由于大雨”引出比赛改期的原因。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”引出目的，不能引出已经发生的原因，“为了大雨”不通。"}, {"text": "对于", "is_correct": false, "explanation": "语义：“对于”引出话题或对象，不表示比赛改期的原因。"}, {"text": "按照", "is_correct": false, "explanation": "搭配：“按照”后接标准、计划或规定，不能接“大雨”。"}], "explanations": {"由于": "正确答案。“由于大雨”引出比赛改期的原因。", "为了": "语义：“为了”引出目的，不能引出已经发生的原因，“为了大雨”不通。", "对于": "语义：“对于”引出话题或对象，不表示比赛改期的原因。", "按照": "搭配：“按照”后接标准、计划或规定，不能接“大雨”。"}, "sentence_index": 0, "correct_answer": "由于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "由于要参加比赛，他每天练习。", "explanation": "这里应该用〈为了〉。“由于”引出已经发生的原因，“为了”引出目的；“要参加比赛”是目的，不能作原因。"}, {"text": "由于你来，我就走。", "explanation": "这里应该用〈如果〉。“由于”引出已经发生或确定的原因，不能表示假设的条件。"}, {"text": "天下大雨，由于比赛改到了明天。", "explanation": "这里应该用〈因此〉。“由于”引出原因，不能引出结果；“比赛改到了明天”是结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85960, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "由于", "is_correct": true, "explanation": "正确答案。“由于时间关系”引出先谈这些的原因。"}, {"text": "经过", "is_correct": false, "explanation": "搭配：“经过”后接过程或经历，不能说“经过时间关系”。"}, {"text": "随着", "is_correct": false, "explanation": "搭配：“随着”后接变化或发展，“时间关系”不是变化过程，这里不通。"}, {"text": "通过", "is_correct": false, "explanation": "语义：“通过”表示方式或途径，这里说的是原因。"}], "explanations": {"由于": "正确答案。“由于时间关系”引出先谈这些的原因。", "经过": "搭配：“经过”后接过程或经历，不能说“经过时间关系”。", "随着": "搭配：“随着”后接变化或发展，“时间关系”不是变化过程，这里不通。", "通过": "语义：“通过”表示方式或途径，这里说的是原因。"}, "sentence_index": 6, "correct_answer": "由于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "由于下课以后，我们去吃饭。", "explanation": "这里应去掉“由于”，直接说“下课以后，我们去吃饭”。“由于”只引出原因，不能表示时间先后。"}, {"text": "我先吃饭，由于我再去上班。", "explanation": "这里应该用〈然后〉。“由于”引出原因，不能表示动作的先后顺序。"}, {"text": "他由于坐飞机去北京。", "explanation": "这里表示交通方式，应改用〈乘〉。“由于”引出原因，不能表示交通方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "因为由于天气不好，比赛推迟了。", "corrected_sentence": "由于天气不好，比赛推迟了。", "error_description": "“因为”和“由于”都引出原因，不能叠用。应去掉“因为”，写成“由于天气不好，比赛推迟了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "由于的临时有事，他没有参加会议。", "corrected_sentence": "由于临时有事，他没有参加会议。", "error_description": "“由于”后面直接接原因，中间不能加“的”。应写成“由于临时有事”，不能说“由于的临时有事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85961, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "录播", "is_correct": true, "explanation": "反义：“录播”是录制后再播出，与直播“事情发生的同时播出”正好相反。"}, {"text": "跳舞", "is_correct": false, "explanation": "无关：“跳舞”与播出方式没有反义关系。"}, {"text": "写信", "is_correct": false, "explanation": "无关：“写信”与直播的播出方式没有反义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "无关：“打扫”与直播的播出方式没有反义关系。"}], "correct_answer": "录播", "explanations": {"录播": "反义：“录播”是录制后再播出，与直播“事情发生的同时播出”正好相反。", "跳舞": "无关：“跳舞”与播出方式没有反义关系。", "写信": "无关：“写信”与直播的播出方式没有反义关系。", "打扫": "无关：“打扫”与直播的播出方式没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85961, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "录播", "is_correct": true, "explanation": "反义：“录播”是录制后再播出，与直播“事情发生的同时播出”相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：“唱歌”与播出方式没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”与播出方式没有反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "无关：“读书”与播出方式没有反义关系。"}], "correct_answer": "录播", "explanations": {"录播": "反义：“录播”是录制后再播出，与直播“事情发生的同时播出”相反。", "唱歌": "无关：“唱歌”与播出方式没有反义关系。", "散步": "无关：“散步”与播出方式没有反义关系。", "读书": "无关：“读书”与播出方式没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85961, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "直播是事情一边发生，一边让大家在电视或手机上看到。", "primary_collocate": null, "pronunciation": "zhí bō", "ipa": "tʂɻ̩˧˥ pwo˥", "syllable_count": 2, "sentences": [{"text": "今晚的比赛在手机上直播。", "target_word": "直播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在家直播足球比赛。", "target_word": "直播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台直播了今天的晚会。", "target_word": "直播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天晚上直播唱歌。", "target_word": "直播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能不能直播一下这里的雪？", "target_word": "直播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛没有直播。", "target_word": "直播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上直播做饭。", "target_word": "直播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天的新闻会直播吗？", "target_word": "直播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起看他直播吧。", "target_word": "直播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直播的时候，网很慢。", "target_word": "直播", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "直播了", "label": "体标"}, {"form": "直播过", "label": "体标"}, {"form": "直播间", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情发生的同时通过电视或手机让大家看到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '537c4520-879d-4465-a1a7-51ade1e4b38d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85961, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直播", "is_correct": true, "explanation": "正确：“在手机上直播”表示比赛同时在手机上让大家看到，与句意吻合。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复器物，不能用于比赛这种事件。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是物品或身体，不能接“比赛”作宾语。"}, {"text": "加班", "is_correct": false, "explanation": "配价：“加班”是不及物动词，不能说“比赛……加班”。"}], "explanations": {"直播": "正确：“在手机上直播”表示比赛同时在手机上让大家看到，与句意吻合。", "修理": "语义：“修理”指修复器物，不能用于比赛这种事件。", "洗": "搭配：“洗”的对象是物品或身体，不能接“比赛”作宾语。", "加班": "配价：“加班”是不及物动词，不能说“比赛……加班”。"}, "sentence_index": 0, "correct_answer": "直播"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电影院直播了那部电影。", "explanation": "这里应该用〈播放〉。直播指事情发生的同时播出，电影是事先录好的，不能直播。"}, {"text": "他把照片直播到网上。", "explanation": "这里应该用〈上传〉。直播的内容必须是正在发生的事件，照片是静态的，不能直播。"}, {"text": "那部动画片昨天直播了。", "explanation": "这里应该用〈播放〉。动画片是事先制作好的，不是正在发生的事件，不能说直播。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85961, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直播", "is_correct": true, "explanation": "正确：“在网上直播做饭”表示边做饭边在网上让大家看到，与句意吻合。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、场所，不能接“做饭”这类动作。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不能带动词宾语“做饭”。"}, {"text": "绣", "is_correct": false, "explanation": "语义：“绣”指刺绣，与在网上做饭的意思毫无关系。"}], "explanations": {"直播": "正确：“在网上直播做饭”表示边做饭边在网上让大家看到，与句意吻合。", "打扫": "搭配：“打扫”的对象是房间、场所，不能接“做饭”这类动作。", "游泳": "配价：“游泳”是不及物动词，不能带动词宾语“做饭”。", "绣": "语义：“绣”指刺绣，与在网上做饭的意思毫无关系。"}, "sentence_index": 6, "correct_answer": "直播"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在海边直播了一部短片。", "explanation": "这里应该用〈拍摄〉。直播的是正在发生的事情，短片是事先拍好的。"}, {"text": "这本书是一年前直播的。", "explanation": "这里应该用〈印刷〉。书是印好的成品，不是正在发生的事件，不能说直播。"}, {"text": "这个数字是三年前直播的。", "explanation": "这里应该用〈计算〉。直播的是正在发生的事件，三年前算出的数字不是现场事件，不能说直播。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85961, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把网上直播这场音乐会。", "corrected_sentence": "我们在网上直播这场音乐会。", "error_description": "表示地点的“在网上”应用介词“在”引出，写成“在网上直播”；“把网上”误用了处置介词“把”，不能引出地点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85961, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天在网上直播了做饭。", "corrected_sentence": "他每天在网上直播做饭。", "error_description": "“直播”表示经常性的动作，后面不能加“了”，应说“每天在网上直播做饭”；“直播了做饭”与“每天”的习惯性语义冲突。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b5bd27b-9964-4a62-9a6b-c3aeb80c6467') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
