INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85963, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "表是戴在手上用来看时间的东西。", "primary_collocate": null, "pronunciation": "biǎo", "ipa": "pjɑʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他手上戴着一块新表。", "target_word": "表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的表慢了五分钟。", "target_word": "表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看一下表，现在几点了？", "target_word": "表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸送给我一块红色的表。", "target_word": "表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块表是爷爷留下来的。", "target_word": "表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把表忘在家里了，所以不知道时间。", "target_word": "表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天早上都看表，怕上课迟到。", "target_word": "表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块表很贵，我买不起。", "target_word": "表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的表坏了，不走了。", "target_word": "表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你看看我的表，现在是三点。", "target_word": "表", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "只", "label": "量词"}, {"form": "手表", "label": "复合"}, {"form": "錶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "戴在手腕上用来看时间的计时器具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20572383-2a84-4d2e-a2d6-e1113f08bf28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85963, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "表", "is_correct": true, "explanation": "表（biǎo）指戴在手腕上用来看时间的手表，是正确答案。"}, {"text": "标", "is_correct": false, "explanation": "biāo（第一声）与 biǎo（第三声）声调不同，意思是标记。"}, {"text": "扁", "is_correct": false, "explanation": "biǎn 与 biǎo 只差韵尾（n 与 o），声调相同，意思是扁平。"}, {"text": "保", "is_correct": false, "explanation": "bǎo 与 biǎo 少了介音 i，声调相同，意思是保护。"}, {"text": "宝", "is_correct": false, "explanation": "bǎo 与 biǎo 只差介音 i，声调相同，意思是宝贝。"}, {"text": "膘", "is_correct": false, "explanation": "biāo（第一声）与 biǎo（第三声）只差声调，意思是脂肪层，如“膘肥”。"}], "explanations": {"表": "表（biǎo）指戴在手腕上用来看时间的手表，是正确答案。", "标": "biāo（第一声）与 biǎo（第三声）声调不同，意思是标记。", "扁": "biǎn 与 biǎo 只差韵尾（n 与 o），声调相同，意思是扁平。", "保": "bǎo 与 biǎo 少了介音 i，声调相同，意思是保护。", "宝": "bǎo 与 biǎo 只差介音 i，声调相同，意思是宝贝。", "膘": "biāo（第一声）与 biǎo（第三声）只差声调，意思是脂肪层，如“膘肥”。"}, "sentence_index": null, "correct_answer": "表"}, "level_3": {"options": [{"text": "表", "is_correct": true, "explanation": "“表”指戴在手上的手表，与“戴着”和“新”搭配，符合句意。"}, {"text": "手帕", "is_correct": false, "explanation": "搭配：“戴”用于手表、戒指等，不能说戴手帕。"}, {"text": "肥皂", "is_correct": false, "explanation": "语义：肥皂不是戴在手上的物品，与句中“戴着”不符。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不能戴在手上，句子说不通。"}], "explanations": {"表": "“表”指戴在手上的手表，与“戴着”和“新”搭配，符合句意。", "手帕": "搭配：“戴”用于手表、戒指等，不能说戴手帕。", "肥皂": "语义：肥皂不是戴在手上的物品，与句中“戴着”不符。", "饼干": "语义：饼干不能戴在手上，句子说不通。"}, "sentence_index": 0, "correct_answer": "表"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的墙上挂着一个大表。", "explanation": "这里应该用〈钟〉。挂在墙上的计时器叫钟，表是戴在手腕上的小型计时器。"}, {"text": "请你在这张表上签名。", "explanation": "这里的〈表〉指表格，不是戴在手上的手表。"}, {"text": "我买了一本表。", "explanation": "这里应该用〈块〉。手表用“块”计量，“本”用于书册，不能用于手表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983850f8-aa5e-46c1-a983-9f88fd71ecce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85963, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "表", "is_correct": true, "explanation": "表（biǎo）指戴在手腕上用来看时间的手表，是正确答案。"}, {"text": "镖", "is_correct": false, "explanation": "biāo（第一声）与 biǎo（第三声）只差声调，意思是飞镖。"}, {"text": "瞟", "is_correct": false, "explanation": "piǎo 与 biǎo 只差声母的送气与否（p 与 b），声调相同，意思是斜着眼看。"}, {"text": "渺", "is_correct": false, "explanation": "miǎo 与 biǎo 只差声母（m 与 b），韵母与声调相同，意思是微小、渺茫。"}, {"text": "鳔", "is_correct": false, "explanation": "biào（第四声）与 biǎo（第三声）只差声调，意思是鱼鳔。"}], "explanations": {"表": "表（biǎo）指戴在手腕上用来看时间的手表，是正确答案。", "镖": "biāo（第一声）与 biǎo（第三声）只差声调，意思是飞镖。", "瞟": "piǎo 与 biǎo 只差声母的送气与否（p 与 b），声调相同，意思是斜着眼看。", "渺": "miǎo 与 biǎo 只差声母（m 与 b），韵母与声调相同，意思是微小、渺茫。", "鳔": "biào（第四声）与 biǎo（第三声）只差声调，意思是鱼鳔。"}, "sentence_index": null, "correct_answer": "表"}, "level_3": {"options": [{"text": "表", "is_correct": true, "explanation": "“表”指手表，可以用来看时间，与“看”和“怕上课迟到”的语境相符。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“看”不与“面包”搭配，早上看面包与“怕迟到”的语境无关。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套不能用来查看时间，与“怕上课迟到”的语境不符。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：看报纸与“怕上课迟到”的语境无关，报纸不是用来看时间的东西。"}], "explanations": {"表": "“表”指手表，可以用来看时间，与“看”和“怕上课迟到”的语境相符。", "面包": "搭配：“看”不与“面包”搭配，早上看面包与“怕迟到”的语境无关。", "手套": "语义：手套不能用来查看时间，与“怕上课迟到”的语境不符。", "报纸": "语义：看报纸与“怕上课迟到”的语境无关，报纸不是用来看时间的东西。"}, "sentence_index": 6, "correct_answer": "表"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨房里的表响了，该关火了。", "explanation": "这里应该用〈计时器〉。厨房里定时响的是计时器，戴在手上的表不这样用。"}, {"text": "我家的水表坏了，要找人来修。", "explanation": "这里的〈表〉指测量用量的仪器，如水表、电表，不是戴在手上看时间的表。"}, {"text": "我写了一封信，以表谢意。", "explanation": "这里的〈表〉是动词，意思是表示，与名词“手表”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983850f8-aa5e-46c1-a983-9f88fd71ecce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85963, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈送了我一本表。", "corrected_sentence": "妈妈送了我一块表。", "error_description": "“表”指手表，量词应用“块”，不能用“本”（“本”用于书籍等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983850f8-aa5e-46c1-a983-9f88fd71ecce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85963, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶手腕上穿着一块旧表。", "corrected_sentence": "奶奶手腕上戴着一块旧表。", "error_description": "“表”戴在手上，应用动词“戴”，不能用“穿”（“穿”用于衣服、鞋袜等）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983850f8-aa5e-46c1-a983-9f88fd71ecce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
