INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85965, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "“许多”是说很多很多。", "primary_collocate": null, "pronunciation": "xǔ duō", "ipa": "ɕy˨˩˦ tuo˥˥", "syllable_count": 2, "sentences": [{"text": "公园里有许多人在跑步。", "target_word": "许多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近有许多好吃的饭馆。", "target_word": "许多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着许多书。", "target_word": "许多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，花园里开了许多花。", "target_word": "许多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去过许多国家。", "target_word": "许多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个周末我要做许多事情。", "target_word": "许多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里坐着许多学生。", "target_word": "许多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我买了许多新衣服。", "target_word": "许多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上下了许多雪。", "target_word": "许多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在中国认识了许多朋友。", "target_word": "许多", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "许许多多", "label": "重叠"}], "register": "通用", "sense_fingerprint": "许多：形容数量很多，放在名词前面作定语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60f41c19-c9f1-4287-85b2-aea15cba001d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85965, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "许多", "is_correct": true, "explanation": "正确：“许多”是形容词，表示数量很大，可以放在“有”后面修饰“人”。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”形容光线或颜色，不表示数量，“公园里有明亮人”说不通。"}, {"text": "宽阔", "is_correct": false, "explanation": "搭配：“宽阔”修饰场地或道路，不能修饰人，填入后不成话。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”形容声音或状态，不表示数量，“公园里有安静人”说不通。"}], "explanations": {"许多": "正确：“许多”是形容词，表示数量很大，可以放在“有”后面修饰“人”。", "明亮": "语义：“明亮”形容光线或颜色，不表示数量，“公园里有明亮人”说不通。", "宽阔": "搭配：“宽阔”修饰场地或道路，不能修饰人，填入后不成话。", "安静": "语义：“安静”形容声音或状态，不表示数量，“公园里有安静人”说不通。"}, "sentence_index": 0, "correct_answer": "许多"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "只有许多人同意这个方案。", "explanation": "这里应该用〈少数〉。“只有”限定数量很少，与表示数量大的“许多”冲突，应说“只有少数人同意”。"}, {"text": "他只剩许多钱，连车票都买不起。", "explanation": "这里应该用〈一点〉。“只剩”强调数量少，“许多”表示数量大，应说“他只剩一点钱”。"}, {"text": "这次比赛只有许多选手参加。", "explanation": "这里应该用〈几位〉。“只有”限定人数少，“许多”表示数量大，应说“只有几位选手参加”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85965, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "许多", "is_correct": true, "explanation": "正确：“许多”是形容词，表示数量很大，可以放在“坐着”后面修饰“学生”。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容空间，不修饰人，“坐着宽敞学生”不通。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”形容物体的厚度，不能修饰人，填入后不成话。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”形容光线或颜色，不表示人的数量，“坐着亮学生”说不通。"}], "explanations": {"许多": "正确：“许多”是形容词，表示数量很大，可以放在“坐着”后面修饰“学生”。", "宽敞": "搭配：“宽敞”形容空间，不修饰人，“坐着宽敞学生”不通。", "厚": "搭配：“厚”形容物体的厚度，不能修饰人，填入后不成话。", "亮": "语义：“亮”形容光线或颜色，不表示人的数量，“坐着亮学生”说不通。"}, "sentence_index": 6, "correct_answer": "许多"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在中国只认识了许多朋友。", "explanation": "这里应该用〈几个〉。“只”限定数量很少，与表示数量大的“许多”矛盾，应说“只认识了几个朋友”。"}, {"text": "这次考试我只得了许多分。", "explanation": "这里应该用〈几分〉。“只得”说明分数低，“许多”表示数量大，与语境矛盾，应说“只得了几分”。"}, {"text": "这个小村子里只住着许多户人家。", "explanation": "这里应该用〈几户〉。“只住着”限定户数少，“许多”表示数量大，应说“只住着几户人家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85965, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "图书馆里有很许多书。", "corrected_sentence": "图书馆里有许多书。", "error_description": "错误形式：「有很许多书」；正确形式：「有许多书」。“许多”本身已经表示数量很大，前面不能再加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85965, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班有很许多同学。", "corrected_sentence": "我们班有许多同学。", "error_description": "错误形式：「有很许多同学」；正确形式：「有许多同学」。“许多”本身已经表示数量很大，前面不能再加“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
