INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85966, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容词，数量很大，相当于“很多”。", "primary_collocate": null, "pronunciation": "xǔ duō", "ipa": "ɕy˨˩˦ tuo˥˥", "syllable_count": 2, "sentences": [{"text": "他有许多问题想问老师。", "target_word": "许多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里有许多学生在看书。", "target_word": "许多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天吃了许多水果。", "target_word": "许多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有许多公园。", "target_word": "许多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，这里发生了许多变化。", "target_word": "许多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手机里有许多照片。", "target_word": "许多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，我收到了许多礼物。", "target_word": "许多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班有许多同学喜欢音乐。", "target_word": "许多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明花了许多时间做作业。", "target_word": "许多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她读过许多有名的小说。", "target_word": "许多", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "许许多多", "label": "重叠"}], "register": "通用", "sense_fingerprint": "许多：形容词，表示数量大，相当于“很多”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60f41c19-c9f1-4287-85b2-aea15cba001d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85966, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "许多", "is_correct": true, "explanation": "正确：“许多”表示数量大，可以修饰“问题”，“他有许多问题”通顺。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”形容外貌或样子，不表示数量，“他有漂亮问题”说不通。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：“干净”形容物品或环境是否洁净，不能修饰“问题”。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”形容物体的厚度，不能修饰“问题”，填入后不成话。"}], "explanations": {"许多": "正确：“许多”表示数量大，可以修饰“问题”，“他有许多问题”通顺。", "漂亮": "语义：“漂亮”形容外貌或样子，不表示数量，“他有漂亮问题”说不通。", "干净": "搭配：“干净”形容物品或环境是否洁净，不能修饰“问题”。", "厚": "搭配：“厚”形容物体的厚度，不能修饰“问题”，填入后不成话。"}, "sentence_index": 0, "correct_answer": "许多"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小城只剩许多家商店了。", "explanation": "这里应该用〈几家〉。“只剩”强调数量少，“许多”表示数量大，应说“只剩几家商店了”。"}, {"text": "这个城市只有许多处公园值得去。", "explanation": "这里应该用〈几处〉。“只有”限定数量少，“许多”表示数量大，应说“只有几处公园值得去”。"}, {"text": "这个城市只有许多座公园。", "explanation": "这里应该用〈一座〉。“只有”限定数量少，“许多”表示数量大，应说“这个城市只有一座公园”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85966, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "许多", "is_correct": true, "explanation": "正确：“许多”表示数量大，可以修饰“礼物”，“收到了许多礼物”通顺。"}, {"text": "深", "is_correct": false, "explanation": "搭配：“深”形容深度，不修饰“礼物”，“收到了深礼物”不通。"}, {"text": "瘦", "is_correct": false, "explanation": "搭配：“瘦”形容人或物的胖瘦，不能修饰“礼物”，填入后不成话。"}, {"text": "响", "is_correct": false, "explanation": "语义：“响”形容声音大，与礼物无关，也不表示数量，“收到了响礼物”说不通。"}], "explanations": {"许多": "正确：“许多”表示数量大，可以修饰“礼物”，“收到了许多礼物”通顺。", "深": "搭配：“深”形容深度，不修饰“礼物”，“收到了深礼物”不通。", "瘦": "搭配：“瘦”形容人或物的胖瘦，不能修饰“礼物”，填入后不成话。", "响": "语义：“响”形容声音大，与礼物无关，也不表示数量，“收到了响礼物”说不通。"}, "sentence_index": 6, "correct_answer": "许多"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她只读过许多本有名的小说。", "explanation": "这里应该用〈几本〉。“只”限定数量很少，与表示数量大的“许多”矛盾，应说“只读过几本”。"}, {"text": "这个月她只看了许多页书。", "explanation": "这里应该用〈几页〉。“只看了”强调数量少，“许多”表示数量大，与语境矛盾，应说“只看了几页”。"}, {"text": "她的书架上只摆着许多套有名的小说。", "explanation": "这里应该用〈一套〉。“只摆着”限定数量少，“许多”表示数量大，应说“只摆着一套”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小区里有很许多老人。", "corrected_sentence": "这个小区里有许多老人。", "error_description": "错误形式：「很许多老人」；正确形式：「许多老人」。“许多”本身已经表示数量大，前面不能再加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她每天花很许多时间读书。", "corrected_sentence": "她每天花许多时间读书。", "error_description": "错误形式：「很许多时间」；正确形式：「许多时间」。“许多”本身已经表示数量大，前面不能再加“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85967, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "关", "is_correct": true, "explanation": "正确答案。“开空调”与“关空调”是反义词，“关”表示使机器停止运转。"}, {"text": "写", "is_correct": false, "explanation": "与“开”的这一义项没有反义关系，“写”表示写字。"}, {"text": "读", "is_correct": false, "explanation": "与“开”的这一义项没有反义关系，“读”表示看着文字发出声音或理解文字。"}, {"text": "跑", "is_correct": false, "explanation": "与“开”的这一义项没有反义关系，“跑”表示快速移动。"}], "correct_answer": "关", "explanations": {"关": "正确答案。“开空调”与“关空调”是反义词，“关”表示使机器停止运转。", "写": "与“开”的这一义项没有反义关系，“写”表示写字。", "读": "与“开”的这一义项没有反义关系，“读”表示看着文字发出声音或理解文字。", "跑": "与“开”的这一义项没有反义关系，“跑”表示快速移动。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85967, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85967, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“开”是把关着的东西打开，或者让机器动起来（包括驾驶车辆）。", "primary_collocate": null, "pronunciation": "kāi", "ipa": "kʰaɪ˥", "syllable_count": 1, "sentences": [{"text": "屋里很黑，请开灯。", "target_word": "开", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想看新闻，请开电视。", "target_word": "开", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他会开车，常送我上班。", "target_word": "开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太冷了，请开空调。", "target_word": "开", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水太热，你把水龙头开小一点。", "target_word": "开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸开了灯，屋子一下子亮了。", "target_word": "开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他开着车，一边听音乐。", "target_word": "开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把风扇开着，我去买点水。", "target_word": "开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你开门，我忘了带钥匙。", "target_word": "开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我开过这种车，很容易。", "target_word": "开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开了", "label": "完成体"}, {"form": "开着", "label": "持续体"}, {"form": "开过", "label": "经历体"}, {"form": "开开", "label": "重叠"}, {"form": "開", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开：打开关着的东西，或使机器、电器运转（包括驾驶车辆）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e3854f-4e11-4bc9-a35e-a40d78ee0dbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85967, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "开", "is_correct": true, "explanation": "正确答案。“开”是动词，表示打开关着的东西，或使机器、电器运转。"}, {"text": "该", "is_correct": false, "explanation": "与“开”只有声母不同（g 与 k，g 不送气），意思是应该。"}, {"text": "拆", "is_correct": false, "explanation": "与“开”只有声母不同（ch 与 k），意思是把连接的东西分开。"}, {"text": "呆", "is_correct": false, "explanation": "与“开”只有声母不同（d 与 k），意思是发呆、呆板。"}, {"text": "嗨", "is_correct": false, "explanation": "与“开”只有声母不同（h 与 k），是叹词，表示打招呼。"}], "explanations": {"开": "正确答案。“开”是动词，表示打开关着的东西，或使机器、电器运转。", "该": "与“开”只有声母不同（g 与 k，g 不送气），意思是应该。", "拆": "与“开”只有声母不同（ch 与 k），意思是把连接的东西分开。", "呆": "与“开”只有声母不同（d 与 k），意思是发呆、呆板。", "嗨": "与“开”只有声母不同（h 与 k），是叹词，表示打招呼。"}, "sentence_index": null, "correct_answer": "开"}, "level_3": {"options": [{"text": "开", "is_correct": true, "explanation": "正确答案。“请开灯”表示请把灯打开。"}, {"text": "关", "is_correct": false, "explanation": "语义：“关灯”与“屋里很黑”的要求相反，屋里黑时应该开灯。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象不能是“灯”，“吃灯”不通。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”用于帽子、眼镜等，“戴灯”不通。"}], "explanations": {"开": "正确答案。“请开灯”表示请把灯打开。", "关": "语义：“关灯”与“屋里很黑”的要求相反，屋里黑时应该开灯。", "吃": "搭配：“吃”的对象不能是“灯”，“吃灯”不通。", "戴": "搭配：“戴”用于帽子、眼镜等，“戴灯”不通。"}, "sentence_index": 0, "correct_answer": "开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太冷了，我开了一件大衣。", "explanation": "这里应该用〈穿〉。“开”用于门窗、机器等，不能用于衣服；穿衣服要用〈穿〉。"}, {"text": "太冷了，我想开一杯热水。", "explanation": "这里应该用〈倒〉。“开”表示使机器、电器运转，不能用于倒水；倒热水要用〈倒〉。"}, {"text": "太冷了，我们开了一个决定。", "explanation": "这里应该用〈做〉。“开”不能跟“决定”搭配，做决定要用〈做〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85967, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开", "is_correct": true, "explanation": "正确答案。“开着车”表示正在驾驶车辆，“一边听音乐”与之相符。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“车”作宾语，“睡着车”不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲等，“唱着车”不通。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，“写着车”不通。"}], "explanations": {"开": "正确答案。“开着车”表示正在驾驶车辆，“一边听音乐”与之相符。", "睡": "配价：“睡”是不及物动词，不能带“车”作宾语，“睡着车”不通。", "唱": "搭配：“唱”的对象是歌曲等，“唱着车”不通。", "写": "搭配：“写”的对象是文字，“写着车”不通。"}, "sentence_index": 6, "correct_answer": "开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他开了眼睛，看见了窗外的雪。", "explanation": "这里应该用〈睁开〉。“开”不能直接跟“眼睛”搭配表示睁眼。"}, {"text": "谜底开了，大家都很惊讶。", "explanation": "这里应该用〈揭开〉。“开”不能用于谜底，揭开谜底要说“揭开”。"}, {"text": "他开了这个疑问，还没有想明白。", "explanation": "这里应该用〈解开〉。“开”不能直接跟“疑问”搭配，解答疑问要说“解开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
