INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85968, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "关", "is_correct": true, "explanation": "正确答案。“开门”与“关门”是反义词，“商店十点才开门”的反面是“关门”。"}, {"text": "买", "is_correct": false, "explanation": "与“开”的这一义项没有反义关系，“买”表示购买。"}, {"text": "读", "is_correct": false, "explanation": "与“开”的这一义项没有反义关系，“读”表示看着文字发出声音或理解文字。"}, {"text": "跑", "is_correct": false, "explanation": "与“开”的这一义项没有反义关系，“跑”表示快速移动。"}], "correct_answer": "关", "explanations": {"关": "正确答案。“开门”与“关门”是反义词，“商店十点才开门”的反面是“关门”。", "买": "与“开”的这一义项没有反义关系，“买”表示购买。", "读": "与“开”的这一义项没有反义关系，“读”表示看着文字发出声音或理解文字。", "跑": "与“开”的这一义项没有反义关系，“跑”表示快速移动。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85968, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动词，使关闭的东西张开、打通；也指启动、开始，也指花朵绽放。", "primary_collocate": null, "pronunciation": "kāi", "ipa": "kʰaɪ˥", "syllable_count": 1, "sentences": [{"text": "我没带钥匙，请你开门。", "target_word": "开", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天热，我想开窗。", "target_word": "开", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "箱子太紧了，请你帮我开一下。", "target_word": "开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天到了，花都开了。", "target_word": "开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店九点开，晚上十点关。", "target_word": "开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在学校旁边开了一家小书店。", "target_word": "开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门开着，我直接走了进去。", "target_word": "开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间太闷，请你把窗户开大一点。", "target_word": "开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园早上六点就开了。", "target_word": "开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店十点才开门，我们先去喝茶吧。", "target_word": "开", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "开了", "label": "完成体"}, {"form": "开着", "label": "持续体"}, {"form": "开过", "label": "经历体"}, {"form": "开开", "label": "重叠"}, {"form": "開", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开：使关着的东西张开、打通，或开始经营，或花朵绽放", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e3854f-4e11-4bc9-a35e-a40d78ee0dbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85968, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "开", "is_correct": true, "explanation": "正确答案。“开”是动词，表示使关着的东西张开、打通，或开始。"}, {"text": "该", "is_correct": false, "explanation": "与“开”只有声母不同（g 与 k，g 不送气），意思是应该。"}, {"text": "拆", "is_correct": false, "explanation": "与“开”只有声母不同（ch 与 k），意思是把连接的东西分开。"}, {"text": "呆", "is_correct": false, "explanation": "与“开”只有声母不同（d 与 k），意思是发呆、呆板。"}, {"text": "嗨", "is_correct": false, "explanation": "与“开”只有声母不同（h 与 k），是叹词，表示打招呼。"}], "explanations": {"开": "正确答案。“开”是动词，表示使关着的东西张开、打通，或开始。", "该": "与“开”只有声母不同（g 与 k，g 不送气），意思是应该。", "拆": "与“开”只有声母不同（ch 与 k），意思是把连接的东西分开。", "呆": "与“开”只有声母不同（d 与 k），意思是发呆、呆板。", "嗨": "与“开”只有声母不同（h 与 k），是叹词，表示打招呼。"}, "sentence_index": null, "correct_answer": "开"}, "level_3": {"options": [{"text": "开", "is_correct": true, "explanation": "正确答案。“请你开门”表示请对方把门打开。"}, {"text": "关", "is_correct": false, "explanation": "语义：“关门”与“没带钥匙、要进门”的意思相反，关门会把人挡在外面。"}, {"text": "拿", "is_correct": false, "explanation": "搭配：“拿”不能以“门”为宾语，“拿门”不通。"}, {"text": "找", "is_correct": false, "explanation": "搭配：“找”的对象是人或物，“找门”不能表示打开门。"}], "explanations": {"开": "正确答案。“请你开门”表示请对方把门打开。", "关": "语义：“关门”与“没带钥匙、要进门”的意思相反，关门会把人挡在外面。", "拿": "搭配：“拿”不能以“门”为宾语，“拿门”不通。", "找": "搭配：“找”的对象是人或物，“找门”不能表示打开门。"}, "sentence_index": 0, "correct_answer": "开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春天到了，花都开会了。", "explanation": "这句中的“开”被理解为召集会议，花不能召集会议；这里的“开”指花朵绽放。"}, {"text": "春天到了，花都开药了。", "explanation": "这句中的“开”被理解为医生开具处方，花不能开处方；这里的“开”指花朵绽放。"}, {"text": "春天到了，花都开刀了。", "explanation": "这句中的“开”被理解为做手术，花不能做手术；这里的“开”指花朵绽放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85968, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开", "is_correct": true, "explanation": "正确答案。“门开着”表示门是打开的状态，“我直接走了进去”与之相符。"}, {"text": "锁", "is_correct": false, "explanation": "语义：“锁着”表示门被锁住，与“我直接走了进去”矛盾。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”用于帽子、眼镜等，不能以“门”为宾语。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣服、鞋袜，“穿着门”不通。"}], "explanations": {"开": "正确答案。“门开着”表示门是打开的状态，“我直接走了进去”与之相符。", "锁": "语义：“锁着”表示门被锁住，与“我直接走了进去”矛盾。", "戴": "搭配：“戴”用于帽子、眼镜等，不能以“门”为宾语。", "穿": "搭配：“穿”用于衣服、鞋袜，“穿着门”不通。"}, "sentence_index": 6, "correct_answer": "开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他开了一个誓言，要永远不再抽烟。", "explanation": "这里应该用〈立〉。“开”不能跟“誓言”搭配，立誓言要说“立下”。"}, {"text": "妈妈开了一首诗，读给我们听。", "explanation": "这里应该用〈读〉。“开”不能用于诗，读诗要说“读”。"}, {"text": "他开了一个微笑，看起来很开心。", "explanation": "这里应该用〈露出〉。“开”不能用于表情，露出微笑要说“露出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
