INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85969, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "游行是很多人一起在街上走，表示庆祝或有话要说。", "primary_collocate": null, "pronunciation": "yóu xíng", "ipa": "joʊ˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "周末，很多人一起在街上游行。", "target_word": "游行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家举着牌子游行，想让别人听到他们的话。", "target_word": "游行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年的时候，我们看到人们在街上游行。", "target_word": "游行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们唱着歌，在学校门口游行。", "target_word": "游行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们游行是为了表达自己的想法。", "target_word": "游行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天路上很堵，因为有人在游行。", "target_word": "游行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想和我们一起去游行吗？", "target_word": "游行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游行的人越来越多，路都走不通了。", "target_word": "游行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们去看人们游行。", "target_word": "游行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们沿着大路游行，要求保护环境。", "target_word": "游行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遊行", "label": "繁体"}, {"form": "游行了", "label": "体标"}, {"form": "游行过", "label": "体标"}], "register": "中性", "sense_fingerprint": "很多人一起在街上走，表达庆祝或想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef952436-ac10-4596-8374-89ff1cbf54ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85969, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "游行", "is_correct": true, "explanation": "正确答案：游行（yóu xíng），指很多人一起在街上走，表达庆祝或想法。"}, {"text": "有形", "is_correct": false, "explanation": "yǒu（第三声）与 yóu（第二声）声调不同，意思是有形体、看得见。"}, {"text": "有幸", "is_correct": false, "explanation": "yǒu（第三声）与 yóu（第二声）声调不同，xìng（第四声）与 xíng（第二声）声调也不同，意思是幸运地能够，如“有幸认识你”。"}, {"text": "游兴", "is_correct": false, "explanation": "yóu 相同，xìng（第四声）与 xíng（第二声）只差声调，意思是游玩的兴致。"}], "explanations": {"游行": "正确答案：游行（yóu xíng），指很多人一起在街上走，表达庆祝或想法。", "有形": "yǒu（第三声）与 yóu（第二声）声调不同，意思是有形体、看得见。", "有幸": "yǒu（第三声）与 yóu（第二声）声调不同，xìng（第四声）与 xíng（第二声）声调也不同，意思是幸运地能够，如“有幸认识你”。", "游兴": "yóu 相同，xìng（第四声）与 xíng（第二声）只差声调，意思是游玩的兴致。"}, "sentence_index": null, "correct_answer": "游行"}, "level_3": {"options": [{"text": "游行", "is_correct": true, "explanation": "游行：很多人一起在街上走，表达庆祝或想法，符合“周末，很多人一起在街上”。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”是个人清洁身体，不是一起在街上做的事。"}, {"text": "下雨", "is_correct": false, "explanation": "搭配：“下雨”的主语只能是天气，人不能下雨。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”指答题测验，不是在街上聚集的活动。"}], "explanations": {"游行": "游行：很多人一起在街上走，表达庆祝或想法，符合“周末，很多人一起在街上”。", "洗澡": "语义：“洗澡”是个人清洁身体，不是一起在街上做的事。", "下雨": "搭配：“下雨”的主语只能是天气，人不能下雨。", "考试": "语义：“考试”指答题测验，不是在街上聚集的活动。"}, "sentence_index": 0, "correct_answer": "游行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们放假时在家里游行，一天都没出门。", "explanation": "这里应该用〈待着〉。游行是很多人一起在街上走，在家里不出门要用〈待着〉。"}, {"text": "早上我在操场上游行，锻炼身体。", "explanation": "这里应该用〈跑步〉。游行指很多人列队上街，一个人锻炼要用跑步。"}, {"text": "我一个人在床边游行，很放松。", "explanation": "这里应该用〈溜达〉。游行是很多人一起在街上走，一个人在屋里随便走走要用〈溜达〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85969, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "游行", "is_correct": true, "explanation": "正确答案：游行（yóu xíng），指很多人一起在街上走，表达庆祝或想法。"}, {"text": "油性", "is_correct": false, "explanation": "yóu 相同，xìng（第四声）与 xíng（第二声）只差声调，意思是油脂的性质，如“油性皮肤”。"}, {"text": "有型", "is_correct": false, "explanation": "yǒu（第三声）与 yóu（第二声）声调不同，xíng 相同，意思是时髦、好看、有风格。"}, {"text": "油星", "is_correct": false, "explanation": "yóu 相同，xīng（第一声）与 xíng（第二声）只差声调，意思是小油点，如“油星儿”。"}], "explanations": {"游行": "正确答案：游行（yóu xíng），指很多人一起在街上走，表达庆祝或想法。", "油性": "yóu 相同，xìng（第四声）与 xíng（第二声）只差声调，意思是油脂的性质，如“油性皮肤”。", "有型": "yǒu（第三声）与 yóu（第二声）声调不同，xíng 相同，意思是时髦、好看、有风格。", "油星": "yóu 相同，xīng（第一声）与 xíng（第二声）只差声调，意思是小油点，如“油星儿”。"}, "sentence_index": null, "correct_answer": "游行"}, "level_3": {"options": [{"text": "游行", "is_correct": true, "explanation": "游行：很多人一起在街上走，表达庆祝或想法，符合“一起去”的集体活动。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”是身体发热，不是一起去做的活动。"}, {"text": "结冰", "is_correct": false, "explanation": "搭配：“结冰”的对象是水等液体，不能说一起去结冰。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”是身体不舒服，不能作为一起去做的事。"}], "explanations": {"游行": "游行：很多人一起在街上走，表达庆祝或想法，符合“一起去”的集体活动。", "发烧": "语义：“发烧”是身体发热，不是一起去做的活动。", "结冰": "搭配：“结冰”的对象是水等液体，不能说一起去结冰。", "生病": "语义：“生病”是身体不舒服，不能作为一起去做的事。"}, "sentence_index": 6, "correct_answer": "游行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚饭后，我一个人在小区里游行，很放松。", "explanation": "这里应该用〈散步〉。游行是很多人一起在街上走，一个人在小区里慢慢走要用〈散步〉。"}, {"text": "我们在窗口游行买票。", "explanation": "这里应该用〈排队〉。游行是列队行进，买票要在窗口排队。"}, {"text": "周末我们去商场游行，买了很多衣服。", "explanation": "这里应该用〈逛街〉。游行是列队上街表态，在商场随便看看要用逛街。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
