INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85969, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们参加了一本游行。", "corrected_sentence": "孩子们参加了一场游行。", "error_description": "量词错误：“本”用于书本，不能用来数“游行”这种集体活动，应该用“场”。正确形式：一场游行。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
