INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85970, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "许多人排队在街上行进，以示庆祝、纪念或抗议。", "primary_collocate": null, "pronunciation": "yóu xíng", "ipa": "joʊ˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "国庆节那天，很多人在街上游行。", "target_word": "游行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们为了要求涨工资上街游行。", "target_word": "游行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们举着旗子在广场游行。", "target_word": "游行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷们为了庆祝夺冠，在市中心游行。", "target_word": "游行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下午三点，大家排好队开始游行。", "target_word": "游行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们游行是为了纪念那位老英雄。", "target_word": "游行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天有人在市政府门口游行。", "target_word": "游行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民们游行抗议新的规定。", "target_word": "游行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没有参加过游行。", "target_word": "游行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在路边看着游行的人们。", "target_word": "游行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遊行", "label": "繁体"}, {"form": "游行了", "label": "体标"}, {"form": "游行过", "label": "体标"}], "register": "中性", "sense_fingerprint": "多人列队走上街头，庆祝、纪念或抗议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef952436-ac10-4596-8374-89ff1cbf54ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85970, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "游行", "is_correct": true, "explanation": "正确答案：游行（yóu xíng），指很多人列队走上街头。"}, {"text": "有形", "is_correct": false, "explanation": "yǒu（第三声）与 yóu（第二声）声调不同，意思是有形体、看得见。"}, {"text": "有幸", "is_correct": false, "explanation": "yǒu（第三声）与 yóu（第二声）声调不同，xìng（第四声）与 xíng（第二声）声调也不同，意思是幸运地能够，如“有幸认识你”。"}, {"text": "游兴", "is_correct": false, "explanation": "yóu 相同，xìng（第四声）与 xíng（第二声）只差声调，意思是游玩的兴致。"}], "explanations": {"游行": "正确答案：游行（yóu xíng），指很多人列队走上街头。", "有形": "yǒu（第三声）与 yóu（第二声）声调不同，意思是有形体、看得见。", "有幸": "yǒu（第三声）与 yóu（第二声）声调不同，xìng（第四声）与 xíng（第二声）声调也不同，意思是幸运地能够，如“有幸认识你”。", "游兴": "yóu 相同，xìng（第四声）与 xíng（第二声）只差声调，意思是游玩的兴致。"}, "sentence_index": null, "correct_answer": "游行"}, "level_3": {"options": [{"text": "游行", "is_correct": true, "explanation": "游行：多人列队上街，表示庆祝、纪念或抗议，符合“很多人在街上”。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”指答题测验，不是在街上聚集的活动。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”需要水，街上没有水，这句话说不通。"}, {"text": "下雨", "is_correct": false, "explanation": "搭配：“下雨”的主语只能是天气，人不能下雨。"}], "explanations": {"游行": "游行：多人列队上街，表示庆祝、纪念或抗议，符合“很多人在街上”。", "考试": "语义：“考试”指答题测验，不是在街上聚集的活动。", "游泳": "语义：“游泳”需要水，街上没有水，这句话说不通。", "下雨": "搭配：“下雨”的主语只能是天气，人不能下雨。"}, "sentence_index": 0, "correct_answer": "游行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上在公园游行，很放松。", "explanation": "这里应该用〈散步〉。游行指很多人列队上街，一个人在公园走走要用散步。"}, {"text": "我们在门口游行买票。", "explanation": "这里应该用〈排队〉。游行是列队行进，不是等候，买票要用排队。"}, {"text": "周末我们在家里游行，一直不出门。", "explanation": "这里应该用〈休息〉。游行是很多人列队上街，在家里不出门要用〈休息〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85970, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "游行", "is_correct": true, "explanation": "正确答案：游行（yóu xíng），指很多人列队走上街头。"}, {"text": "油性", "is_correct": false, "explanation": "yóu 相同，xìng（第四声）与 xíng（第二声）只差声调，意思是油脂的性质，如“油性皮肤”。"}, {"text": "有型", "is_correct": false, "explanation": "yǒu（第三声）与 yóu（第二声）声调不同，xíng 相同，意思是时髦、好看、有风格。"}, {"text": "油星", "is_correct": false, "explanation": "yóu 相同，xīng（第一声）与 xíng（第二声）只差声调，意思是小油点，如“油星儿”。"}], "explanations": {"游行": "正确答案：游行（yóu xíng），指很多人列队走上街头。", "油性": "yóu 相同，xìng（第四声）与 xíng（第二声）只差声调，意思是油脂的性质，如“油性皮肤”。", "有型": "yǒu（第三声）与 yóu（第二声）声调不同，xíng 相同，意思是时髦、好看、有风格。", "油星": "yóu 相同，xīng（第一声）与 xíng（第二声）只差声调，意思是小油点，如“油星儿”。"}, "sentence_index": null, "correct_answer": "游行"}, "level_3": {"options": [{"text": "游行", "is_correct": true, "explanation": "游行：多人列队上街，表示庆祝、纪念或抗议，符合“有人在市政府门口”的集会场景。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：“发芽”是植物的变化，人不能在门口发芽。"}, {"text": "结冰", "is_correct": false, "explanation": "搭配：“结冰”的对象是水等液体，不能说人在门口结冰。"}, {"text": "开花", "is_correct": false, "explanation": "语义：“开花”是植物的事，这句话说不通。"}], "explanations": {"游行": "游行：多人列队上街，表示庆祝、纪念或抗议，符合“有人在市政府门口”的集会场景。", "发芽": "语义：“发芽”是植物的变化，人不能在门口发芽。", "结冰": "搭配：“结冰”的对象是水等液体，不能说人在门口结冰。", "开花": "语义：“开花”是植物的事，这句话说不通。"}, "sentence_index": 6, "correct_answer": "游行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏天的时候，我们去湖里游行。", "explanation": "这里应该用〈游泳〉。游行是在街上列队行进，在水里游要用游泳。"}, {"text": "周末我们去商场游行，买了很多东西。", "explanation": "这里应该用〈逛街〉。游行是列队上街表态，在商场随便看看要用逛街。"}, {"text": "早上我在河边游行，锻炼身体。", "explanation": "这里应该用〈跑步〉。游行指很多人列队上街，一个人锻炼要用跑步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85970, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生们游行的很整齐。", "corrected_sentence": "学生们游行得很整齐。", "error_description": "补语标志错误：动词后面的补语要用“得”，写成“的”不对。正确形式：游行得很整齐。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85970, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市民们参加了一本游行。", "corrected_sentence": "市民们参加了一场游行。", "error_description": "量词错误：“本”用于书本，不能用来数“游行”这种集体活动，应该用“场”。正确形式：一场游行。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06480a9e-3e9e-443f-af5a-6912a8034e9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
