INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85973, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大学是长大以后学很多知识的地方，学生在那里学习很多年。", "primary_collocate": null, "pronunciation": "dà xué", "ipa": "ta˥˩ ɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "他在大学学了四年历史。", "target_word": "大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上大学以后，我很少回家。", "target_word": "大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妹妹明年要去上大学了。", "target_word": "大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在大学里，你可以学到很多新知识。", "target_word": "大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业以后，我们就离开了大学。", "target_word": "大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想进大学读书。", "target_word": "大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学四年，她学会了做饭和游泳。", "target_word": "大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时没有机会上大学。", "target_word": "大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了上大学，他每天学习到很晚。", "target_word": "大学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们是在大学认识的。", "target_word": "大学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}, {"form": "大學", "label": "繁体"}], "register": "中性", "sense_fingerprint": "长大后学习知识的阶段和地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e3854f-4e11-4bc9-a35e-a40d78ee0dbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85973, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大雪", "is_correct": false, "explanation": "xuě（第三声）与 xué（第二声）声调不同，意思是大雪（节气名）。"}, {"text": "大学", "is_correct": true, "explanation": "正确答案：大学（dà xué），指长大以后学习知识的阶段和地方。"}, {"text": "大写", "is_correct": false, "explanation": "xiě（第三声）与 xué 韵母不同（ie 与 üe），声调也不同，意思是大写字母。"}, {"text": "大选", "is_correct": false, "explanation": "xuǎn（第三声）与 xué 韵母和声调都不同，意思是全国性的选举。"}], "explanations": {"大雪": "xuě（第三声）与 xué（第二声）声调不同，意思是大雪（节气名）。", "大学": "正确答案：大学（dà xué），指长大以后学习知识的阶段和地方。", "大写": "xiě（第三声）与 xué 韵母不同（ie 与 üe），声调也不同，意思是大写字母。", "大选": "xuǎn（第三声）与 xué 韵母和声调都不同，意思是全国性的选举。"}, "sentence_index": null, "correct_answer": "大学"}, "level_3": {"options": [{"text": "大学", "is_correct": true, "explanation": "正确：大学指长大以后学习知识的阶段，“在……学习”指在这一阶段学习。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不是学习历史的地方，“学了四年历史”无法在医院发生。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：“在工厂学历史”不搭配，工厂不是学习场所。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：幼儿园的孩子不会学四年历史，与句中的学习内容和时长冲突。"}], "explanations": {"大学": "正确：大学指长大以后学习知识的阶段，“在……学习”指在这一阶段学习。", "医院": "语义：医院不是学习历史的地方，“学了四年历史”无法在医院发生。", "工厂": "搭配：“在工厂学历史”不搭配，工厂不是学习场所。", "幼儿园": "语义：幼儿园的孩子不会学四年历史，与句中的学习内容和时长冲突。"}, "sentence_index": 0, "correct_answer": "大学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我女儿三岁就去大学了。", "explanation": "这里应该用〈幼儿园〉。大学是长大以后学习的阶段，三岁的孩子应说“去幼儿园”。"}, {"text": "这列火车十分钟后在大学进站。", "explanation": "这里应该用〈车站〉。火车要在车站进站，大学不是车站。"}, {"text": "飞机每天早上在大学起飞。", "explanation": "这里应该用〈机场〉。飞机要在机场起飞，大学是学校，不能作为起飞的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85973, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大学", "is_correct": true, "explanation": "正确：大学指长大以后学习的阶段，“四年”的学习时期与之相符。"}, {"text": "办公室", "is_correct": false, "explanation": "语义：办公室不是人的学习阶段，与“学会做饭和游泳”的学习生活不符。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园不是学习生活的阶段，与“四年”的时期含义冲突。"}, {"text": "车间", "is_correct": false, "explanation": "搭配：“车间四年”不能指一段学习生活，与“学会做饭和游泳”搭配不当。"}], "explanations": {"大学": "正确：大学指长大以后学习的阶段，“四年”的学习时期与之相符。", "办公室": "语义：办公室不是人的学习阶段，与“学会做饭和游泳”的学习生活不符。", "公园": "语义：公园不是学习生活的阶段，与“四年”的时期含义冲突。", "车间": "搭配：“车间四年”不能指一段学习生活，与“学会做饭和游泳”搭配不当。"}, "sentence_index": 6, "correct_answer": "大学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我十岁的时候已经在大学了。", "explanation": "这里应该用〈小学〉。大学是长大以后的阶段，十岁的孩子应在小学。"}, {"text": "我儿子四岁，每天早上去大学玩。", "explanation": "这里应该用〈幼儿园〉。大学是长大以后学习的地方，四岁的孩子应该去幼儿园。"}, {"text": "我十三岁时进了一所大学。", "explanation": "这里应该用〈中学〉。大学是高中毕业以后的阶段，十三岁的孩子应上中学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85973, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我表哥在一大学学了三年工程。", "corrected_sentence": "我表哥在一所大学学了三年工程。", "error_description": "错误：“大学”前的数词“一”须配量词“所”，应说“一所大学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85973, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她高考那年考上了一条大学。", "corrected_sentence": "她高考那年考上了一所大学。", "error_description": "量词错误：“大学”的量词应用“所”，不能说“一条大学”，应说“一所大学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13402954-c630-4519-a3be-3fd308727130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
