INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85975, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "领导人是带着大家做事的人。", "primary_collocate": null, "pronunciation": "lǐng dǎo rén", "ipa": "liŋ˨˩ tɑʊ˨˩ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "他是我们小组的领导人。", "target_word": "领导人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个队需要一位好领导人。", "target_word": "领导人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都喜欢这位领导人。", "target_word": "领导人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个好领导人会听大家的话。", "target_word": "领导人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是这个团队的领导人。", "target_word": "领导人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组的领导人是小王。", "target_word": "领导人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的领导人带着大家一起做事。", "target_word": "领导人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个登山队的领导人是王先生。", "target_word": "领导人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的领导人对大家很好。", "target_word": "领导人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好领导人先做事，再说话。", "target_word": "领导人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "領導人", "label": "繁体"}, {"form": "最高领导人", "label": "复合"}], "register": "中性", "sense_fingerprint": "领导人：带着大家做事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5929168-3d77-4b29-8202-61f2e45ccbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85975, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "领导人", "is_correct": true, "explanation": "正确。“小组的……”指带领小组做事的人，只有“领导人”符合。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是物品，不能指小组里的人。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不指人，不能担任小组的带头人。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“他是……的成绩”不成立，“成绩”是结果，不能指人。"}], "explanations": {"领导人": "正确。“小组的……”指带领小组做事的人，只有“领导人”符合。", "桌子": "语义：“桌子”是物品，不能指小组里的人。", "天气": "语义：“天气”不指人，不能担任小组的带头人。", "成绩": "搭配：“他是……的成绩”不成立，“成绩”是结果，不能指人。"}, "sentence_index": 0, "correct_answer": "领导人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑是我们组的领导人。", "explanation": "这里误把〈领导人〉用于物品。领导人指带领大家做事的人，只能指人；电脑是设备，应说〈设备〉。"}, {"text": "我们班来了一只新领导人。", "explanation": "这里应该用〈位〉。量词“只”用于动物，指人要用“位”或“个”。"}, {"text": "这部电影的领导人是张先生。", "explanation": "这里应该用〈导演〉。领导人指带领大家做事的人，拍电影的负责人要用“导演”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85975, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "领导人", "is_correct": true, "explanation": "正确。“带着大家一起做事”的主体必须是人，只有“领导人”符合。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是物件，不能带着大家做事。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是人，无法带领大家。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“带着大家一起做事”需要有施动能力的人，“空气”不能这样搭配。"}], "explanations": {"领导人": "正确。“带着大家一起做事”的主体必须是人，只有“领导人”符合。", "窗户": "语义：“窗户”是物件，不能带着大家做事。", "天空": "语义：“天空”不是人，无法带领大家。", "空气": "搭配：“带着大家一起做事”需要有施动能力的人，“空气”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "领导人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛的领导人是老王。", "explanation": "这里应该用〈裁判〉。领导人指带领大家做事的人，比赛的执法者要用“裁判”。"}, {"text": "我们小组新来了一座领导人。", "explanation": "这里应该用〈位〉。指人的领导人用“位”或“个”，“座”用于山、楼等大型物体。"}, {"text": "这首歌是我们班的领导人。", "explanation": "这里误把〈领导人〉用于作品。领导人指带领大家做事的人，只能指人；歌曲是作品，应说〈作品〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85975, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们选了一只新领导人。", "corrected_sentence": "我们选了一位新领导人。", "error_description": "错误形式是“一只领导人”，正确形式是“一位领导人”。“领导人”指人，量词应用“位”，“只”只用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85975, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次会议来了三位领导人们。", "corrected_sentence": "这次会议来了三位领导人。", "error_description": "错误形式是“三位领导人们”，正确形式是“三位领导人”。“三位”已表示数量，“领导人”后面不能再加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
