INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85977, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“目前”是说现在这个时候。", "primary_collocate": null, "pronunciation": "mù qián", "ipa": "mu˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "目前我正在准备考试。", "target_word": "目前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他目前在北京学习中文。", "target_word": "目前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "目前学校里没有人。", "target_word": "目前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "目前的问题是没有钱。", "target_word": "目前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我目前还不想换工作。", "target_word": "目前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "目前我家离公司很近。", "target_word": "目前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "目前我身体很好，不用担心。", "target_word": "目前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "目前大家都在等老师来。", "target_word": "目前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店目前没有这种水果。", "target_word": "目前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "目前我只有一个中国朋友。", "target_word": "目前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词：现在这个时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2ce387-de1a-4dee-a2b5-d7f05cb692cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85977, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "目前", "is_correct": true, "explanation": "“目前”指说话时的这段时间，与“正在准备考试”的进行状态相符。"}, {"text": "以前", "is_correct": false, "explanation": "语义：“以前”指过去的时间，与表示现在进行的“正在”矛盾。"}, {"text": "将来", "is_correct": false, "explanation": "语义：“将来”指未来的时间，与表示现在进行的“正在”矛盾。"}, {"text": "当初", "is_correct": false, "explanation": "搭配：“当初”指过去某一时刻，不与表示进行的“正在”搭配。"}], "explanations": {"目前": "“目前”指说话时的这段时间，与“正在准备考试”的进行状态相符。", "以前": "语义：“以前”指过去的时间，与表示现在进行的“正在”矛盾。", "将来": "语义：“将来”指未来的时间，与表示现在进行的“正在”矛盾。", "当初": "搭配：“当初”指过去某一时刻，不与表示进行的“正在”搭配。"}, "sentence_index": 0, "correct_answer": "目前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "目前我们会搬到北京去。", "explanation": "〈目前〉指说话时的这段时间，不能用来指将来，指将来应该用〈将来〉。"}, {"text": "他目前三天前就走了。", "explanation": "〈目前〉指说话时的现在，不能与“三天前”这种过去的时间同用，讲过去的事应该用〈以前〉。"}, {"text": "目前是我的生日。", "explanation": "〈目前〉指一段时间，不能用来指某一天，这里应该用〈今天〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85977, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "目前", "is_correct": true, "explanation": "“目前”指说话时的这段时间，与“我身体很好，不用担心”的现状相符。"}, {"text": "从前", "is_correct": false, "explanation": "语义：“从前”指以往的时期，与描述现状并让人放心的陈述不合。"}, {"text": "往后", "is_correct": false, "explanation": "语义：“往后”指以后的时间，与描述现状的陈述不合。"}, {"text": "此后", "is_correct": false, "explanation": "语义：“此后”指某个时间之后，与描述现状的陈述不合。"}], "explanations": {"目前": "“目前”指说话时的这段时间，与“我身体很好，不用担心”的现状相符。", "从前": "语义：“从前”指以往的时期，与描述现状并让人放心的陈述不合。", "往后": "语义：“往后”指以后的时间，与描述现状的陈述不合。", "此后": "语义：“此后”指某个时间之后，与描述现状的陈述不合。"}, "sentence_index": 6, "correct_answer": "目前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们目前三点到学校。", "explanation": "〈目前〉指说话时的这一段时间，不能用来安排某个具体时刻发生的事，这里应该用〈今天〉。"}, {"text": "目前我会和老师去北京。", "explanation": "〈目前〉指说话时的这段时间，不能用来指将来，指将来应该用〈将来〉。"}, {"text": "我目前去年去过上海。", "explanation": "〈目前〉指说话时的现在，不能与“去年”这种过去的时间同用，讲过去应该用〈以前〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85977, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "目前我还没有目前工作。", "corrected_sentence": "目前我还没有工作。", "error_description": "时间词“目前”只能出现一次。“目前我还没有目前工作”中多了一个“目前”，正确形式是“目前我还没有工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85977, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们目前的在学汉语。", "corrected_sentence": "我们目前在学汉语。", "error_description": "“目前的”是定语，只能修饰名词（如“目前的问题”），不能直接接动词短语“在学汉语”。去掉“的”，正确形式是“我们目前在学汉语”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf851ef-0ea4-463a-af52-2d79e38f2b23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
