INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85979, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "骗是说假话，让别人相信。", "primary_collocate": null, "pronunciation": "piàn", "ipa": "pʰi̯ɛn˥˩", "syllable_count": 1, "sentences": [{"text": "他说假话骗妈妈。", "target_word": "骗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我没骗你，是真的。", "target_word": "骗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他骗老师说自己生病了。", "target_word": "骗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你为什么要骗我？", "target_word": "骗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明骗朋友说他没有钱。", "target_word": "骗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她从来没有骗过自己的孩子。", "target_word": "骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我知道你在骗我，快说实话吧。", "target_word": "骗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把我骗了，说今天不用上班。", "target_word": "骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子骗了爸爸，说作业做完了。", "target_word": "骗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑着骗我说，他已经吃过饭了。", "target_word": "骗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "骗了", "label": "体标"}, {"form": "骗过", "label": "体标"}, {"form": "騙", "label": "繁体"}], "register": "口语", "sense_fingerprint": "说假话让别人信以为真", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c500fdf8-63d3-43a2-81b5-b65303588367') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85979, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "骗", "is_correct": true, "explanation": "正确：骗（piàn，第四声），意思是说假话让别人相信。"}, {"text": "变", "is_correct": false, "explanation": "变（biàn，第四声）与 piàn 声母不同（b 与 p），意思是改变。"}, {"text": "遍", "is_correct": false, "explanation": "遍（biàn，第四声）与 piàn 声母不同（b 与 p），意思是次、全部。"}, {"text": "偏", "is_correct": false, "explanation": "偏（piān，第一声）与 piàn 声调不同，意思是偏向、偏偏。"}, {"text": "篇", "is_correct": false, "explanation": "篇（piān，第一声）与 piàn 声调不同，意思是文章。"}], "explanations": {"骗": "正确：骗（piàn，第四声），意思是说假话让别人相信。", "变": "变（biàn，第四声）与 piàn 声母不同（b 与 p），意思是改变。", "遍": "遍（biàn，第四声）与 piàn 声母不同（b 与 p），意思是次、全部。", "偏": "偏（piān，第一声）与 piàn 声调不同，意思是偏向、偏偏。", "篇": "篇（piān，第一声）与 piàn 声调不同，意思是文章。"}, "sentence_index": null, "correct_answer": "骗"}, "level_3": {"options": [{"text": "骗", "is_correct": true, "explanation": "正确：骗指说假话让人相信，符合「他说假话……妈妈」的句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的宾语应是食物，「吃妈妈」不通。"}, {"text": "修", "is_correct": false, "explanation": "语义：「修」指修理物品，不能以人为对象，与「说假话」的意思不合。"}, {"text": "缝", "is_correct": false, "explanation": "配价：「缝」的对象是布料或伤口，不能以人为宾语。"}], "explanations": {"骗": "正确：骗指说假话让人相信，符合「他说假话……妈妈」的句意。", "吃": "搭配：「吃」的宾语应是食物，「吃妈妈」不通。", "修": "语义：「修」指修理物品，不能以人为对象，与「说假话」的意思不合。", "缝": "配价：「缝」的对象是布料或伤口，不能以人为宾语。"}, "sentence_index": 0, "correct_answer": "骗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他为什么要用力骗我的书？", "explanation": "这里应该用〈抢〉。骗靠谎言使人上当，不能用“用力”来描述，这里是强行夺取。"}, {"text": "他骗着一袋米走了很远。", "explanation": "这里应该用〈扛〉。扛是把重物架在肩上，骗是说假话让人相信，不能用来表示负重。"}, {"text": "我每天骗十页书。", "explanation": "这里应该用〈读〉。读是看着文字出声或默念，骗是说假话让人相信，不能用来说读书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85979, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "骗", "is_correct": true, "explanation": "正确：骗（piàn，第四声），意思是说假话让别人相信。"}, {"text": "便", "is_correct": false, "explanation": "便（biàn，第四声）与 piàn 声母不同（b 与 p），意思是方便。"}, {"text": "辩", "is_correct": false, "explanation": "辩（biàn，第四声）与 piàn 声母不同（b 与 p），意思是争论、辩解。"}, {"text": "辨", "is_correct": false, "explanation": "辨（biàn，第四声）与 piàn 声母不同（b 与 p），意思是分辨。"}, {"text": "票", "is_correct": false, "explanation": "票（piào，第四声）与 piàn 韵母不同（ao 与 an），意思是票据、车票。"}], "explanations": {"骗": "正确：骗（piàn，第四声），意思是说假话让别人相信。", "便": "便（biàn，第四声）与 piàn 声母不同（b 与 p），意思是方便。", "辩": "辩（biàn，第四声）与 piàn 声母不同（b 与 p），意思是争论、辩解。", "辨": "辨（biàn，第四声）与 piàn 声母不同（b 与 p），意思是分辨。", "票": "票（piào，第四声）与 piàn 韵母不同（ao 与 an），意思是票据、车票。"}, "sentence_index": null, "correct_answer": "骗"}, "level_3": {"options": [{"text": "骗", "is_correct": true, "explanation": "正确：骗指说假话让人相信，符合「你在……我，快说实话吧」的句意。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：「煮」的对象是食物，「煮我」不通。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：「烤」的对象是食物，「烤我」不通。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：「翻译」的对象是语言文字，不能以人为对象，与句意不合。"}], "explanations": {"骗": "正确：骗指说假话让人相信，符合「你在……我，快说实话吧」的句意。", "煮": "搭配：「煮」的对象是食物，「煮我」不通。", "烤": "搭配：「烤」的对象是食物，「烤我」不通。", "翻译": "语义：「翻译」的对象是语言文字，不能以人为对象，与句意不合。"}, "sentence_index": 6, "correct_answer": "骗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他小心地骗着老爷爷下楼。", "explanation": "这里应该用〈扶〉。扶是用手搀住，骗是用谎言使人上当，句中指身体上的帮助。"}, {"text": "护士细心骗病人。", "explanation": "这里应该用〈照顾〉。照顾是细心护理，骗是用谎言使人上当，二者不同。"}, {"text": "黑布骗住了他的眼睛。", "explanation": "这里应该用〈蒙〉。骗的动作主体必须是能说谎的人，黑布不能骗人，应说“蒙住”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85979, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他骗我过一次。", "corrected_sentence": "他骗过我一次。", "error_description": "错误：“骗我过”；正确：“骗过我”。动态助词“过”必须紧跟动词“骗”，不能放在宾语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85979, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他骗我得团团转。", "corrected_sentence": "他骗得我团团转。", "error_description": "错误：“骗我得团团转”；正确：“骗得我团团转”。程度补语“得”必须紧接动词“骗”，“我”是补语中的主语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
