INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85980, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用谎言或手段使人上当。", "primary_collocate": null, "pronunciation": "piàn", "ipa": "pʰi̯ɛn˥˩", "syllable_count": 1, "sentences": [{"text": "他想骗我。", "target_word": "骗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他那套话差点骗得我上当。", "target_word": "骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人用假电话骗了她的钱。", "target_word": "骗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小心，坏人会骗你的钱。", "target_word": "骗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那个人骗老人买了很贵的药。", "target_word": "骗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用网上的假消息骗了很多人。", "target_word": "骗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们想骗我把钱放到他们的卡里。", "target_word": "骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的老板骗过不少外国游客。", "target_word": "骗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你骗不了我，我都知道了。", "target_word": "骗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他靠好听的话骗了她所有的钱。", "target_word": "骗", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "骗了", "label": "体标"}, {"form": "骗过", "label": "体标"}, {"form": "騙", "label": "繁体"}], "register": "口语", "sense_fingerprint": "用谎言或手段让人上当，多指骗取钱财", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c500fdf8-63d3-43a2-81b5-b65303588367') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85980, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "骗", "is_correct": true, "explanation": "正确：骗（piàn，第四声），意思是用谎言或手段使人上当。"}, {"text": "变", "is_correct": false, "explanation": "变（biàn，第四声）与 piàn 声母不同（b 与 p），意思是改变。"}, {"text": "遍", "is_correct": false, "explanation": "遍（biàn，第四声）与 piàn 声母不同（b 与 p），意思是次、全部。"}, {"text": "偏", "is_correct": false, "explanation": "偏（piān，第一声）与 piàn 声调不同，意思是偏向、偏偏。"}, {"text": "篇", "is_correct": false, "explanation": "篇（piān，第一声）与 piàn 声调不同，意思是文章。"}], "explanations": {"骗": "正确：骗（piàn，第四声），意思是用谎言或手段使人上当。", "变": "变（biàn，第四声）与 piàn 声母不同（b 与 p），意思是改变。", "遍": "遍（biàn，第四声）与 piàn 声母不同（b 与 p），意思是次、全部。", "偏": "偏（piān，第一声）与 piàn 声调不同，意思是偏向、偏偏。", "篇": "篇（piān，第一声）与 piàn 声调不同，意思是文章。"}, "sentence_index": null, "correct_answer": "骗"}, "level_3": {"options": [{"text": "骗", "is_correct": true, "explanation": "正确：骗指用谎言使人上当，符合「他想……我」的句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」指进食，「想吃我」是想把人吃掉，与“想骗我”的意图不符。"}, {"text": "穿", "is_correct": false, "explanation": "配价：「穿」的宾语应是衣物，不能带人作宾语。"}, {"text": "烤", "is_correct": false, "explanation": "语义：「烤」指用火加热食物，用于人不合句意。"}], "explanations": {"骗": "正确：骗指用谎言使人上当，符合「他想……我」的句意。", "吃": "语义：「吃」指进食，「想吃我」是想把人吃掉，与“想骗我”的意图不符。", "穿": "配价：「穿」的宾语应是衣物，不能带人作宾语。", "烤": "语义：「烤」指用火加热食物，用于人不合句意。"}, "sentence_index": 0, "correct_answer": "骗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用拳头骗班里的新同学。", "explanation": "这里应该用〈欺负〉。骗是用谎言使人上当，不能用拳头动手，这里指以强凌弱。"}, {"text": "他骗着书包去上学。", "explanation": "这里应该用〈背〉。背是把东西负在身上，骗是用谎言使人上当，不能用来说背书包。"}, {"text": "小偷趁她不注意，用力骗走了钱包。", "explanation": "这里应该用〈抢〉。骗靠谎言使人上当，不能用“用力”来描述，这里是强行夺取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85980, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "骗", "is_correct": true, "explanation": "正确：骗（piàn，第四声），意思是用谎言或手段使人上当。"}, {"text": "便", "is_correct": false, "explanation": "便（biàn，第四声）与 piàn 声母不同（b 与 p），意思是方便。"}, {"text": "辩", "is_correct": false, "explanation": "辩（biàn，第四声）与 piàn 声母不同（b 与 p），意思是争论、辩解。"}, {"text": "辨", "is_correct": false, "explanation": "辨（biàn，第四声）与 piàn 声母不同（b 与 p），意思是分辨。"}, {"text": "票", "is_correct": false, "explanation": "票（piào，第四声）与 piàn 韵母不同（ao 与 an），意思是票据、车票。"}], "explanations": {"骗": "正确：骗（piàn，第四声），意思是用谎言或手段使人上当。", "便": "便（biàn，第四声）与 piàn 声母不同（b 与 p），意思是方便。", "辩": "辩（biàn，第四声）与 piàn 声母不同（b 与 p），意思是争论、辩解。", "辨": "辨（biàn，第四声）与 piàn 声母不同（b 与 p），意思是分辨。", "票": "票（piào，第四声）与 piàn 韵母不同（ao 与 an），意思是票据、车票。"}, "sentence_index": null, "correct_answer": "骗"}, "level_3": {"options": [{"text": "骗", "is_correct": true, "explanation": "正确：骗表示用手段使人上当，与「想……把钱放进他们的卡里」的目的相符。"}, {"text": "送", "is_correct": false, "explanation": "语义：「送」是把东西给人，与钱要放进「他们的卡里」方向相反。"}, {"text": "退", "is_correct": false, "explanation": "语义：「退」是把钱还给对方，与钱流入「他们的卡里」相矛盾。"}, {"text": "拿", "is_correct": false, "explanation": "搭配：「拿」接人作宾语表示抓取，「拿我」与「放到卡里」不搭配。"}], "explanations": {"骗": "正确：骗表示用手段使人上当，与「想……把钱放进他们的卡里」的目的相符。", "送": "语义：「送」是把东西给人，与钱要放进「他们的卡里」方向相反。", "退": "语义：「退」是把钱还给对方，与钱流入「他们的卡里」相矛盾。", "拿": "搭配：「拿」接人作宾语表示抓取，「拿我」与「放到卡里」不搭配。"}, "sentence_index": 6, "correct_answer": "骗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他慢慢地骗着老奶奶过马路。", "explanation": "这里应该用〈扶〉。扶是用手搀住，骗是用谎言使人上当，句中指身体上的帮助。"}, {"text": "妈妈骗了一碗汤。", "explanation": "这里应该用〈盛〉。盛是把食物装进器皿，骗是用谎言使人上当，不能用来表示盛汤。"}, {"text": "他用手骗门三下。", "explanation": "这里应该用〈敲〉。敲是用手或器物轻击，骗是用谎言使人上当，不能用来表示敲门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85980, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把我的钱骗了走。", "corrected_sentence": "他把我的钱骗走了。", "error_description": "错误：“骗了走”；正确：“骗走了”。结果补语“走”必须紧接动词“骗”，“了”放在补语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85980, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用假身份骗了到很多钱。", "corrected_sentence": "他用假身份骗到了很多钱。", "error_description": "错误：“骗了到”；正确：“骗到了”。结果补语“到”必须紧接动词“骗”，“了”放在补语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
