INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85981, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“站”是人用两只脚立在地上，身体不躺也不坐。", "primary_collocate": null, "pronunciation": "zhàn", "ipa": "ʈʂan˥˩", "syllable_count": 1, "sentences": [{"text": "老师让大家站好。", "target_word": "站", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请站直，不要弯腰。", "target_word": "站", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他站在桌子旁边写字。", "target_word": "站", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子太小，还站不稳。", "target_word": "站", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "教室里没有座位，我们只好站着听课。", "target_word": "站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站了一会儿，觉得腿很酸。", "target_word": "站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明站起来回答问题。", "target_word": "站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地铁上人很多，我一直站着，直到下车。", "target_word": "站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站不住了，就靠着墙坐下。", "target_word": "站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全班同学都站成一排拍照。", "target_word": "站", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "站着", "label": "体标"}, {"form": "站了", "label": "体标"}, {"form": "站过", "label": "体标"}], "register": "中性", "sense_fingerprint": "站：动词，人用双脚直立的姿势，不坐不躺", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4282b7-916c-4da7-bd32-a72c5ffbca2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85981, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "站", "is_correct": true, "explanation": "正确：站，zhàn（第四声），意思是人用两只脚立在地上。"}, {"text": "展", "is_correct": false, "explanation": "zhǎn（第三声）与 zhàn（第四声）声调不同，意思是展开。"}, {"text": "颤", "is_correct": false, "explanation": "chàn 与 zhàn 声母不同（ch/zh），意思是颤抖。"}, {"text": "账", "is_correct": false, "explanation": "zhàng 与 zhàn 韵母不同（ang/an），意思是账目。"}, {"text": "赞", "is_correct": false, "explanation": "zàn 与 zhàn 声母不同（z/zh），意思是赞美。"}, {"text": "沾", "is_correct": false, "explanation": "zhān（第一声）与 zhàn（第四声）声调不同，意思是沾上。"}], "explanations": {"站": "正确：站，zhàn（第四声），意思是人用两只脚立在地上。", "展": "zhǎn（第三声）与 zhàn（第四声）声调不同，意思是展开。", "颤": "chàn 与 zhàn 声母不同（ch/zh），意思是颤抖。", "账": "zhàng 与 zhàn 韵母不同（ang/an），意思是账目。", "赞": "zàn 与 zhàn 声母不同（z/zh），意思是赞美。", "沾": "zhān（第一声）与 zhàn（第四声）声调不同，意思是沾上。"}, "sentence_index": null, "correct_answer": "站"}, "level_3": {"options": [{"text": "站", "is_correct": true, "explanation": "正确：“站”指人用脚立着，与“站好”的姿势相符。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”指快速移动，与“站好”所说的站立姿势不符。"}, {"text": "卧", "is_correct": false, "explanation": "语域：“卧”是书面词，指躺下，与“站好”的姿势相反。"}, {"text": "倒", "is_correct": false, "explanation": "搭配：“倒”不能与“好”组成描述站立姿势的说法。"}], "explanations": {"站": "正确：“站”指人用脚立着，与“站好”的姿势相符。", "跑": "语义：“跑”指快速移动，与“站好”所说的站立姿势不符。", "卧": "语域：“卧”是书面词，指躺下，与“站好”的姿势相反。", "倒": "搭配：“倒”不能与“好”组成描述站立姿势的说法。"}, "sentence_index": 0, "correct_answer": "站"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他站在床上，盖着被子睡着了。", "explanation": "这里应该用〈躺〉。“站”指人用脚立着，盖着被子睡觉时人是躺着的；应说“他躺在床上，盖着被子睡着了”。"}, {"text": "他站着坐在沙发上，舒舒服服地看书。", "explanation": "这里应该用〈坐〉。“站”指人用脚立着，句中“站着坐在沙发上”自相矛盾；应说“他坐在沙发上，舒舒服服地看书”。"}, {"text": "车子站在路边等乘客。", "explanation": "这里应该用〈停〉。“站”指人立着，车辆停靠要用“停”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85981, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "站", "is_correct": true, "explanation": "正确：站，zhàn（第四声），意思是人用两只脚立在地上。"}, {"text": "散", "is_correct": false, "explanation": "sàn 与 zhàn 声母不同（s/zh），意思是散开。"}, {"text": "镇", "is_correct": false, "explanation": "zhèn 与 zhàn 韵母不同（en/an），意思是城镇。"}, {"text": "胀", "is_correct": false, "explanation": "zhàng 与 zhàn 韵母不同（ang/an），意思是膨胀。"}], "explanations": {"站": "正确：站，zhàn（第四声），意思是人用两只脚立在地上。", "散": "sàn 与 zhàn 声母不同（s/zh），意思是散开。", "镇": "zhèn 与 zhàn 韵母不同（en/an），意思是城镇。", "胀": "zhàng 与 zhàn 韵母不同（ang/an），意思是膨胀。"}, "sentence_index": null, "correct_answer": "站"}, "level_3": {"options": [{"text": "站", "is_correct": true, "explanation": "正确：“站”表示起身立起，与“站起来回答”相符。"}, {"text": "走", "is_correct": false, "explanation": "语义：“走起来”是开始走动，与“起来回答问题”的意思不符。"}, {"text": "躺", "is_correct": false, "explanation": "搭配：“躺起来”指从躺卧状态起身，不能与“起来回答问题”搭配。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”指在水中移动，与“起来回答问题”完全不搭。"}], "explanations": {"站": "正确：“站”表示起身立起，与“站起来回答”相符。", "走": "语义：“走起来”是开始走动，与“起来回答问题”的意思不符。", "躺": "搭配：“躺起来”指从躺卧状态起身，不能与“起来回答问题”搭配。", "游": "语义：“游”指在水中移动，与“起来回答问题”完全不搭。"}, "sentence_index": 6, "correct_answer": "站"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他躺在床上，站着看书。", "explanation": "这里应该去掉〈站〉。“站”指人用脚立着，句中“躺在床上”与站立矛盾；应说“他躺在床上看书”。"}, {"text": "老人坐在地上，站得很稳。", "explanation": "这里应该用〈坐〉。“站”指人用脚立着，句中“坐在地上”与站立矛盾；应说“老人坐在地上，坐得很稳”。"}, {"text": "他跪在草地上，站着看天。", "explanation": "这里应该去掉〈站〉。“站”指人用脚立着，句中“跪在草地上”与站立矛盾；应说“他跪在草地上看天”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85981, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他站窗户旁边看书。", "corrected_sentence": "他站在窗户旁边看书。", "error_description": "错误在于漏掉了“在”。表示站在某处时要说“站在＋地点”，“站窗户旁边”不通顺；应改为“站在窗户旁边”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85981, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她站过起来唱了一首歌。", "corrected_sentence": "她站起来唱了一首歌。", "error_description": "错误在于“过”的位置。“站起来”是动词加趋向补语，中间不能插入“过”；“站过起来”不通顺，应改为“站起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
