INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85982, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85982, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动词，人直着身体用脚支撑立在某处；也指停留。", "primary_collocate": null, "pronunciation": "zhàn", "ipa": "ʈʂan˥˩", "syllable_count": 1, "sentences": [{"text": "他站在门口等你。", "target_word": "站", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别站在路中间，太危险。", "target_word": "站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她站在窗前看雨。", "target_word": "站", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "听到喊声，他马上站在原地不动了。", "target_word": "站", "complexity_tier": "T3", "furigana": "tīng dào hǎn shēng, tā mǎshàng zhàn zài yuándì bú dòng le.", "sentence_source": "generated"}, {"text": "他站在雨里等了一个小时。", "target_word": "站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车还没停，请先站在黄线后面。", "target_word": "站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她站在人群后面，什么也看不见。", "target_word": "站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你站在我旁边，帮我看一下。", "target_word": "站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在原地站了很久，不知道去哪儿。", "target_word": "站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们站在山顶，看着下面的小城。", "target_word": "站", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "站着", "label": "体标"}, {"form": "站了", "label": "体标"}, {"form": "站过", "label": "体标"}], "register": "中性", "sense_fingerprint": "站：动词，立在某个地点，或停下来不动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4282b7-916c-4da7-bd32-a72c5ffbca2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85982, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "站", "is_correct": true, "explanation": "正确：站，zhàn（第四声），意思是立在某处。"}, {"text": "展", "is_correct": false, "explanation": "zhǎn（第三声）与 zhàn（第四声）声调不同，意思是展开。"}, {"text": "颤", "is_correct": false, "explanation": "chàn 与 zhàn 声母不同（ch/zh），意思是颤抖。"}, {"text": "账", "is_correct": false, "explanation": "zhàng 与 zhàn 韵母不同（ang/an），意思是账目。"}, {"text": "赞", "is_correct": false, "explanation": "zàn 与 zhàn 声母不同（z/zh），意思是赞美。"}, {"text": "沾", "is_correct": false, "explanation": "zhān（第一声）与 zhàn（第四声）声调不同，意思是沾上。"}], "explanations": {"站": "正确：站，zhàn（第四声），意思是立在某处。", "展": "zhǎn（第三声）与 zhàn（第四声）声调不同，意思是展开。", "颤": "chàn 与 zhàn 声母不同（ch/zh），意思是颤抖。", "账": "zhàng 与 zhàn 韵母不同（ang/an），意思是账目。", "赞": "zàn 与 zhàn 声母不同（z/zh），意思是赞美。", "沾": "zhān（第一声）与 zhàn（第四声）声调不同，意思是沾上。"}, "sentence_index": null, "correct_answer": "站"}, "level_3": {"options": [{"text": "站", "is_correct": true, "explanation": "正确：“站”表示人立在某处，与“在门口等你”相符。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”是快速移动，与“在门口等你”的停留状态相矛盾。"}, {"text": "吃", "is_correct": false, "explanation": "语法：“吃”不能表示人站立或停留在门口，“他吃在门口等你”不通。"}, {"text": "飞", "is_correct": false, "explanation": "语义：“飞”指在空中移动，人不能飞着在门口等人。"}], "explanations": {"站": "正确：“站”表示人立在某处，与“在门口等你”相符。", "跑": "语义：“跑”是快速移动，与“在门口等你”的停留状态相矛盾。", "吃": "语法：“吃”不能表示人站立或停留在门口，“他吃在门口等你”不通。", "飞": "语义：“飞”指在空中移动，人不能飞着在门口等人。"}, "sentence_index": 0, "correct_answer": "站"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌子站在门口，一直没动。", "explanation": "这里应该用〈放〉。“站”指人或动物用脚立着，桌子没有脚，不能说“站”；应说“桌子放在门口”。"}, {"text": "他站在门口，一直躺着不动。", "explanation": "这里应该用〈躺〉。“站”指人立着，句中却说“躺着不动”，二者矛盾；应说“他躺在门口，一直不动”。"}, {"text": "他站在空中，慢慢地落下来。", "explanation": "这里应该用〈飘〉。“站”需要用脚支撑，人不能站在空中；应说“他飘在空中，慢慢地落下来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85982, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "站", "is_correct": true, "explanation": "正确：站，zhàn（第四声），意思是立在某处。"}, {"text": "散", "is_correct": false, "explanation": "sàn 与 zhàn 声母不同（s/zh），意思是散开。"}, {"text": "镇", "is_correct": false, "explanation": "zhèn 与 zhàn 韵母不同（en/an），意思是城镇。"}, {"text": "胀", "is_correct": false, "explanation": "zhàng 与 zhàn 韵母不同（ang/an），意思是膨胀。"}], "explanations": {"站": "正确：站，zhàn（第四声），意思是立在某处。", "散": "sàn 与 zhàn 声母不同（s/zh），意思是散开。", "镇": "zhèn 与 zhàn 韵母不同（en/an），意思是城镇。", "胀": "zhàng 与 zhàn 韵母不同（ang/an），意思是膨胀。"}, "sentence_index": null, "correct_answer": "站"}, "level_3": {"options": [{"text": "站", "is_correct": true, "explanation": "正确：“站”表示人立在某处，与“在人群后面”的位置相符。"}, {"text": "冲", "is_correct": false, "explanation": "语义：“冲”是向前猛冲，与“在人群后面”的位置不符。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”指在水中移动，与“人群后面”的陆地场景不符。"}, {"text": "扑", "is_correct": false, "explanation": "搭配：“扑”后面要接目标或方向，“扑在人群后面”不成立。"}], "explanations": {"站": "正确：“站”表示人立在某处，与“在人群后面”的位置相符。", "冲": "语义：“冲”是向前猛冲，与“在人群后面”的位置不符。", "游": "语义：“游”指在水中移动，与“人群后面”的陆地场景不符。", "扑": "搭配：“扑”后面要接目标或方向，“扑在人群后面”不成立。"}, "sentence_index": 6, "correct_answer": "站"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他躺在门口，站着等你。", "explanation": "这里应该去掉〈站着〉。“站”指人用脚立着，句中“躺在门口”与站立矛盾；应说“他躺在门口等你”。"}, {"text": "她趴在山顶，站着看下面的小城。", "explanation": "这里应该去掉〈站着〉。“站”指人用脚立着，句中“趴在山顶”与站立矛盾；应说“她趴在山顶，看下面的小城”。"}, {"text": "雨站在窗外，一直不停。", "explanation": "这里应该用〈下〉。“站”指人或动物用脚立着，雨没有脚，不能说站，应说“下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validatio