INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85983, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "资料是写在纸上或电脑里，可以帮我们做事和学习的东西。", "primary_collocate": null, "pronunciation": "zī liào", "ipa": "tsɿ⁵⁵ liɑʊ⁵¹", "syllable_count": 2, "sentences": [{"text": "我在网上找到了很多学习资料。", "target_word": "资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些资料都放在电脑里。", "target_word": "资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们发了一份新资料。", "target_word": "资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这份资料打印出来。", "target_word": "资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的学习资料放在桌子上。", "target_word": "资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天看资料到很晚。", "target_word": "资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有汉语学习资料吗？", "target_word": "资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些资料可以帮你准备考试。", "target_word": "资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "资料太多了，我不知道先看哪个。", "target_word": "资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把资料放进了书包里。", "target_word": "资料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "资料库", "label": "复合"}], "register": "中性", "sense_fingerprint": "纸上或电脑里的学习、做事用的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97e07d7-e53b-4f4d-b1cf-a3cc62b4f69f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85983, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "资料", "is_correct": true, "explanation": "资料指纸上或电脑里可以帮助学习和做事的东西，在网上找到的正是这类东西，符合语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不是学习用的东西，“网上找到很多学习冰箱”说不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是身体的状态，不是可以在网上找到的学习用东西。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：“学习”不修饰“手套”，两者不搭配。"}], "explanations": {"资料": "资料指纸上或电脑里可以帮助学习和做事的东西，在网上找到的正是这类东西，符合语境。", "冰箱": "语义：冰箱是家用电器，不是学习用的东西，“网上找到很多学习冰箱”说不通。", "体温": "语义：体温是身体的状态，不是可以在网上找到的学习用东西。", "手套": "搭配：“学习”不修饰“手套”，两者不搭配。"}, "sentence_index": 0, "correct_answer": "资料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座房子的墙用了很多资料。", "explanation": "这里应该用〈材料〉。资料指纸上或电脑里供学习和做事用的东西，砌墙要用材料。"}, {"text": "这座山里有丰富的资料。", "explanation": "这里应该用〈资源〉。山里的矿产、水源要说资源，资料不能指自然资源。"}, {"text": "做面包要先准备面粉、酵母等资料。", "explanation": "这里应该用〈原料〉。面粉、酵母是做面包的原料，资料不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85983, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资料", "is_correct": true, "explanation": "资料是学习用的文字或电子材料，“汉语学习资料”是常见说法，符合语境。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是用来开锁的，不是汉语学习用的东西。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶是饮品，不能作为“汉语学习”的用品。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“汉语学习”不搭配“窗户”，两者不能组合。"}], "explanations": {"资料": "资料是学习用的文字或电子材料，“汉语学习资料”是常见说法，符合语境。", "钥匙": "语义：钥匙是用来开锁的，不是汉语学习用的东西。", "牛奶": "语义：牛奶是饮品，不能作为“汉语学习”的用品。", "窗户": "搭配：“汉语学习”不搭配“窗户”，两者不能组合。"}, "sentence_index": 6, "correct_answer": "资料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把一只资料放进了书包里。", "explanation": "这里应该用〈份〉。资料要用量词“份”计量，“只”用于动物或成对的东西。"}, {"text": "我收到了一颗资料。", "explanation": "这里应该用〈份〉。“颗”用于粒状的东西，资料要用“份”计量。"}, {"text": "老师给了我们一座资料。", "explanation": "这里应该用〈份〉。“座”用于山、房屋等大型物体，资料不能这样计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85983, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今天收到了一位资料。", "corrected_sentence": "我今天收到了一份资料。", "error_description": "量词错误：“位”只用于人，不能用来计量“资料”，应用量词“份”。正确说法是“一份资料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85983, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他看了过这份资料。", "corrected_sentence": "他看过这份资料。", "error_description": "助词错误：“看”后只用经验助词“过”，多加的“了”是错误的。正确说法是“他看过这份资料。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
