INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85984, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用来参考、研究或说明问题的材料、数据。", "primary_collocate": null, "pronunciation": "zī liào", "ipa": "tsɿ⁵⁵ liɑʊ⁵¹", "syllable_count": 2, "sentences": [{"text": "写文章以前，要先查资料。", "target_word": "资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为研究收集了很多资料。", "target_word": "资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份资料说明了问题的原因。", "target_word": "资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李正在整理调查资料。", "target_word": "资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些资料对我们的研究很有用。", "target_word": "资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告里的资料都是真的。", "target_word": "资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用病人的资料做了研究。", "target_word": "资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司需要新的市场资料。", "target_word": "资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在图书馆里查历史资料。", "target_word": "资料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题的资料还不够多。", "target_word": "资料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "资料库", "label": "复合"}], "register": "中性", "sense_fingerprint": "供参考、研究或说明问题的材料和数据", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97e07d7-e53b-4f4d-b1cf-a3cc62b4f69f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85984, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "资料", "is_correct": true, "explanation": "资料是用来参考和研究的材料，“写文章以前查资料”符合语境。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：脚印是踩在地上的痕迹，不是写文章前要查的材料。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块与写文章无关，也不是可以查找的参考材料。"}, {"text": "皮带", "is_correct": false, "explanation": "搭配：“查”不搭配“皮带”，两者不能组合。"}], "explanations": {"资料": "资料是用来参考和研究的材料，“写文章以前查资料”符合语境。", "脚印": "语义：脚印是踩在地上的痕迹，不是写文章前要查的材料。", "冰块": "语义：冰块与写文章无关，也不是可以查找的参考材料。", "皮带": "搭配：“查”不搭配“皮带”，两者不能组合。"}, "sentence_index": 0, "correct_answer": "资料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用这些资料盖了一间小房子。", "explanation": "这里应该用〈材料〉。资料指参考、研究用的文字和数据，盖房子要用材料。"}, {"text": "妈妈去市场买了很多做饭的资料。", "explanation": "这里应该用〈食材〉。做饭用的菜、肉要说食材，资料指参考、研究用的文字和数据。"}, {"text": "港口卸下了很多资料。", "explanation": "这里应该用〈货物〉。港口卸下的是货物，资料不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85984, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资料", "is_correct": true, "explanation": "资料是用来研究的材料，“医生用病人的资料做研究”符合语境。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是医学研究的材料。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的学习任务，不是病人的研究对象。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“做研究”的对象是材料或数据，不搭配“钢琴”。"}], "explanations": {"资料": "资料是用来研究的材料，“医生用病人的资料做研究”符合语境。", "歌曲": "语义：歌曲不是医学研究的材料。", "作业": "语义：作业是学生的学习任务，不是病人的研究对象。", "钢琴": "搭配：“做研究”的对象是材料或数据，不搭配“钢琴”。"}, "sentence_index": 6, "correct_answer": "资料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他借了一只资料。", "explanation": "这里应该用〈份〉。资料要用量词“份”计量，“只”用于动物或成对的东西。"}, {"text": "这个问题有一颗资料。", "explanation": "这里应该用〈份〉。“颗”用于粒状的东西，资料要用“份”计量。"}, {"text": "他查了一座资料。", "explanation": "这里应该用〈份〉。“座”用于山、房屋等大型物体，资料不能这样计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他写论文前查了很多条资料。", "corrected_sentence": "他写论文前查了很多份资料。", "error_description": "量词错误：这里计量的是整份的资料，应用量词“份”，不能用“条”。正确说法是“很多份资料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我读了过这份资料。", "corrected_sentence": "我读过这份资料。", "error_description": "助词错误：“读”后只用经验助词“过”，多加的“了”是错误的。正确说法是“我读过这份资料。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
