INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85987, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "下面是在某个东西的下边。", "primary_collocate": null, "pronunciation": "xià mian", "ipa": "ɕjɑ˥˩ mjɛn", "syllable_count": 2, "sentences": [{"text": "桌子下面有一只小猫。", "target_word": "下面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "床下面放着我的鞋。", "target_word": "下面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树下面坐着几个老人。", "target_word": "下面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥下面有很多鱼。", "target_word": "下面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书在椅子下面，你看到了吗？", "target_word": "下面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把箱子放到桌子下面。", "target_word": "下面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图下面写着一行小字。", "target_word": "下面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家在你家下面，是三楼。", "target_word": "下面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他蹲在窗户下面等你。", "target_word": "下面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨很大，我们站在伞下面。", "target_word": "下面", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "某物体下边的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20572383-2a84-4d2e-a2d6-e1113f08bf28') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85987, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "下面", "is_correct": true, "explanation": "正确：下面（xià mian）表示某物下边的位置。"}, {"text": "下限", "is_correct": false, "explanation": "xiàn（第四声）与 mian 的声母和声调都不同，意思是“下限”（最低的界限）。"}, {"text": "下联", "is_correct": false, "explanation": "lián（第二声）与 mian 的声母不同，意思是“下联”（对联的下半句）。"}, {"text": "下田", "is_correct": false, "explanation": "tián（第二声）与 mian 的声母不同，意思是“下田”（到田里去干活）。"}, {"text": "假面", "is_correct": false, "explanation": "jiǎ（第三声）与 xià 的声母不同，意思是“假面”（假的面具）。"}], "explanations": {"下面": "正确：下面（xià mian）表示某物下边的位置。", "下限": "xiàn（第四声）与 mian 的声母和声调都不同，意思是“下限”（最低的界限）。", "下联": "lián（第二声）与 mian 的声母不同，意思是“下联”（对联的下半句）。", "下田": "tián（第二声）与 mian 的声母不同，意思是“下田”（到田里去干活）。", "假面": "jiǎ（第三声）与 xià 的声母不同，意思是“假面”（假的面具）。"}, "sentence_index": null, "correct_answer": "下面"}, "level_3": {"options": [{"text": "下面", "is_correct": true, "explanation": "正确：“下面”表示桌子的下方，与“有一只小猫”的语境相符。"}, {"text": "以后", "is_correct": false, "explanation": "语义：“以后”指时间或顺序在后，不表示空间上的下方。"}, {"text": "以北", "is_correct": false, "explanation": "搭配：“以北”要求前面是较大的地理范围，不能用在“桌子”后面。"}, {"text": "以东", "is_correct": false, "explanation": "搭配：“以东”要求前面是较大的地理范围，不能用在“桌子”后面。"}], "explanations": {"下面": "正确：“下面”表示桌子的下方，与“有一只小猫”的语境相符。", "以后": "语义：“以后”指时间或顺序在后，不表示空间上的下方。", "以北": "搭配：“以北”要求前面是较大的地理范围，不能用在“桌子”后面。", "以东": "搭配：“以东”要求前面是较大的地理范围，不能用在“桌子”后面。"}, "sentence_index": 0, "correct_answer": "下面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他比我下面三岁。", "explanation": "这里应该用〈小〉。“下面”表示下边的位置，不能用来比较年龄；说年纪比别人小要用“小”。"}, {"text": "他手下面有五个人。", "explanation": "这里应该用〈手底下〉。“手底下”是固定说法，指部下、手下的人；“手下面”不能这样用。"}, {"text": "我们下面再见。", "explanation": "这里应该用〈下次〉。“下次再见”是固定说法；“下面”不表示下一次的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983850f8-aa5e-46c1-a983-9f88fd71ecce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85987, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "下面", "is_correct": true, "explanation": "正确：下面（xià mian）表示某物下边的位置。"}, {"text": "下陷", "is_correct": false, "explanation": "xiàn（第四声）与 mian 的声母和声调都不同，意思是“下陷”（向下塌陷）。"}, {"text": "下线", "is_correct": false, "explanation": "xiàn（第四声）与 mian 的声母和声调都不同，意思是“下线”（产品从生产线上下来）。"}, {"text": "下篇", "is_correct": false, "explanation": "piān（第一声）与 mian 的声母不同，意思是“下篇”（文章或书的后半部分）。"}, {"text": "下弦", "is_correct": false, "explanation": "xián（第二声）与 mian 的声母不同，意思是“下弦”（半月的一个阶段，即下弦月）。"}], "explanations": {"下面": "正确：下面（xià mian）表示某物下边的位置。", "下陷": "xiàn（第四声）与 mian 的声母和声调都不同，意思是“下陷”（向下塌陷）。", "下线": "xiàn（第四声）与 mian 的声母和声调都不同，意思是“下线”（产品从生产线上下来）。", "下篇": "piān（第一声）与 mian 的声母不同，意思是“下篇”（文章或书的后半部分）。", "下弦": "xián（第二声）与 mian 的声母不同，意思是“下弦”（半月的一个阶段，即下弦月）。"}, "sentence_index": null, "correct_answer": "下面"}, "level_3": {"options": [{"text": "下面", "is_correct": true, "explanation": "正确：“下面”表示地图的下方，与“写着一行小字”的语境相符。"}, {"text": "以南", "is_correct": false, "explanation": "搭配：“以南”要求前面是较大的地理范围，不能用在“地图”后面。"}, {"text": "以西", "is_correct": false, "explanation": "搭配：“以西”要求前面是较大的地理范围，不能用在“地图”后面。"}, {"text": "以外", "is_correct": false, "explanation": "语义：“以外”指某个范围之外，句子说的是地图上的文字，不应写在地图之外。"}], "explanations": {"下面": "正确：“下面”表示地图的下方，与“写着一行小字”的语境相符。", "以南": "搭配：“以南”要求前面是较大的地理范围，不能用在“地图”后面。", "以西": "搭配：“以西”要求前面是较大的地理范围，不能用在“地图”后面。", "以外": "语义：“以外”指某个范围之外，句子说的是地图上的文字，不应写在地图之外。"}, "sentence_index": 6, "correct_answer": "下面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的成绩比我下面三分。", "explanation": "这里应该用〈低〉。“下面”不表示分数的高低；说成绩比别人低要用“低”。"}, {"text": "我下面一年去北京工作。", "explanation": "这里应该用〈明年〉或〈下一年〉。“下面”不能修饰表示年份的时间，说下一年要用“明年”。"}, {"text": "下面我们讨论第二个问题。", "explanation": "这里的“下面”表示“接下来、后面要说的”，是时间、顺序上的意思，不是某物下边的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983850f8-aa5e-46c1-a983-9f88fd71ecce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85987, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "猫在沙发下面了睡觉。", "corrected_sentence": "猫在沙发下面睡觉。", "error_description": "“下面”是方位词，后面不能直接加“了”。应说“猫在沙发下面睡觉”，“猫在沙发下面了睡觉”是错误。正确句：猫在沙发下面睡觉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983850f8-aa5e-46c1-a983-9f88fd71ecce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85987, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "钥匙在沙发下面里。", "corrected_sentence": "钥匙在沙发下面。", "error_description": "“下面”本身就是方位词，后面不能再加“里”。错误形式是“沙发下面里”，正确形式是“沙发下面”。正确句：钥匙在沙发下面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '983850f8-aa5e-46c1-a983-9f88fd71ecce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
