INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85989, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坐", "is_correct": false, "explanation": "无关：“坐”指身体停放在椅子等物上，与“不在”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "无关：“唱”指发出歌声，与“不在”没有反义关系。"}, {"text": "在", "is_correct": true, "explanation": "正确。“在”与“不在”意义相反，表示人在某处。"}, {"text": "洗", "is_correct": false, "explanation": "无关：“洗”指用水清除污物，与“不在”没有反义关系。"}], "correct_answer": "在", "explanations": {"坐": "无关：“坐”指身体停放在椅子等物上，与“不在”没有反义关系。", "唱": "无关：“唱”指发出歌声，与“不在”没有反义关系。", "在": "正确。“在”与“不在”意义相反，表示人在某处。", "洗": "无关：“洗”指用水清除污物，与“不在”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85989, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "“不在”是说这个人不在这里，去了别的地方。", "primary_collocate": null, "pronunciation": "bù zài", "ipa": "pu⁵¹ tsaɪ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "小王现在不在，他去银行了。", "target_word": "不在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理不在办公室，他出去开会了。", "target_word": "不在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不在家，她去超市买东西了。", "target_word": "不在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你来的时候，我正好不在。", "target_word": "不在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸今天不在，晚上才回来。", "target_word": "不在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不在，他去楼下接电话了。", "target_word": "不在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找他三次，他都不在。", "target_word": "不在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问王医生在吗？他现在不在。", "target_word": "不在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟不在房间，他去同学家玩了。", "target_word": "不在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出差了，这个星期都不在公司。", "target_word": "不在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "人不在这里，去了别的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1dfd233-60e1-4be7-a6ef-22ae12c1f292') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85989, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在场", "is_correct": false, "explanation": "语义：“在场”指人在现场，与后半句“他去银行了”矛盾。"}, {"text": "不在", "is_correct": true, "explanation": "正确。“不在”说明小王不在这里，与“他去银行了”一致。"}, {"text": "到场", "is_correct": false, "explanation": "语义：“到场”指赶到现场，与“他去银行了”矛盾。"}, {"text": "出席", "is_correct": false, "explanation": "语域：“出席”偏正式书面，与口语句不合；且指参加会议等活动，与“去银行”不符。"}], "explanations": {"在场": "语义：“在场”指人在现场，与后半句“他去银行了”矛盾。", "不在": "正确。“不在”说明小王不在这里，与“他去银行了”一致。", "到场": "语义：“到场”指赶到现场，与“他去银行了”矛盾。", "出席": "语域：“出席”偏正式书面，与口语句不合；且指参加会议等活动，与“去银行”不符。"}, "sentence_index": 0, "correct_answer": "不在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班不在三十个人。", "explanation": "这里应该用〈不到〉。“不在”指人或东西不处于某个地点，不能用来表示人数没有达到某个数。"}, {"text": "她不在我的朋友，只是同事。", "explanation": "这里应该用〈不是〉。“不在”指人或东西不处于某个地点，不能用来判断两人是什么关系。"}, {"text": "他不在十八岁，还是个孩子。", "explanation": "这里应该用〈未满〉。“不在”指不处于某个地点，不能用来表示年龄还没达到某个岁数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85989, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现身", "is_correct": false, "explanation": "语域：“现身”偏书面，与口语句不合；且表示出现，与“找他三次”的结果矛盾。"}, {"text": "打算", "is_correct": false, "explanation": "语法：“打算”后面要接要做的事，“他都打算”不完整，也不能说明为什么找不到他。"}, {"text": "不在", "is_correct": true, "explanation": "正确。“不在”说明他每次都不在，解释了为什么找不到他。"}, {"text": "露面", "is_correct": false, "explanation": "语义：“露面”指出现在人前，与“找他三次”找不到人的语境矛盾。"}], "explanations": {"现身": "语域：“现身”偏书面，与口语句不合；且表示出现，与“找他三次”的结果矛盾。", "打算": "语法：“打算”后面要接要做的事，“他都打算”不完整，也不能说明为什么找不到他。", "不在": "正确。“不在”说明他每次都不在，解释了为什么找不到他。", "露面": "语义：“露面”指出现在人前，与“找他三次”找不到人的语境矛盾。"}, "sentence_index": 6, "correct_answer": "不在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次花的钱不在一万。", "explanation": "这里应该用〈不止〉。“不在”指不处于某个地点，不能用来表示数额超过某个数。"}, {"text": "我不在你的看法上。", "explanation": "这里应该用〈不同意〉。“不在”指不处于某个地点，不能用来表示对别人观点的态度。"}, {"text": "这台电脑不在两千块钱。", "explanation": "这里应该用〈低于〉。“不在”指不处于某个地点，不能用来表示价格比某个数少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85989, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今天不不在公司，下午才来。", "corrected_sentence": "他今天不在公司，下午才来。", "error_description": "错误：多了一个“不”。“不在”前面不能再加“不”，应说“他今天不在公司”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
