INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85990, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "动词，表示人或东西不处于某个地点。", "primary_collocate": null, "pronunciation": "bù zài", "ipa": "pu⁵¹ tsaɪ̯⁵¹", "syllable_count": 2, "sentences": [{"text": "我的钥匙不在桌子上。", "target_word": "不在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机不在包里，可能忘在家里了。", "target_word": "不在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那本词典不在书架上，我找了半天。", "target_word": "不在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家书店不在这条街上。", "target_word": "不在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那封信不在信箱里，可能被风吹走了。", "target_word": "不在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那支笔不在抽屉里，可能掉在地上了。", "target_word": "不在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的书不在我这儿。", "target_word": "不在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫不在院子里，它跑到哪儿去了？", "target_word": "不在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把伞不在门口的架子上，应该是被人拿走了。", "target_word": "不在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家不在市中心，在城市的东边。", "target_word": "不在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "人或东西不处于某个地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: 3 words above tier T1 (max 2): 封信 (Zipf 3.81), 信箱 (Zipf 3.77), 风吹 (Zipf 3.3)']::text[], 'f1dfd233-60e1-4be7-a6ef-22ae12c1f292') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85990, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挂", "is_correct": false, "explanation": "搭配：“挂”多指悬挂在墙上等处，不说钥匙“挂在桌子上”。"}, {"text": "停", "is_correct": false, "explanation": "语义：“停”指停止或停留，与钥匙放在桌子上的存放义不合。"}, {"text": "不在", "is_correct": true, "explanation": "正确。“不在”表示钥匙不处于桌子上，与句意一致。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与“钥匙在桌子上”的表述不合。"}], "explanations": {"挂": "搭配：“挂”多指悬挂在墙上等处，不说钥匙“挂在桌子上”。", "停": "语义：“停”指停止或停留，与钥匙放在桌子上的存放义不合。", "不在": "正确。“不在”表示钥匙不处于桌子上，与句意一致。", "吃": "语义：“吃”指进食，与“钥匙在桌子上”的表述不合。"}, "sentence_index": 0, "correct_answer": "不在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店不在十个员工。", "explanation": "这里应该用〈不到〉。“不在”指人或东西不处于某个地点，不能用来表示人数没有达到某个数。"}, {"text": "他不在老板，是员工。", "explanation": "这里应该用〈不是〉。“不在”指人或东西不处于某个地点，不能用来判断一个人的身份。"}, {"text": "他不在二十岁，还是个孩子。", "explanation": "这里应该用〈未满〉。“不在”指不处于某个地点，不能用来表示年龄还未达到某个岁数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85990, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "来", "is_correct": false, "explanation": "语义：“来”要求能移动的主语，书不能“来”，与句意不合。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”指发出歌声，不能用来表示书放在我这儿。"}, {"text": "不在", "is_correct": true, "explanation": "正确。“不在”表示书不在我这儿，与句意一致。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”指人或动物快速移动，书不能“跑”到我这儿。"}], "explanations": {"来": "语义：“来”要求能移动的主语，书不能“来”，与句意不合。", "唱": "搭配：“唱”指发出歌声，不能用来表示书放在我这儿。", "不在": "正确。“不在”表示书不在我这儿，与句意一致。", "跑": "语义：“跑”指人或动物快速移动，书不能“跑”到我这儿。"}, "sentence_index": 6, "correct_answer": "不在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次的费用不在三百元。", "explanation": "这里应该用〈不超过〉。“不在”指不处于某个地点，不能用来表示数额的上限。"}, {"text": "我不在你的方案上。", "explanation": "这里应该用〈不同意〉。“不在”指不处于某个地点，不能用来表示对别人方案的态度。"}, {"text": "这次比赛的奖金不在一万。", "explanation": "这里应该用〈高于〉。“不在”指不处于某个地点，不能用来表示数额超过某个数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85990, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的书不在在桌子上。", "corrected_sentence": "我的书不在桌子上。", "error_description": "错误：多了一个“在”。“不在”后直接接处所“桌子上”，不能重复“在”，应说“我的书不在桌子上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85990, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天没不在家，我给他打了电话。", "corrected_sentence": "他昨天不在家，我给他打了电话。", "error_description": "错误：“没”与“不”叠用。“不在”本身已表示否定，前面不能再加“没”，应说“他昨天不在家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9032c27b-5f69-4509-92e5-d01d50e6aa82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
