INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85991, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "“元”是说钱的数目，是中国钱的一种叫法。", "primary_collocate": null, "pronunciation": "yuán", "ipa": "ɥɛn³⁵", "syllable_count": 1, "sentences": [{"text": "这本书只要十五元。", "target_word": "元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一杯茶二十元。", "target_word": "元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服八十元，不贵。", "target_word": "元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "苹果一斤六元。", "target_word": "元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天花了三十元。", "target_word": "元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "午饭一共四十五元。", "target_word": "元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给了我五十元。", "target_word": "元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个包要一百二十元。", "target_word": "元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐车到那儿只要三元。", "target_word": "元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋一百元，你买吗？", "target_word": "元", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "元钱", "label": "复合"}], "register": "中性", "sense_fingerprint": "说价钱、花钱多少时用的钱数叫法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97e07d7-e53b-4f4d-b1cf-a3cc62b4f69f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85991, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "元", "is_correct": true, "explanation": "元 yuán 是钱的单位，正是要找的词。"}, {"text": "远", "is_correct": false, "explanation": "yuǎn（第三声）与 yuán（第二声）声调不同，意思是远。"}, {"text": "院", "is_correct": false, "explanation": "yuàn（第四声）与 yuán（第二声）声调不同，意思是院子。"}, {"text": "愿", "is_correct": false, "explanation": "yuàn（第四声）与 yuán（第二声）声调不同，意思是愿意。"}, {"text": "盐", "is_correct": false, "explanation": "yán（第二声）比 yuán 少了介音 u，意思是盐。"}], "explanations": {"元": "元 yuán 是钱的单位，正是要找的词。", "远": "yuǎn（第三声）与 yuán（第二声）声调不同，意思是远。", "院": "yuàn（第四声）与 yuán（第二声）声调不同，意思是院子。", "愿": "yuàn（第四声）与 yuán（第二声）声调不同，意思是愿意。", "盐": "yán（第二声）比 yuán 少了介音 u，意思是盐。"}, "sentence_index": null, "correct_answer": "元"}, "level_3": {"options": [{"text": "元", "is_correct": true, "explanation": "“元”是计量钱数的量词，“只要十五元”表示价钱，符合语境。"}, {"text": "本", "is_correct": false, "explanation": "语义：“本”计量的是书册，不能用来表示价钱。"}, {"text": "件", "is_correct": false, "explanation": "搭配：“件”不用来计量“书”，也不能表示价钱。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”多用于动物或成对的东西，不能用于“书”或价钱。"}], "explanations": {"元": "“元”是计量钱数的量词，“只要十五元”表示价钱，符合语境。", "本": "语义：“本”计量的是书册，不能用来表示价钱。", "件": "搭配：“件”不用来计量“书”，也不能表示价钱。", "只": "搭配：“只”多用于动物或成对的东西，不能用于“书”或价钱。"}, "sentence_index": 0, "correct_answer": "元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "元很重要，大家都离不开。", "explanation": "这里应该用〈钱〉。元是计量单位，要和数字连用（如“五元”），不能单独作主语，应说“钱很重要”。"}, {"text": "我花了很多元。", "explanation": "这里应该用〈钱〉。元要和具体数字连用，“很多”不能直接修饰“元”，应说“我花了很多钱”。"}, {"text": "他把元全花光了。", "explanation": "这里应该用〈钱〉。元前面要有数字，“把元全花光”不通，应说“把钱全花光”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85991, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "元", "is_correct": true, "explanation": "元 yuán 是钱的单位，正是要找的词。"}, {"text": "约", "is_correct": false, "explanation": "yuē（第一声）与 yuán（第二声）声调不同，意思是大约。"}, {"text": "月", "is_correct": false, "explanation": "yuè（第四声）与 yuán（第二声）声调不同，意思是月亮、月份。"}, {"text": "越", "is_correct": false, "explanation": "yuè（第四声）与 yuán（第二声）声调不同，意思是越来越。"}, {"text": "言", "is_correct": false, "explanation": "yán（第二声）比 yuán 少了介音 u，意思是说话。"}], "explanations": {"元": "元 yuán 是钱的单位，正是要找的词。", "约": "yuē（第一声）与 yuán（第二声）声调不同，意思是大约。", "月": "yuè（第四声）与 yuán（第二声）声调不同，意思是月亮、月份。", "越": "yuè（第四声）与 yuán（第二声）声调不同，意思是越来越。", "言": "yán（第二声）比 yuán 少了介音 u，意思是说话。"}, "sentence_index": null, "correct_answer": "元"}, "level_3": {"options": [{"text": "元", "is_correct": true, "explanation": "“元”计量钱数，“给了我五十元”表示金额，符合语境。"}, {"text": "名", "is_correct": false, "explanation": "搭配：“名”用于人，不能用来计量“给我”的东西或钱。"}, {"text": "座", "is_correct": false, "explanation": "语义：“座”指山、建筑等大型物体，不能计量钱。"}, {"text": "所", "is_correct": false, "explanation": "语义：“所”计量房屋、学校等，“给了我五十所”与钱数矛盾。"}], "explanations": {"元": "“元”计量钱数，“给了我五十元”表示金额，符合语境。", "名": "搭配：“名”用于人，不能用来计量“给我”的东西或钱。", "座": "语义：“座”指山、建筑等大型物体，不能计量钱。", "所": "语义：“所”计量房屋、学校等，“给了我五十所”与钱数矛盾。"}, "sentence_index": 6, "correct_answer": "元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天工作十元。", "explanation": "这里应该用〈小时〉，说“工作十个小时”。元只计钱数，不能计量时间。"}, {"text": "这袋米重五元。", "explanation": "这里应该用〈公斤〉。元只计钱数，计量重量要用“公斤”或“斤”。"}, {"text": "我们班有三元学生。", "explanation": "这里应该用〈名〉。元只计钱数，数人要用“名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85991, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这支笔只要四块元。", "corrected_sentence": "这支笔只要四元。", "error_description": "量词错误：“元”和“块”都是货币单位，不能叠用，应说“四元”或“四块”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85991, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这顿饭一共两十元。", "corrected_sentence": "这顿饭一共二十元。", "error_description": "数词错误：“十”前不能用“两”，应说“二十”。正确说法是“这顿饭一共二十元。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
