INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85992, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "中国货币的基本单位，一元等于十角。", "primary_collocate": null, "pronunciation": "yuán", "ipa": "ɥɛn³⁵", "syllable_count": 1, "sentences": [{"text": "一元等于十角。", "target_word": "元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国钱的基本单位是元。", "target_word": "元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一元钱可以换十个一角。", "target_word": "元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这张十元的钱给我。", "target_word": "元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小店只收一元的硬币。", "target_word": "元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一张一百元的钱可以换十张十元的。", "target_word": "元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一元的硬币比一角的大。", "target_word": "元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有两张五元的钱。", "target_word": "元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的小盒里有三枚一元硬币。", "target_word": "元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十元就是一百角。", "target_word": "元", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "元钱", "label": "复合"}], "register": "中性", "sense_fingerprint": "中国货币的基本单位，和角的换算", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97e07d7-e53b-4f4d-b1cf-a3cc62b4f69f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85992, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "元", "is_correct": true, "explanation": "元 yuán 是货币的基本单位，正是要找的词。"}, {"text": "远", "is_correct": false, "explanation": "yuǎn（第三声）与 yuán（第二声）声调不同，意思是远。"}, {"text": "院", "is_correct": false, "explanation": "yuàn（第四声）与 yuán（第二声）声调不同，意思是院子。"}, {"text": "愿", "is_correct": false, "explanation": "yuàn（第四声）与 yuán（第二声）声调不同，意思是愿意。"}, {"text": "盐", "is_correct": false, "explanation": "yán（第二声）比 yuán 少了介音 u，意思是盐。"}], "explanations": {"元": "元 yuán 是货币的基本单位，正是要找的词。", "远": "yuǎn（第三声）与 yuán（第二声）声调不同，意思是远。", "院": "yuàn（第四声）与 yuán（第二声）声调不同，意思是院子。", "愿": "yuàn（第四声）与 yuán（第二声）声调不同，意思是愿意。", "盐": "yán（第二声）比 yuán 少了介音 u，意思是盐。"}, "sentence_index": null, "correct_answer": "元"}, "level_3": {"options": [{"text": "元", "is_correct": true, "explanation": "“一元等于十角”中，“元”是货币基本单位，与“角”换算。"}, {"text": "分", "is_correct": false, "explanation": "语义：“分”比“角”小得多，一分不等于十角，这样换算不成立。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”计量纸币时要带名词，如“一张一百元的钱”；“一张等于十角”不成立，不能作货币单位。"}, {"text": "次", "is_correct": false, "explanation": "语义：“次”计量次数，不能表示货币单位。"}], "explanations": {"元": "“一元等于十角”中，“元”是货币基本单位，与“角”换算。", "分": "语义：“分”比“角”小得多，一分不等于十角，这样换算不成立。", "张": "搭配：“张”计量纸币时要带名词，如“一张一百元的钱”；“一张等于十角”不成立，不能作货币单位。", "次": "语义：“次”计量次数，不能表示货币单位。"}, "sentence_index": 0, "correct_answer": "元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "元不能当饭吃。", "explanation": "这里应该用〈钱〉。元是计量单位，要和数字连用（如“一元”），不能单独指钱，应说“钱不能当饭吃”。"}, {"text": "他花光了身上的元。", "explanation": "这里应该用〈钱〉。元前面要有数字，“身上的元”不通，应说“身上的钱”。"}, {"text": "他把元存进了银行。", "explanation": "这里应该用〈钱〉。元要和数字连用，不能直接当“钱”存进银行，应说“他把钱存进了银行”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85992, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "元", "is_correct": true, "explanation": "元 yuán 是货币的基本单位，正是要找的词。"}, {"text": "约", "is_correct": false, "explanation": "yuē（第一声）与 yuán（第二声）声调不同，意思是大约。"}, {"text": "月", "is_correct": false, "explanation": "yuè（第四声）与 yuán（第二声）声调不同，意思是月亮、月份。"}, {"text": "越", "is_correct": false, "explanation": "yuè（第四声）与 yuán（第二声）声调不同，意思是越来越。"}, {"text": "言", "is_correct": false, "explanation": "yán（第二声）比 yuán 少了介音 u，意思是说话。"}], "explanations": {"元": "元 yuán 是货币的基本单位，正是要找的词。", "约": "yuē（第一声）与 yuán（第二声）声调不同，意思是大约。", "月": "yuè（第四声）与 yuán（第二声）声调不同，意思是月亮、月份。", "越": "yuè（第四声）与 yuán（第二声）声调不同，意思是越来越。", "言": "yán（第二声）比 yuán 少了介音 u，意思是说话。"}, "sentence_index": null, "correct_answer": "元"}, "level_3": {"options": [{"text": "元", "is_correct": true, "explanation": "“一元的硬币”中，“元”计量货币面值，符合语境。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”多用于动物或成对的东西，不能用来计量硬币。"}, {"text": "座", "is_correct": false, "explanation": "语义：“座”指大型建筑或山，不能修饰硬币。"}, {"text": "头", "is_correct": false, "explanation": "语义：“头”多用于牲畜，不能用来计量硬币。"}], "explanations": {"元": "“一元的硬币”中，“元”计量货币面值，符合语境。", "只": "搭配：“只”多用于动物或成对的东西，不能用来计量硬币。", "座": "语义：“座”指大型建筑或山，不能修饰硬币。", "头": "语义：“头”多用于牲畜，不能用来计量硬币。"}, "sentence_index": 6, "correct_answer": "元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车跑了三元。", "explanation": "这里应该用〈公里〉。元只计钱数，不能计量距离。"}, {"text": "他读了两元书。", "explanation": "这里应该用〈本〉。元只计钱数，计量书要用“本”。"}, {"text": "我养了三元猫。", "explanation": "这里应该用〈只〉。元只计钱数，计量猫要用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85992, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一元元钱可以买两块糖。", "corrected_sentence": "一元钱可以买两块糖。", "error_description": "重复错误：“元”多写了一次。“一元钱”中只用一个“元”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85992, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两十元就是两百角。", "corrected_sentence": "二十元就是两百角。", "error_description": "数词错误：十位数不能说“两十”，应为“二十”。“两”不能用于“十”前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
