INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85994, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词或介词，表示原因，相当于“因为”。", "primary_collocate": null, "pronunciation": "yīn", "ipa": "in⁵⁵", "syllable_count": 1, "sentences": [{"text": "比赛因下雨改到了明天。", "target_word": "因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因生病没有来上课。", "target_word": "因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王因工作忙，很少回家。", "target_word": "因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校因天气不好停课了。", "target_word": "因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机因大雾晚点了两个小时。", "target_word": "因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她因家里有事先走了。", "target_word": "因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店因装修暂时不开门。", "target_word": "因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我因感冒没去看电影。", "target_word": "因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因下大雪，路上的车很少。", "target_word": "因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因迟到，不好意思地笑了。", "target_word": "因", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "因为", "label": "复合"}, {"form": "因此", "label": "复合"}], "register": "书面", "sense_fingerprint": "放在原因前，表示因为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97e07d7-e53b-4f4d-b1cf-a3cc62b4f69f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85994, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "因", "is_correct": true, "explanation": "正确。因（yīn，第一声）表示原因，相当于“因为”。"}, {"text": "银", "is_correct": false, "explanation": "yín（第二声）与 yīn（第一声）声调不同，意思是银子、银色。"}, {"text": "引", "is_correct": false, "explanation": "yǐn（第三声）与 yīn（第一声）声调不同，意思是引导、引起。"}, {"text": "英", "is_correct": false, "explanation": "yīng 与 yīn 只有韵尾不同（-ng 与 -n），意思是英国、英雄。"}], "explanations": {"因": "正确。因（yīn，第一声）表示原因，相当于“因为”。", "银": "yín（第二声）与 yīn（第一声）声调不同，意思是银子、银色。", "引": "yǐn（第三声）与 yīn（第一声）声调不同，意思是引导、引起。", "英": "yīng 与 yīn 只有韵尾不同（-ng 与 -n），意思是英国、英雄。"}, "sentence_index": null, "correct_answer": "因"}, "level_3": {"options": [{"text": "因", "is_correct": true, "explanation": "正确。“因”引出原因，“比赛因下雨改到了明天”句意通顺。"}, {"text": "为了", "is_correct": false, "explanation": "语义：“为了”表示目的，改期不能是为了“下雨”。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：“虽然”表示让步，与“改到明天”的因果关系相悖。"}, {"text": "只有", "is_correct": false, "explanation": "搭配：“只有”要与“才”呼应，单独不能引出原因。"}], "explanations": {"因": "正确。“因”引出原因，“比赛因下雨改到了明天”句意通顺。", "为了": "语义：“为了”表示目的，改期不能是为了“下雨”。", "虽然": "语义：“虽然”表示让步，与“改到明天”的因果关系相悖。", "只有": "搭配：“只有”要与“才”呼应，单独不能引出原因。"}, "sentence_index": 0, "correct_answer": "因"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个方案因地制宜，很适合我们学校。", "explanation": "这里的“因”是“依据、根据”义，见于成语“因地制宜”，与本词条表示原因的连词义不同，不能用来引出原因。"}, {"text": "这种药的效果因人而异。", "explanation": "这里的“因”是“依据”义，见于成语“因人而异”，表示根据每个人的不同，与本词条表示原因的连词义不同。"}, {"text": "价格因质量不同而有高有低。", "explanation": "这里的“因”是“依据、随着”义（因……而……），表示根据质量不同，与本词条表示原因的连词义不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85994, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "因", "is_correct": true, "explanation": "正确。因（yīn，第一声）表示原因，相当于“因为”。"}, {"text": "印", "is_correct": false, "explanation": "yìn（第四声）与 yīn（第一声）声调不同，意思是印章。"}, {"text": "饮", "is_correct": false, "explanation": "yǐn（第三声）与 yīn（第一声）声调不同，意思是喝。"}, {"text": "衣", "is_correct": false, "explanation": "yī 与 yīn 只有韵尾不同（去掉 -n），意思是衣服。"}, {"text": "鹰", "is_correct": false, "explanation": "yīng 与 yīn 只有韵尾不同（-ng 与 -n），意思是老鹰。"}], "explanations": {"因": "正确。因（yīn，第一声）表示原因，相当于“因为”。", "印": "yìn（第四声）与 yīn（第一声）声调不同，意思是印章。", "饮": "yǐn（第三声）与 yīn（第一声）声调不同，意思是喝。", "衣": "yī 与 yīn 只有韵尾不同（去掉 -n），意思是衣服。", "鹰": "yīng 与 yīn 只有韵尾不同（-ng 与 -n），意思是老鹰。"}, "sentence_index": null, "correct_answer": "因"}, "level_3": {"options": [{"text": "因", "is_correct": true, "explanation": "正确。“因”引出原因，“商店因装修暂时不开门”句意通顺。"}, {"text": "即使", "is_correct": false, "explanation": "语义：“即使”表示让步，装修与暂时不开门之间是因果关系，不是让步。"}, {"text": "哪怕", "is_correct": false, "explanation": "搭配：“哪怕”后一般接极端假设，不能引出“装修”这一具体原因。"}, {"text": "纵然", "is_correct": false, "explanation": "语义：“纵然”表示让步，与“暂时不开门”的因果关系不合。"}], "explanations": {"因": "正确。“因”引出原因，“商店因装修暂时不开门”句意通顺。", "即使": "语义：“即使”表示让步，装修与暂时不开门之间是因果关系，不是让步。", "哪怕": "搭配：“哪怕”后一般接极端假设，不能引出“装修”这一具体原因。", "纵然": "语义：“纵然”表示让步，与“暂时不开门”的因果关系不合。"}, "sentence_index": 6, "correct_answer": "因"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事要因情况而定。", "explanation": "这里的“因”是“依据、根据”义，见于“因情况而定”，不是表示原因的连词。"}, {"text": "他因材施教，很受学生欢迎。", "explanation": "这里的“因”是“依据、根据”义，见于成语“因材施教”，与表示原因的连词义不同。"}, {"text": "我们应当因时制宜，灵活处理。", "explanation": "这里的“因”是“依据、根据”义，见于成语“因时制宜”，与表示原因的连词义不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他因了头疼，没有去上班。", "corrected_sentence": "他因头疼，没有去上班。", "error_description": "“因”后面不能加“了”。正确说法是“他因头疼，没有去上班。”多出的“了”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小李因加班，因错过了末班车。", "corrected_sentence": "小李因加班，错过了末班车。", "error_description": "“因”重复使用：前一分句已用“因”引出原因，后一分句不应再加“因”。正确说法是“小李因加班，错过了末班车。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
