INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85995, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "“关于”是说下面要讲的事和什么有关。", "primary_collocate": null, "pronunciation": "guān yú", "ipa": "kwan˥˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "关于这件事，我想问你一个问题。", "target_word": "关于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "关于明天的会，老师还没通知我们。", "target_word": "关于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "关于这个问题，大家有不同的看法。", "target_word": "关于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "关于他的病，医生说不用担心。", "target_word": "关于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "关于价格，我们可以再谈谈。", "target_word": "关于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "关于旅行的计划，你有什么想法？", "target_word": "关于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "关于学习方法，他给了我很多建议。", "target_word": "关于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "关于那天晚上的事，我什么都不记得了。", "target_word": "关于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关于工作，我已经跟经理说过了。", "target_word": "关于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关于去机场的路线，我问了朋友。", "target_word": "关于", "complexity_tier": "T3", "furigana": "guān yú qù jī chǎng de lù xiàn, wǒ wèn le péng you.", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "关于：介词，放在句首引出接下来要谈的话题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4282b7-916c-4da7-bd32-a72c5ffbca2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85995, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "关于", "is_correct": true, "explanation": "正确答案。关于是介词，引出接下来要谈的话题。"}, {"text": "甘于", "is_correct": false, "explanation": "甘于（gān yú）的第一音节少了介音 u，与 guān 声母相同、韵母不同；甘于意思是甘心、乐意，不是引出话题的关于。"}, {"text": "惯于", "is_correct": false, "explanation": "惯于（guàn yú）与 guān yú 的第一音节声调不同，guàn 是第四声，意思是习惯于。"}, {"text": "专于", "is_correct": false, "explanation": "专于（zhuān yú）与 guān yú 声母不同（zh 与 g），意思是专注于。"}], "explanations": {"关于": "正确答案。关于是介词，引出接下来要谈的话题。", "甘于": "甘于（gān yú）的第一音节少了介音 u，与 guān 声母相同、韵母不同；甘于意思是甘心、乐意，不是引出话题的关于。", "惯于": "惯于（guàn yú）与 guān yú 的第一音节声调不同，guàn 是第四声，意思是习惯于。", "专于": "专于（zhuān yú）与 guān yú 声母不同（zh 与 g），意思是专注于。"}, "sentence_index": null, "correct_answer": "关于"}, "level_3": {"options": [{"text": "关于", "is_correct": true, "explanation": "正确答案。关于引出话题，与“关于这件事，我想问你一个问题”相符。"}, {"text": "按照", "is_correct": false, "explanation": "搭配：“按照”后要接规则、标准或计划，不能说“按照这件事”。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”需带处置对象并与动词连用，“把这件事，我想问你一个问题”不成立。"}, {"text": "替", "is_correct": false, "explanation": "配价：“替”后接代替或为之服务的人，不能接“这件事”。"}], "explanations": {"关于": "正确答案。关于引出话题，与“关于这件事，我想问你一个问题”相符。", "按照": "搭配：“按照”后要接规则、标准或计划，不能说“按照这件事”。", "把": "语法：“把”需带处置对象并与动词连用，“把这件事，我想问你一个问题”不成立。", "替": "配价：“替”后接代替或为之服务的人，不能接“这件事”。"}, "sentence_index": 0, "correct_answer": "关于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我关于图书馆借了一本书。", "explanation": "这里应该用〈从〉。关于只引出谈论的对象，不能表示从哪里得到东西；从图书馆借书要用“从”。"}, {"text": "我们关于热情的服务赢得了顾客。", "explanation": "这里应该用〈凭〉。关于不能表示凭借什么取得结果；“凭热情的服务赢得了顾客”要用“凭”。"}, {"text": "我关于同事去了北京。", "explanation": "这里应该用〈跟〉。关于不能表示和谁一起做事；“跟同事去北京”要用“跟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85995, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关于", "is_correct": true, "explanation": "正确答案。关于引出谈论的内容，与“关于学习方法，他给了我很多建议”相符。"}, {"text": "比", "is_correct": false, "explanation": "语义：“比”表示比较，句中没有可以相互比较的两项。"}, {"text": "向", "is_correct": false, "explanation": "配价：“向”引出动作的对象，给建议的对象应是人，不能接“学习方法”。"}, {"text": "给", "is_correct": false, "explanation": "语法：“给”后接受益对象，“学习方法”不能作受益者，“给学习方法，他给了我很多建议”不通。"}], "explanations": {"关于": "正确答案。关于引出谈论的内容，与“关于学习方法，他给了我很多建议”相符。", "比": "语义：“比”表示比较，句中没有可以相互比较的两项。", "向": "配价：“向”引出动作的对象，给建议的对象应是人，不能接“学习方法”。", "给": "语法：“给”后接受益对象，“学习方法”不能作受益者，“给学习方法，他给了我很多建议”不通。"}, "sentence_index": 6, "correct_answer": "关于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他关于沙发上看电视。", "explanation": "这里应该用〈在〉。关于不能表示动作发生的地点；“在沙发上看电视”要用“在”。"}, {"text": "他关于大家发言。", "explanation": "这里应该用〈替〉。关于只引出谈论的内容，不能表示代替谁做事；为大家做事要说“替大家发言”。"}, {"text": "我关于老师请教了问题。", "explanation": "这里应该用〈向〉。关于不能表示向谁请教；表示请教的对象要用“向老师请教”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85995, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "关于关于那个计划，我们下周再讨论。", "corrected_sentence": "关于那个计划，我们下周再讨论。", "error_description": "错误形式：“关于”重复出现。“关于”是介词，引出话题，只用一次，不能叠用。正确形式为“关于那个计划，我们下周再讨论”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85995, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "关于的周末的安排，我还没想好。", "corrected_sentence": "关于周末的安排，我还没想好。", "error_description": "错误形式：“关于”后面多加了“的”。“关于”是介词，后面直接接话题，不能带“的”。正确形式为“关于周末的安排，我还没想好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
