INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85996, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，引出讲述、涉及的对象或范围。", "primary_collocate": null, "pronunciation": "guān yú", "ipa": "kwan˥˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "我昨天看了一本关于历史的书。", "target_word": "关于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写了一篇关于环保的文章。", "target_word": "关于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一部关于爱情的电影。", "target_word": "关于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上有很多关于这个城市的介绍。", "target_word": "关于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她给我讲了一个关于猫的故事。", "target_word": "关于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没听说过关于这件事的消息。", "target_word": "关于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问了几个关于课文的问题。", "target_word": "关于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想找几本关于孩子教育的书。", "target_word": "关于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很想知道关于考试的消息。", "target_word": "关于", "complexity_tier": "T3", "furigana": "tā hěn xiǎng zhī dào guān yú kǎo shì de xiāo xi.", "sentence_source": "generated"}, {"text": "报纸上有一条关于天气的新闻。", "target_word": "关于", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "关于：介词，与“的”连用，限定书、文章、消息等内容涉及的对象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac4282b7-916c-4da7-bd32-a72c5ffbca2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85996, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "关于", "is_correct": true, "explanation": "正确答案。关于修饰书、文章、消息等，引出它们涉及的内容。"}, {"text": "甘于", "is_correct": false, "explanation": "甘于（gān yú）的第一音节少了介音 u，与 guān 声母相同、韵母不同；甘于意思是甘心、乐意，不是“关于历史的书”的关于。"}, {"text": "惯于", "is_correct": false, "explanation": "惯于（guàn yú）与 guān yú 的第一音节声调不同，guàn 是第四声，意思是习惯于。"}, {"text": "专于", "is_correct": false, "explanation": "专于（zhuān yú）与 guān yú 声母不同（zh 与 g），意思是专注于。"}], "explanations": {"关于": "正确答案。关于修饰书、文章、消息等，引出它们涉及的内容。", "甘于": "甘于（gān yú）的第一音节少了介音 u，与 guān 声母相同、韵母不同；甘于意思是甘心、乐意，不是“关于历史的书”的关于。", "惯于": "惯于（guàn yú）与 guān yú 的第一音节声调不同，guàn 是第四声，意思是习惯于。", "专于": "专于（zhuān yú）与 guān yú 声母不同（zh 与 g），意思是专注于。"}, "sentence_index": null, "correct_answer": "关于"}, "level_3": {"options": [{"text": "关于", "is_correct": true, "explanation": "正确答案。关于修饰书，说明这本书的内容是历史。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”需带处置对象并与动词连用，不能修饰名词“书”，“我昨天看了一本把历史的书”不通。"}, {"text": "向", "is_correct": false, "explanation": "语义：“向”表示方向或对象，书不能朝着历史去，“向历史的书”讲不通。"}, {"text": "跟", "is_correct": false, "explanation": "搭配：“跟”引出的对象不能修饰书，这里应说“跟历史有关的书”。"}], "explanations": {"关于": "正确答案。关于修饰书，说明这本书的内容是历史。", "把": "语法：“把”需带处置对象并与动词连用，不能修饰名词“书”，“我昨天看了一本把历史的书”不通。", "向": "语义：“向”表示方向或对象，书不能朝着历史去，“向历史的书”讲不通。", "跟": "搭配：“跟”引出的对象不能修饰书，这里应说“跟历史有关的书”。"}, "sentence_index": 0, "correct_answer": "关于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很关于历史。", "explanation": "这里应该用〈关心〉。关于是修饰书籍、文章等内容的介词，不能单独作谓语；“他很关心历史”才通顺。"}, {"text": "这是一把关于历史的椅子。", "explanation": "这里应该说“有历史的椅子”。关于修饰的是书、文章、消息等有内容的东西，不能用来修饰椅子。"}, {"text": "我买了一件关于两百块的衬衫。", "explanation": "这里应该用〈值〉。关于引出话题，不能表示价值；说衬衫的价钱要用“值”，即“值两百块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85996, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关于", "is_correct": true, "explanation": "正确答案。关于修饰问题，说明问题涉及课文，与“关于课文的问题”相符。"}, {"text": "至于", "is_correct": false, "explanation": "配价：“至于”引出话题，不能修饰名词，“至于课文的问题”不成立。"}, {"text": "比", "is_correct": false, "explanation": "语义：“比”表示比较，句中没有可以相比的两项。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”后接代替的人，不能修饰问题，“替课文的问题”讲不通。"}], "explanations": {"关于": "正确答案。关于修饰问题，说明问题涉及课文，与“关于课文的问题”相符。", "至于": "配价：“至于”引出话题，不能修饰名词，“至于课文的问题”不成立。", "比": "语义：“比”表示比较，句中没有可以相比的两项。", "替": "语义：“替”后接代替的人，不能修饰问题，“替课文的问题”讲不通。"}, "sentence_index": 6, "correct_answer": "关于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我关于那位老师去了北京。", "explanation": "这里应该用〈为了〉。关于只引出谈论的对象，不能表示目的；“为了那位老师去北京”要用“为了”。"}, {"text": "我关于这条新闻很有兴趣。", "explanation": "这里应该用〈对〉。关于引出谈论的内容，不能表示人对事物的兴趣；“对这条新闻很有兴趣”要用对。"}, {"text": "报纸上有一个关于天气的读者。", "explanation": "这里不能用关于修饰人。关于修饰的是新闻、文章等有内容的东西；读天气新闻的人要说“看天气新闻的读者”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85996, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想买一本关于的绘画的书。", "corrected_sentence": "我想买一本关于绘画的书。", "error_description": "错误形式：“关于”后面多加了“的”。“关于”是介词，后面直接接话题，不能带“的”。正确形式为“我想买一本关于绘画的书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85996, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "报纸上有一条关于了雨的新闻。", "corrected_sentence": "报纸上有一条关于雨的新闻。", "error_description": "错误形式：“关于”后面多加了“了”。“关于”是介词，不能带“了”表示完成，应改为“关于雨的新闻”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '889f1d97-79f3-4b0c-8f58-d6ec32fa4e46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
