INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85997, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“分”是把一个东西分开，变成几个。", "primary_collocate": null, "pronunciation": "fēn", "ipa": "fən˥", "syllable_count": 1, "sentences": [{"text": "请把这张纸分成两半。", "target_word": "分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用刀把面包分成三块。", "target_word": "分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块饼太大，我们分着吃吧。", "target_word": "分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把头发分成两边扎起来。", "target_word": "分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把书分成了三堆。", "target_word": "分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把木头分成几段。", "target_word": "分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些衣服分成两类。", "target_word": "分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把大房间分成两个小间。", "target_word": "分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书分上下两册。", "target_word": "分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一瓶水分成两杯。", "target_word": "分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分了", "label": "完成体"}, {"form": "分过", "label": "经历体"}, {"form": "分着", "label": "持续体"}, {"form": "分开", "label": "复合词"}], "register": "中性", "sense_fingerprint": "把一个东西分开变成几个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c97e07d7-e53b-4f4d-b1cf-a3cc62b4f69f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85997, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分", "is_correct": true, "explanation": "正确。分（fēn，第一声）表示把一个东西分开，变成几个。"}, {"text": "粉", "is_correct": false, "explanation": "fěn（第三声）与 fēn（第一声）声调不同，意思是粉末。"}, {"text": "风", "is_correct": false, "explanation": "fēng 与 fēn 只有韵尾不同（-ng 与 -n），意思是风。"}, {"text": "翻", "is_correct": false, "explanation": "fān 与 fēn 只有元音不同（a 与 e），意思是翻转、翻动。"}, {"text": "份", "is_correct": false, "explanation": "fèn（第四声）与 fēn（第一声）声调不同，意思是份额、一份。"}], "explanations": {"分": "正确。分（fēn，第一声）表示把一个东西分开，变成几个。", "粉": "fěn（第三声）与 fēn（第一声）声调不同，意思是粉末。", "风": "fēng 与 fēn 只有韵尾不同（-ng 与 -n），意思是风。", "翻": "fān 与 fēn 只有元音不同（a 与 e），意思是翻转、翻动。", "份": "fèn（第四声）与 fēn（第一声）声调不同，意思是份额、一份。"}, "sentence_index": null, "correct_answer": "分"}, "level_3": {"options": [{"text": "分", "is_correct": true, "explanation": "正确。“分”表示把纸分开变成两半，“请把这张纸分成两半”句意通顺。"}, {"text": "涂", "is_correct": false, "explanation": "搭配：“涂”指涂抹，不能表示把纸分开成两半。"}, {"text": "藏", "is_correct": false, "explanation": "语义：“藏”是隐藏，与把纸分开的意思不合。"}, {"text": "贴", "is_correct": false, "explanation": "语义：“贴”是粘在一起，与把纸分开变成两半的意思相反。"}], "explanations": {"分": "正确。“分”表示把纸分开变成两半，“请把这张纸分成两半”句意通顺。", "涂": "搭配：“涂”指涂抹，不能表示把纸分开成两半。", "藏": "语义：“藏”是隐藏，与把纸分开的意思不合。", "贴": "语义：“贴”是粘在一起，与把纸分开变成两半的意思相反。"}, "sentence_index": 0, "correct_answer": "分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中分了三十分。", "explanation": "这里应该用〈得〉（得分）。“分”表示分开变成几个，不能表示获得分数。"}, {"text": "老师把这两个字分给了我。", "explanation": "这里的“分”是分配义，指把东西分给人，与“把一个东西分开，变成几个”的义项不同。"}, {"text": "他分了五分钟把饼吃掉。", "explanation": "这里应该用〈用〉（用时）。“分”表示分开变成几个，不能表示花费时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85997, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "分", "is_correct": true, "explanation": "正确。分（fēn，第一声）表示把一个东西分开，变成几个。"}, {"text": "坟", "is_correct": false, "explanation": "fén（第二声）与 fēn（第一声）声调不同，意思是坟墓。"}, {"text": "封", "is_correct": false, "explanation": "fēng 与 fēn 只有韵尾不同（-ng 与 -n），意思是封上、封闭。"}, {"text": "愤", "is_correct": false, "explanation": "fèn（第四声）与 fēn（第一声）声调不同，意思是愤怒。"}], "explanations": {"分": "正确。分（fēn，第一声）表示把一个东西分开，变成几个。", "坟": "fén（第二声）与 fēn（第一声）声调不同，意思是坟墓。", "封": "fēng 与 fēn 只有韵尾不同（-ng 与 -n），意思是封上、封闭。", "愤": "fèn（第四声）与 fēn（第一声）声调不同，意思是愤怒。"}, "sentence_index": null, "correct_answer": "分"}, "level_3": {"options": [{"text": "分", "is_correct": true, "explanation": "正确。“分”表示把衣服分成几类，“请把这些衣服分成两类”句意通顺。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洗，与按类别分开的意思无关。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”是焚烧，与分类的意思无关。"}, {"text": "叠", "is_correct": false, "explanation": "搭配：“叠”指折叠或堆放，不能接“成两类”表示分类。"}], "explanations": {"分": "正确。“分”表示把衣服分成几类，“请把这些衣服分成两类”句意通顺。", "洗": "语义：“洗”是清洗，与按类别分开的意思无关。", "烧": "语义：“烧”是焚烧，与分类的意思无关。", "叠": "搭配：“叠”指折叠或堆放，不能接“成两类”表示分类。"}, "sentence_index": 6, "correct_answer": "分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上分半个小时步。", "explanation": "这里应该用〈跑〉。“分”表示把东西分开变成几个，不能表示跑步。"}, {"text": "他把书分在了桌子上。", "explanation": "这里应该用〈放〉。“分”表示分开变成几个，不能表示放置物品。"}, {"text": "他把这块饼分担成了三份。", "explanation": "这里应该用〈分成〉。“分担”指共同承担，不能用来表示把东西分开变成几份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.va