validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85998, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分", "is_correct": true, "explanation": "正确。分（fēn，第一声）表示把整体分成几部分，或分配。"}, {"text": "粉", "is_correct": false, "explanation": "fěn（第三声）与 fēn（第一声）声调不同，意思是粉末。"}, {"text": "风", "is_correct": false, "explanation": "fēng 与 fēn 只有韵尾不同（-ng 与 -n），意思是风。"}, {"text": "翻", "is_correct": false, "explanation": "fān 与 fēn 只有元音不同（a 与 e），意思是翻转、翻动。"}, {"text": "份", "is_correct": false, "explanation": "fèn（第四声）与 fēn（第一声）声调不同，意思是份额、一份。"}], "explanations": {"分": "正确。分（fēn，第一声）表示把整体分成几部分，或分配。", "粉": "fěn（第三声）与 fēn（第一声）声调不同，意思是粉末。", "风": "fēng 与 fēn 只有韵尾不同（-ng 与 -n），意思是风。", "翻": "fān 与 fēn 只有元音不同（a 与 e），意思是翻转、翻动。", "份": "fèn（第四声）与 fēn（第一声）声调不同，意思是份额、一份。"}, "sentence_index": null, "correct_answer": "分"}, "level_3": {"options": [{"text": "分", "is_correct": true, "explanation": "正确。“分”表示分给，“老师把苹果分给了同学们”句意通顺。"}, {"text": "藏", "is_correct": false, "explanation": "语义：“藏”是隐藏，与把苹果分给同学的意思相反。"}, {"text": "抢", "is_correct": false, "explanation": "语义：“抢”是夺取，与“给”所表示的分发义相悖。"}, {"text": "砸", "is_correct": false, "explanation": "搭配：“砸”一般不与“给”构成分发的搭配。"}], "explanations": {"分": "正确。“分”表示分给，“老师把苹果分给了同学们”句意通顺。", "藏": "语义：“藏”是隐藏，与把苹果分给同学的意思相反。", "抢": "语义：“抢”是夺取，与“给”所表示的分发义相悖。", "砸": "搭配：“砸”一般不与“给”构成分发的搭配。"}, "sentence_index": 0, "correct_answer": "分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们昨天分手了。", "explanation": "这里的“分”是“分手”义，指关系结束，不是把整体分成几部分或分配。"}, {"text": "他分了我一拳。", "explanation": "这里应该用〈打〉。“分”表示分开、分配，不能表示用拳头击打。"}, {"text": "他一眼就分出了我是谁。", "explanation": "这里应该用〈认出〉。“分”表示分开、区分，认出人要用“认”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85998, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "分", "is_correct": true, "explanation": "正确。分（fēn，第一声）表示把整体分成几部分，或分配。"}, {"text": "坟", "is_correct": false, "explanation": "fén（第二声）与 fēn（第一声）声调不同，意思是坟墓。"}, {"text": "封", "is_correct": false, "explanation": "fēng 与 fēn 只有韵尾不同（-ng 与 -n），意思是封上、封闭。"}, {"text": "愤", "is_correct": false, "explanation": "fèn（第四声）与 fēn（第一声）声调不同，意思是愤怒。"}], "explanations": {"分": "正确。分（fēn，第一声）表示把整体分成几部分，或分配。", "坟": "fén（第二声）与 fēn（第一声）声调不同，意思是坟墓。", "封": "fēng 与 fēn 只有韵尾不同（-ng 与 -n），意思是封上、封闭。", "愤": "fèn（第四声）与 fēn（第一声）声调不同，意思是愤怒。"}, "sentence_index": null, "correct_answer": "分"}, "level_3": {"options": [{"text": "分", "is_correct": true, "explanation": "正确。“分”表示把钱分成几份，“他把钱分成两份”句意通顺。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”表示丢弃，不能与“成两份”搭配，说不通。"}, {"text": "花", "is_correct": false, "explanation": "语义：“花”表示用掉钱，不是把钱拆分成两份。"}, {"text": "丢", "is_correct": false, "explanation": "语义：“丢”表示失去，与把钱拆成两份的意思无关。"}], "explanations": {"分": "正确。“分”表示把钱分成几份，“他把钱分成两份”句意通顺。", "扔": "搭配：“扔”表示丢弃，不能与“成两份”搭配，说不通。", "花": "语义：“花”表示用掉钱，不是把钱拆分成两份。", "丢": "语义：“丢”表示失去，与把钱拆成两份的意思无关。"}, "sentence_index": 6, "correct_answer": "分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把地板分了一遍。", "explanation": "这里应该用〈擦〉。“分”表示分开、分配，不能表示擦拭地面。"}, {"text": "他分好了那台电脑。", "explanation": "这里应该用〈修〉。“分”表示分开、分配，不能表示修理。"}, {"text": "他分了一千米的路。", "explanation": "这里应该用〈走〉。“分”表示分开、分配，不能表示行走一段距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把西瓜分开了四块。", "corrected_sentence": "他把西瓜分成了四块。", "error_description": "“分”后面的补语应用“成”，表示分成几部分；“分开”表示离开、分离，不能直接接数量。正确说法是“他把西瓜分成了四块。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85998, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这笔钱分了给三个朋友。", "corrected_sentence": "我把这笔钱分给了三个朋友。", "error_description": "“了”应放在“分给”之后，说“分给了”。不能放在“分”和“给”之间，正确说法是“我把这笔钱分给了三个朋友。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6d6a68f-78c5-414d-8182-a358c82b864b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
