INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85999, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“见”是用眼睛看到，或者和人碰面。", "primary_collocate": null, "pronunciation": "jiàn", "ipa": "tɕjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "明天见，路上小心。", "target_word": "见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天在公司见了王经理。", "target_word": "见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你见过这个人吗？", "target_word": "见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好久不见，你还好吗？", "target_word": "见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他见我来了，马上站了起来。", "target_word": "见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她见外面下起了大雨，就拿了一把伞。", "target_word": "见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在周末见一见老朋友。", "target_word": "见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天下午三点在咖啡馆见。", "target_word": "见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我在地铁上见了一位老同学。", "target_word": "见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天要去机场见一位客人。", "target_word": "见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "见了", "label": "体标"}, {"form": "见过", "label": "体标"}, {"form": "见面", "label": "复合"}, {"form": "看见", "label": "复合"}], "register": "通用", "sense_fingerprint": "见：用眼睛看到；与人碰面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60f41c19-c9f1-4287-85b2-aea15cba001d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85999, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "见", "is_correct": true, "explanation": "正确：见（jiàn，第四声），意思是看到或与人碰面。"}, {"text": "尖", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，意思是尖。"}, {"text": "简", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是简单。"}, {"text": "降", "is_correct": false, "explanation": "jiàng 与 jiàn 韵母不同（ang 与 an），声调相同，意思是降落。"}, {"text": "欠", "is_correct": false, "explanation": "qiàn 与 jiàn 声母不同（q 与 j），声调相同，意思是欠。"}], "explanations": {"见": "正确：见（jiàn，第四声），意思是看到或与人碰面。", "尖": "jiān（第一声）与 jiàn（第四声）声调不同，意思是尖。", "简": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是简单。", "降": "jiàng 与 jiàn 韵母不同（ang 与 an），声调相同，意思是降落。", "欠": "qiàn 与 jiàn 声母不同（q 与 j），声调相同，意思是欠。"}, "sentence_index": null, "correct_answer": "见"}, "level_3": {"options": [{"text": "见", "is_correct": true, "explanation": "正确：“明天见”是道别用语，表示下次见面。"}, {"text": "想", "is_correct": false, "explanation": "语义：“想”表示思念，不用于约定下次见面的道别语。"}, {"text": "闻", "is_correct": false, "explanation": "语义：“闻”指用鼻子嗅或听到消息，不表示见面，填入后语义不通。"}, {"text": "等", "is_correct": false, "explanation": "配价：“等”需要带等待的对象或时间，“明天等，路上小心”不完整。"}], "explanations": {"见": "正确：“明天见”是道别用语，表示下次见面。", "想": "语义：“想”表示思念，不用于约定下次见面的道别语。", "闻": "语义：“闻”指用鼻子嗅或听到消息，不表示见面，填入后语义不通。", "等": "配价：“等”需要带等待的对象或时间，“明天等，路上小心”不完整。"}, "sentence_index": 0, "correct_answer": "见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上回家后都见节目。", "explanation": "这里应该用〈看〉。收看节目要用“看”，“见”只表示用眼睛看到人或事物，不能用于观看节目。"}, {"text": "我昨天在音乐会上见了一首歌。", "explanation": "这里应该用〈听〉。听歌要用“听”，“见”指用眼睛看到或与人会面，不能用于听歌。"}, {"text": "我一进门就见到了饭香。", "explanation": "这里应该用〈闻〉。饭香要用鼻子感受，应说“闻到了饭香”；“见”只表示看到，不能用于闻气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85999, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "见", "is_correct": true, "explanation": "正确：见（jiàn，第四声），意思是看到或与人碰面。"}, {"text": "间", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，意思是房间。"}, {"text": "减", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是减少。"}, {"text": "坚", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，意思是坚固。"}, {"text": "歉", "is_correct": false, "explanation": "qiàn 与 jiàn 声母不同（q 与 j），声调相同，意思是抱歉。"}], "explanations": {"见": "正确：见（jiàn，第四声），意思是看到或与人碰面。", "间": "jiān（第一声）与 jiàn（第四声）声调不同，意思是房间。", "减": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是减少。", "坚": "jiān（第一声）与 jiàn（第四声）声调不同，意思是坚固。", "歉": "qiàn 与 jiàn 声母不同（q 与 j），声调相同，意思是抱歉。"}, "sentence_index": null, "correct_answer": "见"}, "level_3": {"options": [{"text": "见", "is_correct": true, "explanation": "正确：“见一见”是“见”的重叠形式（V一V），表示短暂地见面，“想在周末见一见老朋友”通顺。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”的对象通常是物品，不能用来说“扔老朋友”，填入后不成话。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象通常是物品或身体，不能用来说“洗老朋友”。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”指把东西换成钱，与见面的意思完全不符。"}], "explanations": {"见": "正确：“见一见”是“见”的重叠形式（V一V），表示短暂地见面，“想在周末见一见老朋友”通顺。", "扔": "搭配：“扔”的对象通常是物品，不能用来说“扔老朋友”，填入后不成话。", "洗": "搭配：“洗”的对象通常是物品或身体，不能用来说“洗老朋友”。", "卖": "语义：“卖”指把东西换成钱，与见面的意思完全不符。"}, "sentence_index": 6, "correct_answer": "见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天都见日记。", "explanation": "这里应该用〈写〉。写日记要用“写”，“见”不表示书写的动作。"}, {"text": "我昨天给朋友见了一个电话。", "explanation": "这里应该用〈打〉。打电话要用“打”，“见”不能表示拨打电话的动作。"}, {"text": "他昨天见了一个好觉。", "explanation": "这里应该用〈睡〉。睡好觉要用“睡”，“见”不能表示睡眠的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
